def _freeze_datetime_in(
    monkeypatch: pytest.MonkeyPatch,
    *module_paths: str,
    frozen: datetime | None = None,
) -> datetime:
    """P2-06 helper: patch named backend modules so that `datetime.now()` returns
    a deterministic time, sidestepping pre-existing tests that hard-code
    `latest_nav_date='2026-04-08'` yet rely on live `NAV_FRESHNESS_DAYS=10`.

    Leaves `datetime.fromisoformat` etc intact via subclass.
    """

    import importlib
    from datetime import datetime as _real_datetime

    frozen_value = frozen or _real_datetime(2026, 4, 12, 12, 0, 0)

    class _FrozenDatetime(_real_datetime):
        @classmethod
        def now(cls, tz=None):
            if tz is not None:
                return frozen_value.replace(tzinfo=tz)
            return frozen_value

        @classmethod
        def today(cls):
            return frozen_value

    for path in module_paths:
        mod = importlib.import_module(path)
        monkeypatch.setattr(mod, "datetime", _FrozenDatetime)
    return frozen_value


def _script_tag_with_optional_version(script_name: str) -> str:
    return rf'<script src="/{re.escape(script_name)}(?:\?v=[^"]+)?"></script>'


def _assert_script_loaded_before(html_src: str, first_script: str, second_script: str) -> None:
    first_pattern = _script_tag_with_optional_version(first_script)
    second_pattern = _script_tag_with_optional_version(second_script)
    first_match = re.search(first_pattern, html_src)
    second_match = re.search(second_pattern, html_src)
    assert first_match is not None
    assert second_match is not None
    assert first_match.start() < second_match.start()


