def _nav_rows_for_code(code: str, start: str, end: str, freq: str = "7D") -> list[tuple[str, str]]:
    dates = list(pd.date_range(start=start, end=end, freq=freq))
    end_ts = pd.Timestamp(end)
    if not dates or dates[-1] != end_ts:
        dates.append(end_ts)
    return [(code, ts.date().isoformat()) for ts in dates]


def _load_script_module(module_name: str, relative_path: str):
    script_path = PROJECT_ROOT / relative_path
    spec = importlib.util.spec_from_file_location(module_name, script_path)
    assert spec is not None and spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    sys.modules[module_name] = module
    spec.loader.exec_module(module)
    return module


def test_ensure_project_venv_execs_symlink_path_without_resolving(monkeypatch: pytest.MonkeyPatch, tmp_path: Path) -> None:
    project_root = tmp_path
    venv_bin = project_root / ".venv" / "bin"
    venv_bin.mkdir(parents=True)
    real_python = project_root / "python-real"
    real_python.write_text("", encoding="utf-8")
    venv_python = venv_bin / "python"
    venv_python.symlink_to(real_python)

    execv_calls = []

    def _fake_execv(path: str, argv: list[str]) -> None:
        execv_calls.append((path, argv))
        raise RuntimeError("stop-exec")

    monkeypatch.setattr(sys, "prefix", "/usr", raising=False)
    monkeypatch.setattr(sys, "argv", ["/tmp/daily_short_term_screening.py"], raising=False)
    monkeypatch.setattr(os, "execv", _fake_execv)
    monkeypatch.delenv(_VENV_BOOTSTRAP_ENV, raising=False)

    with pytest.raises(RuntimeError, match="stop-exec"):
        ensure_project_venv(project_root)

    assert execv_calls == [
        (
            str(venv_python),
            [str(venv_python), "/tmp/daily_short_term_screening.py"],
        )
    ]
    assert os.environ[_VENV_BOOTSTRAP_ENV] == str((project_root / ".venv").resolve())


def test_ensure_project_venv_skips_reexec_after_one_attempt(monkeypatch: pytest.MonkeyPatch, tmp_path: Path) -> None:
    project_root = tmp_path
    venv_bin = project_root / ".venv" / "bin"
    venv_bin.mkdir(parents=True)
    (venv_bin / "python").write_text("", encoding="utf-8")

    execv_mock = Mock()

    monkeypatch.setattr(sys, "prefix", "/usr", raising=False)
    monkeypatch.setattr(os, "execv", execv_mock)
    monkeypatch.setenv(_VENV_BOOTSTRAP_ENV, str((project_root / ".venv").resolve()))

    ensure_project_venv(project_root)

    execv_mock.assert_not_called()


def test_daily_period_tasks_block_empty_configured_periods() -> None:
    task_contracts = (
        (
            PROJECT_ROOT / "core/bond_fund_screening/tasks/daily_short_term_screening.py",
            "len(successful_periods) != len(short_term_periods)",
        ),
        (
            PROJECT_ROOT / "core/bond_fund_screening/tasks/daily_long_term_screening.py",
            "len(successful_periods) != len(long_term_periods)",
        ),
    )

    for task_path, completeness_guard in task_contracts:
        source = task_path.read_text(encoding="utf-8")
        assert "配置周期缺失会改变" in source
        assert completeness_guard in source
        assert "视为正常空结果" not in source


def test_audit_publish_pipeline_passes_final_selection_tracker_features(monkeypatch: pytest.MonkeyPatch) -> None:
    module = _load_script_module("audit_holding_period_gate_impact_test_helper", "scripts/audit_holding_period_gate_impact.py")

    universe_df = pd.DataFrame([{"基金代码": "000001", "基础门禁通过": True}])
    publish_official_df = pd.DataFrame([{"基金代码": "000001", "项目推荐结论": "正式推荐"}])
    tracker_features_df = pd.DataFrame(
        [
            {
                "基金代码": "000001",
                "出现次数": 6,
                "出现频率(%)": 60.0,
                "连续缺席期数": 0,
                "当前是否在榜": "是",
                "跟踪总期数": 10,
            }
        ]
    )
    call_log: dict[str, object] = {}

    monkeypatch.setattr(module, "_append_project_decision_columns", lambda df, **kwargs: df.copy())
    monkeypatch.setattr(module, "_apply_fixed_quality_thresholds", lambda df: df.copy())
    monkeypatch.setattr(
        module,
        "_compute_dynamic_style_thresholds",
        lambda df: ({"未知": {"scale_billion_min": 0.0}}, {"scale_billion_min": 0.0}, {"未知": {"threshold_source": "style_quantile_robust"}}),
    )
    monkeypatch.setattr(module, "_apply_dynamic_quality_thresholds", lambda df, **kwargs: df.copy())
    monkeypatch.setattr(module, "_apply_enhanced_supplemental_gate", lambda df: df.copy())
    monkeypatch.setattr(module, "_apply_publish_post_filters", lambda df, **kwargs: publish_official_df.copy())

    def _fake_build_final_selection_tracker_features(settings, *, current_run_id, current_generated_at, current_nav_snapshot_date, current_df):
        call_log["tracker_run_id"] = current_run_id
        call_log["tracker_generated_at"] = current_generated_at
        call_log["tracker_nav_snapshot_date"] = current_nav_snapshot_date
        call_log["tracker_input_codes"] = current_df["基金代码"].tolist()
        return tracker_features_df.copy()

    def _fake_apply_final_official_selection(df, *, settings=None, tracker_features_df=None):
        call_log["final_selection_settings"] = settings
        call_log["final_selection_tracker_features"] = tracker_features_df.copy() if isinstance(tracker_features_df, pd.DataFrame) else tracker_features_df
        return df.copy()

    monkeypatch.setattr(module, "_build_final_selection_tracker_features", _fake_build_final_selection_tracker_features)
    monkeypatch.setattr(module, "_apply_final_official_selection", _fake_apply_final_official_selection)
    monkeypatch.setattr(module, "_apply_exported_autostock_status_map", lambda df, **kwargs: df.copy())
    monkeypatch.setattr(module, "_demote_autostock_hard_block_rows", lambda df: (df.copy(), pd.DataFrame()))
    monkeypatch.setattr(module, "_append_formal_group_column", lambda df: df.copy())
    monkeypatch.setattr(module, "_apply_incremental_safety_watch_alignment", lambda **kwargs: (kwargs["publish_track_df"].copy(), kwargs["official_df"].copy(), set()))

    settings = SimpleNamespace()
    result = module._run_publish_pipeline(
        universe_df=universe_df,
        decision_map={},
        soft_warning_map={},
        autostock_status_map={},
        settings=settings,
        run_id="20260423_102814_sync",
        generated_at="2026-04-23T10:29:12",
        snapshot_date="2026-04-22",
    )

    assert not result["official_df"].empty
    assert call_log["tracker_run_id"] == "20260423_102814_sync"
    assert call_log["tracker_generated_at"] == "2026-04-23T10:29:12"
    assert call_log["tracker_nav_snapshot_date"] == "2026-04-22"
    assert call_log["tracker_input_codes"] == ["000001"]
    assert call_log["final_selection_settings"] is settings
    pd.testing.assert_frame_equal(
        call_log["final_selection_tracker_features"],
        tracker_features_df,
        check_dtype=False,
    )


