def test_nav_history_consistency_audit_flags_accum_nav_gap_regression() -> None:
    dates = pd.date_range("2025-01-01", periods=40, freq="D")
    unit_nav = np.linspace(1.0000, 1.0400, len(dates))
    accum_nav = unit_nav + 0.0800
    accum_nav[-1] = unit_nav[-1] + 0.0200

    rows = [
        {
            "fcode": "000001",
            "shortname": "测试债券A",
            "ftype": "债券型-长债",
            "type_category": "fixed_income",
            "nav_date": ts.date().isoformat(),
            "unit_nav": float(unit_nav[idx]),
            "accum_nav": float(accum_nav[idx]),
            "daily_growth": 0.10,
        }
        for idx, ts in enumerate(dates)
    ]

    result = analyze_fund_nav_history_consistency(rows)

    assert result is not None
    assert "accum_nav_gap_regression" in result["issue_keys"]
    assert result["accum_gap_regression_count"] >= 1
    assert result["max_accum_gap_regression"] > 0.01


def test_nav_history_consistency_audit_prefers_accum_nav_conflict_when_accum_series_is_reliable() -> None:
    dates = pd.date_range("2025-01-01", periods=40, freq="D")
    rows = []
    unit_nav = 1.0
    accum_nav = 1.0
    for idx, ts in enumerate(dates):
        if idx > 0:
            unit_nav *= 1.0010
            accum_nav *= 1.0050
        rows.append(
            {
                "fcode": "000002",
                "shortname": "测试债券B",
                "ftype": "债券型-中短债",
                "type_category": "fixed_income",
                "nav_date": ts.date().isoformat(),
                "unit_nav": unit_nav,
                "accum_nav": accum_nav,
                "daily_growth": 0.50 if idx > 0 else None,
            }
        )

    result = analyze_fund_nav_history_consistency(
        rows,
        daily_growth_cumulative_diff_tolerance=0.001,
        daily_growth_step_diff_tolerance=0.001,
    )

    assert result is not None
    assert result["accum_nav_reliable"] is True
    assert result["uses_unit_nav_fallback_checks"] is False
    assert "daily_growth_total_return_conflicts_with_accum_nav" not in result["issue_keys"]
    assert "daily_growth_total_return_conflicts_with_unit_nav" not in result["issue_keys"]
    assert "daily_growth_step_conflicts_with_unit_nav" not in result["issue_keys"]
    assert any(
        "daily_growth_total_return_conflicts_with_unit_nav" not in (record.get("issue_keys") or [])
        for record in result["window_records"]
    )


def test_nav_history_consistency_audit_falls_back_to_unit_nav_when_accum_series_is_unreliable() -> None:
    dates = pd.date_range("2025-01-01", periods=40, freq="D")
    rows = []
    for idx, ts in enumerate(dates):
        unit_nav = 1.0 + idx * 0.005
        accum_nav = unit_nav + 0.08
        if idx == len(dates) - 1:
            accum_nav = unit_nav - 0.02
        daily_growth = 0.50 if idx > 0 else None
        rows.append(
            {
                "fcode": "000004",
                "shortname": "测试债券C",
                "ftype": "债券型-中短债",
                "type_category": "fixed_income",
                "nav_date": ts.date().isoformat(),
                "unit_nav": unit_nav,
                "accum_nav": accum_nav,
                "daily_growth": daily_growth,
            }
        )

    result = analyze_fund_nav_history_consistency(
        rows,
        daily_growth_cumulative_diff_tolerance=0.001,
        daily_growth_step_diff_tolerance=0.001,
    )

    assert result is not None
    assert result["accum_nav_reliable"] is False
    assert result["uses_unit_nav_fallback_checks"] is True
    assert "daily_growth_total_return_conflicts_with_unit_nav" in result["issue_keys"]
    assert "daily_growth_total_return_conflicts_with_accum_nav" not in result["issue_keys"]
    assert result["window_records"]
    assert any(
        "daily_growth_total_return_conflicts_with_unit_nav" in (record.get("issue_keys") or [])
        for record in result["window_records"]
    )


