def test_runtime_config_bridge_projects_project_yaml_into_core_shape() -> None:
    project_payload = {
        "project": {"timezone": "Asia/Shanghai"},
        "workflow": {"exclude_holding_days_gt": 90},
        "apis": {
            "tiantian_base_url": "http://example.com:18087",
            "autostock_base_url": "https://api.autostock.cn/v1",
        },
        "paths": {
            "database_path": "backend/data/test.db",
        },
        "collection": {
            "incremental": {
                "only_active": False,
                "max_age_days": 1095,
            },
            "annual_return": {"workers": 8},
            "rank": {"workers": 8},
        },
        "scheduler": {
            "enabled": True,
            "timezone": "Asia/Shanghai",
        },
    }
    compat_defaults = {
        "api": {
            "base_url": "http://legacy.example.com:18087",
            "tiantian": {"base_url": "http://legacy.example.com:18087"},
            "autostock": {"base_url": "https://old.example.com"},
        },
        "database": {"path": "../backend/data/legacy.db"},
        "scheduler": {"enabled": False, "timezone": "UTC"},
        "collection": {"incremental": {"only_active": True, "max_age_days": 90}},
    }

    runtime = build_core_runtime_config(project_payload, compat_defaults)

    assert runtime["api"]["base_url"] == "http://example.com:18087"
    assert runtime["api"]["tiantian"]["base_url"] == "http://example.com:18087"
    assert runtime["api"]["autostock"]["base_url"] == "https://api.autostock.cn/v1"
    assert runtime["database"]["path"].endswith("/backend/data/test.db")
    assert runtime["scheduler"]["enabled"] is True
    assert runtime["scheduler"]["timezone"] == "Asia/Shanghai"
    assert runtime["services"]["tiantian_api_url"] == "http://example.com:18087"
    assert runtime["collection"]["incremental"]["only_active"] is False
    assert runtime["collection"]["incremental"]["max_age_days"] == 1095
    assert runtime["collection"]["annual_return"]["workers"] == 8
    assert runtime["collection"]["rank"]["workers"] == 8
    assert runtime["exclude_holding_days_gt"] == 90
    assert runtime["risk_metrics"]["skip_risk_metrics_for_holding_days_gt"] == 90


def test_config_manager_update_task_config_writes_back_project_yaml(tmp_path: Path) -> None:
    project_config = tmp_path / "project.yaml"
    project_config.write_text(
        json.dumps(
            {
                "project": {"timezone": "Asia/Shanghai"},
                "apis": {"tiantian_base_url": "http://example.com:18087"},
                "paths": {"database_path": "backend/data/bond_funds.db"},
                "scheduler": {
                    "enabled": True,
                    "timezone": "Asia/Shanghai",
                },
            },
            ensure_ascii=False,
        ),
        encoding="utf-8",
    )

    manager = ConfigManager(str(project_config))
    assert manager.update_task_config("daily_nav_update", enabled=False, schedule="7,15", schedule_kind="daily") is True

    saved = yaml.safe_load(project_config.read_text(encoding="utf-8"))
    scheduler = saved["scheduler"]
    assert scheduler["enabled"] is True
    assert scheduler["timezone"] == "Asia/Shanghai"
    assert scheduler["tasks"]["daily_nav_update"] is False
    assert scheduler["schedules"]["daily_nav_update"] == "7,15"


