def test_screening_cleanup_plan_uses_materialized_run_storage_stats(tmp_path: Path) -> None:
    from database import ScreeningDecision, ScreeningPick, ScreeningRun, get_db_manager, init_database
    from database.screening_history_maintenance import build_recent_duplicate_success_cleanup_plan
    from database.screening_run_storage_stats import refresh_screening_run_storage_stats

    db_path = tmp_path / "screening-storage-stats.db"
    assert init_database(str(db_path), drop_existing=True) is True
    manager = get_db_manager(str(db_path))

    now = datetime.now()
    with manager.get_session(task_name="seed_screening_storage_stats_test") as session:
        session.add_all([
            ScreeningRun(
                run_id="run-old",
                started_at=now - timedelta(hours=2),
                finished_at=now - timedelta(hours=2, minutes=-5),
                status="success",
                fund_type="bond",
                period_years=1,
                fund_count_in=10,
                fund_count_pass=2,
            ),
            ScreeningRun(
                run_id="run-new",
                started_at=now - timedelta(hours=1),
                finished_at=now - timedelta(hours=1, minutes=-5),
                status="success",
                fund_type="bond",
                period_years=1,
                fund_count_in=10,
                fund_count_pass=2,
            ),
        ])
        session.add_all([
            ScreeningDecision(run_id="run-old", fcode="000001", step_id=1, passed=True),
            ScreeningDecision(run_id="run-old", fcode="000001", step_id=2, passed=True),
            ScreeningDecision(run_id="run-old", fcode="000002", step_id=1, passed=False),
            ScreeningPick(run_id="run-old", fcode="000001", rank=1, fund_type="bond", period_years=1),
        ])

    refresh_result = refresh_screening_run_storage_stats(
        db_manager=manager,
        run_ids=["run-old", "run-new"],
        stats_source="test_refresh",
    )
    assert refresh_result["upserted_count"] == 2

    with manager.get_session(task_name="plan_screening_storage_stats_test", readonly=True) as session:
        plan = build_recent_duplicate_success_cleanup_plan(
            session,
            recent_days=7,
            fund_types=["bond"],
        )

    assert plan["candidate_run_count"] == 1
    assert plan["_candidate_run_ids"] == ["run-old"]
    assert plan["decisions_to_delete"] == 3
    assert plan["picks_to_delete"] == 1
    assert plan["count_source"] == "materialized"
    assert plan["storage_stats_covered_run_count"] == 1
    assert plan["storage_stats_missing_run_count"] == 0


