def test_screening_cleanup_apply_syncs_materialized_stats(tmp_path: Path) -> None:
    from database import ScreeningDecision, ScreeningPick, ScreeningRun, get_db_manager, init_database
    from database.models import (
        ScreeningDecisionReasonSummary,
        ScreeningPickMetricSnapshot,
        ScreeningRunLatestActivity,
        ScreeningRunStorageStats,
    )
    from database.screening_history_maintenance import cleanup_recent_duplicate_success_runs
    from database.screening_decision_summaries import refresh_screening_decision_summaries
    from database.screening_pick_metric_snapshots import refresh_screening_pick_metric_snapshots
    from database.screening_run_storage_stats import refresh_screening_run_storage_stats

    db_path = tmp_path / "screening-storage-stats-cleanup.db"
    assert init_database(str(db_path), drop_existing=True) is True
    manager = get_db_manager(str(db_path))

    now = datetime.now()
    with manager.get_session(task_name="seed_screening_storage_stats_cleanup_test") as session:
        session.add_all([
            ScreeningRun(
                run_id="run-old",
                started_at=now - timedelta(hours=2),
                finished_at=now - timedelta(hours=2, minutes=-5),
                status="success",
                fund_type="bond",
                period_years=5,
                fund_count_in=10,
                fund_count_pass=2,
            ),
            ScreeningRun(
                run_id="run-new",
                started_at=now - timedelta(hours=1),
                finished_at=now - timedelta(hours=1, minutes=-5),
                status="success",
                fund_type="bond",
                period_years=5,
                fund_count_in=10,
                fund_count_pass=2,
            ),
        ])
        session.add_all([
            ScreeningDecision(run_id="run-old", fcode="000001", step_id=1, passed=True),
            ScreeningDecision(run_id="run-old", fcode="000002", step_id=1, passed=False),
            ScreeningPick(
                run_id="run-old",
                fcode="000001",
                rank=1,
                fund_type="bond",
                period_years=5,
                snapshot_json=json.dumps(
                    {"risk_metrics": {"max_drawdown_duration": 42}},
                    ensure_ascii=False,
                ),
            ),
        ])

    refresh_screening_run_storage_stats(db_manager=manager, stats_source="test_refresh")
    metric_refresh = refresh_screening_pick_metric_snapshots(
        db_manager=manager,
        run_ids=["run-old"],
        stats_source="test_refresh",
    )
    decision_summary_refresh = refresh_screening_decision_summaries(
        db_manager=manager,
        run_ids=["run-old"],
        stats_source="test_refresh",
    )
    assert metric_refresh["inserted_count"] == 1
    assert decision_summary_refresh["reason_inserted_count"] == 2
    assert decision_summary_refresh["latest_activity_inserted_count"] == 1

    result = cleanup_recent_duplicate_success_runs(
        db_manager=manager,
        recent_days=7,
        fund_types=["bond"],
        dry_run=False,
        delete_runs=False,
    )
    assert result["deleted_decisions"] == 2
    assert result["deleted_picks"] == 1
    assert result["deleted_pick_metric_snapshots"] == 1
    assert result["deleted_decision_reason_summaries"] == 2
    assert result["deleted_run_latest_activities"] == 1

    with manager.get_session(task_name="assert_screening_storage_stats_cleanup_test", readonly=True) as session:
        row = session.query(ScreeningRunStorageStats).filter_by(run_id="run-old").one()
        assert row.decision_count == 0
        assert row.pick_count == 0
        assert row.stats_source == "cleanup_recent_duplicate_success_runs"[:40]
        assert session.query(ScreeningPickMetricSnapshot).filter_by(run_id="run-old").count() == 0
        assert session.query(ScreeningDecisionReasonSummary).filter_by(run_id="run-old").count() == 0
        assert session.query(ScreeningRunLatestActivity).filter_by(run_id="run-old").count() == 0


