def test_screening_history_archive_preview_and_execution_preserve_hot_db(
    tmp_path: Path,
) -> None:
    from database import ScreeningDecision, ScreeningPick, ScreeningRun, get_db_manager, init_database
    from database.screening_decision_summaries import refresh_screening_decision_summaries
    from database.screening_pick_metric_snapshots import refresh_screening_pick_metric_snapshots
    from database.screening_run_storage_stats import refresh_screening_run_storage_stats
    from utils.screening_history_archive_execution import execute_screening_history_archive
    from utils.screening_history_archive_preview import (
        build_screening_history_archive_preview_payload,
        write_screening_history_archive_preview_artifacts,
    )

    db_path = tmp_path / "screening-history-archive.db"
    archive_path = tmp_path / "backend/data/archives/screening_history_details_archive.db"
    assert init_database(str(db_path), drop_existing=True) is True
    manager = get_db_manager(str(db_path))

    now = datetime.now()
    with manager.get_session(task_name="seed_screening_history_archive_test") as session:
        session.add_all(
            [
                ScreeningRun(
                    run_id="run-old",
                    started_at=now - timedelta(hours=2),
                    finished_at=now - timedelta(hours=1, minutes=55),
                    status="success",
                    fund_type="bond",
                    period_years=5,
                    fund_count_in=20,
                    fund_count_pass=1,
                ),
                ScreeningRun(
                    run_id="run-live",
                    started_at=now - timedelta(hours=1),
                    finished_at=now - timedelta(minutes=55),
                    status="success",
                    fund_type="bond",
                    period_years=5,
                    fund_count_in=20,
                    fund_count_pass=1,
                ),
            ]
        )
        session.add_all(
            [
                ScreeningDecision(run_id="run-old", fcode="000001", step_id=1, passed=True),
                ScreeningDecision(run_id="run-old", fcode="000002", step_id=1, passed=False),
                ScreeningDecision(run_id="run-live", fcode="000003", step_id=1, passed=True),
                ScreeningPick(
                    run_id="run-old",
                    fcode="000001",
                    rank=1,
                    fund_type="bond",
                    period_years=5,
                    snapshot_json=json.dumps(
                        {"risk_metrics": {"max_drawdown_duration": 21}},
                        ensure_ascii=False,
                    ),
                ),
                ScreeningPick(run_id="run-live", fcode="000003", rank=1, fund_type="bond", period_years=5),
            ]
        )

    refresh_screening_run_storage_stats(db_manager=manager, stats_source="archive_test")
    refresh_screening_pick_metric_snapshots(
        db_manager=manager,
        run_ids=["run-old"],
        stats_source="archive_test",
    )
    refresh_screening_decision_summaries(
        db_manager=manager,
        run_ids=["run-old"],
        stats_source="archive_test",
    )

    cleanup_preview_payload = {
        "db_path": str(db_path),
        "summary": {
            "candidate_run_count": 1,
            "estimated_rows_to_delete": 3,
        },
        "execution_plan": {"scope_run_ids": ["run-old"]},
    }
    cleanup_preflight_payload = {
        "checks": {"ready_for_manual_signoff": True},
        "summary": {"ready_for_manual_signoff": True},
    }

    preview_payload = build_screening_history_archive_preview_payload(
        db_path=db_path,
        preview_payload=cleanup_preview_payload,
        preflight_payload=cleanup_preflight_payload,
        archive_target_path=archive_path,
        project_root=tmp_path,
        output_dir=tmp_path / "audit",
    )
    table_scope = {
        row["table_name"]: row
        for row in preview_payload["table_scope"]
    }
    assert preview_payload["status"] == "success"
    assert preview_payload["summary"]["scope_run_count"] == 1
    assert table_scope["screening_runs"]["scope_row_count"] == 1
    assert table_scope["screening_decisions"]["scope_row_count"] == 2
    assert table_scope["screening_picks"]["scope_row_count"] == 1
    assert table_scope["screening_pick_metric_snapshots"]["scope_row_count"] == 1
    assert table_scope["screening_decision_reason_summary"]["scope_row_count"] >= 1
    assert table_scope["screening_run_latest_activity"]["scope_row_count"] == 1
    assert table_scope["screening_run_storage_stats"]["scope_row_count"] == 1
    assert preview_payload["summary"]["cleanup_preflight_ready"] is True

    preview_json_path, _preview_md_path = write_screening_history_archive_preview_artifacts(
        preview_payload,
        output_dir=tmp_path / "audit",
        timestamp="20260604_preview",
    )
    _dry_json_path, _dry_md_path, dry_payload = execute_screening_history_archive(
        db_path=db_path,
        preview_payload=preview_payload,
        source_preview_artifact=str(preview_json_path),
        output_dir=tmp_path / "audit",
        mode="dry-run",
        archive_target_path=archive_path,
        project_root=tmp_path,
        timestamp="20260604_dry_run",
    )
    assert dry_payload["status"] == "dry-run"
    assert dry_payload["summary"]["scope_run_count"] == 1
    assert not archive_path.exists()

    with manager.get_session(task_name="pre_archive_hot_counts", readonly=True) as session:
        hot_decisions_before = session.query(ScreeningDecision).filter_by(run_id="run-old").count()
        hot_picks_before = session.query(ScreeningPick).filter_by(run_id="run-old").count()

    _json_path, _md_path, execution_payload = execute_screening_history_archive(
        db_path=db_path,
        preview_payload=preview_payload,
        source_preview_artifact=str(preview_json_path),
        output_dir=tmp_path / "audit",
        mode="archive-export",
        archive_target_path=archive_path,
        project_root=tmp_path,
        chunk_size=1,
        timestamp="20260604_archive_export",
    )
    assert execution_payload["status"] == "archive-exported"
    assert execution_payload["summary"]["archive_db_quick_check"] == "ok"
    assert execution_payload["summary"]["inserted_row_count"] >= 7

    with manager.get_session(task_name="post_archive_hot_counts", readonly=True) as session:
        assert session.query(ScreeningDecision).filter_by(run_id="run-old").count() == hot_decisions_before
        assert session.query(ScreeningPick).filter_by(run_id="run-old").count() == hot_picks_before

    conn = sqlite3.connect(archive_path)
    try:
        assert conn.execute("SELECT COUNT(*) FROM screening_decisions WHERE run_id='run-old'").fetchone()[0] == 2
        assert conn.execute("SELECT COUNT(*) FROM screening_picks WHERE run_id='run-old'").fetchone()[0] == 1
        assert conn.execute("SELECT COUNT(*) FROM screening_decisions WHERE run_id='run-live'").fetchone()[0] == 0
    finally:
        conn.close()

    _json_path, _md_path, second_payload = execute_screening_history_archive(
        db_path=db_path,
        preview_payload=preview_payload,
        source_preview_artifact=str(preview_json_path),
        output_dir=tmp_path / "audit",
        mode="archive-export",
        archive_target_path=archive_path,
        project_root=tmp_path,
        chunk_size=1,
        timestamp="20260604_archive_export_second",
    )
    assert second_payload["status"] == "archive-exported"
    assert second_payload["summary"]["inserted_row_count"] == 0
    with manager.get_session(task_name="assert_archive_preserved_hot_run", readonly=True) as session:
        assert session.query(ScreeningRun).filter_by(run_id="run-old").count() == 1


def test_screening_history_archive_rotation_reuses_immutable_shard_and_guard_sums_shards(
    tmp_path: Path,
) -> None:
    from database import ScreeningDecision, ScreeningPick, ScreeningRun, get_db_manager, init_database
    from utils import screening_history_cleanup_execution as cleanup_execution_module
    from utils.screening_history_archive_execution import execute_screening_history_archive
    from utils.screening_history_archive_manifest import load_screening_archive_manifest
    from utils.screening_history_archive_preview import build_screening_history_archive_preview_payload
    from utils.screening_history_archive_rotation import (
        build_screening_history_archive_rotation_payload,
    )

    db_path = tmp_path / "screening-history-sharded-hot.db"
    archive_path = tmp_path / "backend/data/archives/screening_history_details_archive.db"
    assert init_database(str(db_path), drop_existing=True) is True
    manager = get_db_manager(str(db_path))
    now = datetime.now()
    with manager.get_session(task_name="seed_screening_history_shard_rotation") as session:
        session.add(
            ScreeningRun(
                run_id="run-old",
                started_at=now - timedelta(days=45),
                finished_at=now - timedelta(days=45, minutes=-5),
                status="success",
                fund_type="bond",
                period_years=5,
                fund_count_in=20,
                fund_count_pass=1,
            )
        )
        session.add_all(
            [
                ScreeningDecision(run_id="run-old", fcode="000001", step_id=1, passed=True),
                ScreeningPick(
                    run_id="run-old",
                    fcode="000001",
                    rank=1,
                    fund_type="bond",
                    period_years=5,
                ),
            ]
        )

    cleanup_preview = {
        "db_path": str(db_path),
        "summary": {"candidate_run_count": 1, "estimated_rows_to_delete": 3},
        "execution_plan": {"scope_run_ids": ["run-old"]},
    }
    cleanup_preflight = {"checks": {"ready_for_manual_signoff": True}}
    preview = build_screening_history_archive_preview_payload(
        db_path=db_path,
        preview_payload=cleanup_preview,
        preflight_payload=cleanup_preflight,
        archive_target_path=archive_path,
        project_root=tmp_path,
        output_dir=tmp_path / "audit",
    )
    _json_path, _md_path, first_execution = execute_screening_history_archive(
        db_path=db_path,
        preview_payload=preview,
        output_dir=tmp_path / "audit",
        mode="archive-export",
        archive_target_path=archive_path,
        project_root=tmp_path,
        timestamp="first_shard_export",
    )
    assert first_execution["status"] == "archive-exported"
    assert first_execution["summary"]["inserted_row_count"] >= 3

    rotation = build_screening_history_archive_rotation_payload(
        active_archive_path=archive_path,
        project_root=tmp_path,
        mode="rotate",
        max_active_size_bytes=1,
        min_active_run_count=1,
        confirm_rotate=True,
        compute_sha256=False,
        timestamp="20260824_120000",
    )
    assert rotation["status"] == "rotated"
    immutable_path = Path(rotation["rotation_result"]["immutable_shard_path"])
    assert immutable_path.exists()
    assert archive_path.exists()
    with sqlite3.connect(archive_path) as active_archive_conn:
        assert active_archive_conn.execute("PRAGMA quick_check").fetchone()[0] == "ok"
    manifest_state = load_screening_archive_manifest(archive_path, project_root=tmp_path)
    assert manifest_state["status"] == "ready"
    assert len([row for row in manifest_state["shards"] if row["role"] == "immutable"]) == 1

    second_preview = build_screening_history_archive_preview_payload(
        db_path=db_path,
        preview_payload=cleanup_preview,
        preflight_payload=cleanup_preflight,
        archive_target_path=archive_path,
        project_root=tmp_path,
        output_dir=tmp_path / "audit",
    )
    second_path, _second_md_path, second_execution = execute_screening_history_archive(
        db_path=db_path,
        preview_payload=second_preview,
        output_dir=tmp_path / "audit",
        mode="archive-export",
        archive_target_path=archive_path,
        project_root=tmp_path,
        timestamp="second_shard_export",
    )
    assert second_execution["status"] == "archive-exported"
    assert second_execution["summary"]["inserted_row_count"] == 0
    assert second_execution["summary"]["scope_run_count_written_to_active"] == 0
    assert second_execution["summary"]["scope_run_count_reused_from_immutable"] == 1
    assert second_execution["summary"]["archive_shard_count"] == 2
    assert all(row["exact_archive_match"] for row in second_execution["table_results"])

    guard = cleanup_execution_module._build_archive_apply_guard(
        selected_run_ids=["run-old"],
        archive_execution_payload=second_execution,
        source_archive_execution_artifact=str(second_path),
        require_archive_guard=True,
        project_root=tmp_path,
        preflight_payload={"db_path": str(db_path)},
        db_path=db_path,
        archive_target_path=archive_path,
    )
    assert guard["status"] == "ok"
    assert guard["archive_shard_count"] == 2
    assert guard["archive_manifest_generation"] == second_execution["summary"][
        "archive_manifest_generation"
    ]
    assert all(row["exact_archive_match"] for row in guard["table_checks"])


def test_screening_history_archive_manifest_path_escape_fails_closed(tmp_path: Path) -> None:
    from database import ScreeningDecision, ScreeningRun, get_db_manager, init_database
    from utils.screening_history_archive_execution import execute_screening_history_archive
    from utils.screening_history_archive_preview import build_screening_history_archive_preview_payload

    db_path = tmp_path / "screening-history-manifest-escape.db"
    archive_path = tmp_path / "backend/data/archives/screening_history_details_archive.db"
    manifest_path = archive_path.parent / "screening_history_archive_manifest.json"
    assert init_database(str(db_path), drop_existing=True) is True
    manager = get_db_manager(str(db_path))
    with manager.get_session(task_name="seed_screening_history_manifest_escape") as session:
        session.add(
            ScreeningRun(
                run_id="run-old",
                started_at=datetime.now() - timedelta(days=45),
                status="success",
                fund_type="bond",
                period_years=5,
            )
        )
        session.add(
            ScreeningDecision(run_id="run-old", fcode="000001", step_id=1, passed=True)
        )
    manifest_path.parent.mkdir(parents=True, exist_ok=True)
    manifest_path.write_text(
        json.dumps(
            {
                "schema_version": 1,
                "generation": 1,
                "active_shard": {
                    "id": "active",
                    "path": archive_path.name,
                    "format": "sqlite",
                    "state": "writable",
                },
                "immutable_shards": [
                    {
                        "id": "escaped",
                        "path": "../outside.db",
                        "format": "sqlite",
                        "state": "immutable",
                    }
                ],
            },
            ensure_ascii=False,
        ),
        encoding="utf-8",
    )
    preview = build_screening_history_archive_preview_payload(
        db_path=db_path,
        preview_payload={
            "db_path": str(db_path),
            "summary": {"candidate_run_count": 1},
            "execution_plan": {"scope_run_ids": ["run-old"]},
        },
        preflight_payload={"checks": {"ready_for_manual_signoff": True}},
        archive_target_path=archive_path,
        project_root=tmp_path,
        output_dir=tmp_path / "audit",
    )
    assert preview["status"] == "failed"
    assert preview["summary"]["archive_manifest_status"] == "invalid"
    _json_path, _md_path, execution = execute_screening_history_archive(
        db_path=db_path,
        preview_payload=preview,
        output_dir=tmp_path / "audit",
        mode="archive-export",
        archive_target_path=archive_path,
        project_root=tmp_path,
        timestamp="manifest_escape",
    )
    assert execution["status"] == "failed"
    assert "archive_manifest_invalid" in execution["summary"]["error"]
    assert not archive_path.exists()


def test_screening_history_archive_failed_post_write_check_does_not_advance_manifest(
    tmp_path: Path,
    monkeypatch,
) -> None:
    from database import ScreeningDecision, ScreeningRun, get_db_manager, init_database
    from utils import screening_history_archive_execution as archive_execution_module
    from utils.screening_history_archive_manifest import (
        ensure_screening_archive_manifest,
        load_screening_archive_manifest,
    )
    from utils.screening_history_archive_preview import build_screening_history_archive_preview_payload

    db_path = tmp_path / "screening-history-post-write-check.db"
    archive_path = tmp_path / "backend/data/archives/screening_history_details_archive.db"
    assert init_database(str(db_path), drop_existing=True) is True
    manager = get_db_manager(str(db_path))
    with manager.get_session(task_name="seed_screening_history_post_write_check") as session:
        session.add(
            ScreeningRun(
                run_id="run-old",
                started_at=datetime.now() - timedelta(days=45),
                status="success",
                fund_type="bond",
                period_years=5,
            )
        )
        session.add(
            ScreeningDecision(run_id="run-old", fcode="000001", step_id=1, passed=True)
        )

    manifest_path, initial_manifest, created = ensure_screening_archive_manifest(
        archive_path,
        project_root=tmp_path,
    )
    assert created is True
    initial_generation = initial_manifest["generation"]
    preview = build_screening_history_archive_preview_payload(
        db_path=db_path,
        preview_payload={
            "db_path": str(db_path),
            "summary": {"candidate_run_count": 1},
            "execution_plan": {"scope_run_ids": ["run-old"]},
        },
        preflight_payload={"checks": {"ready_for_manual_signoff": True}},
        archive_target_path=archive_path,
        project_root=tmp_path,
        output_dir=tmp_path / "audit",
    )
    monkeypatch.setattr(
        archive_execution_module,
        "_sqlite_quick_check",
        lambda _path: "error:simulated_corruption",
    )

    _json_path, _md_path, execution = (
        archive_execution_module.execute_screening_history_archive(
            db_path=db_path,
            preview_payload=preview,
            output_dir=tmp_path / "audit",
            mode="archive-export",
            archive_target_path=archive_path,
            project_root=tmp_path,
            timestamp="post_write_check_failure",
        )
    )

    assert execution["status"] == "failed"
    assert execution["summary"]["archive_db_quick_check"] == "error:simulated_corruption"
    assert execution["summary"]["error"] == (
        "archive_db_quick_check=error:simulated_corruption"
    )
    assert archive_path.exists()
    manifest_state = load_screening_archive_manifest(
        archive_path,
        manifest_path=manifest_path,
        project_root=tmp_path,
    )
    assert manifest_state["status"] == "ready"
    assert manifest_state["generation"] == initial_generation
    assert "quick_check" not in manifest_state["payload"]["active_shard"]


def test_screening_decision_summaries_refresh_groups_reasons(tmp_path: Path) -> None:
    from sqlalchemy import text

    from database import ScreeningDecision, ScreeningPick, ScreeningRun, get_db_manager, init_database
    from database.models import ScreeningDecisionReasonSummary, ScreeningRunLatestActivity
    from database.screening_decision_summaries import refresh_screening_decision_summaries

    db_path = tmp_path / "screening-decision-summaries.db"
    assert init_database(str(db_path), drop_existing=True) is True
    manager = get_db_manager(str(db_path))

    started_at = datetime(2026, 1, 1, 8, 30, 0)
    first_decision_at = datetime(2026, 1, 1, 9, 0, 0)
    second_decision_at = first_decision_at + timedelta(minutes=1)
    third_decision_at = first_decision_at + timedelta(minutes=2)
    first_pick_at = first_decision_at + timedelta(minutes=5)
    latest_pick_at = first_decision_at + timedelta(minutes=6)

    with manager.get_session(task_name="seed_screening_decision_summary_test") as session:
        session.add_all([
            ScreeningRun(
                run_id="run-summary",
                started_at=started_at,
                finished_at=started_at + timedelta(minutes=30),
                status="success",
                fund_type="bond",
                period_years=3,
            ),
            ScreeningRun(
                run_id="run-empty",
                started_at=started_at + timedelta(minutes=40),
                finished_at=started_at + timedelta(minutes=45),
                status="success",
                fund_type="bond",
                period_years=5,
            ),
        ])
        session.add_all([
            ScreeningDecision(
                run_id="run-summary",
                fcode="000001",
                step_id=1,
                step_name="基础资格",
                passed=False,
                reason_code="NO_NAV_DATA",
                created_at=first_decision_at,
            ),
            ScreeningDecision(
                run_id="run-summary",
                fcode="000002",
                step_id=1,
                step_name="基础资格-兼容名",
                passed=False,
                reason_code="NO_NAV_DATA",
                created_at=second_decision_at,
            ),
            ScreeningDecision(
                run_id="run-summary",
                fcode="000003",
                step_id=1,
                step_name="基础资格",
                passed=True,
                reason_code="PASSED",
                created_at=third_decision_at,
            ),
            ScreeningDecision(
                run_id="run-summary",
                fcode="000004",
                step_id=2,
                step_name="持有期",
                passed=False,
                reason_code=None,
                created_at=first_decision_at + timedelta(minutes=3),
            ),
        ])
        session.add_all([
            ScreeningPick(
                run_id="run-summary",
                fcode="000003",
                rank=1,
                fund_type="bond",
                period_years=3,
                picked_at=first_pick_at,
            ),
            ScreeningPick(
                run_id="run-summary",
                fcode="000005",
                rank=2,
                fund_type="bond",
                period_years=3,
                picked_at=latest_pick_at,
            ),
        ])
        session.flush()
        session.execute(
            text("UPDATE screening_decisions SET created_at = NULL WHERE run_id = :run_id AND fcode = :fcode"),
            {"run_id": "run-summary", "fcode": "000004"},
        )

    result = refresh_screening_decision_summaries(
        db_manager=manager,
        run_ids=["run-summary", "run-empty"],
        stats_source="test_summary",
        chunk_size=1,
    )

    assert result["status"] == "success"
    assert result["run_count"] == 2
    assert result["reason_inserted_count"] == 3
    assert result["latest_activity_inserted_count"] == 2

    with manager.get_session(task_name="assert_screening_decision_summary_test", readonly=True) as session:
        reason_rows = {
            (row.step_id, bool(row.passed), row.reason_code): row
            for row in session.query(ScreeningDecisionReasonSummary)
            .filter_by(run_id="run-summary")
            .all()
        }

        no_nav_row = reason_rows[(1, False, "NO_NAV_DATA")]
        assert no_nav_row.decision_count == 2
        assert no_nav_row.first_decision_at == first_decision_at
        assert no_nav_row.latest_decision_at == second_decision_at
        assert no_nav_row.stats_source == "test_summary"

        passed_row = reason_rows[(1, True, "PASSED")]
        assert passed_row.decision_count == 1
        assert passed_row.latest_decision_at == third_decision_at

        historical_missing_time_row = reason_rows[(2, False, "")]
        assert historical_missing_time_row.decision_count == 1
        assert historical_missing_time_row.first_decision_at is None
        assert historical_missing_time_row.latest_decision_at is None

        latest_row = session.query(ScreeningRunLatestActivity).filter_by(run_id="run-summary").one()
        assert latest_row.decision_count == 4
        assert latest_row.pick_count == 2
        assert latest_row.first_decision_at == first_decision_at
        assert latest_row.latest_decision_at == third_decision_at
        assert latest_row.first_pick_at == first_pick_at
        assert latest_row.latest_pick_at == latest_pick_at
        assert latest_row.latest_detail_at == latest_pick_at

        empty_row = session.query(ScreeningRunLatestActivity).filter_by(run_id="run-empty").one()
        assert empty_row.decision_count == 0
        assert empty_row.pick_count == 0
        assert empty_row.latest_detail_at is None


def test_screening_storage_growth_audit_prefers_latest_activity_summary(tmp_path: Path) -> None:
    from database import ScreeningDecision, ScreeningPick, ScreeningRun, get_db_manager, init_database
    from database.models import ScreeningRunLatestActivity
    from utils.screening_storage_growth_audit import fetch_recent_run_metrics_rows

    db_path = tmp_path / "screening-storage-growth-summary.db"
    assert init_database(str(db_path), drop_existing=True) is True
    manager = get_db_manager(str(db_path))

    anchor = datetime(2026, 1, 10, 12, 0, 0)
    with manager.get_session(task_name="seed_screening_storage_growth_summary_test") as session:
        session.add_all([
            ScreeningRun(
                run_id="run-summary",
                started_at=anchor - timedelta(days=1),
                status="success",
                fund_type="bond",
                period_years=1,
                fund_count_in=10,
                fund_count_pass=1,
                config_snapshot_json=json.dumps({"decision_persist_mode": "picked_only"}),
            ),
            ScreeningRun(
                run_id="run-fallback",
                started_at=anchor - timedelta(hours=1),
                status="success",
                fund_type="bond",
                period_years=1,
                fund_count_in=10,
                fund_count_pass=2,
                config_snapshot_json=json.dumps({"decision_persist_mode": "picked_only"}),
            ),
        ])
        session.add_all([
            ScreeningDecision(run_id="run-summary", fcode="000001", step_id=1, passed=True),
            ScreeningDecision(run_id="run-summary", fcode="000002", step_id=1, passed=False),
            ScreeningDecision(run_id="run-fallback", fcode="000003", step_id=1, passed=True),
            ScreeningPick(run_id="run-summary", fcode="000001", rank=1, fund_type="bond", period_years=1),
            ScreeningPick(run_id="run-fallback", fcode="000003", rank=1, fund_type="bond", period_years=1),
            ScreeningPick(run_id="run-fallback", fcode="000004", rank=2, fund_type="bond", period_years=1),
            ScreeningRunLatestActivity(
                run_id="run-summary",
                fund_type="bond",
                period_years=1,
                status="success",
                started_at=anchor - timedelta(days=1),
                decision_count=2,
                pick_count=1,
                stats_source="test_seed",
            ),
        ])

    conn = sqlite3.connect(str(db_path))
    conn.row_factory = sqlite3.Row
    try:
        rows = fetch_recent_run_metrics_rows(
            conn,
            days=7,
            fund_types=["bond"],
            now=anchor,
            prefer_materialized=True,
        )
    finally:
        conn.close()

    by_run_id = {row["run_id"]: row for row in rows}
    assert by_run_id["run-summary"]["decision_count"] == 2
    assert by_run_id["run-summary"]["pick_count"] == 1
    assert by_run_id["run-summary"]["count_source"] == "screening_run_latest_activity"
    assert by_run_id["run-fallback"]["decision_count"] == 1
    assert by_run_id["run-fallback"]["pick_count"] == 2
    assert by_run_id["run-fallback"]["count_source"] == "detail_scan_fallback"


def test_screening_storage_growth_audit_uses_storage_stats_before_detail_fallback(
    tmp_path: Path,
    monkeypatch,
) -> None:
    from database import ScreeningRun, get_db_manager, init_database
    from database.models import ScreeningRunLatestActivity, ScreeningRunStorageStats
    from utils import screening_storage_growth_audit as growth_audit

    db_path = tmp_path / "screening-storage-growth-storage-stats.db"
