    manager = get_db_manager(str(db_path))

    anchor = datetime(2026, 1, 10, 12, 0, 0)
    with manager.get_session(task_name="seed_screening_storage_growth_storage_stats_test") as session:
        session.add_all([
            ScreeningRun(
                run_id="run-latest-activity",
                started_at=anchor - timedelta(days=1),
                status="success",
                fund_type="bond",
                period_years=1,
                fund_count_in=10,
                fund_count_pass=1,
                config_snapshot_json=json.dumps({"decision_persist_mode": "picked_only"}),
            ),
            ScreeningRun(
                run_id="run-storage-stats",
                started_at=anchor - timedelta(hours=1),
                status="success",
                fund_type="bond",
                period_years=1,
                fund_count_in=10,
                fund_count_pass=2,
                config_snapshot_json=json.dumps({"decision_persist_mode": "picked_only"}),
            ),
        ])
        session.add_all([
            ScreeningRunLatestActivity(
                run_id="run-latest-activity",
                fund_type="bond",
                period_years=1,
                status="success",
                started_at=anchor - timedelta(days=1),
                decision_count=2,
                pick_count=1,
                stats_source="test_seed",
            ),
            ScreeningRunStorageStats(
                run_id="run-storage-stats",
                fund_type="bond",
                period_years=1,
                status="success",
                started_at=anchor - timedelta(hours=1),
                decision_count=11,
                pick_count=5,
                stats_source="test_seed",
            ),
        ])

    def fail_detail_scan(*args, **kwargs):
        raise AssertionError("detail scan fallback should not run when storage stats covers the run")

    monkeypatch.setattr(growth_audit, "fetch_count_by_run_ids", fail_detail_scan)
    conn = sqlite3.connect(str(db_path))
    conn.row_factory = sqlite3.Row
    try:
        rows = growth_audit.fetch_recent_run_metrics_rows(
            conn,
            days=7,
            fund_types=["bond"],
            now=anchor,
            prefer_materialized=True,
        )
    finally:
        conn.close()

    by_run_id = {row["run_id"]: row for row in rows}
    assert by_run_id["run-latest-activity"]["count_source"] == "screening_run_latest_activity"
    assert by_run_id["run-storage-stats"]["decision_count"] == 11
    assert by_run_id["run-storage-stats"]["pick_count"] == 5
    assert by_run_id["run-storage-stats"]["count_source"] == "screening_run_storage_stats"


