def test_api_settings_update_rejects_invalid_base_url(tmp_path: Path) -> None:
    import backend.app as backend_app

    project_config = tmp_path / "project.yaml"
    project_config.write_text(
        """
project:
  timezone: Asia/Shanghai
apis:
  tiantian_base_url: http://old.example:18087
scheduler:
  enabled: true
""".strip(),
        encoding="utf-8",
    )
    temp_settings = load_settings(project_config)
    original_settings = backend_app.settings
    original_manager_settings = backend_app.manager.settings
    try:
        backend_app.settings = temp_settings
        backend_app.manager.settings = temp_settings
        payload, status_code = backend_app._update_api_settings(
            {"tiantian_base_url": "ftp://old.example:18087"}
        )

        saved = yaml.safe_load(project_config.read_text(encoding="utf-8"))
        assert status_code == 400
        assert payload["status"] == "invalid_request"
        assert saved["apis"]["tiantian_base_url"] == "http://old.example:18087"
    finally:
        backend_app.settings = original_settings
        backend_app.manager.settings = original_manager_settings


def test_api_settings_probe_defaults_to_long_enough_tiantian_timeout() -> None:
    import backend.app as backend_app

    with patch.object(
        backend_app,
        "_probe_tiantian_base_url",
        return_value={
            "ok": True,
            "status": "ok",
            "http_status": 200,
            "payload_success": True,
            "datas_count": 1,
            "total_count": 7729,
        },
    ) as probe_mock:
        payload, status_code = backend_app._probe_api_settings(
            {"tiantian_base_url": "http://108.62.161.95:18087"}
        )

    assert status_code == 200
    assert payload["status"] == "ok"
    assert payload["truth_note"]
    semantics = payload["response_semantics"]
    assert semantics["probe_endpoint"] == "/fundMNRank"
    assert semantics["probe_params"] == {"FundType": "31", "pageIndex": 1, "pageSize": 1}
    assert semantics["writes_database"] is False
    assert semantics["writes_business_artifacts"] is False
    assert semantics["business_payload_required"] is True
    assert semantics["success_criteria"] == {
        "http_status_2xx": True,
        "payload_success_true": True,
        "datas_non_empty": True,
    }
    assert semantics["current_business_status"] == "ok"
    assert semantics["truth_policy"] == "read_only_business_probe_no_database_or_artifact_writes"
    assert probe_mock.call_args.kwargs["timeout_seconds"] == 10.0


