def test_api_settings_page_alias_and_frontend_assets_are_versioned() -> None:
    import backend.app as backend_app

    settings_src = (PROJECT_ROOT / "frontend" / "settings.html").read_text(encoding="utf-8")
    settings_js_src = (PROJECT_ROOT / "frontend" / "settings.js").read_text(encoding="utf-8")
    shared_src = (PROJECT_ROOT / "frontend" / "shared.js").read_text(encoding="utf-8")
    all_pages = list((PROJECT_ROOT / "frontend").glob("*.html"))
    asset_version = backend_app._build_api_settings_payload()["frontend"]["asset_version"]

    assert 'href="/api-settings" class="active" aria-current="page">接口设置</a>' in settings_src
    assert "runtime.tiantian_base_url || configured.tiantian_base_url" not in shared_src
    assert "runtime.tiantian_base_url || '-'" in shared_src
    assert 'id="saveAndProbeSettingsBtn"' in settings_src
    assert "buildStatCard('保存接口', currentSettingsPayload?.frontend?.save_endpoint || '/api/settings/apis'" in settings_js_src
    assert "buildStatCard('测试接口', currentSettingsPayload?.frontend?.probe_endpoint || '/api/settings/apis/probe'" in settings_js_src
    assert "frontend.editable_from_frontend ? '已启用' : '未启用'" in settings_js_src
    assert "semantics.success_criteria" in settings_js_src
    assert "<dt>请求</dt>" in settings_js_src
    assert "<dt>Total</dt>" in settings_js_src
    assert "<dt>业务状态</dt>" in settings_js_src
    assert "不写库/不写业务产物" in settings_js_src
    assert "api-probe-errors" in settings_js_src
    assert "api-probe-truth-note" in settings_js_src
    for page_path in all_pages:
        page_src = page_path.read_text(encoding="utf-8")
        if "styles.css" in page_src:
            assert f'href="/styles.css?v={asset_version}"' in page_src
        assert "v=1.9.487" not in page_src
        assert "116.62.209.12" not in page_src
        assert 'href="/settings"' not in page_src

    client = backend_app.app.test_client()
    response = client.get("/api-settings")
    assert response.status_code == 200
    assert f"settings.js?v={asset_version}".encode() in response.data
    assert b"116.62.209.12" not in response.data
    assert "no-store" in response.headers.get("Cache-Control", "")
    assert response.headers.get("Pragma") == "no-cache"
    assert response.headers.get("Expires") == "0"
    alias_response = client.get("/settings")
    assert alias_response.status_code == 200
    assert f"settings.js?v={asset_version}".encode() in alias_response.data
    assert b"116.62.209.12" not in alias_response.data
    assert "no-store" in alias_response.headers.get("Cache-Control", "")
    head_response = client.head("/api-settings")
    assert head_response.status_code == 200
    assert "no-store" in head_response.headers.get("Cache-Control", "")
    assert head_response.headers.get("Pragma") == "no-cache"
    assert head_response.headers.get("Expires") == "0"

    asset_response = client.get("/settings.js")
    assert asset_response.status_code == 200
    assert "no-store" in asset_response.headers.get("Cache-Control", "")
    assert asset_response.headers.get("Pragma") == "no-cache"
    assert asset_response.headers.get("Expires") == "0"
    asset_head_response = client.head("/settings.js")
    assert asset_head_response.status_code == 200
    assert "no-store" in asset_head_response.headers.get("Cache-Control", "")
    assert asset_head_response.headers.get("Pragma") == "no-cache"
    assert asset_head_response.headers.get("Expires") == "0"

    api_response = client.get("/api/settings/apis")
    assert api_response.status_code == 200
    api_payload = api_response.get_json()
    assert api_payload["frontend"]["editable_from_frontend"] is True
    assert api_payload["frontend"]["save_endpoint"] == "/api/settings/apis"
    assert api_payload["frontend"]["probe_endpoint"] == "/api/settings/apis/probe"
    assert api_payload["configured"]["tiantian_base_url"] == "http://tiantian-api:3000"
    assert "116.62.209.12" not in api_response.get_data(as_text=True)
    assert "no-store" in api_response.headers.get("Cache-Control", "")
    assert api_response.headers.get("Pragma") == "no-cache"
    assert api_response.headers.get("Expires") == "0"

    with patch.object(
        backend_app,
        "_probe_tiantian_base_url",
        return_value={"ok": True, "status": "ok", "http_status": 200, "datas_count": 1},
    ):
        probe_response = client.post(
            "/api/settings/apis/probe",
            json={"tiantian_base_url": "http://108.62.161.95:18087"},
        )
    assert "no-store" in probe_response.headers.get("Cache-Control", "")
    probe_payload = probe_response.get_json()
