def test_manager_collector_records_list_and_detail_api_source_evidence(tmp_path: Path) -> None:
    db_path = tmp_path / "manager-evidence.db"
    assert init_database(str(db_path), drop_existing=True) is True
    manager = get_db_manager(str(db_path))
    with manager.get_session() as session:
        session.add(Fund(fcode="000001", shortname="测试基金"))

    class _StubClient:
        def get(self, endpoint: str, params: dict[str, Any] | None = None):
            if endpoint == "/fundMNMangerList":
                assert params == {"FCODE": "000001"}
                return {
                    "Success": True,
                    "Datas": [{"MGRID": "M001", "MGRNAME": "张三", "LEMPDATE": "--"}],
                }
            raise AssertionError(f"unexpected endpoint: {endpoint}")

    collector = ManagerCollector(config={}, db_manager=manager, api_client=_StubClient())
    list_summary = collector._collect_fund_managers()
    list_evidence = collector.get_manager_list_api_source_evidence()

    assert list_summary == {
        "total_funds": 1,
        "success_funds": 1,
        "failed_funds": 0,
        "empty_funds": 0,
        "cooldown_funds": 0,
    }
    assert list_evidence["source"] == "fundMNMangerList"
    assert list_evidence["request_count"] == 1
    assert list_evidence["accepted_response_count"] == 1
    assert list_evidence["returned_record_count"] == 1
    assert list_evidence["saved_fund_count"] == 1

    attempts = {"count": 0}

    def _manager_info(mgr_id: str):
        attempts["count"] += 1
        if attempts["count"] == 1:
            return {"Success": True, "Datas": None}
        return {
            "Success": True,
            "Datas": {
                "MGRID": mgr_id,
                "MGRNAME": "张三",
                "TOTALDAYS": "365",
                "NETNAV": "100000000",
                "FCOUNT": "3",
            },
        }

    collector._ensure_manager_detail_api_source_evidence().reset(target_count=1, stage="test")
    collector.api.get_manager_info = _manager_info

    assert collector.collect_manager_detail("M001") is True
    detail_evidence = collector.get_manager_detail_api_source_evidence()

    assert detail_evidence["source"] == "fundMSNMangerInfo"
    assert detail_evidence["request_count"] == 2
    assert detail_evidence["response_count"] == 2
    assert detail_evidence["accepted_response_count"] == 1
    assert detail_evidence["failed_response_count"] == 1
    assert detail_evidence["saved_fund_count"] == 1
    assert detail_evidence["quality_status_counts"].get("invalid_datas_type") == 1
    assert detail_evidence["quality_status_counts"].get("ok") == 1

    with manager.get_session(readonly=True) as session:
        row = session.query(FundManager).filter_by(mgr_id="M001").one()
        assert row.name == "张三"
        assert row.total_days == 365


