def test_manager_collector_bounded_rotation_and_empty_attempt_timestamp(tmp_path: Path) -> None:
    db_path = tmp_path / "manager-rotation.db"
    assert init_database(str(db_path), drop_existing=True) is True
    manager = get_db_manager(str(db_path))
    now = datetime.now()
    with manager.get_session() as session:
        session.add_all(
            [
                Fund(
                    fcode="000001",
                    shortname="经理名单缺失已到重试期",
                    manager_list_updated_at=now - timedelta(days=8),
                ),
                Fund(
                    fcode="000002",
                    shortname="经理名单完整但已过期",
                    manager_ids="M002",
                    manager_names="李四",
                    manager_list_updated_at=now - timedelta(days=60),
                ),
                Fund(
                    fcode="000003",
                    shortname="经理名单缺失仍在冷却期",
                    manager_list_updated_at=now - timedelta(days=2),
                ),
            ]
        )

    requested_codes: list[str] = []

    class _StubClient:
        def get(self, endpoint: str, params: dict[str, Any] | None = None):
            assert endpoint == "/fundMNMangerList"
            requested_codes.append(str((params or {}).get("FCODE") or ""))
            return {"Success": True, "Datas": []}

    collector = ManagerCollector(
        config={
            "collection": {
                "manager": {
                    "fund_list_refresh_stale_days": 42,
                    "missing_list_retry_days": 7,
                    "max_fund_targets_per_run": 1,
                }
            }
        },
        db_manager=manager,
        api_client=_StubClient(),
    )
    summary = collector._collect_fund_managers(force_update=False)

    assert requested_codes == ["000001"]
    assert summary == {
        "total_funds": 1,
        "success_funds": 0,
        "failed_funds": 1,
        "empty_funds": 1,
        "cooldown_funds": 0,
    }
    with manager.get_session(readonly=True) as session:
        refreshed = session.query(Fund).filter_by(fcode="000001").one()
        assert refreshed.manager_ids is None
        assert refreshed.manager_list_updated_at is not None
        assert refreshed.manager_list_updated_at == now - timedelta(days=8)
        assert refreshed.manager_list_attempted_at > now
        assert refreshed.manager_list_last_status == "empty_response"


def test_manager_detail_bounded_rotation_prefers_oldest_stale_manager(tmp_path: Path) -> None:
    db_path = tmp_path / "manager-detail-rotation.db"
