            [
                Fund(fcode="000001", shortname="基金一", manager_ids="M001", manager_names="张三"),
                Fund(fcode="000002", shortname="基金二", manager_ids="M002", manager_names="李四"),
                Fund(fcode="000003", shortname="基金三", manager_ids="M003", manager_names="王五"),
                FundManager(mgr_id="M001", name="张三", last_updated_at=now - timedelta(days=90)),
                FundManager(mgr_id="M002", name="李四", last_updated_at=now - timedelta(days=70)),
                FundManager(mgr_id="M003", name="王五", last_updated_at=now - timedelta(days=2)),
            ]
