def test_supplement_long_term_history_force_update_marks_stale_no_progress_as_failed(
    tmp_path: Path,
    capsys: pytest.CaptureFixture[str],
) -> None:
    import scripts.supplement_bond_long_term_history as supplement_script

    codes_path = tmp_path / "codes.json"
    codes_path.write_text(json.dumps(["012169"], ensure_ascii=False), encoding="utf-8")

    selected_candidate = {
        "fcode": "012169",
        "stale_annual_returns": True,
        "latest_annual_year": 2024,
        "stale_rank_history": True,
        "latest_rank_date": "2025-08-12",
        "needs_annual_returns": False,
        "needs_rank_history": False,
    }
    post_refresh_candidate = {
        "fcode": "012169",
        "latest_annual_year": 2024,
        "latest_rank_date": "2025-08-12",
    }

    def _fake_run_stage_concurrent(**kwargs):
        code = kwargs["codes"][0]
        stage = kwargs["stage"]
        if stage == "annual_returns":
            return [code], []
        if stage == "rank_history":
            return [code], []
        raise AssertionError(stage)

    with (
        patch.object(
            sys,
            "argv",
            [
                "supplement_bond_long_term_history.py",
                "--codes-file",
                str(codes_path),
                "--force-update",
                "--workers",
                "1",
            ],
        ),
        patch.object(
            supplement_script,
            "load_settings",
            return_value=SimpleNamespace(
                database_path=tmp_path / "test.db",
                config_path=tmp_path / "project.yaml",
            ),
        ),
        patch.object(supplement_script, "load_runtime_config", return_value={}),
        patch.object(supplement_script, "get_db_manager", return_value=SimpleNamespace()),
        patch.object(supplement_script, "APIClient", return_value=SimpleNamespace()),
        patch.object(
            supplement_script,
            "AnnualReturnCollector",
            return_value=SimpleNamespace(collect_fund_annual_returns=lambda _code: True),
        ),
        patch.object(
            supplement_script,
            "RankCollector",
            return_value=SimpleNamespace(collect_fund_rank_history=lambda _code: True),
        ),
        patch.object(
            supplement_script,
            "_read_bond_universe",
            side_effect=[
                ([selected_candidate], [selected_candidate], {"screenable_candidate_total": 1}),
                ([post_refresh_candidate], [post_refresh_candidate], {"screenable_candidate_total": 1}),
            ],
        ),
        patch.object(
            supplement_script,
            "_distinct_history_counts",
            side_effect=[
                {"annual_history_fund_count": 1, "rank_history_fund_count": 1},
                {"annual_history_fund_count": 1, "rank_history_fund_count": 1},
            ],
        ),
        patch.object(supplement_script, "_run_stage_concurrent", side_effect=_fake_run_stage_concurrent),
    ):
        exit_code = supplement_script.main()

    assert exit_code == 0
    summary = json.loads(capsys.readouterr().out)
    assert summary["annual_success_count"] == 0
    assert summary["rank_success_count"] == 0
    assert summary["annual_no_progress_count"] == 1
    assert summary["rank_no_progress_count"] == 1
    assert summary["stale_refresh_no_progress_total"] == 2
    assert summary["annual_failed_count"] == 1
    assert summary["rank_failed_count"] == 1
    assert summary["failed_codes_total"] == 1
    assert {
        "fcode": "012169",
        "stage": "annual_returns",
        "error": "stale_annual_refresh_no_progress",
    } in summary["failed_items_sample"]
    assert {
        "fcode": "012169",
        "stage": "rank_history",
        "error": "stale_rank_refresh_no_progress",
    } in summary["failed_items_sample"]


