def test_nav_collector_incremental_reference_overrides_stale_local_peak() -> None:
    reference_date, context = NavCollector._resolve_incremental_reference_nav_date(
        [
            (datetime.fromisoformat("2026-06-18T00:00:00").date(), 7791),
            (datetime.fromisoformat("2026-06-22T00:00:00").date(), 2),
        ],
        now=datetime.fromisoformat("2026-06-23T21:00:00"),
    )

    assert reference_date == datetime.fromisoformat("2026-06-23T00:00:00").date()
    assert context["local_reference_nav_date"] == datetime.fromisoformat("2026-06-18T00:00:00").date()
    assert context["expected_reference_nav_date"] == datetime.fromisoformat("2026-06-23T00:00:00").date()
    assert context["reference_strategy"] == "expected_business_date_overrides_stale_local_peak"


