def test_nav_collector_incremental_records_api_source_evidence() -> None:
    collector = NavCollector.__new__(NavCollector)
    collector.page_size = 100
    collector._nav_api_source_evidence_lock = threading.Lock()
    collector._nav_api_source_evidence = NavCollector._new_nav_api_source_evidence()
    collector._updated_nav_codes_lock = threading.Lock()
    collector._updated_nav_codes = set()
    collector._recent_outcomes_lock = threading.Lock()
    collector._recent_outcomes = {}
    collector.api = SimpleNamespace(
        get_nav_history=lambda fcode, page_index, page_size: {
            "Success": True,
            "Datas": {
                "LSJZList": [
                    {"FSRQ": "2026-05-12", "DWJZ": "1.0020", "LJJZ": "1.1020", "JZZZL": "0.02"},
                    {"FSRQ": "2026-05-11", "DWJZ": "1.0010", "LJJZ": "1.1010", "JZZZL": "0.01"},
                ]
            },
        }
    )
    saved_records: list[tuple[str, list[dict]]] = []

    def _fake_save_nav_records(fcode: str, records: list[dict]) -> int:
        saved_records.append((fcode, list(records)))
        return len(records)

    collector._save_nav_records = _fake_save_nav_records
    collector._reset_nav_api_source_evidence(collection_mode="incremental")

    inserted = NavCollector._collect_incremental_nav_v2(
        collector,
        "000001",
        datetime.fromisoformat("2026-05-10T00:00:00").date(),
        reference_nav_date=datetime.fromisoformat("2026-05-12T00:00:00").date(),
    )

    evidence = collector.get_nav_api_source_evidence(inserted_nav_record_count=inserted)

    assert inserted == 2
    assert saved_records[0][0] == "000001"
    assert evidence["request_count"] == 1
    assert evidence["response_count"] == 1
    assert evidence["accepted_response_count"] == 1
    assert evidence["failed_response_count"] == 0
    assert evidence["returned_nav_record_count"] == 2
    assert evidence["inserted_nav_record_count"] == 2
    assert evidence["updated_fund_count"] == 1
    assert evidence["latest_payload_nav_date"] == "2026-05-12"


def test_nav_collector_save_nav_records_advances_fund_returns_latest_nav(tmp_path: Path) -> None:
    db_path = tmp_path / "nav_returns_sync.db"
    init_database(str(db_path))
    manager = get_db_manager(str(db_path))
    with manager.get_session() as session:
        session.add(Fund(fcode="000001", shortname="测试债基"))
        session.add(
            FundReturns(
                fcode="000001",
                latest_nav=1.0,
                latest_nav_date=datetime.fromisoformat("2026-06-18T00:00:00").date(),
                daily_growth=0.0,
            )
        )

    collector = NavCollector(config={}, db_manager=manager, api_client=SimpleNamespace())
    saved = collector._save_nav_records(
        "000001",
        [
            {"FSRQ": "2026-06-22", "DWJZ": "1.0020", "LJJZ": "1.1020", "JZZZL": "0.10"},
            {"FSRQ": "2026-06-23", "DWJZ": "1.0030", "LJJZ": "1.1030", "JZZZL": "0.20"},
        ],
    )

    with manager.get_session(readonly=True) as session:
        returns = session.query(FundReturns).filter(FundReturns.fcode == "000001").one()
        nav_count = session.query(FundNavHistory).filter(FundNavHistory.fcode == "000001").count()

    assert saved == 2
    assert nav_count == 2
    assert str(returns.latest_nav_date) == "2026-06-23"
    assert returns.latest_nav == pytest.approx(1.0030)
    assert returns.daily_growth == pytest.approx(0.20)


def test_should_use_incremental_nav_only_requires_any_nav_history_row(tmp_path: Path) -> None:
    from backend.core_runner import should_use_incremental_nav

    db_path = tmp_path / "incremental-nav.db"
    conn = sqlite3.connect(db_path)
    try:
        conn.execute("CREATE TABLE fund_nav_history (id INTEGER PRIMARY KEY, fcode TEXT, nav_date TEXT)")
        conn.commit()

        settings = SimpleNamespace(database_path=db_path)
        assert should_use_incremental_nav(settings) is False

        conn.execute(
            "INSERT INTO fund_nav_history (fcode, nav_date) VALUES (?, ?)",
            ("000001", "2026-05-12"),
        )
        conn.commit()
    finally:
        conn.close()

    assert should_use_incremental_nav(settings) is True


def test_autostock_display_mapping_handles_not_checked_consistently() -> None:
    assert _format_autostock_display_status("strict_match") == "通过"
    assert _format_autostock_display_status("soft_pass_with_warnings") == "通过（含软告警）"
    assert _format_autostock_display_status("hard_block") == "拦截"
    assert _format_autostock_display_status("not_checked") == "未校验"
    assert _format_autostock_display_status("unknown") == "未校验"
    assert _format_autostock_display_status("") == "未校验"
    assert _format_autostock_note_flag("strict_match") == "严格校验通过"
    assert _format_autostock_note_flag("soft_pass_with_warnings") == "存在校验告警"
    assert _format_autostock_note_flag("hard_block") == "校验拦截"
    assert _format_autostock_note_flag("not_checked") == ""
    assert _format_autostock_note_flag("unknown") == ""


def test_official_autostock_status_supplement_fills_missing_rows(tmp_path: Path) -> None:
    df = pd.DataFrame(
        [
            {
                "基金代码": "000001",
                "基金名称": "测试债基A",
                "基金类型": "债券型-长债",
                "最新净值日期": "2026-04-08",
                "最新单位净值": 1.234,
                "近1周(%)": 0.12,
                "近1月(%)": 0.35,
                "近3月(%)": 0.88,
                "近6月(%)": 1.56,
                "近1年(%)": 3.21,
                "是否可申购": "可申购",
                "债基风格标签": "利率债",
                "费率合计(%)": "0.40",
                "推荐备注": "",
                "AutoStock原始校验状态": "not_checked",
                "AutoStock告警原因": "",
                "AutoStock校验状态": "未校验",
                "AutoStock校验备注": "",
            },
            {
                "基金代码": "000002",
                "基金名称": "测试债基B",
                "基金类型": "债券型-中短债",
                "最新净值日期": "2026-04-08",
                "最新单位净值": 1.111,
                "近1周(%)": 0.10,
                "近1月(%)": 0.20,
                "近3月(%)": 0.60,
                "近6月(%)": 1.20,
                "近1年(%)": 2.50,
                "是否可申购": "可申购",
                "债基风格标签": "中短债",
                "费率合计(%)": "0.25",
                "推荐备注": "",
                "AutoStock原始校验状态": "unknown",
                "AutoStock告警原因": "",
                "AutoStock校验状态": "未校验",
                "AutoStock校验备注": "",
            },
        ]
    )

    class FakeClient:
        def __init__(self, **kwargs):
            self.kwargs = kwargs

        def get_fund_batch(self, codes, batch_size=50):
            assert codes == ["000001", "000002"]
            assert batch_size == 50
            return [
                {"code": "000001", "name": "测试债基A"},
                {"code": "000002", "name": "测试债基B"},
            ]

    def fake_build_status_map(validation_rows, *, failed_codes=None, normalize_fcode=None, warning_text_builder=None):
        return {
            "000001": {
                "autostock_validation_status": "strict_match",
                "autostock_warning_display": "",
            },
            "000002": {
                "autostock_validation_status": "strict_match",
                "autostock_warning_display": "",
            },
        }

    def fake_compare_candidate(local_row, autostock_row, config):
        return {
            "passed": True,
            "hard_reasons": [],
            "warning_reasons": [],
            "details": {
                "基金代码": autostock_row["code"],
                "基金名称": autostock_row["name"],
                "失败原因": "",
                "告警原因": "",
            },
        }

    # Exercise the supplement path with the current input schema. Unknown
    # provenance stays missing; no date or source is inferred from NAV.
    df = df.assign(**dict.fromkeys(("区间收益基准日", "区间收益来源", "区间收益来源SHA256")))
    fake_settings = SimpleNamespace(
        project_root=tmp_path,
        reports_dir=tmp_path / "reports",
        autostock_base_url="https://api.autostock.cn/v1",
        # P0-04.2: 新增的 AutoStock 速率 / 批量 settings 字段，mock 对齐真实配置默认值。
        autostock_rate_limit_min_interval_seconds=2.0,
        autostock_rate_limit_max_calls_per_hour=100,
        autostock_rate_limit_shared_state_path=tmp_path / "autostock_state.json",
        autostock_batch_fund_default=50,
    )

    with patch(
        "backend.report_builder._load_autostock_runtime_for_report",
        return_value=(FakeClient, fake_build_status_map, fake_compare_candidate),
    ):
        enriched = _supplement_official_autostock_statuses(df, settings=fake_settings)

    assert enriched.loc[0, "AutoStock原始校验状态"] == "strict_match"
    assert enriched.loc[0, "AutoStock校验状态"] == "通过"
    assert enriched.loc[0, "AutoStock校验备注"] == ""
    assert "严格校验通过" in enriched.loc[0, "推荐备注"]
    assert enriched.loc[1, "AutoStock原始校验状态"] == "strict_match"
    assert enriched.loc[1, "AutoStock校验状态"] == "通过"
    assert enriched.loc[1, "AutoStock校验备注"] == ""
    assert "严格校验通过" in enriched.loc[1, "推荐备注"]


