def test_nav_history_maintenance_handles_nav_value_mismatch_with_forced_refresh(tmp_path: Path) -> None:
    db_path = _create_nav_maintenance_db(tmp_path / "nav_maintenance_value_mismatch.db")
    state_file = tmp_path / "scheduler_state.json"
