    conn = sqlite3.connect(db_path)
    try:
        row = conn.execute(
            "SELECT latest_nav_date, latest_nav FROM fund_returns WHERE fcode = '000012'"
        ).fetchone()
    finally:
        conn.close()

    assert row == ("2026-04-13", 1.81)


