def test_run_autostock_nav_tail_fill_skips_fallback_when_quota_exhausted(tmp_path: Path) -> None:
    db_path = _create_autostock_tail_fill_db(tmp_path / "autostock_tail_fill_quota.db")
    settings = SimpleNamespace(
        project_root=PROJECT_ROOT,
        database_path=db_path,
        reports_dir=tmp_path / "reports",
        autostock_base_url="https://api.autostock.cn/v1",
        autostock_rate_limit_max_calls_per_hour=100,
    )

    class DummyClient:
        def __init__(self):
            self.batch_calls: list[tuple[tuple[str, ...], int]] = []

        def get_fund_batch_with_meta(self, codes, batch_size=50):
            self.batch_calls.append((tuple(codes), batch_size))
            return [], {
                "requested_unique_total": len(codes),
                "returned_unique_total": 0,
                "missing_count": len(codes),
                "quota_exhausted": True,
            }

    dummy_client = DummyClient()
    with patch("backend.autostock_nav_tail_fill._build_autostock_client", return_value=(dummy_client, 50)):
        result = run_autostock_nav_tail_fill(settings)

    assert result["maintenance_result"]["returned_total"] == 0
    assert result["maintenance_result"]["missing_response_total"] == 3
    assert result["maintenance_result"]["quota_exhausted"] is True
    assert result["maintenance_result"]["fallback_recovered_total"] == 0
    assert result["fallback_recovery"]["attempted"] is False
    assert result["fallback_recovery"]["initial_missing_count"] == 3
    assert result["fallback_recovery"]["remaining_missing_count"] == 3
    assert result["fallback_recovery"]["stages"][0]["skipped"] is True
    assert result["fallback_recovery"]["stages"][0]["skip_reason"] == "initial_batch_quota_exhausted"
    assert dummy_client.batch_calls == [(("026750", "026751", "960027"), 50)]


def test_run_autostock_nav_tail_fill_opens_empty_circuit_before_single_code_fallback(
    tmp_path: Path,
) -> None:
    db_path = _create_autostock_tail_fill_db(tmp_path / "autostock_tail_fill_probe_limit.db")
    conn = sqlite3.connect(db_path)
    try:
        for idx in range(4, 17):
            code = f"99{idx:04d}"
            conn.execute("INSERT INTO funds VALUES (?, ?, ?, ?)", (code, f"扩展债基{idx}", "债券型-长债", "31"))
            conn.execute("INSERT INTO fund_returns VALUES (?, ?, ?, ?, ?)", (code, None, None, None, None))
        conn.commit()
    finally:
        conn.close()

    settings = SimpleNamespace(
        project_root=PROJECT_ROOT,
        database_path=db_path,
        reports_dir=tmp_path / "reports",
        autostock_base_url="https://api.autostock.cn/v1",
        autostock_rate_limit_max_calls_per_hour=100,
    )

    class DummyClient:
        def __init__(self):
            self.batch_calls: list[tuple[tuple[str, ...], int]] = []
            self.detail_calls: list[tuple[tuple[str, ...], int]] = []

        def get_fund_batch_with_meta(self, codes, batch_size=50):
            normalized = tuple(codes)
            self.batch_calls.append((normalized, batch_size))
            return [], {
                "requested_unique_total": len(codes),
                "returned_unique_total": 0,
                "missing_count": len(codes),
                "quota_exhausted": False,
            }

        def get_fund_detail_batch(self, codes, batch_size=50, start_date=None, end_date=None):
            self.detail_calls.append((tuple(codes), batch_size))
            return []

        def get_last_fund_detail_batch_meta(self):
            return {
                "requested_unique_total": 16,
                "returned_unique_total": 0,
                "missing_count": 16,
                "quota_exhausted": False,
            }

    dummy_client = DummyClient()
    with patch("backend.autostock_nav_tail_fill._build_autostock_client", return_value=(dummy_client, 50)):
        result = run_autostock_nav_tail_fill(settings)

    single_stage = result["fallback_recovery"]["stages"][-1]
    assert single_stage["stage"] == "single_code_retry"
    assert single_stage["skipped"] is True
    assert single_stage["skip_reason"] == "upstream_empty_circuit_open"
    assert single_stage["upstream_empty_circuit_open"] is True
    assert single_stage["single_retry_limit"] == 0
    assert single_stage["requested_total"] == 0
    assert single_stage["skipped_unprobed_count"] == 16
    assert result["fallback_recovery"]["upstream_empty_circuit_open"] is True
    assert result["fallback_recovery"]["empty_circuit_skipped_single_retry_count"] == 16
    assert result["maintenance_result"]["upstream_empty_circuit_open"] is True
    assert result["maintenance_result"]["empty_circuit_skipped_single_retry_count"] == 16
    assert len(dummy_client.batch_calls) == 2


