def test_final_selection_governance_queue_loader_prefers_current_report_run(tmp_path: Path) -> None:
    from backend.final_selection_governance_queue import (
        load_final_selection_governance_action_codes,
        load_final_selection_governance_queue,
    )

    reports_dir = tmp_path / "reports"
    audit_dir = reports_dir / "audit" / "final_selection_contraction_shadow"
    audit_dir.mkdir(parents=True)
    latest_report_file = reports_dir / "latest.json"
    latest_report_file.write_text(json.dumps({"run_id": "current_run"}), encoding="utf-8")

    def _write_queue_artifact(path: Path, run_id: str, code: str) -> None:
        payload = {
            "run_id": run_id,
            "source_report_run_id": run_id,
            "generated_at": "2026-05-23T22:30:00",
            "final_selection_contraction_shadow": {
                "incremental_candidate_safety_review": {
                    "governance_summary": {
                        "automation_queue": {
                            "available": True,
                            "queue_total": 1,
                            "candidate_code_total": 1,
                            "queue_rows": [
                                {
                                    "action_key": "resolve_autostock_unknown",
                                    "fund_code": code,
                                }
                            ],
                        }
                    }
                }
            },
        }
        path.write_text(json.dumps(payload), encoding="utf-8")

    current_artifact = audit_dir / "final_selection_contraction_shadow_current.json"
    stale_artifact = audit_dir / "final_selection_contraction_shadow_stale.json"
    _write_queue_artifact(current_artifact, "current_run", "000001")
    _write_queue_artifact(stale_artifact, "stale_run", "999999")
    os.utime(stale_artifact, (stale_artifact.stat().st_atime + 10, stale_artifact.stat().st_mtime + 10))

    settings = SimpleNamespace(
        project_root=tmp_path,
        reports_dir=reports_dir,
        latest_report_file=latest_report_file,
    )

    queue = load_final_selection_governance_queue(settings)
    codes = load_final_selection_governance_action_codes(settings, "resolve_autostock_unknown")

    assert queue["available"] is True
    assert queue["reason"] == "ok"
    assert queue["run_id"] == "current_run"
    assert queue["target_report_run_id"] == "current_run"
    assert queue["target_report_run_source"] == "latest_report_file"
    assert queue["current_report_run_id"] == "current_run"
    assert queue["artifact_path"] == str(current_artifact)
    assert codes == {"000001"}


