            ('026750','测试债基B','missing_latest_nav_date',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,'missing_response','same_day','autostock_fund_batch','run_today','2026-04-21T09:00:00','2026-04-21T09:00:00'),
            ('026751','测试债基C','missing_latest_nav_date',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,'missing_response','same_day','autostock_fund_batch','run_today','2026-04-21T09:00:00','2026-04-21T09:00:00')
