def test_nav_history_maintenance_skips_truncated_history_tail_in_cooldown(tmp_path: Path) -> None:
    db_path = _create_nav_maintenance_db(tmp_path / "nav_maintenance_tail_skip.db")
    reports_dir = tmp_path / "reports"
    scheduler_state_file = tmp_path / "scheduler_state.json"
    maintenance_state_file = scheduler_state_file.with_name("nav_history_maintenance_state.json")
    maintenance_state_file.write_text(
        json.dumps(
            {
                "next_index": 0,
                "updated_at": "2026-04-11T09:00:00",
                "truncated_history_cooldown": {
                    "000001": {
                        "consecutive_no_progress_runs": 3,
                        "skip_runs_remaining": 2,
                        "last_attempted_at": "2026-04-10T09:00:00",
                        "last_before_first_nav_date": "2020-02-01",
                        "last_after_first_nav_date": "2020-02-01",
                        "last_gap_days": 1857,
                        "last_inserted_records": 0,
                        "status": "suspected_upstream_limited_tail",
                    }
                },
            },
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    attempted_codes: list[str] = []

    def _fake_collect(code: str, *args, **kwargs) -> int:
        attempted_codes.append(code)
        return 0

    settings = SimpleNamespace(
        project_root=PROJECT_ROOT,
        database_path=db_path,
        scheduler_state_file=scheduler_state_file,
        reports_dir=reports_dir,
        tiantian_base_url="http://example.invalid",
        effective_nav_coverage_ratio=0.9,
        effective_nav_weekday_only=True,
    )
    fake_ctx = SimpleNamespace(
        settings=settings,
        nav_collector=SimpleNamespace(collect_fund_history=_fake_collect),
    )

    with patch("backend.nav_history_maintenance._build_context", return_value=fake_ctx):
        summary = run_nav_history_maintenance(
            settings,
            limit=2,
            allowed_issue_types=["missing_nav", "truncated_history"],
        )

    assert summary["selection"]["truncated_history_cooldown_enabled"] is True
    assert summary["selection"]["truncated_history_cooldown_skipped_total"] == 1
    assert summary["selection"]["truncated_history_cooldown_skipped_samples"][0]["fcode"] == "000001"
    assert summary["selection"]["effective_scope_candidate_total"] == 1
    assert summary["maintenance_result"]["processed_total"] == 1
    assert attempted_codes == ["000002"]

    state_payload = json.loads(maintenance_state_file.read_text(encoding="utf-8"))
    assert state_payload["truncated_history_cooldown"]["000001"]["skip_runs_remaining"] == 1


def test_nav_history_maintenance_marks_no_progress_truncated_history_as_tail(tmp_path: Path) -> None:
    db_path = _create_nav_maintenance_db(tmp_path / "nav_maintenance_tail_mark.db")
