def test_long_term_feature_frame_requires_current_complete_annual_window(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    _freeze_datetime_in(monkeypatch, "backend.report_builder")

    db_path = tmp_path / "long_term_feature_current_window.db"
    conn = sqlite3.connect(db_path)
    try:
        conn.execute(
            """
            CREATE TABLE fund_annual_returns (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                fcode TEXT,
                year INTEGER,
                annual_return REAL,
                percentile REAL
            )
            """
        )
        conn.execute(
            """
            CREATE TABLE fund_rank_history (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                fcode TEXT,
                rank_date TEXT,
                period TEXT,
                percentile REAL
            )
            """
        )
        for year, annual_return in (
            (2020, 1.0),
            (2022, 1.1),
            (2023, 1.2),
            (2024, 1.3),
            (2025, 1.4),
        ):
            conn.execute(
                "INSERT INTO fund_annual_returns (fcode, year, annual_return, percentile) VALUES ('000001', ?, ?, 0.25)",
                (year, annual_return),
            )
        for year, annual_return in (
            (2021, 1.0),
            (2022, 1.1),
            (2023, 1.2),
            (2024, 1.3),
            (2025, 1.4),
        ):
            conn.execute(
                "INSERT INTO fund_annual_returns (fcode, year, annual_return, percentile) VALUES ('000002', ?, ?, 0.25)",
                (year, annual_return),
            )
        conn.commit()
    finally:
        conn.close()

    feature_df, summary = _build_long_term_feature_frame(db_path)

    by_code = {row["fcode"]: row for row in feature_df.to_dict(orient="records")}
    assert summary["annual_feature_ready_fund_count"] == 1
    assert by_code["000001"]["long_term_annual_feature_ready"] is False
    assert by_code["000002"]["long_term_annual_feature_ready"] is True


def test_long_term_feature_frame_uses_split_rank_archive_fallback_without_union(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import backend.report_builder as report_builder

    _freeze_datetime_in(monkeypatch, "backend.report_builder", frozen=datetime(2026, 4, 12, 12, 0, 0))
    db_path = tmp_path / "long_term_feature_rank_archive.db"
    archive_db = tmp_path / "fund_rank_history_before_2026-04-01.db"
    conn = sqlite3.connect(db_path)
    archive_conn = sqlite3.connect(archive_db)
    try:
        conn.execute(
            """
            CREATE TABLE fund_annual_returns (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                fcode TEXT,
                year INTEGER,
                annual_return REAL,
                percentile REAL
            )
            """
        )
        conn.execute(
            """
            CREATE TABLE fund_rank_history (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                fcode TEXT,
                rank_date TEXT,
                period TEXT,
                percentile REAL
            )
            """
        )
        for code in ("000100", "000200"):
            for year in (2021, 2022, 2023, 2024, 2025):
                conn.execute(
                    """
                    INSERT INTO fund_annual_returns (fcode, year, annual_return, percentile)
                    VALUES (?, ?, 2.0, 0.25)
                    """,
                    (code, year),
                )
        for day in range(1, 25):
            conn.execute(
                "INSERT INTO fund_rank_history (fcode, rank_date, period, percentile) VALUES ('000100', ?, 'overall', 0.2)",
                (f"2026-03-{day:02d}",),
            )
        conn.commit()

        archive_conn.execute(
            """
            CREATE TABLE fund_rank_history_archive (
                fcode TEXT,
                rank_date TEXT,
                period TEXT,
                percentile REAL
            )
            """
        )
        for day in range(1, 25):
            archive_conn.execute(
                "INSERT INTO fund_rank_history_archive VALUES ('000200', ?, 'overall', 0.2)",
                (f"2026-03-{day:02d}",),
            )
        archive_conn.execute(
            "INSERT INTO fund_rank_history_archive VALUES ('000300', '2026-03-20', 'overall', 0.2)"
        )
        archive_conn.commit()
    finally:
        archive_conn.close()
        conn.close()

    monkeypatch.setattr(
        report_builder,
        "load_latest_rank_history_archive_binding",
        lambda: {
            "archive_path": str(archive_db),
            "archive_table_name": "fund_rank_history_archive",
            "archive_cutoff_date": "2026-04-01",
        },
    )

    def _fail_union_source(*_args: Any, **_kwargs: Any) -> str:
        raise AssertionError("long-term rank feature metrics should not materialize hot/cold UNION source")

    monkeypatch.setattr(report_builder, "build_rank_history_union_source_sql", _fail_union_source)
    report_builder._LONG_TERM_RANK_METRICS_CACHE.clear()

    feature_df, summary = _build_long_term_feature_frame(db_path)

    by_code = {row["fcode"]: row for row in feature_df.to_dict(orient="records")}
    assert summary["candidate_total"] == 3
    assert summary["rank_feature_ready_fund_count"] == 2
    assert summary["full_feature_ready_fund_count"] == 2
    assert by_code["000100"]["long_term_rank_feature_ready"] is True
    assert by_code["000200"]["long_term_rank_feature_ready"] is True
    assert by_code["000300"]["long_term_annual_feature_ready"] is False
    assert by_code["000300"]["long_term_rank_feature_ready"] is False


def test_long_term_rank_metrics_uses_cached_snapshot_latest_dates_without_full_hot_scan(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import backend.report_builder as report_builder

    db_path = tmp_path / "long_term_rank_metrics_fast.db"
    with sqlite3.connect(db_path) as conn:
        conn.execute(
            """
            CREATE TABLE fund_rank_history (
                fcode TEXT NOT NULL,
                rank_date TEXT NOT NULL,
                percentile REAL,
                PRIMARY KEY (fcode, rank_date)
            )
            """
        )
        conn.executemany(
            "INSERT INTO fund_rank_history(fcode, rank_date, percentile) VALUES (?, ?, ?)",
            [
                ("000001", "2025-05-31", 0.90),
                ("000001", "2025-06-06", 0.30),
                ("000001", "2026-05-01", 0.20),
                ("000001", "2026-06-05", 0.10),
                ("000002", "2025-06-05", 0.80),
                ("000002", "2025-06-07", 0.40),
                ("000002", "2026-06-05", 0.20),
            ],
        )
        conn.commit()

    monkeypatch.setattr(
        report_builder,
        "_load_cached_long_term_history_rank_snapshot_stats",
        lambda _db_path, _rank_archive_attach, *, cache_snapshot=None: {
            "hot_percentile_codes": {"000001", "000002"},
            "latest_date_map": {
                "000001": "2026-06-05",
                "000002": "2026-06-05",
            }
        },
    )

    def _fail_hot_code_scan(_conn: sqlite3.Connection) -> set[str]:
        raise AssertionError("cached snapshot hot_percentile_codes should avoid DISTINCT hot-code scan")

    monkeypatch.setattr(report_builder, "_read_hot_rank_percentile_codes", _fail_hot_code_scan)

    def _fail_old_hot_scan(_conn: sqlite3.Connection) -> pd.DataFrame:
        raise AssertionError("cached snapshot fast path should avoid old latest-rank CTE")

    monkeypatch.setattr(report_builder, "_read_long_term_rank_metrics_from_hot", _fail_old_hot_scan)
    original_read_sql_query = report_builder.pd.read_sql_query
    captured_rank_queries: list[tuple[str, Any]] = []

    def _record_rank_query(sql: str, *args: Any, **kwargs: Any) -> pd.DataFrame:
        captured_rank_queries.append((str(sql), kwargs.get("params")))
        return original_read_sql_query(sql, *args, **kwargs)

    monkeypatch.setattr(report_builder.pd, "read_sql_query", _record_rank_query)
    report_builder._LONG_TERM_RANK_METRICS_CACHE.clear()

    with sqlite3.connect(db_path) as conn:
        rank_metrics_df = _read_long_term_rank_metrics(conn, db_path, None)

    assert report_builder._LONG_TERM_RANK_METRICS_FAST_BATCH_SIZE >= 1000
    assert len(captured_rank_queries) == 1
    captured_sql, captured_params = captured_rank_queries[0]
    assert "WITH latest_rank" not in captured_sql
    assert "fund_rank_history.fcode IN" in captured_sql
    assert tuple(captured_params) == ("2026-06-05", "2026-06-05", "000001", "000002")

    by_code = {row["fcode"]: row for row in rank_metrics_df.to_dict(orient="records")}
    assert set(by_code) == {"000001", "000002"}
    assert by_code["000001"]["latest_rank_date"] == "2026-06-05"
    assert by_code["000001"]["rank_count_12m"] == 3
    assert by_code["000001"]["rank_top30_count_12m"] == 3
    assert by_code["000002"]["rank_count_12m"] == 3
    assert by_code["000002"]["rank_top30_count_12m"] == 1


