def test_coverage_layers_keep_table_bond_screenable_publishable_scopes_distinct() -> None:
    layers = _build_coverage_layers(
        universe_snapshot={
            "stored_universe_count": 100,
            "active_universe_count": 90,
            "stored_has_latest_nav_count": 88,
            "stored_has_1y_risk_metrics_count": 82,
            "stored_holding_period_blocked_count": 11,
            "has_latest_nav_count": 80,
            "has_1y_risk_metrics_count": 70,
            "holding_period_blocked_count": 9,
            "screenable_universe_count": 60,
        },
        long_term_history_snapshot={
            "annual_return_history_fund_count": 45,
            "rank_history_fund_count": 44,
            "full_feature_ready_fund_count": 30,
        },
        stage_b_candidate_pool_count=25,
    )

    assert layers["table_coverage"]["base_fund_count"] == 100
    assert layers["table_coverage"]["has_latest_nav_ratio"] == 0.88
    assert layers["bond_universe_coverage"]["base_fund_count"] == 90
    assert layers["bond_universe_coverage"]["screenable_universe_count"] == 60
    assert layers["bond_universe_coverage"]["screenable_universe_ratio"] == 0.6667
    assert layers["screenable_universe_coverage"]["base_fund_count"] == 60
