@pytest.mark.parametrize("with_nav_table", [False, True])
@pytest.mark.parametrize("include_stale_candidates", [False, True])
def test_long_term_universe_reuses_nav_year_groups(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    with_nav_table: bool,
    include_stale_candidates: bool,
) -> None:
    _freeze_datetime_in(monkeypatch, "backend.long_term_history_maintenance")
    db_path = _create_long_term_maintenance_priority_db(tmp_path / "nav_year_groups.db")
    if with_nav_table:
        with sqlite3.connect(db_path) as conn:
            conn.execute("CREATE TABLE fund_nav_history (fcode TEXT, nav_date TEXT)")
            # Deliberately isolated boundary/NULL fixtures, not observed NAVs.
            conn.executemany(
                "INSERT INTO fund_nav_history VALUES (?, ?)",
                [
                    ("000001", "2020-12-31"),
                    ("000001", "2021-01-01"),
                    ("000001", "2021-01-04"),
                    ("000001", "2025-12-31"),
                    ("000001", "2026-01-01"),
                    ("000002", None),
                    ("000002", ""),
                ],
            )
    statements: list[str] = []
    connect = sqlite3.connect

    def traced_connect(*args, **kwargs):
        conn = connect(*args, **kwargs)
        conn.set_trace_callback(statements.append)
        return conn

    monkeypatch.setattr(sqlite3, "connect", traced_connect)
    settings = SimpleNamespace(
        database_path=db_path,
        effective_nav_coverage_ratio=0.9,
        effective_nav_weekday_only=True,
        exclude_holding_days_gt=90,
    )
    universe, _, _ = _read_long_term_candidates(
        settings, db_path, include_stale_candidates=include_stale_candidates,
    )
    rows = {row["fcode"]: row for row in universe}
    assert rows["000001"]["annual_feature_window_nav_present_years"] == (
        [2021, 2025] if with_nav_table else []
    )
    assert rows["000002"]["annual_feature_window_nav_present_years"] == []
    assert rows["000003"]["annual_feature_window_nav_present_years"] == []
    grouped_window_queries = [sql for sql in statements if "AS nav_year" in sql]
    assert len(grouped_window_queries) == (1 if with_nav_table else 0)


