def test_long_term_history_local_nav_backfill_recovers_semantic_null_annual_return(tmp_path: Path) -> None:
    db_path = _create_long_term_annual_backfill_db(tmp_path / "long_term_annual_backfill.db")
    settings = SimpleNamespace(database_path=db_path)

    summary = _backfill_semantic_null_annual_returns_from_nav(settings)

    assert summary["scanned_null_year_rows"] == 2
    assert summary["eligible_null_year_rows"] == 1
    assert summary["backfilled_row_count"] == 1
    assert summary["backfilled_codes"] == ["000001"]

    conn = sqlite3.connect(db_path)
    try:
        recovered = conn.execute(
            "SELECT annual_return FROM fund_annual_returns WHERE fcode='000001' AND year=2023"
        ).fetchone()[0]
        untouched = conn.execute(
            "SELECT annual_return FROM fund_annual_returns WHERE fcode='000002' AND year=2023"
        ).fetchone()[0]
    finally:
        conn.close()

    assert recovered is not None
    assert abs(recovered - 4.6016) < 0.01
    assert untouched is None


