def test_long_term_history_local_nav_backfill_inserts_missing_current_window_year_row(tmp_path: Path) -> None:
    db_path = _create_long_term_annual_backfill_db(tmp_path / "long_term_annual_backfill_missing_window_year.db")
    conn = sqlite3.connect(db_path)
    try:
        conn.execute("DELETE FROM fund_annual_returns WHERE fcode='000001'")
        conn.execute("DELETE FROM fund_annual_returns WHERE fcode='000002'")
        conn.execute("INSERT INTO fund_annual_returns VALUES ('000001', 2022, 1.1)")
        conn.execute("INSERT INTO fund_annual_returns VALUES ('000001', 2023, 1.2)")
        conn.execute("INSERT INTO fund_annual_returns VALUES ('000001', 2024, 1.3)")
        conn.execute("INSERT INTO fund_annual_returns VALUES ('000001', 2025, 1.4)")
        full_year_dates = pd.date_range("2021-01-04", "2021-12-31", freq="4D")
        if full_year_dates[-1] != pd.Timestamp("2021-12-31"):
            full_year_dates = full_year_dates.append(pd.DatetimeIndex([pd.Timestamp("2021-12-31")]))
        full_rows = []
        value = 1.0
        for idx, ts in enumerate(full_year_dates):
            if idx > 0:
                value *= 1.0005
            full_rows.append(("000001", ts.date().isoformat(), round(value, 6), round(value, 6), 0.05 if idx > 0 else None))
        conn.executemany(
            "INSERT INTO fund_nav_history (fcode, nav_date, unit_nav, accum_nav, daily_growth) VALUES (?, ?, ?, ?, ?)",
            full_rows,
        )
        conn.commit()
    finally:
        conn.close()

    settings = SimpleNamespace(database_path=db_path)
    summary = _backfill_semantic_null_annual_returns_from_nav(
        settings,
        eligible_missing_window_years_by_code={"000001": [2021]},
    )

    assert summary["scanned_null_year_rows"] == 0
    assert summary["eligible_null_year_rows"] == 0
    assert summary["scanned_missing_window_year_rows"] == 1
    assert summary["eligible_missing_window_year_rows"] == 1
    assert summary["backfilled_missing_window_year_row_count"] == 1
    assert summary["backfilled_row_count"] == 1
    assert summary["backfilled_codes"] == ["000001"]
    assert summary["sample_rows"][0]["backfill_mode"] == "insert_missing_window_year_row"

    conn = sqlite3.connect(db_path)
    try:
        recovered = conn.execute(
            "SELECT annual_return FROM fund_annual_returns WHERE fcode='000001' AND year=2021"
        ).fetchone()[0]
    finally:
        conn.close()

    assert recovered is not None


