def test_long_term_history_maintenance_rotation_advances_without_skipping_remaining_candidates() -> None:
    before_candidates = [
        {"fcode": "000001"},
        {"fcode": "000002"},
        {"fcode": "000003"},
        {"fcode": "000004"},
    ]
    after_candidates = [
        {"fcode": "000003"},
        {"fcode": "000004"},
    ]

    selected, start_index = _rotate_long_term_candidates(before_candidates, start_index=0, limit=2)
    next_index = _resolve_next_rotation_index(
        before_candidates,
        after_candidates,
        start_index=start_index,
        limit=2,
    )

    assert [row["fcode"] for row in selected] == ["000001", "000002"]
    assert next_index == 0


def test_long_term_candidate_priority_keeps_existing_missing_bucket_order_and_older_stale_first() -> None:
    candidates = [
        {
            "fcode": "000004",
            "priority_band": 0,
            "issue_types": ["stale_rank_history"],
            "latest_rank_date": "2026-04-10",
            "latest_annual_year": 2025,
        },
        {
            "fcode": "000003",
            "priority_band": 0,
            "issue_types": ["stale_rank_history"],
            "latest_rank_date": "2026-03-01",
            "latest_annual_year": 2025,
        },
        {
            "fcode": "000002",
            "priority_band": 0,
            "issue_types": ["missing_rank_history"],
            "latest_rank_date": "",
            "latest_annual_year": 2025,
        },
        {
            "fcode": "000001",
            "priority_band": 0,
            "issue_types": ["missing_annual_returns", "missing_rank_history"],
            "latest_rank_date": "",
            "latest_annual_year": 0,
        },
    ]

    ordered = sorted(candidates, key=_candidate_priority)

    assert [row["fcode"] for row in ordered] == ["000002", "000001", "000003", "000004"]


def test_long_term_history_maintenance_rotation_uses_full_scope_when_limit_non_positive() -> None:
    candidates = [
        {"fcode": "000001"},
        {"fcode": "000002"},
        {"fcode": "000003"},
    ]

    selected, start_index = _rotate_long_term_candidates(candidates, start_index=1, limit=0)
    next_index = _resolve_next_rotation_index(
        candidates,
        candidates,
        start_index=start_index,
        limit=0,
    )

    assert [row["fcode"] for row in selected] == ["000002", "000003", "000001"]
    assert next_index == 1


def test_long_term_history_maintenance_expands_limit_for_large_high_priority_stale_backlog(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    _freeze_datetime_in(monkeypatch, "backend.long_term_history_maintenance")

    reports_dir = tmp_path / "reports"
    scheduler_state_file = tmp_path / "scheduler_state.json"
    db_path = tmp_path / "long_term_high_priority_stale_backlog.db"
    stale_candidates = [
        {
            "fcode": f"{index:06d}",
            "shortname": f"测试债券{index:06d}",
            "publishable_priority": True,
            "screenable_universe": True,
            "buyable": True,
            "active_universe": True,
            "fresh_nav": True,
            "risk_ready": True,
            "holding_period_blocked": False,
            "needs_annual_returns": False,
            "needs_rank_history": False,
            "stale_annual_returns": False,
            "stale_rank_history": True,
            "latest_annual_year": 2025,
            "latest_rank_date": "2026-03-01",
            "priority_label": "publishable_priority",
            "history_maturity_reason": "estab_date_mature",
            "issue_types": ["stale_rank_history"],
        }
        for index in range(1, 201)
    ]
    post_refresh_universe = [
        {
            **row,
            "stale_rank_history": False,
            "latest_rank_date": "2026-04-12",
            "issue_types": [],
        }
        for row in stale_candidates
    ]

    class FakeAnnualCollector:
        default_workers = 1

        @staticmethod
        def _resolve_submit_batch_size(workers: int, total_items: int) -> int:
            return total_items

        @staticmethod
        def collect_fund_annual_returns(code: str) -> bool:
            return True

    class FakeRankCollector:
        default_workers = 1

        @staticmethod
        def _resolve_submit_batch_size(workers: int, total_items: int) -> int:
            return total_items

        @staticmethod
        def collect_fund_rank_history(code: str) -> bool:
            return True

    settings = SimpleNamespace(
        database_path=db_path,
        effective_nav_coverage_ratio=0.9,
        effective_nav_weekday_only=True,
        exclude_holding_days_gt=90,
        scheduler_state_file=scheduler_state_file,
        reports_dir=reports_dir,
        project_root=PROJECT_ROOT,
        scheduler_long_term_history_empty_payload_retry_days=7,
        scheduler_long_term_history_empty_payload_upstream_limited_failures=3,
        scheduler_long_term_history_rank_stale_days=30,
        scheduler_long_term_history_stale_refresh_retry_days=28,
        scheduler_long_term_history_stale_refresh_upstream_limited_failures=2,
        scheduler_long_term_history_high_priority_stale_backlog_trigger=100,
        scheduler_long_term_history_high_priority_stale_limit=160,
    )

    with (
        patch(
            "backend.long_term_history_maintenance._build_context",
            return_value=SimpleNamespace(
                annual_collector=FakeAnnualCollector(),
                rank_collector=FakeRankCollector(),
            ),
        ),
        patch(
            "backend.long_term_history_maintenance._read_bond_universe",
            side_effect=[
                (list(stale_candidates), list(stale_candidates), {"screenable_candidate_total": 200}),
                (list(post_refresh_universe), [], {"screenable_candidate_total": 0}),
            ],
        ),
        patch(
            "backend.long_term_history_maintenance._sync_terminal_upstream_limited_runtime_exclusions",
            return_value={
                "allow_persist": False,
                "terminal_upstream_limited_total": 0,
                "written_rule_count": 0,
                "removed_rule_count": 0,
                "rules_path": None,
            },
        ),
    ):
        result = run_long_term_history_maintenance(
            settings,
            limit=80,
            refresh_stale=True,
        )

    selection = result["selection"]
    maintenance_result = result["maintenance_result"]
    state_payload = json.loads(
        scheduler_state_file.with_name("long_term_history_maintenance_state.json").read_text(encoding="utf-8")
    )

    assert selection["automatic_scope_applied"] is True
    assert selection["adaptive_limit_applied"] is True
    assert selection["adaptive_limit_reason"] == "high_priority_stale_backlog"
    assert selection["limit"] == 80
    assert selection["effective_limit"] == 160
    assert selection["high_priority_stale_candidate_total"] == 200
    assert selection["publishable_priority_stale_candidate_total"] == 200
