def test_long_term_history_stage_concurrent_preserves_success_and_failure_records() -> None:
    class FakeCollector:
        default_workers = 3
        logged_failures = []

        @staticmethod
        def _resolve_submit_batch_size(workers: int, total_items: int) -> int:
            return 2

        @classmethod
        def log_collection(cls, **kwargs):
            cls.logged_failures.append(kwargs)

    def _collect(code: str) -> bool:
        if code == "000002":
            return False
        if code == "000003":
            raise RuntimeError("boom")
        return True

    success_codes, failed_items = _run_stage_concurrent(
        collector=FakeCollector(),
        codes=["000001", "000002", "000003", "000004"],
        collect_func=_collect,
        stage="rank_history",
        log=lambda _message: None,
    )

    assert set(success_codes) == {"000001", "000004"}
    failed_by_code = {item["fcode"]: item for item in failed_items}
    assert failed_by_code["000002"]["stage"] == "rank_history"
    assert failed_by_code["000002"]["error"] == "collector_returned_false"
    assert failed_by_code["000003"]["stage"] == "rank_history"
    assert failed_by_code["000003"]["error"] == "boom"
    assert len(FakeCollector.logged_failures) == 2
    assert {item["fcode"] for item in FakeCollector.logged_failures} == {"000002", "000003"}


def test_long_term_history_stage_concurrent_uses_collector_outcome_status_for_false_results() -> None:
    class FakeCollector:
        default_workers = 2
        logged_failures = []

        def __init__(self) -> None:
            self.outcomes = {
                "000001": {
                    "success": False,
                    "status": "empty_period_records",
                    "message": "上游返回空收益率记录",
                }
            }

        @staticmethod
        def _resolve_submit_batch_size(workers: int, total_items: int) -> int:
            return total_items

        @classmethod
        def log_collection(cls, **kwargs):
            cls.logged_failures.append(kwargs)

        def consume_recent_outcome(self, code: str):
            return self.outcomes.pop(code, None)

    collector = FakeCollector()

    def _collect(code: str) -> bool:
        return False

    success_codes, failed_items = _run_stage_concurrent(
        collector=collector,
        codes=["000001"],
        collect_func=_collect,
        stage="annual_returns",
        log=lambda _message: None,
    )

    assert success_codes == []
    assert failed_items == [{"fcode": "000001", "stage": "annual_returns", "error": "empty_period_records"}]
    assert FakeCollector.logged_failures[-1]["message"] == "上游返回空收益率记录"


