def test_long_term_history_maintenance_concurrent_stage_counts_are_stable(tmp_path: Path) -> None:
    db_path = _create_long_term_maintenance_priority_db(tmp_path / "long_term_concurrent_counts.db")
    reports_dir = tmp_path / "reports"
    scheduler_state_file = tmp_path / "scheduler_state.json"

    class FakeAnnualCollector:
        default_workers = 2

        @staticmethod
        def _resolve_submit_batch_size(workers: int, total_items: int) -> int:
            return total_items

        @staticmethod
        def collect_fund_annual_returns(code: str) -> bool:
            return code != "000001"

    class FakeRankCollector:
        default_workers = 2

        @staticmethod
        def _resolve_submit_batch_size(workers: int, total_items: int) -> int:
            return total_items

        @staticmethod
        def collect_fund_rank_history(code: str) -> bool:
            return code == "000002"

    settings = SimpleNamespace(
        database_path=db_path,
        effective_nav_coverage_ratio=0.9,
        effective_nav_weekday_only=True,
        exclude_holding_days_gt=90,
        scheduler_state_file=scheduler_state_file,
        reports_dir=reports_dir,
    )

    with patch(
        "backend.long_term_history_maintenance._build_context",
        return_value=SimpleNamespace(
            annual_collector=FakeAnnualCollector(),
            rank_collector=FakeRankCollector(),
        ),
    ):
        result = run_long_term_history_maintenance(settings, target_codes=["000001", "000002"])

    maintenance_result = result["maintenance_result"]
    assert maintenance_result["processed_total"] == 2
    assert maintenance_result["annual_target_total"] == 1
    assert maintenance_result["rank_target_total"] == 2
    assert maintenance_result["annual_success_total"] == 0
    assert maintenance_result["rank_success_total"] == 0
    assert maintenance_result["annual_failed_total"] == 1
    assert maintenance_result["rank_failed_total"] == 2
    failed_pairs = {(item["fcode"], item["stage"]) for item in maintenance_result["failed_items_sample"]}
    assert ("000001", "annual_returns") in failed_pairs
    assert ("000001", "rank_history") in failed_pairs
    assert ("000002", "rank_history") in failed_pairs
    failed_reasons = {(item["fcode"], item["stage"], item["error"]) for item in maintenance_result["failed_items_sample"]}
    assert ("000002", "rank_history", "rank_history_gap_no_progress") in failed_reasons


