def test_long_term_history_stale_scope_nav_buckets_separate_fresh_and_short_staleness(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    _freeze_datetime_in(monkeypatch, "backend.long_term_history_maintenance")

    assert _classify_priority_scope_not_ready_nav_bucket(0) == "fresh_0_30d"
    assert _classify_priority_scope_not_ready_nav_bucket(30) == "fresh_0_30d"
    assert _classify_priority_scope_not_ready_nav_bucket(31) == "short_31_60d"
    assert _classify_priority_scope_not_ready_nav_bucket(60) == "short_31_60d"
    assert _classify_priority_scope_not_ready_nav_bucket(61) == "medium_61_120d"
    assert _classify_priority_scope_not_ready_nav_bucket(121) == "deep_121_365d"
    assert _classify_priority_scope_not_ready_nav_bucket(366) == "terminal_gt_365d"
    assert _classify_priority_scope_not_ready_nav_bucket(None) == "unknown"

    def _stale_scope_row(code: str, latest_nav_date: str | None) -> dict[str, object]:
            return {
                "fcode": code,
                "shortname": f"stale {code}",
                "priority_label": "active_priority",
                "publishable_priority": False,
                "screenable_universe": False,
                "buyable": False,
                "active_universe": True,
                "fresh_nav": True,
            "risk_ready": True,
            "holding_period_blocked": False,
            "latest_nav_date": latest_nav_date,
            "history_maturity_reason": "estab_date_mature",
            "needs_annual_returns": False,
            "needs_rank_history": False,
            "annual_history_missing_raw": False,
            "rank_history_missing_raw": False,
            "stale_annual_returns": False,
            "stale_rank_history": True,
        }

    priority_summary = _build_priority_blocked_summary(
        [
            _stale_scope_row("000001", "2026-04-12"),
            _stale_scope_row("000002", "2026-03-02"),
            _stale_scope_row("000003", "2026-02-10"),
            _stale_scope_row("000004", "2025-12-12"),
            _stale_scope_row("000005", "2025-04-11"),
            _stale_scope_row("000006", None),
        ],
        {},
    )
    full_summary = priority_summary["stale_scope_not_ready_full_summary"]

    assert full_summary["counts_by_nav_bucket"]["fresh_0_30d"] == 1
    assert full_summary["counts_by_nav_bucket"]["short_31_60d"] == 1
    assert full_summary["counts_by_nav_bucket"]["medium_61_120d"] == 1
    assert full_summary["counts_by_nav_bucket"]["deep_121_365d"] == 1
    assert full_summary["counts_by_nav_bucket"]["terminal_gt_365d"] == 1
    assert full_summary["counts_by_nav_bucket"]["unknown"] == 1
    assert full_summary["recoverable_total"] == 2
    assert full_summary["fresh_recoverable_total"] == 1
    assert full_summary["short_recoverable_total"] == 1
    assert full_summary["medium_watch_total"] == 1
    assert full_summary["deep_watch_total"] == 1
    assert full_summary["terminal_candidate_total"] == 1
    assert full_summary["unknown_nav_staleness_total"] == 1

    governance_summary = build_long_term_governance_summary(
        {"candidate_fund_count": 6},
        {
            "coverage_progress": {},
            "upstream_observation_summary": {},
            "priority_blocked_summary": priority_summary,
        },
    )
    stale_scope_summary = governance_summary["stale_scope_not_ready_summary"]
    assert stale_scope_summary["counts_by_nav_bucket"]["fresh_0_30d"] == 1
    assert stale_scope_summary["counts_by_nav_bucket"]["short_31_60d"] == 1
    assert stale_scope_summary["recoverable_total"] == 2


def test_long_term_history_maintenance_summary_includes_gap_audit(tmp_path: Path) -> None:
    db_path = _create_long_term_maintenance_priority_db(tmp_path / "long_term_gap_summary.db")
    reports_dir = tmp_path / "reports"
    scheduler_state_file = tmp_path / "scheduler_state.json"

    class FakeAnnualCollector:
        default_workers = 1

        @staticmethod
        def _resolve_submit_batch_size(workers: int, total_items: int) -> int:
            return total_items

        @staticmethod
        def collect_fund_annual_returns(code: str) -> bool:
            return code == "000001"

    class FakeRankCollector:
        default_workers = 1

        @staticmethod
        def _resolve_submit_batch_size(workers: int, total_items: int) -> int:
            return total_items

        @staticmethod
        def collect_fund_rank_history(code: str) -> bool:
            return False

    settings = SimpleNamespace(
        database_path=db_path,
        effective_nav_coverage_ratio=0.9,
        effective_nav_weekday_only=True,
        exclude_holding_days_gt=90,
        scheduler_state_file=scheduler_state_file,
        reports_dir=reports_dir,
        scheduler_long_term_history_empty_payload_retry_days=7,
        scheduler_long_term_history_empty_payload_upstream_limited_failures=3,
        scheduler_long_term_history_rank_stale_days=30,
        scheduler_long_term_history_stale_refresh_retry_days=28,
        scheduler_long_term_history_stale_refresh_upstream_limited_failures=2,
    )

    with patch(
        "backend.long_term_history_maintenance._build_context",
        return_value=SimpleNamespace(
            annual_collector=FakeAnnualCollector(),
            rank_collector=FakeRankCollector(),
        ),
    ):
        result = run_long_term_history_maintenance(settings, target_codes=["000001", "000002"])

    gap_audit = result["long_term_gap_audit"]
    assert gap_audit["artifact_path"] is not None
    assert Path(gap_audit["artifact_path"]).exists()
    assert "action_counts" in gap_audit
    assert "source_counts" in gap_audit
    failed_reason_summary = result["maintenance_result"]["failed_reason_summary"]
    assert failed_reason_summary["rank_history"]["reason_counts"]["collector_returned_false"] == 2
    governance_summary = result["maintenance_result"]["failed_reason_governance_summary"]
    assert governance_summary["action_totals"]["retry_locally_now"] == 2
    assert governance_summary["stage_reason_actions"]["rank_history"]["collector_returned_false"]["governance_action"] == "retry_locally_now"
    upstream_observation_summary = result["maintenance_result"]["upstream_observation_summary"]
    assert upstream_observation_summary["pending_recovery_total"] == 0
    assert upstream_observation_summary["upstream_limited_watchlist_total"] == 0
    assert upstream_observation_summary["pending_subtype_counts"] == {}
    assert upstream_observation_summary["upstream_limited_subtype_counts"] == {}
    priority_blocked_summary = result["maintenance_result"]["priority_blocked_summary"]
    assert priority_blocked_summary["total"] >= 0
    assert "samples_by_bucket" in priority_blocked_summary
    coverage_progress = result["maintenance_result"]["coverage_progress"]
    assert "annual_history_ready_delta" in coverage_progress
    assert "rank_history_ready_delta" in coverage_progress
    assert "before" in coverage_progress
    assert "after" in coverage_progress
    assert "annual_history_ready_ratio" in coverage_progress["before"]
    assert "annual_history_ready_ratio" in coverage_progress["after"]
    assert result["processed_total"] == result["maintenance_result"]["processed_total"]
    assert result["rank_success_total"] == result["maintenance_result"]["rank_success_total"]
    assert result["annual_return_success_total"] == result["maintenance_result"]["annual_success_total"]
    assert result["annual_failed_total"] == result["maintenance_result"]["annual_failed_total"]
    assert result["rank_failed_total"] == result["maintenance_result"]["rank_failed_total"]


