def test_long_term_history_targeted_refresh_stale_persists_failure_backoff_without_rotating_state(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    _freeze_datetime_in(monkeypatch, "backend.long_term_history_maintenance")

    db_path = _create_long_term_maintenance_priority_db(tmp_path / "long_term_targeted_stale_backoff.db")
    reports_dir = tmp_path / "reports"
    scheduler_state_file = tmp_path / "scheduler_state.json"
    maintenance_state_file = scheduler_state_file.with_name("long_term_history_maintenance_state.json")
    maintenance_state_file.write_text(
        json.dumps(
            {
                "next_index": 7,
                "updated_at": "2026-04-10T11:00:00",
                "failure_backoff": {},
            },
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    stale_candidate = {
        "fcode": "012169",
        "shortname": "测试债券Stale",
        "publishable_priority": True,
        "screenable_universe": True,
        "buyable": True,
        "active_universe": True,
        "fresh_nav": True,
        "risk_ready": True,
        "holding_period_blocked": False,
        "needs_annual_returns": False,
        "needs_rank_history": False,
        "stale_annual_returns": True,
        "stale_rank_history": True,
        "latest_annual_year": 2024,
        "latest_rank_date": "2026-03-01",
        "priority_label": "publishable_priority",
    }
    post_stale_candidate = dict(stale_candidate)

    class FakeAnnualCollector:
        default_workers = 1

        @staticmethod
        def _resolve_submit_batch_size(workers: int, total_items: int) -> int:
            return total_items

        @staticmethod
        def collect_fund_annual_returns(code: str) -> bool:
            return True

    class FakeRankCollector:
        default_workers = 1

        @staticmethod
        def _resolve_submit_batch_size(workers: int, total_items: int) -> int:
            return total_items

        @staticmethod
        def collect_fund_rank_history(code: str) -> bool:
            return True

    settings = SimpleNamespace(
        database_path=db_path,
        effective_nav_coverage_ratio=0.9,
        effective_nav_weekday_only=True,
        exclude_holding_days_gt=90,
        scheduler_state_file=scheduler_state_file,
        reports_dir=reports_dir,
        project_root=PROJECT_ROOT,
        scheduler_long_term_history_empty_payload_retry_days=7,
        scheduler_long_term_history_empty_payload_upstream_limited_failures=3,
        scheduler_long_term_history_rank_stale_days=30,
        scheduler_long_term_history_stale_refresh_retry_days=28,
        scheduler_long_term_history_stale_refresh_upstream_limited_failures=2,
    )

    with (
        patch(
            "backend.long_term_history_maintenance._build_context",
            return_value=SimpleNamespace(
                annual_collector=FakeAnnualCollector(),
                rank_collector=FakeRankCollector(),
            ),
        ),
        patch(
            "backend.long_term_history_maintenance._read_bond_universe",
            side_effect=[
                ([stale_candidate], [stale_candidate], {"screenable_candidate_total": 1}),
                ([post_stale_candidate], [post_stale_candidate], {"screenable_candidate_total": 1}),
            ],
        ),
        patch(
            "backend.long_term_history_maintenance._sync_terminal_upstream_limited_runtime_exclusions",
            return_value={
                "allow_persist": False,
                "terminal_upstream_limited_total": 0,
                "written_rule_count": 0,
                "removed_rule_count": 0,
                "rules_path": None,
            },
        ),
    ):
        result = run_long_term_history_maintenance(
            settings,
            target_codes=["012169"],
            refresh_stale=True,
        )

    state_payload = json.loads(maintenance_state_file.read_text(encoding="utf-8"))
    assert state_payload["next_index"] == 7
    assert state_payload["failure_backoff"]["012169"]["consecutive_failures"] == 1
    assert state_payload["failure_backoff"]["012169"]["upstream_limited"] is False
    assert state_payload["failure_backoff"]["012169"]["last_error"] == (
        "stale_annual_refresh_no_progress | stale_rank_refresh_no_progress"
    )

    assert result["selection"]["requested_target_codes"] == ["012169"]
    assert result["selection"]["failure_backoff_enabled"] is True
    assert result["selection"]["automatic_scope_applied"] is False
    assert result["selection"]["cooldown_skipped_candidate_total"] == 0
    assert result["selection"]["rotation_state_after"] is None
    assert result["selection"]["rotation_next_index"] is None

    maintenance_result = result["maintenance_result"]
    assert maintenance_result["processed_total"] == 1
    assert maintenance_result["stale_refresh_no_progress_failed_total"] == 2
    assert maintenance_result["upstream_observation_summary"]["pending_recovery_total"] == 1
    assert maintenance_result["upstream_observation_summary"]["pending_retry_window_total"] == 1

    samples = result["long_term_gap_audit"]["samples_by_action"]["retry_locally_later"]
    assert any(sample["fcode"] == "012169" for sample in samples)


