def test_long_term_history_maintenance_exposes_failed_reason_governance_summary(tmp_path: Path) -> None:
    db_path = _create_long_term_maintenance_priority_db(tmp_path / "long_term_governance_summary.db")
    reports_dir = tmp_path / "reports"
    scheduler_state_file = tmp_path / "scheduler_state.json"

    class FakeAnnualCollector:
        default_workers = 1

        @staticmethod
        def _resolve_submit_batch_size(workers: int, total_items: int) -> int:
            return total_items

        @staticmethod
        def collect_fund_annual_returns(code: str) -> bool:
            return False

        def consume_recent_outcome(self, code: str) -> dict[str, str]:
            return {"status": "invalid_datas_type"}

    class FakeRankCollector:
        default_workers = 1

        @staticmethod
        def _resolve_submit_batch_size(workers: int, total_items: int) -> int:
            return total_items

        @staticmethod
        def collect_fund_rank_history(code: str) -> bool:
            return False

        def consume_recent_outcome(self, code: str) -> dict[str, str]:
            return {"status": "empty_rank_records"}

    settings = SimpleNamespace(
        database_path=db_path,
        effective_nav_coverage_ratio=0.9,
        effective_nav_weekday_only=True,
        exclude_holding_days_gt=90,
        scheduler_state_file=scheduler_state_file,
        reports_dir=reports_dir,
    )

    with patch(
        "backend.long_term_history_maintenance._build_context",
        return_value=SimpleNamespace(
            annual_collector=FakeAnnualCollector(),
            rank_collector=FakeRankCollector(),
        ),
    ):
        result = run_long_term_history_maintenance(settings, target_codes=["000001"])

    governance_summary = result["maintenance_result"]["failed_reason_governance_summary"]
    assert governance_summary["action_totals"]["observe_upstream_source"] == 2
    assert governance_summary["stage_reason_actions"]["annual_returns"]["invalid_datas_type"]["governance_action"] == "observe_upstream_source"
    assert governance_summary["stage_reason_actions"]["rank_history"]["empty_rank_records"]["governance_action"] == "observe_upstream_source"
    observation_summary = result["maintenance_result"]["upstream_observation_summary"]
    assert observation_summary["pending_recovery_total"] == 0
    assert observation_summary["upstream_limited_watchlist_total"] == 0
    assert observation_summary["pending_subtype_counts"] == {}
    assert observation_summary["upstream_limited_subtype_counts"] == {}


def test_rank_collector_save_rank_history_deduplicates_duplicate_dates(tmp_path: Path) -> None:
    db_path = tmp_path / "rank_dedup.db"
    assert init_database(str(db_path), drop_existing=True) is True

    collector = RankCollector(config={"database": {"path": str(db_path)}}, db_manager=get_db_manager(db_path=str(db_path)))

    saved = collector._save_rank_history(
        "000001",
        [
            {"PDATE": "2024-01-01", "QRANK": 10, "QSC": 100},
            {"PDATE": "2024-01-01", "QRANK": 12, "QSC": 100},
            {"PDATE": "2024-02-01", "QRANK": 8, "QSC": 100},
        ],
    )

    assert saved is True

    conn = sqlite3.connect(db_path)
    try:
        rows = conn.execute(
            "SELECT rank_date, rank_position, category_total FROM fund_rank_history WHERE fcode='000001' ORDER BY rank_date"
        ).fetchall()
    finally:
        conn.close()

    assert rows == [
        ("2024-01-01", 12, 100),
        ("2024-02-01", 8, 100),
    ]


def test_rank_collector_reuses_exact_cold_rows_and_routes_revisions_hot(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    db_path = tmp_path / "backend/data/bond_funds.db"
    archive_path = tmp_path / "backend/data/archives/fund_rank_history_before_2024-03-01.db"
    db_path.parent.mkdir(parents=True)
    archive_path.parent.mkdir(parents=True)
    assert init_database(str(db_path), drop_existing=True) is True
    archive_conn = sqlite3.connect(str(archive_path))
    try:
        archive_conn.execute(
            """
            CREATE TABLE fund_rank_history_archive (
                fcode TEXT NOT NULL,
                rank_date TEXT NOT NULL,
                period TEXT,
                rank_position INTEGER,
                category_total INTEGER,
                percentile REAL,
                created_at TEXT
            )
            """
        )
        archive_conn.execute(
            """
            CREATE UNIQUE INDEX idx_fund_rank_history_archive_key
            ON fund_rank_history_archive (fcode, rank_date, COALESCE(period, ''))
            """
        )
        archive_conn.executemany(
            "INSERT INTO fund_rank_history_archive VALUES (?, ?, ?, ?, ?, ?, ?)",
            [
                ("000001", "2024-01-01", "overall", 10, 100, 0.10, "2024-01-02"),
                ("000001", "2024-02-01", "overall", 20, 100, 0.20, "2024-02-02"),
            ],
        )
        archive_conn.commit()
    finally:
        archive_conn.close()

    monkeypatch.setattr(
        "collectors.rank_collector.load_latest_rank_history_archive_binding",
        lambda: {
            "archive_path": str(archive_path),
            "active_db_path": str(db_path),
            "archive_table_name": "fund_rank_history_archive",
            "archive_cutoff_date": "2024-03-01",
        },
    )
    collector = RankCollector(
        config={"database": {"path": str(db_path)}},
        db_manager=get_db_manager(db_path=str(db_path)),
    )
    collector.reset_api_source_evidence(target_count=1, collection_mode="test")

    assert collector._save_rank_history(
        "000001",
        [
            {"PDATE": "2024-01-01", "QRANK": 10, "QSC": 100},
            {"PDATE": "2024-02-01", "QRANK": 21, "QSC": 100},
            {"PDATE": "2024-03-01", "QRANK": 30, "QSC": 100},
        ],
    ) is True

    conn = sqlite3.connect(str(db_path))
    try:
        rows = conn.execute(
            """
            SELECT rank_date, rank_position, category_total
            FROM fund_rank_history
            WHERE fcode = '000001'
            ORDER BY rank_date
            """
        ).fetchall()
    finally:
        conn.close()
    assert rows == [
        ("2024-02-01", 21, 100),
        ("2024-03-01", 30, 100),
    ]
    evidence = collector.get_api_source_evidence()
    assert evidence["written_record_count"] == 2
    assert evidence["archive_reused_record_count"] == 1
    assert evidence["archive_conflict_record_count"] == 1
    assert evidence["archive_lookup_error_count"] == 0


