def test_supplement_bond_holding_period_recognizes_alias_and_closed_term_patterns() -> None:
    module = _load_script_module("supplement_bond_holding_period", "scripts/supplement_bond_holding_period.py")

    alias_match = module.parse_holding_match("银华安颐中短债双月持有期债券A")
    assert alias_match is not None
    assert alias_match.days == 60
    assert alias_match.keyword == "双月持有期"

    quarter_match = module.parse_holding_match("博时季季乐持有期债券A")
    assert quarter_match is not None
    assert quarter_match.days == 90
    assert quarter_match.keyword == "季季乐持有期"

    half_year_match = module.parse_holding_match("博时双季享持有期债券A")
    assert half_year_match is not None
    assert half_year_match.days == 180
    assert half_year_match.keyword == "双季享持有期"

    closed_match = module.parse_holding_match("华泰保兴兴元180天封闭债券A")
    assert closed_match is not None
    assert closed_match.days == 180
    assert closed_match.keyword == "180天封闭"


