def test_audit_holding_period_no_signal_edges_marks_historical_run_as_cross_run_current_db_state(
    tmp_path: Path,
) -> None:
    module = _load_script_module(
        "audit_holding_period_no_signal_edges_run_scope_test",
        "scripts/audit_holding_period_no_signal_edges.py",
    )

    reports_dir = tmp_path / "reports"
    runs_dir = reports_dir / "runs"
    archived_runs_dir = reports_dir / "archive" / "superseded_runs"
    latest_run_id = "20260430_latest"
    archived_run_id = "20260430_archived"

    latest_report_file = reports_dir / "latest.json"
    latest_report_file.parent.mkdir(parents=True, exist_ok=True)
    latest_report_file.write_text(
        json.dumps({"run_id": latest_run_id, "artifacts": {}}, ensure_ascii=False),
        encoding="utf-8",
    )

    archived_run_dir = archived_runs_dir / archived_run_id
    archived_run_dir.mkdir(parents=True, exist_ok=True)
    (archived_run_dir / f"bond_analysis_report_{archived_run_id}.json").write_text(
        json.dumps({"run_id": archived_run_id, "artifacts": {}}, ensure_ascii=False),
        encoding="utf-8",
    )

    db_path = tmp_path / "audit.db"
    conn = sqlite3.connect(str(db_path))
    try:
        conn.execute(
            """
            CREATE TABLE funds (
                fcode TEXT PRIMARY KEY,
                shortname TEXT,
                fullname TEXT,
                ftype TEXT,
                investment_strategy TEXT,
                investment_target TEXT,
                has_holding_period INTEGER,
                holding_days INTEGER,
                holding_keywords TEXT,
                holding_period_source TEXT
            )
            """
        )
        conn.execute(
            """
            INSERT INTO funds (
                fcode, shortname, fullname, ftype, investment_strategy, investment_target,
                has_holding_period, holding_days, holding_keywords, holding_period_source
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                "000001",
                "示例债基",
                "示例债基A",
                "债券型基金",
                "封闭运作期到期后开放。",
                "",
                0,
                0,
                "",
                "",
            ),
        )
        conn.commit()
    finally:
        conn.close()

    settings = SimpleNamespace(
        latest_report_file=latest_report_file,
        reports_dir=reports_dir,
        runs_dir=runs_dir,
        archived_runs_dir=archived_runs_dir,
        project_root=tmp_path,
        database_path=db_path,
    )

    summary = module.run_holding_period_no_signal_edges_audit(
        settings,
        run_id=archived_run_id,
        project_root=tmp_path,
        limit=5,
    )

    assert summary["run_id"] == archived_run_id
    assert summary["auxiliary_scope"] == "cross_run_current_db_state"
    assert summary["auxiliary_scope_label"] == "历史 run + 当前库状态"
    assert summary["replay_precision_status"] == "missing"
    assert Path(summary["artifact_path"]).exists()
    assert Path(summary["preview_csv_path"]).exists()
    assert Path(summary["markdown_path"]).exists()


