def test_audit_annual_return_gate_shadow_local_forward_validation_uses_real_nav(
    tmp_path: Path,
) -> None:
    module = _load_script_module(
        "audit_annual_return_gate_shadow_forward_validation_for_test",
        "scripts/audit_annual_return_gate_shadow.py",
    )
    db_path = tmp_path / "funds.db"
    conn = sqlite3.connect(db_path)
    try:
        conn.execute(
            "CREATE TABLE fund_nav_history (fcode TEXT, nav_date TEXT, unit_nav REAL, daily_growth REAL)"
        )
        # Synthetic provider total-return fixture, with complete daily observations.
        rows = []
        for code, terminal in (("000001", 1.01), ("000002", .99)):
            daily = terminal ** (1 / 30) - 1
            for index, day in enumerate(pd.date_range("2026-01-01", periods=31)):
                rows.append((code, day.date().isoformat(), 100 * (1 + daily) ** index,
                             None if index == 0 else daily * 100))
        conn.executemany("INSERT INTO fund_nav_history VALUES (?, ?, ?, ?)", rows)
        conn.commit()
    finally:
        conn.close()

    result = module._build_local_shadow_forward_validation(
        SimpleNamespace(database_path=db_path),
        scenario_key="dominant_style_band_all",
        label="中短债/70-79.99 全量局部影子复核",
        snapshot_date="2026-01-01",
        added_codes={"000001"},
        removed_codes={"000002"},
    )

    assert result["available"] is True
    assert result["business_value_synthesis"] == "forbidden"
    assert result["missing_value_policy"] == "preserve_missing_semantics"
    assert result["threshold_change_supported_now"] is False
    assert result["status"] == "ready"
    assert result["forward_direction"] == "added_forward_potentially_better"
    assert result["ready_window_count"] == 1
    first_window = result["window_summaries"][0]
    assert first_window["window"] == "1个月"
    assert first_window["status"] == "ready"
    assert first_window["signal"] == "added_forward_better"
    assert first_window["median_return_delta_added_minus_removed_pct"] == pytest.approx(2.0)
    assert result["window_summaries"][1]["status"] == "future_data_pending"


