def test_supplement_bond_holding_period_detail_assisted_matching_avoids_name_join_boundary_artifacts() -> None:
    module = _load_script_module("supplement_bond_holding_period", "scripts/supplement_bond_holding_period.py")

    share_class_match = module.parse_holding_match(
        "东方永泰纯债1年A",
        "",
        "",
        "本基金在封闭期与开放期采取不同的投资策略。封闭期投资策略如下。",
    )
    assert share_class_match is not None
    assert share_class_match.days == 365
    assert share_class_match.keyword == "1年"

    suffix_match = module.parse_holding_match(
        "中加聚鑫纯债一年D",
        "",
        "",
        "本基金在封闭期与开放期采取不同的投资策略。封闭期投资策略如下。",
    )
    assert suffix_match is not None
    assert suffix_match.days == 365
    assert suffix_match.keyword == "一年"

    fullname_boundary_match = module.parse_holding_match(
        "中金新辉1年",
        "中金新辉",
        "",
        "本基金在封闭期与开放期采取不同的投资策略。封闭期投资策略如下。",
    )
    assert fullname_boundary_match is not None
    assert fullname_boundary_match.days == 365
    assert fullname_boundary_match.keyword == "1年"


