def test_detail_collector_bounded_rotation_prefers_oldest_stale_rows(tmp_path: Path) -> None:
    from collectors.detail_collector import FundDetailCollector

    db_path = tmp_path / "detail_rotation.db"
    assert init_database(str(db_path), drop_existing=True) is True
    db_manager = get_db_manager(db_path=str(db_path))
    now = datetime.now()

    def _complete_fund(fcode: str, updated_at: datetime) -> Fund:
        return Fund(
            fcode=fcode,
            shortname=f"测试基金{fcode}",
            ftype="债券型-长债",
            type_category="fixed_income",
            benchmark="中债综合指数",
            estab_date=datetime(2020, 1, 1).date(),
            risk_level=2,
            company_id="C001",
            company_name="测试基金公司",
            mgr_fee_rate=0.2,
            trust_fee_rate=0.05,
            detail_updated_at=updated_at,
        )

    with db_manager.get_session() as session:
        session.add_all(
            [
                _complete_fund("000001", now - timedelta(days=70)),
                _complete_fund("000002", now - timedelta(days=90)),
                _complete_fund("000003", now - timedelta(days=80)),
                _complete_fund("000004", now - timedelta(days=5)),
            ]
        )

    collector = FundDetailCollector(
        config={
            "collection": {
                "detail": {
                    "refresh_stale_days": 56,
                    "max_targets_per_run": 2,
                }
            }
        },
        db_manager=db_manager,
    )
    collector.empty_detail_report_dir = tmp_path / "empty-detail-reports"

    assert collector._load_target_fcodes(force_update=False) == ["000002", "000003"]


