def test_accumulation_tracker_append_normalizes_new_rows_without_futurewarning(tmp_path) -> None:
    import warnings

    from bond_fund_screening.utils.accumulation_tracker import AccumulationTracker

    tracker = AccumulationTracker(str(tmp_path / "tracker.xlsx"), verbose=False)
    tracker.df_tracker = tracker._normalize_tracker_frame(
        pd.DataFrame(
            [
                {
                    "fcode": "000001",
                    "shortname": "已在榜基金",
                    "appearance_count": 1,
                    "appearance_ratio": None,
                    "first_appear_date": "2026-06-04",
                    "last_appear_date": "2026-06-04",
                    "days_since_last": 0,
                    "consecutive_absence": 0,
                    "latest_return": 3.2,
                    "latest_sharpe_ratio": 1.1,
                    "latest_max_drawdown": 0.01,
                    "latest_max_drawdown_duration": None,
                    "return_score": None,
                    "risk_score": None,
                    "stability_score": None,
                    "liquidity_score": None,
                    "comprehensive_score": None,
                    "grade": None,
                    "score_mode": None,
                }
            ],
            columns=AccumulationTracker.COLUMNS,
        )
    )

    df_daily = pd.DataFrame(
        [
            {
                "fcode": "000001",
                "shortname": "已在榜基金",
                "main_return": 3.4,
                "sharpe_ratio": 1.2,
                "max_drawdown": 0.009,
            },
            {
                "fcode": "000002",
                "shortname": "新增基金",
                "main_return": 3.1,
                "sharpe_ratio": 1.0,
                "max_drawdown": 0.011,
            },
        ]
    )

    with warnings.catch_warnings():
        warnings.simplefilter("error", FutureWarning)
        result = tracker._update_tracker_data(df_daily, "2026-06-05")

    assert result["new_funds"] == 1
    assert result["updated_funds"] == 1
    assert len(tracker.df_tracker) == 2
    assert str(tracker.df_tracker["return_score"].dtype) == "Float64"
    assert str(tracker.df_tracker["appearance_count"].dtype) == "Int64"


def test_accumulation_tracker_accepts_exact_same_run_input_across_midnight(tmp_path) -> None:
    from bond_fund_screening.tasks.accumulation_file_utils import resolve_explicit_final_file

    output_dir = tmp_path / "core_output"
    output_dir.mkdir()
    same_run_file = output_dir / "当日最终优质基金_20260818_235943.xlsx"
    next_day_file = output_dir / "当日最终优质基金_20260819_000500.xlsx"
    same_run_file.write_bytes(b"same-run")
    next_day_file.write_bytes(b"unrelated-newer-file")

    resolved = resolve_explicit_final_file(
        output_dir,
        same_run_file,
        label="当日最终优质基金",
    )

    assert resolved == same_run_file.resolve()


def test_accumulation_tracker_rejects_explicit_input_outside_output_contract(tmp_path) -> None:
    from bond_fund_screening.tasks.accumulation_file_utils import resolve_explicit_final_file

    output_dir = tmp_path / "core_output"
    output_dir.mkdir()
    outside_file = tmp_path / "当日最终优质基金_20260818_235943.xlsx"
    outside_file.write_bytes(b"outside")

    with pytest.raises(FileNotFoundError, match="不在配置输出目录内"):
        resolve_explicit_final_file(
            output_dir,
            outside_file,
            label="当日最终优质基金",
        )


