def test_final_selection_contraction_explainability_scores_selected_and_removed_rows() -> None:
    candidate_df = pd.DataFrame(
        [
            {
                "基金代码": "000001",
                "基金名称": "稳定纯债",
                "正式榜分组": "纯债稳健榜",
                "债基风格标签": "中短债",
                "项目质量信心": "高信心",
                "正式投资评分": 78.0,
                "综合加权得分": 80.0,
                "1年-年化收益(%)": 4.0,
            },
            {
                "基金代码": "000002",
                "基金名称": "低频新样本",
                "正式榜分组": "纯债稳健榜",
                "债基风格标签": "中短债",
                "项目质量信心": "中信心",
                "正式投资评分": 66.0,
                "综合加权得分": 82.0,
                "1年-年化收益(%)": 3.5,
            },
            {
                "基金代码": "000003",
                "基金名称": "稳定增强",
                "正式榜分组": "增强债弹性榜",
                "债基风格标签": "一级债增强",
                "项目质量信心": "高信心",
                "正式投资评分": 77.0,
                "综合加权得分": 79.0,
                "1年-年化收益(%)": 5.1,
            },
        ]
    )
    official_df = candidate_df[candidate_df["基金代码"].isin(["000001", "000003"])].copy()
    removed_df = candidate_df[candidate_df["基金代码"].eq("000002")].copy()
    removed_df["项目推荐原因代码"] = "final_selection_stability_cap"
    tracker_features_df = pd.DataFrame(
        [
            {"基金代码": "000001", "出现次数": 8, "出现频率(%)": 100.0, "跟踪总期数": 8},
            {"基金代码": "000002", "出现次数": 1, "出现频率(%)": 12.5, "跟踪总期数": 8},
            {"基金代码": "000003", "出现次数": 8, "出现频率(%)": 100.0, "跟踪总期数": 8},
        ]
    )

    result = _build_final_selection_contraction_explainability(
        candidate_df,
        official_df=official_df,
        removed_after_final_selection_df=removed_df,
        tracker_features_df=tracker_features_df,
        settings=SimpleNamespace(
            final_selection_high_score_new_fund_threshold=85.0,
            final_selection_low_score_new_fund_threshold=75.0,
        ),
    )

    row_map = {row["基金代码"]: row for row in result.to_dict(orient="records")}
    assert row_map["000002"]["正式精选状态"] == "最终精选未入围"
    assert row_map["000002"]["_final_new_low_penalty"] == 8.0
    assert row_map["000002"]["最终精选解释"] == "稳定性 cap 收敛，转入自动诊断"
    assert row_map["000001"]["正式精选状态"] == "正式入围"
    assert row_map["000001"]["_final_history_occurrence_bonus"] == pytest.approx(9.6)
    assert row_map["000001"]["_final_stability_score"] > row_map["000002"]["_final_stability_score"]

    summary = _build_final_selection_contraction_summary(result, preview_top_n=2)
    assert summary["available"] is True
    assert summary["input_count"] == 3
    assert summary["official_count"] == 2
    assert summary["removed_count"] == 1
    assert summary["stability_cap_removed_count"] == 1
    assert summary["style_summary"][0]["输入样本数"] >= 1
    assert summary["preview"][0]["基金代码"] == "000002"


