def test_autostock_candidate_return_pct_point_fallback_does_not_hard_block() -> None:
    local_row = {
        "基金代码": "000015",
        "基金名称": "华夏纯债债券A",
        "基金类型": "债券型-长债",
        "最新净值日期": "2026-06-23",
        "区间收益基准日": "2026-06-23",  # Isolated numerical-tolerance fixture, explicitly dated.
        "最新单位净值": 1.1985,
        "近1周(%)": 0.13,
        "近1月(%)": 0.26,
        "近3月(%)": 0.96,
        "近6月(%)": 1.61,
        "近1年(%)": 2.12,
    }
    autostock_row = {
        "code": "000015",
        "name": "华夏纯债债券A",
        "type": "债券型",
        "netWorthDate": "2026-06-23",
        "netWorth": 1.1985,
        "lastWeekGrowth": "0.13%",
        "lastMonthGrowth": "0.26%",
        "lastThreeMonthsGrowth": "0.96%",
        "lastSixMonthsGrowth": "1.52%",
        "lastYearGrowth": "2.12%",
    }
    config = {
        "nav_relative_tolerance_pct": 1.0,
        "nav_absolute_tolerance": 0.001,
        "return_relative_tolerance_pct": 5.0,
        "return_absolute_tolerance": 0.5,
        "return_small_base_threshold": 1.0,
        "nav_date_soft_lag_days": 5,
    }

    class DummyConverter:
        @staticmethod
        def parse_growth_rate(value):
            text = str(value).replace("%", "").strip()
            return float(text) if text else None

    result = compare_candidate_with_autostock(
        pd.Series(local_row),
        autostock_row,
        config,
        converter_cls=DummyConverter,
        normalize_fcode=lambda value: str(value).zfill(6),
        safe_float_fn=lambda value: float(value) if value not in (None, "") else None,
        normalize_iso_date_fn=lambda value: str(value) if value else None,
        is_type_match_fn=lambda local_type, autostock_type: "债券" in str(local_type) and "债券" in str(autostock_type),
        compare_return_with_autostock_fn=compare_return_with_autostock,
        return_field_mappings=(
            ("近1周(%)", "lastWeekGrowth", "return_1w"),
            ("近1月(%)", "lastMonthGrowth", "return_1m"),
            ("近3月(%)", "lastThreeMonthsGrowth", "return_3m"),
            ("近6月(%)", "lastSixMonthsGrowth", "return_6m"),
            ("近1年(%)", "lastYearGrowth", "return_1y"),
        ),
    )

    assert result["passed"] is True
    assert result["hard_reasons"] == []
    assert result["details"]["return_6m_diff"] == pytest.approx(5.9211)
    assert result["details"]["return_6m_abs_diff_pct_point"] == pytest.approx(0.09)
    assert result["details"]["return_6m_diff_mode"] == "absolute_pct_point_fallback"


