def test_publish_contraction_root_cause_flags_hard_block_contraction() -> None:
    from scripts.audit_publish_contraction_root_cause import _build_findings, _build_pair_delta

    baseline = {
        "run_id": "baseline",
        "counts": {"final_count": 320, "dynamic_final_count": 436},
        "base_gate_soft_warning_removed_count": 0,
        "autostock": {
            "filtered_count": 58,
            "passed_count": 1190,
            "warning_counts": [],
        },
        "publish_chain": {
            "records": {
                "final_official_records": {"code_count": 320},
                "dynamic_reference_export_records": {"code_count": 436},
                "final_selection_removed_records": {
                    "code_count": 87,
                    "hard_block_count": 0,
                    "final_selection_stability_cap_count": 87,
                },
            }
        },
    }
    previous_success = {
        "run_id": "previous_success",
        "counts": {"final_count": 235, "dynamic_final_count": 275},
        "base_gate_soft_warning_removed_count": 0,
        "autostock": {
            "filtered_count": 448,
            "passed_count": 750,
            "warning_counts": [{"reason": "latest_nav_date_soft_lag", "count": 612}],
        },
        "publish_chain": {
            "records": {
                "final_official_records": {"code_count": 235},
                "dynamic_reference_export_records": {"code_count": 275},
                "final_selection_removed_records": {
                    "code_count": 102,
                    "hard_block_count": 85,
                    "final_selection_stability_cap_count": 17,
                },
            }
        },
    }
    latest = {
        "run_id": "latest",
        "counts": {"final_count": 209, "dynamic_final_count": 231},
        "base_gate_soft_warning_removed_count": 0,
        "autostock": {
            "filtered_count": 448,
            "passed_count": 750,
            "warning_counts": [{"reason": "latest_nav_date_soft_lag", "count": 612}],
        },
        "publish_chain": {
            "records": {
                "final_official_records": {"code_count": 209},
                "dynamic_reference_export_records": {"code_count": 231},
                "final_selection_removed_records": {
                    "code_count": 128,
                    "hard_block_count": 111,
                    "final_selection_stability_cap_count": 17,
                },
            }
        },
    }

    findings = _build_findings([baseline, previous_success, latest])
    topics = {item["topic"] for item in findings}

    assert "Final list contraction explained by AutoStock hard blocks" in topics
    assert "Second contraction caused by additional hard blocks" in topics
    assert "AutoStock filter shock versus current published baseline" in topics
    latest_pair_delta = _build_pair_delta(previous_success, latest)
    assert latest_pair_delta["final_selection_hard_block_delta"] == 26
    assert latest_pair_delta["final_count_delta"] == -26


