def test_publication_registry_skips_validation_only_refresh_from_formal_publication(
    tmp_path: Path,
) -> None:
    latest_report_file = tmp_path / "latest.json"
    publication_registry_file = tmp_path / "publication_registry.json"

    _write_report(
        tmp_path / "20260519_073340_sync",
        run_id="20260519_073340_sync",
        generated_at="2026-05-19T07:33:40",
        candidate_date="2026-05-18",
        final_count=313,
        dynamic_final_count=499,
        candidate_fund_count=7316,
        risk_effective_fund_count=5543,
        screenable_universe_count=5541,
        publishable_pool_count=6350,
        risk_coverage_sufficient=True,
    )
    validation_run_dir = tmp_path / "20260519_090001_sync"
    _write_report(
        validation_run_dir,
        run_id="20260519_090001_sync",
        generated_at="2026-05-19T09:00:01",
        candidate_date="2026-05-18",
        final_count=319,
        dynamic_final_count=499,
        candidate_fund_count=7316,
        risk_effective_fund_count=5543,
        screenable_universe_count=5541,
        publishable_pool_count=6350,
        risk_coverage_sufficient=True,
    )
    validation_report_path = validation_run_dir / "bond_analysis_report_20260519_090001_sync.json"
    validation_payload = json.loads(validation_report_path.read_text(encoding="utf-8"))
    validation_payload["publication_control"] = {
        "mode": "validation_only",
        "reason": "reuse_existing_outputs_lightweight_refresh",
        "eligible_for_formal_publication": False,
    }
    validation_report_path.write_text(
        json.dumps(validation_payload, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )

    latest_report_file.write_text(
        validation_report_path.read_text(encoding="utf-8"),
        encoding="utf-8",
    )

    settings = SimpleNamespace(
        runs_dir=tmp_path,
        latest_report_file=latest_report_file,
        publication_registry_file=publication_registry_file,
    )

    registry = build_publication_registry(settings)

    assert registry["current_published_run_id"] == "20260519_073340_sync"
    validation_record = next(item for item in registry["superseded_runs"] if item["run_id"] == "20260519_090001_sync")
    assert validation_record["publishable"] is False
    assert validation_record["publish_state"] == "superseded"
    blocker_codes = {item["code"] for item in validation_record["publish_blockers"]}
    assert "validation_refresh_not_publishable" in blocker_codes


