def test_report_builder_incremental_review_summary_and_flags() -> None:
    incremental_review_df = pd.DataFrame(
        [
            {
                "基金代码": "000001",
                "基金名称": "测试新增增强债A",
                FORMAL_GROUP_LABEL: "增强债弹性榜",
                "即时体检结论": "需持续跟踪",
                "体检备注": "年化分位偏后；评分分位偏后",
            },
            {
                "基金代码": "000002",
                "基金名称": "测试新增纯债A",
                FORMAL_GROUP_LABEL: "纯债稳健榜",
                "即时体检结论": "当前未见显著拖累",
                "体检备注": "",
            },
            {
                "基金代码": "000003",
                "基金名称": "测试新增纯债B",
                FORMAL_GROUP_LABEL: "纯债稳健榜",
                "即时体检结论": "轻度跟踪",
                "体检备注": "年化分位偏后",
            },
        ]
    )
    summary_df = _build_incremental_review_summary_frame(incremental_review_df)
    summary_map = dict(zip(summary_df["指标"], summary_df["数值"]))

    assert summary_map["相对上一快照新增正式样本数"] == 3
    assert summary_map["新增样本中当前未见显著拖累数"] == 1
    assert summary_map["新增样本中需持续跟踪数"] == 1
    assert "增强债弹性榜 1" in str(summary_map["需持续跟踪样本主要集中分组"])
    assert "年化分位偏后（1）" in str(summary_map["需持续跟踪样本主要偏弱信号"])

    export_df = pd.DataFrame(
        [
            {"基金代码": "000001", "基金名称": "测试新增增强债A"},
            {"基金代码": "000010", "基金名称": "存量样本"},
        ]
    )
    flagged_df = _attach_incremental_review_flags(export_df, incremental_review_df)
    flagged_map = {row["基金代码"]: row for row in flagged_df.to_dict(orient="records")}

    assert flagged_map["000001"]["新增样本复核状态"] == "需持续跟踪"
    assert flagged_map["000001"]["新增样本体检备注"] == "年化分位偏后；评分分位偏后"
    assert flagged_map["000010"]["新增样本复核状态"] == ""


