    archive_dir = reports_dir / "archive" / "superseded_runs"
    current_run_id = "20260430_112635_sync"
    future_run_id = "20260430_134808_sync"
    current_generated_at = "2026-04-30T11:28:29"
    future_generated_at = "2026-04-30T13:56:30"
    snapshot_date = "2026-04-29"

    current_excel = runs_dir / current_run_id / "__final_selection_in_memory__.xlsx"
    future_excel = archive_dir / future_run_id / "正式推荐债券基金_future.xlsx"
    current_excel.parent.mkdir(parents=True, exist_ok=True)
    future_excel.parent.mkdir(parents=True, exist_ok=True)
    current_excel.write_text("stub", encoding="utf-8")
    future_excel.write_text("stub", encoding="utf-8")

    future_report_path = archive_dir / future_run_id / f"bond_analysis_report_{future_run_id}.json"
    future_report_path.write_text(
        json.dumps(
            {
                "run_id": future_run_id,
                "generated_at": future_generated_at,
                "counts": {"final_count": 312},
                "artifacts": {"filtered_excel": str(future_excel.relative_to(project_root))},
            },
            ensure_ascii=False,
        ),
        encoding="utf-8",
    )

    settings = SimpleNamespace(
        project_root=project_root,
        runs_dir=runs_dir,
    )
    registry = {
        "canonical_runs": [
            {
                "run_id": future_run_id,
                "report_path": str(future_report_path),
                "snapshot": {"candidate_date": snapshot_date},
            }
        ]
    }

    history = _load_project_report_history(
        settings,
        current_run_id=current_run_id,
        current_generated_at=current_generated_at,
        current_filtered_excel=current_excel,
        current_final_count=306,
        current_nav_snapshot_date=snapshot_date,
        publication_registry_builder=lambda _settings: registry,
    )

    assert [item["run_id"] for item in history] == [current_run_id]
    assert history[0]["nav_snapshot_date"] == snapshot_date


