def test_low_vol_monthly_shadow_metrics_are_shared_with_report_and_audit_script() -> None:
    nav_dates = pd.to_datetime(
        [
            *pd.bdate_range("2026-01-05", periods=10).tolist(),
            *pd.bdate_range("2026-02-02", periods=10).tolist(),
            *pd.bdate_range("2026-03-02", periods=10).tolist(),
        ]
    )
    daily_growth_pct = pd.Series([0.05] * len(nav_dates), index=nav_dates)

    shared_metrics = _compute_low_vol_monthly_shadow_metrics(daily_growth_pct)

    module = _load_script_module(
        "audit_low_vol_risk_metric_distortion_shared_metrics_for_test",
        "scripts/audit_low_vol_risk_metric_distortion.py",
    )
    audit_metrics = module._compute_monthly_shadow_metrics_from_series(daily_growth_pct)

    assert shared_metrics["calendar_month_count"] == 3
    assert shared_metrics["positive_month_ratio_calendar_pct"] == 100.0
    assert audit_metrics["calendar_month_count"] == shared_metrics["calendar_month_count"]
    assert (
        audit_metrics["positive_month_ratio_calendar_pct"]
        == shared_metrics["positive_month_ratio_calendar_pct"]
    )


def test_daily_refresh_collects_before_screening_when_local_snapshot_already_advanced() -> None:
    scheduler = ProjectScheduler.__new__(ProjectScheduler)
    scheduler.settings = SimpleNamespace(
        database_path=Path("/tmp/unused.db"),
        latest_report_file=Path("/tmp/latest.json"),
        reports_dir=Path("/tmp/reports"),
        effective_nav_coverage_ratio=0.9,
        effective_nav_weekday_only=True,
    )
    scheduler.workflow_manager = SimpleNamespace(
        is_running=lambda: False,
        run_sync=lambda options: {"run_id": "screen_run_1", "counts": {"final_count": 123}},
    )
    scheduler._log = lambda message: None
    scheduler._build_host_runtime_snapshot = lambda: {
        "scheduler_service_runtime": {"unit_name": "fund-ana-scheduler.service", "running": True},
        "web_service_runtime": {"unit_name": "fund-ana-web.service", "running": True},
    }

    snapshot = SimpleNamespace(
        candidate_date="2026-04-08",
        signature="sig-1",
        to_dict=lambda: {"candidate_date": "2026-04-08", "signature": "sig-1", "ready": True},
    )

    with (
        patch("backend.scheduler.load_effective_nav_snapshot", return_value=snapshot),
        patch("backend.scheduler.load_latest_screened_db_snapshot", return_value={"candidate_date": "2026-04-07", "signature": "old"}),
        patch(
            "backend.scheduler.screening_snapshot_changed",
            side_effect=[
                (True, "effective_nav_snapshot_advanced"),
                (True, "effective_nav_snapshot_advanced"),
            ],
        ),
        patch("backend.scheduler.run_project_pipeline") as mocked_collection,
        patch(
            "backend.scheduler.run_nav_history_maintenance",
            return_value={"maintenance_result": {"processed_total": 0, "recovered_total": 0, "nav_records_inserted": 0}},
        ),
        patch(
            "backend.scheduler.run_autostock_nav_tail_fill",
            return_value={"maintenance_result": {"processed_total": 0, "shadow_fill_ready_total": 0}},
        ),
        patch(
            "backend.scheduler.run_long_term_history_maintenance",
            return_value={"maintenance_result": {"processed_total": 0, "annual_success_total": 0, "rank_success_total": 0}},
        ),
    ):
        result = ProjectScheduler._execute_daily_refresh(scheduler)

    mocked_collection.assert_called_once()
    collection_options = mocked_collection.call_args.args[1]
    assert collection_options["run_collection"] is True
    assert collection_options["run_screening"] is False
    assert collection_options["collection_profile"] == "daily"
    assert collection_options["skip_risk_calculation"] is False
    assert collection_options["risk_refresh_changed_nav_only"] is True
    assert result["status"] == "success"
    assert result["collection_skipped"] is False
    assert result["screening_triggered"] is True
    assert result["screening_reason"] == "effective_nav_snapshot_advanced"
    assert result["screening_final_count"] == 123
    assert result["host_runtime_snapshot"]["scheduler_service_runtime"]["unit_name"] == "fund-ana-scheduler.service"


