    assert collection_options["risk_refresh_changed_nav_only"] is True
    assert mocked_long_term_maintenance.call_args.kwargs["limit"] == 80
    assert mocked_long_term_maintenance.call_args.kwargs["refresh_stale"] is True
    assert len(workflow_calls) == 1
    assert workflow_calls[0]["run_collection"] is False
    assert workflow_calls[0]["run_screening"] is True
    assert workflow_calls[0]["risk_refresh_changed_nav_only"] is True
    assert workflow_calls[0]["force_calculate_risk"] is True
    assert "skip_risk_calculation" not in workflow_calls[0]
    assert result["status"] == "success"
    assert result["collection_skipped"] is False
