def test_daily_refresh_lineage_rescreen_requirement_checks_task_history(tmp_path: Path) -> None:
    db_path = tmp_path / "lineage.db"
    latest_report = tmp_path / "latest.json"
    latest_report.write_text(json.dumps({"run_id": "manual_run_1"}), encoding="utf-8")
    conn = sqlite3.connect(db_path)
    try:
        conn.execute(
            """
            CREATE TABLE task_history (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                task_name TEXT,
                status TEXT,
                started_at TEXT,
                completed_at TEXT,
                duration REAL,
                records_processed INTEGER,
                records_succeeded INTEGER,
                records_failed INTEGER,
                error_message TEXT,
                error_traceback TEXT,
                extra_data TEXT
            )
            """
        )
        conn.execute(
            """
            INSERT INTO task_history (
                task_name, status, started_at, completed_at, records_failed, error_message, extra_data
            ) VALUES (?, ?, ?, ?, ?, ?, ?)
            """,
            (
                "scheduled_daily_bond_refresh",
                "success",
                "2026-06-08 07:30:00",
                "2026-06-08 07:40:00",
                0,
                None,
                json.dumps({"screening_run_id": "scheduled_run_1", "screening_triggered": True}),
            ),
        )
        conn.commit()
    finally:
        conn.close()

    scheduler = ProjectScheduler.__new__(ProjectScheduler)
    scheduler.settings = SimpleNamespace(database_path=db_path, latest_report_file=latest_report)

    missing = ProjectScheduler._daily_refresh_lineage_rescreen_required(scheduler, refresh_window="daily")
    assert missing["required"] is True
    assert missing["reason"] == "latest_report_missing_scheduled_daily_lineage"
    assert missing["latest_report_run_id"] == "manual_run_1"

    conn = sqlite3.connect(db_path)
    try:
        conn.execute(
            """
            INSERT INTO task_history (
                task_name, status, started_at, completed_at, records_failed, error_message, extra_data
            ) VALUES (?, ?, ?, ?, ?, ?, ?)
            """,
            (
                "scheduled_daily_bond_refresh",
                "success",
                "2026-06-08 08:30:00",
                "2026-06-08 08:40:00",
                0,
                None,
                json.dumps({"screening_run_id": "manual_run_1", "screening_triggered": True}),
            ),
        )
        conn.commit()
    finally:
        conn.close()

    repaired = ProjectScheduler._daily_refresh_lineage_rescreen_required(scheduler, refresh_window="daily")
    assert repaired["required"] is False
    assert repaired["reason"] == "lineage_ok"


