def _collect_funds_missing_semantics(missing_count: int) -> dict[str, Any]:
    def _field(raw_field: str, business_field: str) -> dict[str, Any]:
        return {
            "raw_field": raw_field,
            "business_field": business_field,
            "missing_count": missing_count,
            "raw_field_present_count": 10,
            "raw_field_absent_count": 0,
            "non_missing_count": 8,
            "value_type_counts": {"str": 10},
            "missing_reason_counts": {"raw_value_placeholder_text": missing_count},
            "missing_samples": [
                {
                    "page": 1,
                    "fcode": "000001",
                    "raw_field_present": True,
                    "raw_value_type": "str",
                    "missing_reason": "raw_value_placeholder_text",
                }
            ],
        }

    return {
        "schema_version": 1,
        "source": "fundMNRank",
        "truth_policy": "preserve_missing_semantics",
        "missing_value_handling": (
            "Missing snapshot fields are recorded as upstream missing evidence; "
            "the collector does not synthesize nav_date/nav_value or convert them to 0."
        ),
        "fields": {
            "FSRQ": _field("FSRQ", "nav_date"),
            "DWJZ": _field("DWJZ", "nav_value"),
        },
    }


def _collect_funds_evidence(*, include_missing_semantics: bool) -> dict[str, Any]:
    missing_count = 2
    type_evidence: dict[str, Any] = {
        "source": "fundMNRank",
        "fund_type": "31",
        "missing_nav_date_count": missing_count,
        "missing_nav_value_count": missing_count,
    }
    evidence: dict[str, Any] = {
        "schema_version": 2,
        "task": "collect-funds",
        "source": "fundMNRank",
        "fund_types": ["31"],
        "type_count": 1,
        "total_page_request_count": 1,
        "total_accepted_page_count": 1,
        "total_failed_page_count": 0,
        "total_declared_count": 10,
        "total_collected_record_count": 10,
        "unique_record_count": 10,
        "total_missing_nav_date_count": missing_count,
        "total_missing_nav_value_count": missing_count,
        "types": [type_evidence],
    }
    if include_missing_semantics:
        semantics = _collect_funds_missing_semantics(missing_count)
        evidence["snapshot_missing_semantics"] = semantics
        type_evidence["snapshot_missing_semantics"] = semantics
    return evidence


def _write_collect_funds_subprocess_log(
    project_root: Path,
    *,
    run_dir_name: str,
    started_at: str,
    finished_at: str,
    include_missing_semantics: bool,
) -> Path:
    log_dir = project_root / "reports" / ".audit" / "subprocess_logs" / run_dir_name
    log_dir.mkdir(parents=True, exist_ok=True)
    stdout_path = log_dir / "collect-funds.stdout.log"
    evidence = _collect_funds_evidence(include_missing_semantics=include_missing_semantics)
    stdout_path.write_text(
        "api_source_evidence=" + json.dumps(evidence, ensure_ascii=False) + "\n",
        encoding="utf-8",
    )
    index_path = log_dir / "subprocess_index.json"
    index_path.write_text(
        json.dumps(
            {
                "items": [
                    {
                        "task_name": "collect-funds",
                        "success": True,
                        "return_code": 0,
                        "timed_out": False,
                        "started_at": started_at,
                        "finished_at": finished_at,
                        "stdout_path": f"/app/reports/.audit/subprocess_logs/{run_dir_name}/{stdout_path.name}",
                    }
                ]
            }
        ),
        encoding="utf-8",
    )
    return index_path


def _write_scheduler_task_log(project_root: Path, index_path: Path) -> Path:
    task_log = project_root / "logs" / "tasks" / "task_1_scheduled_daily_bond_refresh.log"
    task_log.parent.mkdir(parents=True, exist_ok=True)
    relative_index = index_path.relative_to(project_root)
    task_log.write_text(
        f"2026-06-09 11:20:00 scheduled_daily_bond_refresh: "
        f"[core-pipeline] subprocess_index=/app/{relative_index.as_posix()} count=3 failed=0\n",
        encoding="utf-8",
    )
    return task_log


def _insert_scheduler_lineage_row(
    db_path: Path,
    *,
    run_id: str,
    task_log: Path,
    project_root: Path,
) -> None:
    conn = sqlite3.connect(db_path)
    try:
        conn.execute(
            """
            INSERT INTO task_history (
                task_name, status, started_at, completed_at, records_failed, error_message, extra_data
            ) VALUES (?, ?, ?, ?, ?, ?, ?)
            """,
            (
                "scheduled_daily_bond_refresh",
                "success",
                "2026-06-09 11:02:00",
                "2026-06-09 11:20:00",
                0,
                None,
                json.dumps(
                    {
                        "screening_run_id": run_id,
                        "screening_triggered": True,
                        "screening_reason": "automation_lineage_repair_rescreen",
                        "task_log_path": f"/app/{task_log.relative_to(project_root).as_posix()}",
                    }
                ),
            ),
        )
        conn.commit()
    finally:
        conn.close()


def _scheduler_for_lineage_contract_fixture(
    tmp_path: Path,
    *,
    run_id: str = "canonical_run_1",
    lineage_contract_has_missing_semantics: bool,
    write_newer_contract: bool,
) -> ProjectScheduler:
    db_path = tmp_path / "lineage.db"
    latest_report = tmp_path / "reports" / "latest.json"
    latest_report.parent.mkdir(parents=True, exist_ok=True)
    latest_report.write_text(json.dumps({"run_id": run_id}), encoding="utf-8")
    _create_scheduler_lineage_task_history(db_path)
    old_index = _write_collect_funds_subprocess_log(
        tmp_path,
        run_dir_name="20260609_110253",
        started_at="2026-06-09T11:02:56",
        finished_at="2026-06-09T11:11:25",
        include_missing_semantics=lineage_contract_has_missing_semantics,
    )
    task_log = _write_scheduler_task_log(tmp_path, old_index)
    _insert_scheduler_lineage_row(
        db_path,
        run_id=run_id,
        task_log=task_log,
        project_root=tmp_path,
    )
    if write_newer_contract:
        _write_collect_funds_subprocess_log(
            tmp_path,
            run_dir_name="20260609_131914",
            started_at="2026-06-09T13:19:16",
            finished_at="2026-06-09T13:28:51",
            include_missing_semantics=True,
        )

    scheduler = ProjectScheduler.__new__(ProjectScheduler)
    scheduler.settings = SimpleNamespace(
        database_path=db_path,
        latest_report_file=latest_report,
        reports_dir=tmp_path / "reports",
        project_root=tmp_path,
    )
    return scheduler


