def test_daily_refresh_caps_stale_long_term_maintenance_when_limit_non_positive() -> None:
    scheduler = ProjectScheduler.__new__(ProjectScheduler)
    scheduler.settings = SimpleNamespace(
        database_path=Path("/tmp/unused.db"),
        latest_report_file=Path("/tmp/latest.json"),
        reports_dir=Path("/tmp/reports"),
        scheduler_daily_nav_history_sync_enabled=True,
        scheduler_daily_nav_history_sync_limit=0,
        scheduler_daily_long_term_history_enabled=True,
        scheduler_daily_long_term_history_limit=0,
        scheduler_daily_long_term_history_refresh_stale=True,
        effective_nav_coverage_ratio=0.9,
        effective_nav_weekday_only=True,
    )
    scheduler.workflow_manager = SimpleNamespace(
        is_running=lambda: False,
        run_sync=lambda options: {"run_id": "screen_run_full", "counts": {"final_count": 12}},
    )
    scheduler._log = lambda message: None

    before_snapshot = SimpleNamespace(
        candidate_date="2026-04-11",
        signature="sig-1",
        to_dict=lambda: {"candidate_date": "2026-04-11", "signature": "sig-1", "ready": True},
    )
    after_snapshot = SimpleNamespace(
        candidate_date="2026-04-12",
        signature="sig-2",
        to_dict=lambda: {"candidate_date": "2026-04-12", "signature": "sig-2", "ready": True},
    )

    with (
        patch("backend.scheduler.load_effective_nav_snapshot", side_effect=[before_snapshot, after_snapshot]),
        patch("backend.scheduler.load_latest_screened_db_snapshot", return_value={"candidate_date": "2026-04-11", "signature": "old"}),
        patch("backend.scheduler.screening_snapshot_changed", side_effect=[(False, "effective_nav_date_already_screened"), (True, "effective_nav_snapshot_advanced")]),
        patch("backend.scheduler.run_project_pipeline"),
        patch("backend.scheduler.run_nav_history_maintenance", return_value={"maintenance_result": {"processed_total": 200}}) as mocked_nav_maintenance,
        patch(
            "backend.scheduler.run_autostock_nav_tail_fill",
            return_value={"maintenance_result": {"processed_total": 0, "shadow_fill_ready_total": 0}},
        ),
        patch("backend.scheduler.run_long_term_history_maintenance", return_value={"maintenance_result": {"processed_total": 150}}) as mocked_long_term_maintenance,
    ):
        result = ProjectScheduler._execute_daily_refresh(scheduler)

    assert mocked_nav_maintenance.call_args.kwargs["limit"] is None
    assert mocked_long_term_maintenance.call_args.kwargs["limit"] == 80
    assert mocked_long_term_maintenance.call_args.kwargs["refresh_stale"] is True
    assert result["status"] == "success"
    assert result["screening_triggered"] is True


