def test_finalize_task_attaches_task_run_audit_metadata_before_task_history_finish(monkeypatch) -> None:
    scheduler = ProjectScheduler.__new__(ProjectScheduler)
    scheduler.settings = SimpleNamespace()
    refresh_calls: list[str] = []
    monkeypatch.setattr("backend.scheduler.seal_task_run_audit", lambda *args: None)

    class _Recorder:
        def __init__(self):
            self.calls: list[dict[str, Any]] = []

        def finish_task(self, task_info, **kwargs):
            kwargs["extra_data"] = kwargs.pop("completion_result_factory")(datetime.now())
            self.calls.append(
                {
                    "task_info": dict(task_info),
                    **kwargs,
                }
            )
            return kwargs["extra_data"]

    recorder = _Recorder()
    scheduler.task_recorder = recorder
    scheduler.state_store = SimpleNamespace(
        finish_task=lambda task_name, result: None,
        stage_task_result=lambda task_name, result: None,
        set_jobs=lambda jobs: None,
    )
    scheduler._serialize_jobs = lambda: []
    scheduler._refresh_runtime_status_summary = lambda: refresh_calls.append("refreshed")
    scheduler._write_task_run_audit = lambda **kwargs: {
        "artifact_path": "reports/.audit/scheduler_task_runs/20260428/task.json",
        "artifact_path_relative": "reports/.audit/scheduler_task_runs/20260428/task.json",
        "artifact_project_path": "reports/.audit/scheduler_task_runs/20260428/task.json",
        "task_key": "intraday_refresh",
        "status": "degraded",
        "workflow_run_id": "20260428_230001_sync",
        "task_log_path": "logs/tasks/task_7_scheduled_intraday_bond_refresh.log",
        "task_log_path_relative": "logs/tasks/task_7_scheduled_intraday_bond_refresh.log",
        "task_log_project_path": "logs/tasks/task_7_scheduled_intraday_bond_refresh.log",
    }

    result = ProjectScheduler._finalize_task(
        scheduler,
        task_info={
            "id": 7,
            "task_name": "scheduled_intraday_bond_refresh",
            "started_at": "2026-04-28 23:00:01",
        },
        task_name="scheduled_intraday_bond_refresh",
        result={
            "task_name": "scheduled_intraday_bond_refresh",
            "status": "success",
            "started_at": "2026-04-28T23:00:01",
            "finished_at": "2026-04-28T23:05:00",
        },
    )

    assert result["task_run_audit"]["artifact_path"].endswith("task.json")
    assert result["task_run_audit"]["artifact_project_path"].endswith("task.json")
    assert result["task_run_audit_path"].endswith("task.json")
    assert recorder.calls[0]["extra_data"]["task_run_audit_path"].endswith("task.json")
    assert recorder.calls[0]["extra_data"]["task_run_audit"]["task_log_project_path"].endswith(".log")
    assert refresh_calls == ["refreshed"]


def test_finalize_task_compacts_large_task_history_extra_data_without_losing_closure_fields(
    tmp_path: Path, monkeypatch,
) -> None:
    scheduler = ProjectScheduler.__new__(ProjectScheduler)
