    class _Recorder:
        def finish_task(self, task_info, **kwargs):
            kwargs["extra_data"] = kwargs.pop("completion_result_factory")(datetime.now())
            recorder_calls.append({"task_info": dict(task_info), **kwargs})
            return kwargs["extra_data"]

    scheduler.task_recorder = _Recorder()
