def test_scheduler_workflow_subprocess_supports_skip_risk_calculation_flag(tmp_path: Path) -> None:
    scheduler = ProjectScheduler.__new__(ProjectScheduler)
    scheduler.settings = SimpleNamespace(
        project_root=tmp_path,
        run_collection_by_default=True,
        run_screening_by_default=True,
    )
    scheduler.workflow_manager = SimpleNamespace()

    captured: dict[str, Any] = {}

    class _FakeProcess:
        def __init__(self) -> None:
            self.stdout = iter(['{"run_id":"run-1","counts":{"final_count":1}}\n'])

        def wait(self) -> int:
            return 0

    def _fake_popen(cmd, cwd, stdout, stderr, text, bufsize):
        captured["cmd"] = list(cmd)
        captured["cwd"] = cwd
        return _FakeProcess()

    with patch("backend.scheduler.subprocess.Popen", side_effect=_fake_popen):
        result = ProjectScheduler._run_workflow_in_subprocess(
            scheduler,
            {
                "run_collection": False,
                "run_screening": True,
                "collection_profile": "daily",
                "force_calculate_risk": True,
                "risk_refresh_changed_nav_only": True,
                "risk_refresh_target_fcodes_file": str(tmp_path / "maintenance_targets.json"),
                "skip_risk_calculation": True,
            },
        )

    cmd = captured["cmd"]
    assert "--skip-collection" in cmd
    assert "--force-calculate-risk" in cmd
    assert "--risk-refresh-changed-nav-only" in cmd
    assert "--risk-refresh-target-fcodes-file" in cmd
    assert str(tmp_path / "maintenance_targets.json") in cmd
    assert "--skip-risk-calculation" in cmd
    assert result["run_id"] == "run-1"


