def test_embedded_scheduler_reuses_global_workflow_manager() -> None:
    import backend.app as backend_app

    original_scheduler = backend_app._embedded_scheduler
    original_inflight = backend_app._scheduler_bootstrap_inflight
    original_retry_after = backend_app._scheduler_bootstrap_retry_after
    original_should_bootstrap = backend_app._should_bootstrap_embedded_scheduler

    created: list[object] = []

    class FakeScheduler:
        def __init__(self, *, settings=None, workflow_manager=None, logger=None):
            self.settings = settings
            self.workflow_manager = workflow_manager
            self.logger = logger
            self._started = False
            created.append(self)

        def start(self):
            self._started = True

    try:
        backend_app._embedded_scheduler = None
        backend_app._scheduler_bootstrap_inflight = False
        backend_app._scheduler_bootstrap_retry_after = 0.0
        backend_app._should_bootstrap_embedded_scheduler = lambda: True

        with patch.object(backend_app, "ProjectScheduler", FakeScheduler):
            backend_app.ensure_embedded_scheduler()
            for _ in range(100):
                if created:
                    break
                time.sleep(0.01)

        assert created
        assert created[0].workflow_manager is backend_app.manager
        assert backend_app._embedded_scheduler is created[0]
        assert created[0]._started is True
    finally:
        backend_app._embedded_scheduler = original_scheduler
        backend_app._scheduler_bootstrap_inflight = original_inflight
        backend_app._scheduler_bootstrap_retry_after = original_retry_after
        backend_app._should_bootstrap_embedded_scheduler = original_should_bootstrap


def test_load_scheduler_status_defers_stale_recovery_to_exclusive_lease_owner(tmp_path: Path) -> None:
    state_file = tmp_path / "scheduler_state.json"
    heartbeat_file = tmp_path / "scheduler_heartbeat.json"
    state_file.write_text(
        json.dumps(
            {
                "scheduler_running": True,
                "pid": 999999,
                "started_at": "2026-04-09T09:31:59",
                "stopped_at": None,
                "last_heartbeat_at": "2026-04-09T09:33:59",
                "jobs": [{"id": "weekly_maintenance"}],
                "current_task": {
                    "task_name": "scheduled_weekly_bond_maintenance",
                    "started_at": "2026-04-09T09:31:59",
                },
                "last_runs": {},
                "last_error": None,
            },
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )
    heartbeat_file.write_text(
        json.dumps(
            {
                "heartbeat_at": "2026-04-09T09:33:59",
                "pid": 999999,
                "scheduler_running": True,
                "current_task": {
                    "task_name": "scheduled_weekly_bond_maintenance",
                    "started_at": "2026-04-09T09:31:59",
                },
            },
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    settings = SimpleNamespace(
        scheduler_state_file=state_file,
        scheduler_heartbeat_file=heartbeat_file,
        scheduler_enabled=True,
        database_path=tmp_path / "unused.db",
        effective_nav_coverage_ratio=0.9,
        effective_nav_weekday_only=True,
        latest_report_file=tmp_path / "latest.json",
    )

    snapshot = SimpleNamespace(to_dict=lambda: {"candidate_date": "2026-04-08", "ready": True})

    with (
        patch.object(ProjectScheduler, "_pid_is_alive", return_value=False),
        patch("backend.scheduler.load_effective_nav_snapshot", return_value=snapshot),
        patch("backend.scheduler.load_latest_screened_db_snapshot", return_value=None),
    ):
        payload = load_scheduler_status(settings)

    assert payload["scheduler_running"] is False
    assert payload["scheduler_state_claimed_running"] is True
    assert payload["scheduler_recovery_deferred"] is True
    assert payload["scheduler_recovery_boundary"] == "exclusive_scheduler_lease_owner_only"
    assert payload["pid"] == 999999
    assert payload["current_task"]["task_name"] == "scheduled_weekly_bond_maintenance"
    assert payload["last_error"] is None

    heartbeat_payload = json.loads(heartbeat_file.read_text(encoding="utf-8"))
    assert heartbeat_payload["scheduler_running"] is True
    assert heartbeat_payload["pid"] == 999999
    assert heartbeat_payload["current_task"]["task_name"] == "scheduled_weekly_bond_maintenance"


