def test_task_recorder_recovers_stale_running_rows(tmp_path: Path) -> None:
    db_path = tmp_path / "runtime.db"
    recorder = SqliteTaskRecorder(db_path)
    recorder.start_task("scheduled_daily_bond_refresh")
    recorder.start_task("scheduled_weekly_bond_maintenance")

    result = recorder.recover_stale_tasks("scheduler_process_missing")

    assert result["recovered_total"] == 2
    assert result["recovered_task_names"] == [
        "scheduled_daily_bond_refresh",
        "scheduled_weekly_bond_maintenance",
    ]

    conn = sqlite3.connect(db_path)
    try:
        history_rows = conn.execute(
            "SELECT task_name, status, completed_at, error_message FROM task_history ORDER BY id"
        ).fetchall()
        status_rows = conn.execute(
            "SELECT task_name, status, completed_at, error_message FROM task_status ORDER BY task_name"
        ).fetchall()
    finally:
        conn.close()

    assert all(row[1] == "failed" for row in history_rows)
    assert all(row[2] for row in history_rows)
    assert all(row[3] == "scheduler_process_missing" for row in history_rows)
    assert all(row[1] == "failed" for row in status_rows)
    assert all(row[2] for row in status_rows)
    assert all(row[3] == "scheduler_process_missing" for row in status_rows)


def test_load_database_overview_exposes_freshness_guidance(tmp_path: Path) -> None:
    import backend.app as backend_app

    db_path = tmp_path / "funds.db"
    conn = sqlite3.connect(db_path)
    try:
        conn.execute("CREATE TABLE funds (fcode TEXT, last_updated_at TEXT)")
        conn.execute("CREATE TABLE fund_returns (fcode TEXT, latest_nav_date TEXT, last_updated_at TEXT)")
        conn.execute("CREATE TABLE fund_nav_history (fcode TEXT, nav_date TEXT)")
        conn.execute("CREATE TABLE fund_risk_metrics (fcode TEXT, period TEXT, end_date TEXT, calculated_at TEXT)")
        conn.execute("INSERT INTO funds VALUES ('000001', '2026-04-20T23:38:02')")
        conn.execute("INSERT INTO fund_returns VALUES ('000001', '2026-04-20', '2026-04-20T23:38:28')")
        conn.execute("INSERT INTO fund_nav_history VALUES ('000001', '2026-04-20')")
        conn.execute("INSERT INTO fund_risk_metrics VALUES ('000001', '1y', '2026-04-20', '2026-04-21 08:23:31.451208')")
        conn.commit()
    finally:
        conn.close()

    original_db_path = backend_app.settings.database_path
    try:
        backend_app.settings.database_path = db_path
        with patch.object(backend_app, "load_autostock_nav_tail_fill_snapshot", return_value={}):
            overview = backend_app._load_database_overview({"candidate_date": "2026-04-20", "ready": True})
    finally:
        backend_app.settings.database_path = original_db_path

    guidance = overview["freshness_guidance"]
    assert guidance["primary_fields"] == [
        "latest_nav_business_date",
        "risk_1y_business_date",
        "nav_data_updated_at",
        "risk_data_updated_at",
    ]
    assert guidance["meta_field"] == "fund_meta_updated_at"
    assert guidance["meta_field_role"] == "metadata_only"
    assert "fund_meta_updated_at" in guidance["summary"]
    assert overview["fund_meta_updated_at"] == "2026-04-20T23:38:02"
    assert overview["nav_data_updated_at"] == "2026-04-20T23:38:28"
    assert overview["risk_data_updated_at"] == "2026-04-21 08:23:31.451208"
    assert overview["replay_precision_status"] == "missing"
    assert overview["auxiliary_scope"] == "cross_run_current_db_state"


