def test_scheduler_post_task_catch_up_enqueues_daily_after_weekly_completion(tmp_path: Path) -> None:
    scheduler = ProjectScheduler.__new__(ProjectScheduler)
    state_store = SchedulerStateStore(tmp_path / "post-task-catchup-state.json")
    state_store._persist({**state_store._default_state(), "current_task": None})
    scheduler.state_store = state_store
    scheduler.stop_event = threading.Event()
    scheduler._manual_run_lock = threading.Lock()
    scheduler._post_task_catch_up_lock = threading.Lock()
    scheduler._log = lambda message: None  # type: ignore[method-assign]
    scheduler._resolve_startup_catch_up_jobs = lambda: ["weekly_maintenance", "daily_refresh"]  # type: ignore[method-assign]

    ProjectScheduler._enqueue_post_task_catch_up_if_needed(
        scheduler,
        completed_task_name="scheduled_weekly_bond_maintenance",
    )

    snapshot = state_store.snapshot()
    queue = snapshot["pending_manual_run_requests"]
    assert [item["job_id"] for item in queue] == ["daily_refresh"]
    assert queue[0]["task_name"] == "scheduled_daily_bond_refresh"
    assert queue[0]["requested_by"] == "automation"
    assert queue[0]["execution_mode"] == "automatic_post_task_catch_up"
    assert queue[0]["trigger_source"] == "post_task_catch_up"
    assert queue[0]["trigger_completed_task_name"] == "scheduled_weekly_bond_maintenance"


