def test_run_scheduler_cli_allows_intraday_refresh_once() -> None:
    module = _load_script_module("run_scheduler_script_for_test", "scripts/run_scheduler.py")

    with (
        patch.object(sys, "argv", ["run_scheduler.py", "--once", "intraday_refresh"]),
        patch("backend.config.load_settings", return_value=SimpleNamespace(
            scheduler_enabled=True,
            scheduler_host_mode="embedded_web",
            # P0-01: run_scheduler.py 启动时会调用 ensure_database_schema(settings)，
            # mock settings 需要具备最少的路径字段以通过 bootstrap。
            project_root=PROJECT_ROOT,
            core_root=CORE_ROOT,
            database_path=PROJECT_ROOT / "backend" / "data" / "bond_funds.db",
        )),
        patch("backend.schema_bootstrap.ensure_database_schema", return_value=None),
        patch("backend.scheduler.ProjectScheduler") as scheduler_cls,
    ):
        scheduler = scheduler_cls.return_value
        scheduler.run_once.return_value = {
            "task_name": "scheduled_intraday_bond_refresh",
            "status": "success",
        }
        exit_code = module.main()

    assert exit_code == 0
    scheduler.run_once.assert_called_once_with("intraday_refresh")


