def test_wait_for_manual_run_completion_emits_scheduler_and_workflow_progress(
    tmp_path: Path,
    capsys,
) -> None:
    module = _load_script_module("run_scheduler_script_for_test_progress", "scripts/run_scheduler.py")
    state_file = tmp_path / "scheduler_state.json"
    workflow_state_file = tmp_path / "workflow_state.json"
    publication_registry_file = tmp_path / "publication_registry.json"
    state_file.write_text("{}", encoding="utf-8")
    workflow_state_file.write_text("{}", encoding="utf-8")
    publication_registry_file.write_text(
        json.dumps(
            {
                "current_published_run_id": "20260428_213851_sync",
                "automation_layers": {
                    "latest_successful_is_currently_published": False,
                    "latest_successful_run": {
                        "run_id": "20260428_221001_sync",
                        "publishable": False,
                        "publish_hold": False,
                        "publish_hold_reason_codes": [],
                        "primary_blocker_code": "risk_coverage_insufficient",
                        "primary_blocker_label": "风险覆盖不足",
                        "primary_blocker_detail": "0.72 < 0.80",
                        "publish_blockers": [
                            {
                                "code": "risk_coverage_insufficient",
                                "severity": "blocking",
                                "blocking": True,
                            }
                        ],
                        "publish_governance_summary": {
                            "status": "blocked",
                            "primary_blocker_code": "risk_coverage_insufficient",
                        },
                    },
                },
            },
            ensure_ascii=False,
        ),
        encoding="utf-8",
    )

    settings = SimpleNamespace(
        scheduler_state_file=state_file,
        state_file=workflow_state_file,
        publication_registry_file=publication_registry_file,
    )
    scheduler_snapshots = [
        {
            "manual_run_history": [
                {
                    "request_id": "req-progress",
                    "job_id": "intraday_refresh",
                    "task_name": "scheduled_intraday_bond_refresh",
                    "status": "accepted",
                }
            ],
            "current_task": {
                "task_name": "scheduled_intraday_bond_refresh",
                "started_at": "2026-04-28T22:10:01",
            },
        },
        {
            "manual_run_history": [
                {
                    "request_id": "req-progress",
                    "job_id": "intraday_refresh",
                    "task_name": "scheduled_intraday_bond_refresh",
                    "status": "success",
                    "workflow_run_id": "20260428_221001_sync",
                    "result": {
                        "warning_reason": "risk_coverage_insufficient",
                    },
                }
            ],
            "current_task": None,
        },
    ]
    workflow_snapshots = [
        {
            "status": "succeeded",
            "phase": "completed",
            "run_id": "20260428_214737_sync",
            "last_log": "当前发布报告: reports/runs/20260428_213851_sync/bond_analysis_report_20260428_213851_sync.md",
        },
        {
            "status": "running",
            "phase": "running-core-workflow",
            "run_id": "20260428_221001_sync",
            "last_log": "开始运行批次 20260428_221001_sync",
        },
        {
            "status": "succeeded",
            "phase": "completed",
            "run_id": "20260428_221001_sync",
            "last_log": "当前批次报告生成完成",
        },
    ]

    with (
        patch("backend.scheduler_state.SchedulerStateStore.snapshot", side_effect=scheduler_snapshots),
        patch.object(module, "_load_workflow_runtime_snapshot", side_effect=workflow_snapshots),
        patch.object(module.time, "time", side_effect=[0.0, 0.0, 0.2]),
        patch.object(module.time, "sleep", return_value=None),
    ):
        result = module._wait_for_manual_run_completion(
            settings,
            "req-progress",
            timeout_seconds=1,
            execution_mode="external_scheduler_queue",
            emit_progress=True,
            poll_interval_seconds=0.1,
        )

    assert result["status"] == "degraded"
    assert result["execution_mode"] == "external_scheduler_queue"
    assert result["status_detail"] == "publication_blocked_unpublished"
    assert result["warning_reason"] == "formal_publication_blocked_unpublished"
    assert result["degraded_stage"] == "formal_publication"
    assert result["publication_result"]["status"] == "blocked"
    assert result["publication_result"]["primary_blocker_code"] == "risk_coverage_insufficient"

    progress_lines = [
        json.loads(line)
        for line in capsys.readouterr().err.splitlines()
        if line.strip()
    ]
    progress_events = [line["event"] for line in progress_lines]

    assert progress_events[0] == "waiting_for_scheduler_claim"
    assert "scheduler_task_started" in progress_events
    assert progress_events[-1] == "terminal_status"
    assert not any(
        line["event"] == "workflow_state" and line.get("workflow_run_id") == "20260428_214737_sync"
        for line in progress_lines
    )
    assert any(
        line["event"] == "workflow_state" and line.get("workflow_phase") == "running-core-workflow"
        for line in progress_lines
    )
    assert any(
        line["event"] == "workflow_state" and line.get("workflow_phase") == "completed"
        for line in progress_lines
    )
    assert any(
        line["event"] == "terminal_status"
        and line.get("status") == "degraded"
        and line.get("status_detail") == "publication_blocked_unpublished"
        and line.get("warning_reason") == "risk_coverage_insufficient"
        and line.get("publication_status") == "blocked"
        and line.get("primary_blocker_code") == "risk_coverage_insufficient"
        for line in progress_lines
    )


