    assert exit_code == 1
    assert result["status"] == "rejected"
    assert result["error_code"] == "scheduler_busy"
    assert progress_lines[-1]["event"] == "request_not_accepted"
    assert progress_lines[-1]["status"] == "rejected"
    assert progress_lines[-1]["error_code"] == "scheduler_busy"


