def test_scheduler_internal_run_once_endpoint_requires_loopback_and_bypasses_manual_mode() -> None:
    import backend.app as backend_app

    client = backend_app.app.test_client()
    fake_scheduler = SimpleNamespace(
        request_manual_run=lambda job_id, requested_by="api": {
            "request_id": "req-internal",
            "job_id": job_id,
            "task_name": "scheduled_intraday_bond_refresh",
            "status": "accepted",
            "requested_at": "2026-04-20T21:00:00",
        }
    )

    with (
        patch.object(backend_app, "MANUAL_OPERATION_MODE", False),
        patch.object(backend_app, "_get_live_scheduler", return_value=fake_scheduler),
    ):
        forbidden = client.post(
            "/api/scheduler/internal-run-once",
            json={"job_id": "intraday_refresh"},
            headers={"X-Fund-ANA-Internal-Run": "scheduler-cli"},
            environ_overrides={"REMOTE_ADDR": "10.0.0.8"},
        )
        accepted = client.post(
            "/api/scheduler/internal-run-once",
            json={"job_id": "intraday_refresh"},
            headers={"X-Fund-ANA-Internal-Run": "scheduler-cli"},
            environ_overrides={"REMOTE_ADDR": "127.0.0.1"},
        )

    assert forbidden.status_code == 403
    assert accepted.status_code == 202
    payload = accepted.get_json()
    assert payload["status"] == "accepted"
    assert payload["job_id"] == "intraday_refresh"


