def test_retire_embedded_scheduler_when_external_scheduler_is_alive(tmp_path: Path) -> None:
    state_file = tmp_path / "scheduler_state.json"
    heartbeat_file = tmp_path / "scheduler_heartbeat.json"
    lock_file = tmp_path / "scheduler.lease"
    pid_file = tmp_path / "scheduler.pid"

    import backend.app as backend_app

    original_settings = backend_app.settings
    original_scheduler = backend_app._embedded_scheduler
    shutdown_calls: list[str] = []

    class FakeScheduler:
        _started = True

        def shutdown(self):
            shutdown_calls.append("shutdown")

    runtime_settings = SimpleNamespace(
            scheduler_enabled=True,
            scheduler_host_mode="embedded_web",
            scheduler_state_file=state_file,
            scheduler_heartbeat_file=heartbeat_file,
            scheduler_lock_file=lock_file,
            scheduler_pid_file=pid_file,
            scheduler_heartbeat_interval_seconds=60,
            scheduler_heartbeat_stale_after_seconds=180,
        )
    lease_owner = ProjectScheduler.__new__(ProjectScheduler)
    lease_owner.settings = SimpleNamespace(
        **{**runtime_settings.__dict__, "scheduler_host_mode": "external_process"}
    )
    lease_owner.state_store = SchedulerStateStore(state_file)
    lease_owner.scheduler_instance_id = "external-instance"
    lease_owner._scheduler_lease_handle = None
    lease_owner._scheduler_lease_path = None
    lease_owner._ensure_single_instance()
    lease_owner._mark_state_started()
    lease_owner._write_heartbeat_file()
    try:
        backend_app.settings = runtime_settings
        backend_app._embedded_scheduler = FakeScheduler()
        backend_app._retire_embedded_scheduler_if_disallowed()

        assert shutdown_calls == ["shutdown"]
        assert backend_app._embedded_scheduler is None
    finally:
        backend_app.settings = original_settings
        backend_app._embedded_scheduler = original_scheduler
        lease_owner.state_store.mark_stopped(scheduler_instance_id="external-instance")
        lease_owner._cleanup_pid_file()
        lease_owner._release_single_instance()


