def test_project_scheduler_heartbeat_loop_stops_when_runtime_config_disallows_host(tmp_path: Path) -> None:
    config_path = tmp_path / "project.yaml"
    config_path.write_text(
        yaml.safe_dump(
            {
                "paths": {
                    "database_path": str(tmp_path / "bond_funds.db"),
                    "state_file": str(tmp_path / "workflow_state.json"),
                    "reports_dir": str(tmp_path / "reports"),
                    "runs_dir": str(tmp_path / "reports" / "runs"),
                    "core_output_dir": str(tmp_path / "reports" / "core_output"),
                    "latest_report_file": str(tmp_path / "reports" / "latest.json"),
                    "publication_registry_file": str(tmp_path / "reports" / "publication_registry.json"),
                    "favorites_history_file": str(tmp_path / "backend" / "data" / "favorite_fund_queries.json"),
                    "archived_runs_dir": str(tmp_path / "reports" / "archive" / "superseded_runs"),
                },
                "scheduler": {
                    "enabled": True,
                    "host_mode": "external_process",
                    "state_file": str(tmp_path / "scheduler_state.json"),
                    "heartbeat_file": str(tmp_path / "scheduler_heartbeat.json"),
                    "pid_file": str(tmp_path / "scheduler.pid"),
                    "heartbeat_interval_seconds": 60,
                },
            },
            allow_unicode=True,
        ),
        encoding="utf-8",
    )

    heartbeat_calls: list[str] = []
    shutdown_calls: list[str] = []
    scheduler = ProjectScheduler.__new__(ProjectScheduler)
    scheduler.settings = SimpleNamespace(
        config_path=config_path,
        scheduler_enabled=True,
        scheduler_host_mode="embedded_web",
        scheduler_heartbeat_interval_seconds=60,
    )
    scheduler.stop_event = threading.Event()
    scheduler.state_store = SimpleNamespace(heartbeat=lambda: heartbeat_calls.append("heartbeat"))
    scheduler._write_heartbeat_file = lambda: heartbeat_calls.append("write")
    scheduler.shutdown = lambda: shutdown_calls.append("shutdown") or scheduler.stop_event.set()
    scheduler._log = lambda _message: None

    scheduler._heartbeat_loop()

    assert scheduler.stop_event.is_set() is True
    assert heartbeat_calls == []
    assert shutdown_calls == ["shutdown"]


