def test_risk_sync_audit_demotes_cadence_tail_candidates_from_actionable_total(tmp_path: Path) -> None:
    db_path = tmp_path / "risk_sync_cadence.db"
    conn = sqlite3.connect(db_path)
    try:
        conn.execute(
            "CREATE TABLE funds (fcode TEXT PRIMARY KEY, shortname TEXT, ftype TEXT, type_code TEXT, has_holding_period INTEGER DEFAULT 0, holding_days INTEGER DEFAULT 0)"
        )
        conn.execute("CREATE TABLE fund_returns (fcode TEXT PRIMARY KEY, latest_nav_date TEXT)")
        conn.execute("CREATE TABLE fund_nav_history (fcode TEXT, nav_date TEXT)")
        conn.execute("CREATE TABLE fund_risk_metrics (fcode TEXT, period TEXT, end_date TEXT)")
        conn.executemany(
            "INSERT INTO funds VALUES (?, ?, ?, ?, ?, ?)",
            [
                ("000001", "测试90天滚动持有债券A", "债券型-长债", "31", 1, 90),
                ("000002", "普通开放债券A", "债券型-长债", "31", 0, 0),
            ],
        )
        conn.executemany(
            "INSERT INTO fund_returns VALUES (?, ?)",
            [
                ("000001", "2026-04-09"),
                ("000002", "2026-04-09"),
            ],
        )
        nav_rows = []
        nav_rows.extend(_nav_rows_for_code("000001", "2025-04-09", "2026-04-09"))
        nav_rows.extend(_nav_rows_for_code("000002", "2025-04-09", "2026-04-09"))
        conn.executemany("INSERT INTO fund_nav_history VALUES (?, ?)", nav_rows)
        conn.executemany(
            "INSERT INTO fund_risk_metrics VALUES (?, ?, ?)",
            [
                ("000001", "1y", "2026-04-08"),
                ("000002", "1y", "2026-04-08"),
            ],
        )
        conn.commit()
    finally:
        conn.close()

    settings = SimpleNamespace(
        project_root=PROJECT_ROOT,
        database_path=db_path,
        reports_dir=tmp_path / "reports",
    )

    payload = build_risk_sync_audit(settings)

    assert payload["period_eligible_gap_candidate_total"] == 2
    assert payload["actionable_candidate_total"] == 1
    assert payload["low_priority_cadence_tail_total"] == 1
    actionable_codes = {item["fcode"] for item in payload["actionable_candidate_samples"]}
    cadence_codes = {item["fcode"] for item in payload["low_priority_cadence_tail_samples"]}
    assert actionable_codes == {"000002"}
    assert cadence_codes == {"000001"}


