def test_long_term_gap_audit_cache_key_ignores_scheduler_heartbeat_churn(tmp_path: Path) -> None:
    import backend.app as backend_app

    db_path = tmp_path / "bond_funds.db"
    db_path.write_text("", encoding="utf-8")
    scheduler_state_file = tmp_path / "scheduler_state.json"
    scheduler_state_file.write_text("{}", encoding="utf-8")
    maintenance_state_file = tmp_path / "long_term_history_maintenance_state.json"
    maintenance_state_file.write_text("{}", encoding="utf-8")

    settings = SimpleNamespace(
        database_path=db_path,
        scheduler_state_file=scheduler_state_file,
    )

    calls = {"build_count": 0, "input_count": 0}

    def _fake_inputs():
        calls["input_count"] += 1
        return ([], [], {}, [], {}, [], {})

    def _fake_builder(_settings, *, include_stale_candidates=True, universe=None, candidates=None, stats=None, failure_backoff=None, write_artifact=False):
        calls["build_count"] += 1
        return {"build_seq": calls["build_count"], "include_stale_candidates": include_stale_candidates}

    backend_app._payload_cache.clear()
    backend_app._payload_cache_inflight.clear()
    with (
        patch.object(backend_app, "settings", settings),
        patch("backend.app._maintenance_state_path", return_value=maintenance_state_file),
        patch.object(backend_app, "_load_long_term_gap_audit_bundle_inputs", side_effect=_fake_inputs),
        patch("backend.app.build_long_term_history_gap_audit", side_effect=_fake_builder),
    ):
        first = backend_app._load_long_term_gap_audit_cached()
        scheduler_state_file.write_text('{"last_heartbeat_at":"2026-05-22T08:10:00"}', encoding="utf-8")
        second = backend_app._load_long_term_gap_audit_cached()
        maintenance_state_file.write_text('{"failure_backoff":{"000001":{"consecutive_failures":2}}}', encoding="utf-8")
        third = backend_app._load_long_term_gap_audit_cached()

    assert first["build_seq"] == 1
    assert second["build_seq"] == 1
    assert third["build_seq"] == 3
    assert calls["input_count"] == 2
    assert calls["build_count"] == 4


def test_long_term_gap_audit_bundle_shared_inputs_avoid_duplicate_universe_reads() -> None:
    import backend.app as backend_app

    calls = {"input_count": 0, "full_count": 0, "no_stale_count": 0}

    def _fake_inputs():
        calls["input_count"] += 1
        return ([], [], {}, [], {}, [], {})

    def _fake_builder(_settings, *, include_stale_candidates=True, universe=None, candidates=None, stats=None, failure_backoff=None, write_artifact=False):
        if include_stale_candidates:
            calls["full_count"] += 1
            return {"variant": "full", "build_seq": calls["full_count"]}
        calls["no_stale_count"] += 1
        return {"variant": "no_stale", "build_seq": calls["no_stale_count"]}

    backend_app._payload_cache.clear()
    backend_app._payload_cache_inflight.clear()
    with (
        patch.object(backend_app, "_load_long_term_gap_audit_bundle_inputs", side_effect=_fake_inputs),
        patch.object(backend_app, "build_long_term_history_gap_audit", side_effect=_fake_builder),
    ):
        full = backend_app._load_long_term_gap_audit_cached()
        no_stale = backend_app._load_long_term_no_stale_audit_cached()

    assert full["variant"] == "full"
    assert no_stale["variant"] == "no_stale"
    assert calls["input_count"] == 1
    assert calls["full_count"] == 1
    assert calls["no_stale_count"] == 1


