def test_load_risk_lag_summary_cache_reuses_file_signature_and_invalidates_on_audit_change(
    tmp_path: Path,
) -> None:
    import backend.app as backend_app

    reports_dir = tmp_path / "reports"
    audit_dir = reports_dir / "audit" / "risk_lag_audit"
    audit_dir.mkdir(parents=True, exist_ok=True)
    latest_report_file = reports_dir / "latest.json"
    latest_report_file.write_text(
        json.dumps({"run_id": "20260520_073000_sync", "audit_files": {}}, ensure_ascii=False),
        encoding="utf-8",
    )
    publication_registry_file = reports_dir / "publication_registry.json"
    publication_registry_file.write_text(
        json.dumps({"latest_canonical_run_id": "20260520_073000_sync"}, ensure_ascii=False),
        encoding="utf-8",
    )
    (audit_dir / "risk_lag_audit_20260520_073000.json").write_text(
        json.dumps({"candidate_date": "2026-05-19"}, ensure_ascii=False),
        encoding="utf-8",
    )
    settings = SimpleNamespace(
        project_root=tmp_path,
        reports_dir=reports_dir,
        latest_report_file=latest_report_file,
        publication_registry_file=publication_registry_file,
    )
    calls = {"count": 0}

    def _fake_uncached() -> dict[str, object]:
        calls["count"] += 1
        return {
            "build_seq": calls["count"],
            "samples": [{"fcode": f"{calls['count']:06d}"}],
        }

    backend_app._payload_cache.clear()
    backend_app._payload_cache_inflight.clear()
    try:
        with (
            patch.object(backend_app, "settings", settings),
            patch.object(backend_app, "_load_risk_lag_summary_uncached", side_effect=_fake_uncached),
        ):
            first = backend_app._load_risk_lag_summary()
            first["samples"][0]["fcode"] = "mutated"
            second = backend_app._load_risk_lag_summary()
            (audit_dir / "risk_lag_audit_20260520_080000.json").write_text(
                json.dumps({"candidate_date": "2026-05-19"}, ensure_ascii=False),
                encoding="utf-8",
            )
            third = backend_app._load_risk_lag_summary()
    finally:
        backend_app._payload_cache.clear()
        backend_app._payload_cache_inflight.clear()

    assert calls["count"] == 2
    assert second["build_seq"] == 1
    assert second["samples"][0]["fcode"] == "000001"
    assert third["build_seq"] == 2


