def test_semantic_null_snapshot_audit_summary_reuses_matching_signature_cache() -> None:
    import backend.long_term_governance as ltg

    with ltg._semantic_null_snapshot_audit_cache_lock:
        ltg._semantic_null_snapshot_audit_cache.clear()

    try:
        with (
            patch(
                "backend.config.load_settings",
                return_value=SimpleNamespace(database_path=Path("/tmp/fund-ana-test.db")),
            ),
            patch.object(
                ltg,
                "_load_matching_nav_archive_binding",
                return_value={"archive_path": "/tmp/fund-ana-nav-archive.db"},
            ),
            patch.object(
                ltg,
                "_build_semantic_null_snapshot_audit_cache_signature",
                side_effect=[
                    ("semantic-null-audit", 1),
                    ("semantic-null-audit", 1),
                    ("semantic-null-audit", 2),
                ],
            ),
            patch.object(
                ltg,
                "_build_semantic_null_snapshot_audit_summary_uncached",
                side_effect=[
                    {
                        "available": True,
                        "semantic_total": 1,
                        "samples": [{"fcode": "000001"}],
                    },
                    {
                        "available": True,
                        "semantic_total": 2,
                        "samples": [{"fcode": "000002"}],
                    },
                ],
            ) as uncached_mock,
        ):
            first = ltg._build_semantic_null_snapshot_audit_summary()
            first["samples"][0]["fcode"] = "mutated"

            second = ltg._build_semantic_null_snapshot_audit_summary()
            third = ltg._build_semantic_null_snapshot_audit_summary()

        assert uncached_mock.call_count == 2
        assert second["semantic_total"] == 1
        assert second["samples"][0]["fcode"] == "000001"
        assert third["semantic_total"] == 2
        assert third["samples"][0]["fcode"] == "000002"
    finally:
        with ltg._semantic_null_snapshot_audit_cache_lock:
            ltg._semantic_null_snapshot_audit_cache.clear()


def test_ensure_api_prewarm_includes_dashboard_diagnostic_summary(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import backend.app as backend_app

    calls: list[str] = []

    class _ImmediateThread:
        def __init__(self, target=None, args=(), daemon=None):
            self._target = target
            self._args = args

        def start(self):
            if self._target is not None:
                self._target(*self._args)

    monkeypatch.setattr(backend_app.threading, "Thread", _ImmediateThread)
    monkeypatch.setattr(backend_app, "_api_prewarm_started", False)
    stripped_modules = dict(backend_app.sys.modules)
    stripped_modules.pop("pytest", None)
    monkeypatch.setattr(backend_app.sys, "modules", stripped_modules)
    monkeypatch.delenv("PYTEST_CURRENT_TEST", raising=False)
    monkeypatch.delenv("FUND_ANA_DISABLE_API_PREWARM", raising=False)

    monkeypatch.setattr(backend_app, "_build_latest_dashboard_compact_cached", lambda: calls.append("compact"))
    monkeypatch.setattr(backend_app, "_build_dashboard_overview_cached", lambda: calls.append("overview"))
    monkeypatch.setattr(
        backend_app,
        "_build_latest_dashboard_scoped_detail_cached",
        lambda scope: calls.append(f"detail:{scope}"),
    )
    monkeypatch.setattr(backend_app, "_load_latest_report_cached", lambda: calls.append("latest_report"))
    monkeypatch.setattr(backend_app, "_load_publication_registry_cached", lambda: calls.append("publication"))
    monkeypatch.setattr(backend_app, "_build_scheduler_status_summary_cached", lambda: calls.append("scheduler_summary"))
    monkeypatch.setattr(backend_app, "_build_scheduler_status_detail_cached", lambda: calls.append("scheduler_detail"))
    monkeypatch.setattr(backend_app, "_load_database_integrity_summary", lambda: calls.append("db_integrity"))
    monkeypatch.setattr(backend_app, "_load_long_term_no_stale_audit_cached", lambda: calls.append("long_term_no_stale"))
    monkeypatch.setattr(backend_app, "_load_long_term_gap_audit_cached", lambda: calls.append("long_term_gap"))
    monkeypatch.setattr(
        backend_app,
        "_cached_payload",
        lambda cache_key, ttl_seconds, builder: calls.append(f"cached:{cache_key}"),
    )

    backend_app._ensure_api_prewarm()

    assert "detail:diagnostic_summary" in calls


