def test_risk_analyzer_sortino_uses_full_period_downside_deviation_with_mar() -> None:
    end_date = pd.Timestamp(datetime.now().date())
    dates = pd.date_range(end=end_date, periods=31, freq="12D")
    daily_growth = [None] + [0.10] * 15 + [-0.02] * 15
    nav_values = [1.0]
    for growth in daily_growth[1:]:
        nav_values.append(nav_values[-1] * (1 + growth / 100))

    nav_data = pd.DataFrame(
        {
            "nav": nav_values,
            "accum_nav": nav_values,
            "daily_growth": daily_growth,
        },
        index=dates,
    )

    analyzer = RiskAnalyzer(
        config={
            "risk_metrics": {
                "min_data_points": 30,
                "period_coverage_grace_days": 7,
                "max_metric_nav_lag_days": 30,
                "api_return_alignment_grace_days": 7,
                "risk_free_rate": 0.015,
                "mar": 0.0,
            }
        },
        db_manager=object(),
    )

    metrics = analyzer._calculate_period_metrics(
        nav_data,
        "1y",
        api_snapshot_date=end_date.date().isoformat(),
    )

    assert metrics is not None
    # These 12-day observations use NAV interval returns. All 30 intervals
    # belong to the window, including the interval after the first NAV point.
    returns = np.array([right / left - 1 for left, right in zip(nav_values, nav_values[1:])])
    assert metrics["data_points"] == len(returns) == 30
    actual_years = max((dates.max() - dates.min()).days / 365.25, 1 / 365.25)
    periods_per_year = len(returns) / actual_years
    downside_diff = np.minimum(returns, 0.0)
    downside_std = float(np.sqrt(np.mean(downside_diff * downside_diff)) * np.sqrt(periods_per_year))
    annual_return = (nav_values[-1] / nav_values[0]) ** (1 / actual_years) - 1
    expected = annual_return / downside_std
    assert metrics["raw_sortino_ratio"] == pytest.approx(expected, rel=1e-6)
    assert metrics["sortino_ratio"] == pytest.approx(max(min(expected, 10.0), -10.0), rel=1e-6)


