def test_risk_analyzer_extreme_low_vol_zero_downside_locks_caps_and_zero_drawdown() -> None:
    returns = np.array([0.0004, 0.0006] * 15, dtype=float)
    dates = pd.date_range("2025-01-01", periods=len(returns) + 1, freq="12D")
    nav_values = np.concatenate([[1.0], np.cumprod(1 + returns)])
    nav_data = pd.DataFrame(
        {
            "nav": nav_values,
            "accum_nav": nav_values,
            # Sparse 12-day samples must use NAV pct_change, not daily_growth.
            "daily_growth": [None] + (returns * 100).tolist(),
        },
        index=dates,
    )

    analyzer = RiskAnalyzer(
        config={
            "risk_metrics": {
                "min_data_points": 30,
                "period_coverage_grace_days": 7,
                "max_metric_nav_lag_days": 30,
                "api_return_alignment_grace_days": 7,
                "risk_free_rate": 0.0,
                "mar": 0.0,
            }
        },
        db_manager=object(),
    )

    metrics = analyzer._calculate_period_metrics(
        nav_data,
        "1y",
        api_snapshot_date=dates[-1].date().isoformat(),
    )

    assert metrics is not None
    actual_years = (dates[-1] - dates[0]).days / 365.25
    periods_per_year = len(returns) / actual_years
    expected_total_return = np.prod(1 + returns) - 1
    expected_annual_return = ((1 + expected_total_return) ** (1 / actual_years) - 1) * 100
    expected_volatility = np.std(returns, ddof=1) * np.sqrt(periods_per_year)
    expected_raw_sharpe = (expected_annual_return / 100) / expected_volatility

    assert metrics["data_points"] == len(returns)
    assert metrics["annual_return"] == pytest.approx(expected_annual_return, rel=1e-12)
    assert metrics["volatility"] == pytest.approx(expected_volatility, rel=1e-12)
    assert metrics["max_drawdown"] == pytest.approx(0.0, abs=1e-15)
    assert metrics["calmar_ratio"] is None
    assert metrics["undefined_metric_reasons"]["calmar_ratio"] == "zero_drawdown"
    assert metrics["raw_sharpe_ratio"] == pytest.approx(expected_raw_sharpe, rel=1e-12)
    assert metrics["sharpe_ratio"] == pytest.approx(5.0, rel=1e-12)
    assert metrics["sharpe_ratio_cap_hit"] is True
    assert metrics["raw_sortino_ratio"] is None
    assert metrics["sortino_ratio"] is None
    assert metrics["sortino_ratio_cap_hit"] is None
    assert metrics["var_95"] == pytest.approx(np.percentile(returns, 5), rel=1e-12)
    assert metrics["var_99"] == pytest.approx(np.percentile(returns, 1), rel=1e-12)
    assert metrics["positive_ratio"] == pytest.approx(100.0, rel=1e-12)

    assert metrics["raw_sharpe_ratio"] > metrics["sharpe_ratio"]
    assert metrics["var_95"] > 0
    assert metrics["var_99"] > 0


