def test_risk_analyzer_multiyear_api_return_alignment_annualizes_cumulative_return() -> None:
    returns = np.array([0.0012, -0.0004, 0.0009, 0.0015, -0.0002, 0.0007, 0.0003] * 16, dtype=float)
    dates = pd.date_range("2023-01-01", periods=len(returns) + 1, freq="10D")
    nav_values = np.concatenate([[1.0], np.cumprod(1 + returns)])
    nav_data = pd.DataFrame(
        {
            "nav": nav_values,
            "accum_nav": nav_values,
            # Sparse 10-day samples must use NAV pct_change, not daily_growth.
            "daily_growth": [None] + (returns * 100).tolist(),
        },
        index=dates,
    )

    analyzer = RiskAnalyzer(
        config={
            "risk_metrics": {
                "min_data_points": 30,
                "period_coverage_grace_days": 7,
                "max_metric_nav_lag_days": 30,
                "api_return_alignment_grace_days": 7,
                "risk_free_rate": 0.0,
                "mar": 0.0,
            }
        },
        db_manager=object(),
    )

    aligned_metrics = analyzer._calculate_period_metrics(
        nav_data,
        "3y",
        api_return=9.0,
        api_return_date=dates[-1].date().isoformat(),
        api_snapshot_date=dates[-1].date().isoformat(),
    )
    stale_api_return_metrics = analyzer._calculate_period_metrics(
        nav_data,
        "3y",
        api_return=9.0,
        api_return_date=(dates[-1] - pd.Timedelta(days=30)).date().isoformat(),
        api_snapshot_date=dates[-1].date().isoformat(),
    )

    assert aligned_metrics is not None
    assert stale_api_return_metrics is not None
    expected_api_annual_return = ((1 + 0.09) ** (1 / 3) - 1) * 100
    selected_window = nav_data[nav_data.index >= dates[-1] - pd.Timedelta(days=365 * 3)]
    selected_returns = selected_window["accum_nav"].pct_change().dropna().to_numpy()
    actual_years = (selected_window.index.max() - selected_window.index.min()).days / 365.25
    expected_fallback_annual_return = ((1 + (np.prod(1 + selected_returns) - 1)) ** (1 / actual_years) - 1) * 100

    assert aligned_metrics["annual_return"] == pytest.approx(expected_api_annual_return, rel=1e-12)
    assert stale_api_return_metrics["annual_return"] == pytest.approx(expected_fallback_annual_return, rel=1e-12)
    assert aligned_metrics["annual_return"] != pytest.approx(stale_api_return_metrics["annual_return"], rel=1e-6)
    assert aligned_metrics["data_points"] == len(selected_returns)
    assert aligned_metrics["volatility"] == pytest.approx(stale_api_return_metrics["volatility"], rel=1e-12)
    assert aligned_metrics["max_drawdown"] == pytest.approx(stale_api_return_metrics["max_drawdown"], rel=1e-12)
    assert aligned_metrics["var_95"] == pytest.approx(stale_api_return_metrics["var_95"], rel=1e-12)
    assert aligned_metrics["var_99"] == pytest.approx(stale_api_return_metrics["var_99"], rel=1e-12)
    assert aligned_metrics["positive_ratio"] == pytest.approx(stale_api_return_metrics["positive_ratio"], rel=1e-12)


def test_risk_analyzer_exposes_raw_and_capped_risk_metrics() -> None:
    end_date = pd.Timestamp(datetime.now().date())
    dates = pd.date_range(end=end_date, periods=31, freq="12D")
    daily_growth = [None] + ([0.15, 0.35] * 15)
    daily_growth[1] = -0.000001
    nav_values = [1.0]
    for growth in daily_growth[1:]:
        nav_values.append(nav_values[-1] * (1 + growth / 100))

    nav_data = pd.DataFrame(
        {
            "nav": nav_values,
            "accum_nav": nav_values,
            "daily_growth": daily_growth,
        },
        index=dates,
    )

    analyzer = RiskAnalyzer(
        config={
            "risk_metrics": {
                "min_data_points": 30,
                "period_coverage_grace_days": 7,
                "max_metric_nav_lag_days": 30,
                "api_return_alignment_grace_days": 7,
                "mar": 0.0,
            }
        },
        db_manager=object(),
    )

    metrics = analyzer._calculate_period_metrics(
        nav_data,
        "1y",
        api_snapshot_date=end_date.date().isoformat(),
    )

    assert metrics is not None
    assert metrics["raw_sharpe_ratio"] >= metrics["sharpe_ratio"]
    assert metrics["raw_sortino_ratio"] >= metrics["sortino_ratio"]
    assert metrics["sharpe_ratio"] == pytest.approx(5.0, rel=1e-6)
    assert metrics["sortino_ratio"] == pytest.approx(10.0, rel=1e-6)
    assert metrics["sharpe_ratio_cap_hit"] is True
    assert metrics["sortino_ratio_cap_hit"] is True


