def test_report_builder_read_risk_snapshot_prefers_raw_columns_and_falls_back_cleanly(tmp_path: Path) -> None:
    import backend.report_builder as report_builder

    db_path = tmp_path / "risk_snapshot.db"
    conn = sqlite3.connect(db_path)
    try:
        conn.execute(
            """
            CREATE TABLE fund_risk_metrics (
                fcode TEXT,
                period TEXT,
                end_date TEXT,
                volatility REAL,
                max_drawdown REAL,
                annual_return REAL,
                sharpe_ratio REAL,
                sortino_ratio REAL,
                raw_sharpe_ratio REAL,
                raw_sortino_ratio REAL,
                sharpe_ratio_cap_hit INTEGER,
                sortino_ratio_cap_hit INTEGER,
                calmar_ratio REAL,
                var_95 REAL,
                var_99 REAL,
                positive_ratio REAL
            )
            """
        )
        conn.execute(
            """
            INSERT INTO fund_risk_metrics VALUES
            (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                "000001",
                "1y",
                "2026-04-14",
                0.02,
                0.01,
                3.5,
                5.0,
                10.0,
                6.8,
                12.4,
                1,
                1,
                1.6,
                -0.002,
                -0.003,
                70.0,
            ),
        )
        conn.commit()
    finally:
        conn.close()

    with patch.object(
        report_builder,
        "load_effective_nav_snapshot",
        return_value=SimpleNamespace(
            risk_1y_effective_end_date="2026-04-14",
            risk_1y_latest_end_date="2026-04-14",
        ),
    ):
        df = report_builder._read_risk_snapshot(db_path)

    assert df.iloc[0]["raw_sharpe_ratio"] == pytest.approx(6.8)
    assert df.iloc[0]["raw_sortino_ratio"] == pytest.approx(12.4)
    assert int(df.iloc[0]["sharpe_ratio_cap_hit"]) == 1
    assert int(df.iloc[0]["sortino_ratio_cap_hit"]) == 1


