def test_future_outlier_monitor_uses_latest_risk_rowid_and_preserves_missing_values(tmp_path: Path) -> None:
    from backend.future_outlier_monitor import _load_monitor_snapshot

    db_path = tmp_path / "future_outlier_monitor.db"
    conn = sqlite3.connect(db_path)
    try:
        conn.executescript(
            """
            CREATE TABLE funds (
                fcode TEXT,
                shortname TEXT,
                ftype TEXT,
                is_buyable INTEGER,
                purchase_status TEXT
            );
            CREATE TABLE fund_returns (
                fcode TEXT,
                latest_nav_date TEXT,
                latest_nav REAL,
                daily_growth REAL
            );
            CREATE TABLE fund_nav_history (
                fcode TEXT,
                nav_date TEXT
            );
            CREATE TABLE fund_risk_metrics (
                fcode TEXT,
                period TEXT,
                end_date TEXT,
                annual_return REAL,
                raw_sharpe_ratio REAL,
                sharpe_ratio REAL,
                max_drawdown REAL,
                volatility REAL
            );
            INSERT INTO funds VALUES ('000001', '样本债基', '债券型', 1, '开放申购');
            INSERT INTO fund_returns VALUES ('000001', '2026-06-08', NULL, NULL);
            INSERT INTO fund_nav_history VALUES ('000001', '2026-06-08');
            INSERT INTO fund_risk_metrics VALUES
                ('000001', '1y', '2026-06-05', 1.0, 1.2, 1.1, 0.08, 0.09),
                ('000001', '1y', '2026-06-05', 3.5, 6.8, 5.0, 0.01, 0.02);
            """
        )
        conn.commit()
    finally:
        conn.close()

    rows = _load_monitor_snapshot(
        SimpleNamespace(database_path=db_path),
        ["000001"],
    )

    assert len(rows) == 1
    assert rows[0]["latest_nav"] is None
    assert rows[0]["daily_growth"] is None
    assert rows[0]["latest_risk_end_date"] == "2026-06-05"
    assert rows[0]["annual_return_1y"] == pytest.approx(3.5)
    assert rows[0]["sharpe_ratio_1y"] == pytest.approx(6.8)
    assert rows[0]["max_drawdown_1y"] == pytest.approx(0.01)
    assert rows[0]["volatility_1y"] == pytest.approx(0.02)




