@pytest.mark.usefixtures("command_only_capture_stub")
def test_run_core_pipeline_fails_fast_when_tiantian_business_preflight_unavailable(tmp_path: Path) -> None:
    output_dir = tmp_path / "core-output"
    settings = SimpleNamespace(
        project_root=tmp_path,
        core_root=CORE_ROOT,
        core_output_dir=output_dir,
        reports_dir=tmp_path / "reports",
        runs_dir=tmp_path / "reports" / "runs",
        database_path=tmp_path / "unused.db",
        tiantian_base_url="http://tiantian.example",
        workflow_task_timeout_seconds={},
        workflow_task_idle_timeout_seconds={},
    )
    steps = [
        SimpleNamespace(name="collect-funds", command=["python", "main.py", "collect-funds", "-t", "bond"]),
    ]
    logs: list[str] = []
    started_subprocess = Mock(side_effect=AssertionError("collect subprocess should not start"))

    with ExitStack() as stack:
        stack.enter_context(patch("backend.core_runner.build_core_commands", return_value=steps))
        stack.enter_context(patch("backend.core_runner.ensure_core_output_link", return_value=output_dir))
        stack.enter_context(patch("backend.core_runner.TIANTIAN_BUSINESS_PREFLIGHT_RETRY_INTERVAL_SECONDS", 0))
        stack.enter_context(
            patch(
                "backend.core_runner._probe_tiantian_business",
                return_value={
                    "ok": False,
                    "status": "request_error",
                    "message": "RemoteDisconnected",
                    "base_url": "http://tiantian.example",
                    "url": "http://tiantian.example/fundMNRank?FundType=31&pageIndex=1&pageSize=1",
                    "http_status": None,
                    "errors": ["RemoteDisconnected"],
                },
            )
        )
        stack.enter_context(
            patch("backend.core_runner._run_streaming_subprocess", side_effect=started_subprocess)
        )
        with pytest.raises(TiantianBusinessUnavailableError) as exc_info:
            run_core_pipeline(
                settings,
                {
                    "workflow_run_id": "preflight_fail_test",
                    "run_collection": True,
                    "run_screening": False,
                },
                logs.append,
            )

    assert exc_info.value.stage == "collect-funds"
    assert started_subprocess.call_count == 0
    log_dir = settings.runs_dir / "preflight_fail_test" / "logs" / "subprocess"
    index_path = log_dir / "subprocess_index.json"
    assert index_path.exists()
    index = json.loads(index_path.read_text(encoding="utf-8"))
    assert index["subprocess_count"] == 1
    assert index["failed_task_names"] == ["tiantian-business-preflight"]
    meta_files = [path for path in log_dir.glob("*.meta.json") if path.name != "subprocess_index.json"]
    assert len(meta_files) == 1
    meta = json.loads(meta_files[0].read_text(encoding="utf-8"))
    assert meta["failure_kind"] == "tiantian_business_unavailable"
    assert meta["stage"] == "collect-funds"
    assert meta["attempt_count"] == 3
    assert any("tiantian-preflight" in line for line in logs)


