def test_scheduler_degradation_summary_marks_nav_archive_root_cause_resolved_by_later_evidence(
    tmp_path: Path,
) -> None:
    from backend.scheduler_diagnostics import build_scheduler_run_degradation_summary

    artifact_dir = tmp_path / "reports" / "audit" / "nav_history_archive"
    artifact_dir.mkdir(parents=True)
    historical_artifact = artifact_dir / "nav_history_archive_rolling_runner_20260609_094318.json"
    latest_artifact = artifact_dir / "nav_history_archive_rolling_runner_20260609_1845_post_missing_key_dryrun.json"
    historical_artifact.write_text(
        json.dumps(
            {
                "summary": {
                    "runner_status": "rolling_archive_blocked",
                    "blocker_count": 1,
                    "rolling_archive_blocked_reason": "rolling_archive_cumulative_merge_not_implemented",
                    "stale_hot_missing_archive_key_row_count": 33419,
                    "hot_before_current_cutoff_row_count": 2634104,
                }
            }
        ),
        encoding="utf-8",
    )
    latest_artifact.write_text(
        json.dumps(
            {
                "generated_at": "2026-06-09 19:00:10",
                "summary": {
                    "runner_status": "rolling_archive_not_required",
                    "active_cutoff_date": "2021-06-08",
                    "archive_cutoff_date": "2021-06-08",
                    "blocker_count": 0,
                    "review_item_count": 1,
                    "hot_before_active_cutoff_row_count": 0,
                    "hot_before_current_cutoff_row_count": 0,
                    "stale_hot_missing_archive_key_row_count": 0,
                    "stale_hot_key_conflict_row_count": 0,
                    "archive_out_of_scope_current_row_count": 0,
                    "active_db_quick_check": "ok",
                    "archive_quick_check": "ok",
                },
            }
        ),
        encoding="utf-8",
    )

    summary = build_scheduler_run_degradation_summary(
        {
            "status": "degraded",
            "degraded": True,
            "degraded_stage": "nav-history-archive-preview",
            "warning_reason": "nav_history_archive_preview_failed",
            "nav_history_archive_preview": {
                "artifacts": {
                    "rolling_runner": {
                        "artifact_path": "/app/reports/audit/nav_history_archive/"
                        "nav_history_archive_rolling_runner_20260609_094318.json",
                    }
                }
            },
        },
        task_key="weekly_maintenance",
        project_root=tmp_path,
    )

    evidence = summary["nav_history_archive_resolution_evidence"]
    assert summary["status"] == "degraded"
    assert summary["root_cause_resolved_by_later_evidence"] is True
    assert evidence["truth_policy"] == "read_only_runtime_artifact_evidence_no_state_mutation"
    assert evidence["root_cause_status"] == "resolved_awaiting_next_weekly_maintenance"
    assert evidence["historical_failure"]["stale_hot_missing_archive_key_row_count"] == 33419
    assert evidence["latest_resolution_evidence"]["stale_hot_missing_archive_key_row_count"] == 0
    assert evidence["latest_resolution_evidence"]["hot_before_current_cutoff_row_count"] == 0
    assert evidence["latest_resolution_evidence"]["artifact_path"] == (
        "reports/audit/nav_history_archive/"
        "nav_history_archive_rolling_runner_20260609_1845_post_missing_key_dryrun.json"
    )


def test_automation_autonomy_moves_resolved_weekly_warning_out_of_current_warnings() -> None:
    import backend.app as backend_app

    weekly_resolution = {
        "applicable": True,
        "root_cause_resolved": True,
        "root_cause_status": "resolved_awaiting_next_weekly_maintenance",
        "truth_policy": "read_only_runtime_artifact_evidence_no_state_mutation",
        "current_interpretation": "Historical weekly maintenance remains degraded.",
        "latest_resolution_evidence": {
            "artifact_path": "reports/audit/nav_history_archive/nav_history_archive_rolling_runner_20260609_1845_post_missing_key_dryrun.json",
            "blocker_count": 0,
        },
    }

    summary = backend_app._build_automation_autonomy_summary(
        {
            "scheduler_running": True,
            "effective_nav_snapshot": {"candidate_date": "2026-06-08", "signature": "sig-a"},
            "latest_screened_snapshot": {"candidate_date": "2026-06-08", "signature": "sig-a"},
        },
        {
            "open_issues": [
                {
                    "code": "weekly_maintenance_degraded",
                    "severity": "warning",
                    "detail": "nav-history-archive-preview / nav_history_archive_preview_failed",
                }
            ],
            "runs": {
                "weekly_maintenance": {
                    "degradation_summary": {
                        "nav_history_archive_resolution_evidence": weekly_resolution
                    }
                }
            },
        },
        manual_operations_enabled=False,
        load_database_overview_fn=lambda _snapshot: {
            "autostock_shadow_persistent_tracking_ready": True,
            "autostock_shadow_cooldown_active_today": True,
        },
    )

    assert summary["status"] == "automatic"
    assert summary["manual_intervention_required"] is False
    assert "weekly_maintenance_degraded" not in summary["warning_issue_codes"]
    assert "weekly_maintenance_degraded" in summary["resolved_warning_issue_codes"]
    detail = summary["resolved_warning_issue_details"]["weekly_maintenance_degraded"]
    assert detail["root_cause_resolved"] is True
    assert detail["root_cause_status"] == "resolved_awaiting_next_weekly_maintenance"
    assert detail["truth_policy"] == "read_only_runtime_artifact_evidence_no_state_mutation"
    assert detail["current_warning_suppressed"] is True
    assert detail["effective_signal"] is False


