def test_progress_monitor_emits_non_interactive_heartbeat(monkeypatch: pytest.MonkeyPatch, capsys: pytest.CaptureFixture[str]) -> None:
    import utils.progress as progress_module
    from utils.progress import ProgressMonitor

    clock = {"value": 1000.0}
    monkeypatch.setattr(progress_module.time, "time", lambda: clock["value"])

    monitor = ProgressMonitor(
        2,
        desc="采集基金经理列表",
        unit="只基金",
        heartbeat_interval_seconds=1,
        show_completion_summary=False,
    )
    try:
        monitor._interactive = False
        clock["value"] = 1001.1
        monitor.update(1, success=True)
    finally:
        monitor.close()

    captured = capsys.readouterr()
    assert "[progress] 采集基金经理列表" in captured.out
    assert "processed=1/2" in captured.out
    assert "success=1" in captured.out


def test_fund_collector_retries_rank_page_transient_timeout(monkeypatch: pytest.MonkeyPatch) -> None:
    import collectors.fund_collector as fund_collector_module
    from collectors.fund_collector import FundCollector
    from config.api_config import FundType
    from utils.tiantian_data_quality import TiantianPayloadQuality

    calls: list[int] = []
    sleeps: list[float] = []

    class _FakeApi:
        @staticmethod
        def get_bond_fund_rank(**kwargs):
            calls.append(int(kwargs["page_index"]))
            return {"attempt": len(calls)}

    def _fake_inspect(result, *, endpoint_label):
        if result["attempt"] == 1:
            return [], TiantianPayloadQuality(
                accepted=False,
                has_data=False,
                status="request_failed",
                message=f"{endpoint_label} timeout",
                failure_kind="timeout",
            )
        return [{"FCODE": "000001"}], TiantianPayloadQuality(
            accepted=True,
            has_data=True,
            status="ok",
            message=f"{endpoint_label} ok",
            record_count=1,
        )

    collector = FundCollector.__new__(FundCollector)
    collector.api = _FakeApi()
    monkeypatch.setattr(fund_collector_module, "inspect_tiantian_rank_payload", _fake_inspect)
    monkeypatch.setattr(fund_collector_module.time, "sleep", lambda seconds: sleeps.append(seconds))

    _page_data, records, quality = collector._fetch_rank_page_with_retry(
        fund_type=FundType.BOND,
        page=174,
        page_size=30,
        only_buyable=False,
    )

    assert calls == [174, 174]
    assert sleeps == [2.0]
    assert quality.accepted is True
    assert records == [{"FCODE": "000001"}]


