def test_weekly_maintenance_includes_bond_universe_sync_summary() -> None:
    scheduler = ProjectScheduler.__new__(ProjectScheduler)
    scheduler.settings = SimpleNamespace(
        scheduler_weekly_nav_history_limit=240,
        scheduler_weekly_long_term_history_limit=20,
    )
    scheduler.workflow_manager = SimpleNamespace(is_running=lambda: False)
    scheduler.task_recorder = None
    scheduler.state_store = None
    scheduler._log = lambda message: None

    with (
        patch("backend.scheduler.run_project_pipeline", return_value={}),
        patch(
            "backend.scheduler.run_bond_universe_sync",
            return_value={
                "counts_before_sync": {"local_bond_total": 7441},
                "diffs_after_sync": {
                    "missing_in_local_vs_tiantian_total": 0,
                    "missing_in_local_vs_autostock_total": 12,
                    "missing_in_local_active_vs_tiantian_total": 1,
                    "missing_in_local_active_vs_autostock_total": 13,
                    "newly_synced_codes_total": 28,
                },
            },
        ),
        patch(
            "backend.scheduler.run_nav_history_maintenance",
            return_value={
                "maintenance_result": {
                    "processed_total": 50,
                    "recovered_total": 48,
                    "failed_total": 0,
                },
                "audit_after": {
                    "candidate_total": 379,
                },
            },
        ) as mocked_nav_maintenance,
        patch(
            "backend.scheduler.run_long_term_history_maintenance",
            return_value={
                "maintenance_result": {
                    "processed_total": 20,
                    "annual_success_total": 18,
                    "rank_success_total": 19,
                },
                "audit_after": {
                    "candidate_total": 3100,
                },
            },
        ),
    ):
        result = ProjectScheduler._execute_weekly_maintenance(scheduler)

    assert result["status"] == "success"
    assert result["degraded"] is False
    assert result["bond_universe_sync"]["diffs_after_sync"]["newly_synced_codes_total"] == 28
    assert result["bond_universe_remaining_tiantian_gap"] == 0
    assert result["bond_universe_remaining_autostock_gap"] == 12
    assert result["bond_universe_remaining_active_tiantian_gap"] == 1
    assert result["bond_universe_remaining_active_autostock_gap"] == 13
    assert mocked_nav_maintenance.call_args.kwargs["limit"] == 240
    assert result["nav_history_maintenance"]["maintenance_result"]["processed_total"] == 50
    assert result["nav_history_maintenance_error"] is None
    assert result["long_term_history_maintenance"]["maintenance_result"]["processed_total"] == 20
    assert result["long_term_history_maintenance_error"] is None


