    assert mocked_cleanup_execution.call_args.kwargs["archive_target_path"] == archive_target_path
    assert result["status"] == ("degraded" if columnar_status == "failed" else "success")
    assert columnar.call_count == (0 if columnar_status is None else 1)
    if columnar_status is not None:
        assert columnar.call_args.kwargs["mode"] == "apply"
        assert result["screening_history_archive_rotation"]["columnar_storage"]["status"] == columnar_status
        assert bool(result["screening_history_archive_rotation_error"]) == (columnar_status == "failed")
    assert result["screening_history_archive_preview"]["status"] == "success"
    assert result["screening_history_archive_preview"]["summary"]["total_scope_row_count"] == 300
    assert result["screening_history_archive_preview_error"] is None
    assert result["screening_history_archive_execution"]["status"] == "archive-exported"
    assert result["screening_history_archive_execution"]["summary"]["inserted_row_count"] == 300
    assert result["screening_history_archive_execution_error"] is None
    assert result["screening_history_cleanup_execution"]["archive_guard"]["status"] == "ok"
    assert result["screening_history_cleanup_execution"]["apply_readiness"]["status"] == "ready"


