def test_rank_history_governance_audit_blocks_archive_until_query_compat(tmp_path: Path) -> None:
    from utils.rank_history_governance_audit import (
        build_rank_history_governance_audit_payload,
        write_rank_history_governance_audit_artifacts,
    )

    db_path = tmp_path / "rank-governance.db"
    conn = sqlite3.connect(db_path)
    try:
        conn.execute(
            """
            CREATE TABLE fund_rank_history (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                fcode TEXT NOT NULL,
                rank_date TEXT NOT NULL,
                period TEXT,
                rank_position INTEGER,
                category_total INTEGER,
                percentile REAL,
                created_at TEXT
            )
            """
        )
        conn.execute("CREATE INDEX idx_rank_fcode ON fund_rank_history(fcode)")
        conn.execute("CREATE INDEX idx_rank_date ON fund_rank_history(rank_date)")
        conn.executemany(
            """
            INSERT INTO fund_rank_history (
                fcode, rank_date, period, rank_position, category_total, percentile, created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?)
            """,
            [
                ("000001", "2023-01-03", "1y", 10, 100, 0.10, "2023-01-03"),
                ("000001", "2024-01-03", "1y", 12, 100, 0.12, "2024-01-03"),
                ("000001", "2026-06-01", "1y", 20, 100, 0.20, "2026-06-01"),
                ("000002", "2023-01-03", "1y", 30, 100, 0.30, "2023-01-03"),
                ("000002", "2026-06-01", "1y", 40, 100, 0.40, "2026-06-01"),
            ],
        )
        conn.commit()
    finally:
        conn.close()

    payload = build_rank_history_governance_audit_payload(
        db_path=db_path,
        production_dependencies=[
            {
                "dependency_id": "forced_hot_only_dependency",
                "file": "backend/report_builder.py",
                "purpose": "test blocker injection",
                "cold_query_ready": False,
            }
        ],
    )
    summary = payload["summary"]

    assert summary["status"] == "rank_archive_query_compat_required"
    assert summary["estimated_archive_row_count"] == 3
    assert summary["archive_cutoff_date"] == "2024-06-01"
    assert summary["production_uncovered_dependency_count"] > 0
    assert summary["blocker_count"] == 1
    assert summary["archive_sql_executed"] is False
    assert summary["delete_sql_executed"] is False
    assert summary["vacuum_executed"] is False
    assert payload["blockers"][0]["blocker_id"] == "rank_history_hot_only_production_dependencies"

    out = tmp_path / "reports/audit/rank_history_governance"
    json_path, md_path = write_rank_history_governance_audit_artifacts(
        payload,
        output_dir=out,
        timestamp="20260603_test",
    )
    assert json_path.exists()
    assert md_path.exists()
    assert json.loads(json_path.read_text(encoding="utf-8"))["summary"]["blocker_count"] == 1


