def test_rank_history_archive_apply_runner_archives_and_exact_deletes(tmp_path: Path) -> None:
    from utils.rank_history_archive_apply_runner import (
        build_rank_history_archive_apply_runner_payload,
        write_rank_history_archive_apply_runner_artifacts,
    )
    from utils.rank_history_archive_preflight import build_rank_history_archive_preflight_payload

    db_path = tmp_path / "rank-apply.db"
    archive_path = tmp_path / "backend/data/archives/fund_rank_history_before_2024-06-02.db"
    output_dir = tmp_path / "reports/audit/rank_history_archive"
    conn = sqlite3.connect(db_path)
    try:
        conn.execute(
            """
            CREATE TABLE fund_rank_history (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                fcode TEXT NOT NULL,
                rank_date TEXT NOT NULL,
                period TEXT,
                rank_position INTEGER,
                category_total INTEGER,
                percentile REAL,
                created_at TEXT,
                UNIQUE(fcode, rank_date, period)
            )
            """
        )
        conn.executemany(
            """
            INSERT INTO fund_rank_history (
                fcode, rank_date, period, rank_position, category_total, percentile, created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?)
            """,
            [
                ("000001", "2024-05-30", "overall", 1, 100, 0.01, "2024-05-30"),
                ("000002", "2024-05-31", "overall", 2, 100, 0.02, "2024-05-31"),
                ("000001", "2024-06-01", "overall", 3, 100, 0.03, "2024-06-01"),
                ("000003", "2024-06-02", "overall", 4, 100, 0.04, "2024-06-02"),
            ],
        )
        conn.commit()
    finally:
        conn.close()

    governance_payload = {
        "summary": {
            "archive_cutoff_date": "2024-06-02",
            "archive_target_path": str(archive_path),
            "archive_table_name": "fund_rank_history_archive",
            "estimated_archive_row_count": 3,
            "estimated_archive_fund_count": 2,
            "production_uncovered_dependency_count": 0,
            "blocker_count": 0,
        },
        "production_dependencies": [{"dependency_id": "x", "cold_query_ready": True}],
    }
    preflight = build_rank_history_archive_preflight_payload(
        db_path=db_path,
        project_root=tmp_path,
        governance_payload=governance_payload,
        archive_output_dir=output_dir,
    )

    first = build_rank_history_archive_apply_runner_payload(
        db_path=db_path,
        project_root=tmp_path,
        output_dir=output_dir,
        preflight_payload=preflight,
        mode="auto",
        page_limit=2,
    )
    first_summary = first["summary"]
    assert first_summary["effective_mode"] == "archive_export"
    assert first_summary["archive_sql_executed"] is True
    assert first_summary["archive_export_inserted_row_count"] == 2
    assert first_summary["existing_archive_row_count"] == 2
    assert first_summary["archive_missing_row_count"] == 1
    assert first_summary["live_cold_row_count"] == 3
    assert first_summary["delete_sql_executed"] is False
    write_rank_history_archive_apply_runner_artifacts(
        first,
        output_dir=output_dir,
        timestamp="20260604_first",
    )

    second = build_rank_history_archive_apply_runner_payload(
        db_path=db_path,
        project_root=tmp_path,
        output_dir=output_dir,
        preflight_payload=preflight,
        mode="auto",
        page_limit=10,
    )
    second_summary = second["summary"]
    assert second_summary["archive_export_inserted_row_count"] == 1
    assert second_summary["existing_archive_row_count"] == 3
    assert second_summary["archive_missing_row_count"] == 0
    assert second_summary["runner_status"] == "rank_archive_export_complete_ready_for_hot_delete"
    write_rank_history_archive_apply_runner_artifacts(
        second,
        output_dir=output_dir,
        timestamp="20260604_second",
    )

    blocked_delete = build_rank_history_archive_apply_runner_payload(
        db_path=db_path,
        project_root=tmp_path,
        output_dir=output_dir,
        preflight_payload=preflight,
        mode="auto",
        page_limit=2,
    )
    assert blocked_delete["summary"]["effective_mode"] == "hot_delete"
    assert blocked_delete["summary"]["runner_status"] == "blocked"
    assert any(item["key"] == "hot_delete_backup" for item in blocked_delete["gate_checks"])

    backup_path = tmp_path / "backend/data/backups/bond_funds_pre_rank_archive_test.db"
    backup_path.parent.mkdir(parents=True, exist_ok=True)
    backup_path.write_bytes(b"backup")
    partial_delete = build_rank_history_archive_apply_runner_payload(
        db_path=db_path,
        project_root=tmp_path,
        output_dir=output_dir,
        preflight_payload=preflight,
        backup_artifact_path=backup_path,
        mode="auto",
        page_limit=2,
    )
    partial_summary = partial_delete["summary"]
    assert partial_summary["delete_sql_executed"] is True
    assert partial_summary["hot_delete_deleted_row_count"] == 2
    assert partial_summary["live_cold_row_count"] == 1
    assert partial_summary["archive_binding_active"] is False
    write_rank_history_archive_apply_runner_artifacts(
        partial_delete,
        output_dir=output_dir,
        timestamp="20260604_partial_delete",
    )

    refreshed_governance = {
        "summary": {
            **governance_payload["summary"],
            "estimated_archive_row_count": 1,
            "estimated_archive_fund_count": 1,
        },
        "production_dependencies": governance_payload["production_dependencies"],
    }
    refreshed_preflight = build_rank_history_archive_preflight_payload(
        db_path=db_path,
        project_root=tmp_path,
        governance_payload=refreshed_governance,
        archive_output_dir=output_dir,
    )
    assert refreshed_preflight["summary"]["candidate_row_count"] == 1
    assert refreshed_preflight["summary"]["effective_expected_archive_row_count"] == 3
    assert refreshed_preflight["summary"]["effective_expected_archive_fund_count"] == 2
    assert refreshed_preflight["summary"]["blocker_count"] == 0

    final_delete = build_rank_history_archive_apply_runner_payload(
        db_path=db_path,
        project_root=tmp_path,
        output_dir=output_dir,
        preflight_payload=refreshed_preflight,
        backup_artifact_path=backup_path,
        mode="auto",
        page_limit=10,
    )
    final_summary = final_delete["summary"]
    assert final_summary["hot_delete_deleted_row_count"] == 1
    assert final_summary["live_cold_row_count"] == 0
    assert final_summary["existing_archive_row_count"] == 3
    assert final_summary["archive_binding_active"] is True

    conn = sqlite3.connect(db_path)
    try:
        assert conn.execute(
            "SELECT COUNT(*) FROM fund_rank_history WHERE rank_date < '2024-06-02'"
        ).fetchone()[0] == 0
        assert conn.execute("SELECT COUNT(*) FROM fund_rank_history").fetchone()[0] == 1
    finally:
        conn.close()


