    assert mocked_apply.call_args_list[1].kwargs["backup_artifact_path"] == backup_payload["summary"]["backup_artifact_absolute_path"]
    assert mocked_apply.call_args_list[1].kwargs["mode"] == "auto"
    assert mocked_apply.call_args_list[1].kwargs["page_limit"] == 77
    assert mocked_backup.call_count == 1
    assert mocked_backup.call_args.kwargs["backup_prefix"] == "bond_funds_pre_rank_archive"
    assert result["status"] == "success"
    assert result["rank_history_archive_apply"]["summary"]["archive_binding_active"] is True
    assert result["rank_history_archive_apply"]["backup"]["status"] == "backup_created"
    assert result["rank_history_archive_apply_error"] is None


