def test_database_backup_compression_preview_selects_large_uncompressed_backups(
    tmp_path: Path,
) -> None:
    from utils.database_backup_compression_preview import (
        build_database_backup_compression_preview_payload,
    )

    backup_dir = tmp_path / "backups"
    backup_dir.mkdir()
    active_db = tmp_path / "bond_funds.db"
    active_db.write_bytes(b"active")
    large_backup = (
        backup_dir
        / "bond_funds_pre_rank_vacuum_replace_20260604_rank_vacuum_after_hotdelete.db"
    )
    large_backup.write_bytes(b"x" * 4096)
    small_backup = backup_dir / "bond_funds_pre_nav_archive_20260604.db"
    small_backup.write_bytes(b"x")
    compressed_backup = backup_dir / "bond_funds_pre_screening_cleanup_20260604.db.zst"
    compressed_backup.write_bytes(b"compressed")

    payload = build_database_backup_compression_preview_payload(
        backup_dir=backup_dir,
        active_database_path=active_db,
        min_compress_size_mb=0.001,
        max_sample_files=10,
    )

    assert payload["summary"]["scanned_uncompressed_file_count"] == 2
    assert payload["summary"]["candidate_file_count"] == 1
    assert payload["summary"]["skipped_too_small_file_count"] == 1
    assert payload["candidate_file_samples"][0]["relative_path"] == large_backup.name
    assert payload["execution_plan"]["scope_files"] == [large_backup.name]


def test_database_backup_compression_execution_dry_run_does_not_write_zst(
    tmp_path: Path,
) -> None:
    from utils.database_backup_compression_execution import (
        execute_database_backup_compression,
    )
    from utils.database_backup_compression_preview import (
        build_database_backup_compression_preview_payload,
    )

    backup_dir = tmp_path / "backups"
    backup_dir.mkdir()
    source = backup_dir / "bond_funds_pre_rank_archive_20260604.db"
    source.write_bytes(b"sqlite backup bytes" * 128)
    preview_payload = build_database_backup_compression_preview_payload(
        backup_dir=backup_dir,
        active_database_path=tmp_path / "bond_funds.db",
        min_compress_size_mb=0.0,
    )

    _json_path, _md_path, payload = execute_database_backup_compression(
        preview_payload=preview_payload,
        output_dir=tmp_path / "audit",
        mode="dry-run",
        expected_backup_dir=backup_dir,
    )

    assert payload["status"] == "dry-run"
    assert payload["summary"]["scope_file_total"] == 1
    assert source.exists()
    assert not source.with_suffix(source.suffix + ".zst").exists()


def test_database_backup_compression_execution_apply_verifies_and_removes_source(
    tmp_path: Path,
) -> None:
    if shutil.which("zstd") is None:
        pytest.skip("zstd executable is not available")

    from utils.database_backup_compression_execution import (
        REQUIRED_APPLY_CONFIRMATION,
        execute_database_backup_compression,
    )
    from utils.database_backup_compression_preview import (
        build_database_backup_compression_preview_payload,
    )

    backup_dir = tmp_path / "backups"
    backup_dir.mkdir()
    source = backup_dir / "bond_funds_pre_rank_archive_20260604.db"
    with sqlite3.connect(source) as conn:
        conn.execute("CREATE TABLE entries (code TEXT, value REAL)")
        conn.executemany("INSERT INTO entries VALUES (?, ?)", [("000001", None), ("000002", 0.0)] * 4096)
    source_bytes = source.read_bytes()
    compressed = source.with_suffix(source.suffix + ".zst")
    preview_payload = build_database_backup_compression_preview_payload(
        backup_dir=backup_dir,
        active_database_path=tmp_path / "bond_funds.db",
        min_compress_size_mb=0.0,
    )

    _json_path, _md_path, payload = execute_database_backup_compression(
        preview_payload=preview_payload,
        output_dir=tmp_path / "audit",
        mode="apply",
        confirm_apply=REQUIRED_APPLY_CONFIRMATION,
        expected_backup_dir=backup_dir,
        checkpoint_every=1,
    )

    assert payload["status"] == "applied"
    assert payload["summary"]["compressed_file_count"] == 1
    assert payload["summary"]["source_removed_file_count"] == 1
    assert payload["summary"]["removed_source_size_bytes"] == len(source_bytes)
    assert 0 < payload["summary"]["freed_size_bytes"] < len(source_bytes)
    assert payload["files"][0]["source_sha256"] == payload["files"][0]["decoded_sha256"]
    assert not source.exists()
    assert compressed.exists()


