def test_task_history_governance_preview_is_readonly_and_summarizes_candidates(
    tmp_path: Path,
) -> None:
    from utils.task_history_governance_preview import (
        build_task_history_governance_preview_payload,
        write_task_history_governance_preview_artifacts,
    )

    db_path = tmp_path / "bond_funds.db"
    conn = sqlite3.connect(db_path)
    try:
        conn.execute(
            """
            CREATE TABLE task_history (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                task_name TEXT,
                status TEXT,
                started_at TEXT,
                completed_at TEXT,
                duration REAL,
                records_processed INTEGER,
                records_inserted INTEGER,
                records_updated INTEGER,
                records_failed INTEGER,
                extra_data TEXT
            )
            """
        )

        def insert_row(
            task_name: str,
            status: str,
            started_at: str,
            extra_data: dict[str, Any] | str = "",
        ) -> int:
            raw_extra_data = (
                json.dumps(extra_data, ensure_ascii=False)
                if isinstance(extra_data, dict)
                else str(extra_data)
            )
            cursor = conn.execute(
                """
                INSERT INTO task_history (
                    task_name, status, started_at, completed_at, duration,
                    records_processed, records_inserted, records_updated,
                    records_failed, extra_data
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    task_name,
                    status,
                    started_at,
                    started_at,
                    1.0,
                    1,
                    0,
                    0,
                    0,
                    raw_extra_data,
                ),
            )
            return int(cursor.lastrowid)

        insert_row(
            "scheduled_snapshot_watchdog_refresh",
            "skipped",
            "2026-06-04T01:00:00",
            {"skip_reason": "effective_nav_snapshot_already_screened"},
        )
        insert_row(
            "scheduled_snapshot_watchdog_refresh",
            "skipped",
            "2026-06-03T01:00:00",
            {"skip_reason": "effective_nav_snapshot_already_screened"},
        )
        insert_row(
            "scheduled_snapshot_watchdog_refresh",
            "skipped",
            "2026-06-02T01:00:00",
            {"skip_reason": "effective_nav_snapshot_already_screened"},
        )
        insert_row("scheduled_daily_bond_refresh", "success", "2026-05-02T01:00:00")
        large_row_id = insert_row(
            "scheduled_daily_bond_refresh",
            "success",
            "2026-05-01T01:00:00",
            {"payload": "x" * 300_000},
        )
        multibyte_large_row_id = insert_row(
            "scheduled_intraday_bond_refresh",
            "success",
            "2026-05-01T03:00:00",
            {"payload": "净" * 100_000},
        )
        running_row_id = insert_row(
            "scheduled_daily_bond_refresh",
            "running",
            "2026-05-01T02:00:00",
            {"payload": "still-running"},
        )
        conn.commit()
    finally:
        conn.close()

    payload = build_task_history_governance_preview_payload(
        db_path=db_path,
        generated_at="2026-06-05T12:00:00",
        retention_days=14,
        recent_keep_per_task_status=1,
        large_extra_data_threshold_bytes=262_144,
        max_sample_rows=20,
        max_daily_summary_days=10,
    )

    assert payload["status"] == "success"
    assert payload["preview_only"] is True
    assert payload["execution_plan"]["delete_rows"] is False
    assert payload["execution_plan"]["rewrite_extra_data"] is False
    assert payload["summary"]["total_rows"] == 7
    assert payload["summary"]["snapshot_watchdog_skipped_total"] == 3
    assert payload["snapshot_watchdog_skipped"]["skipped_total"] == 3
    assert (
        payload["snapshot_watchdog_skipped"]["skip_reason_counts"][
            "effective_nav_snapshot_already_screened"
        ]
        == 3
    )
    assert payload["summary"]["large_extra_data_candidate_total"] == 2
    large_candidate_ids = {
        int(item["id"])
        for item in payload["large_extra_data_candidate_samples"]
        if item.get("id") is not None
    }
    assert large_row_id in large_candidate_ids
    assert multibyte_large_row_id in large_candidate_ids
    assert payload["summary"]["retention_candidate_total"] == 1
    retention_sample_ids = {
        int(item["id"])
        for item in payload["retention_candidate_samples"]
        if item.get("id") is not None
    }
    assert large_row_id in retention_sample_ids
    assert running_row_id not in retention_sample_ids

    json_path, markdown_path = write_task_history_governance_preview_artifacts(
        payload,
        output_dir=tmp_path / "audit",
        timestamp="20260605_120000",
    )
    assert json_path.exists()
    assert markdown_path.exists()
    assert json.loads(json_path.read_text(encoding="utf-8"))["preview_only"] is True
    assert "no_database_mutation" in markdown_path.read_text(encoding="utf-8")


def test_task_history_cleanup_dry_run_and_apply_archive_only_safe_statuses(
    tmp_path: Path,
) -> None:
    from utils.task_history_cleanup_execution import (
        REQUIRED_APPLY_CONFIRMATION,
        build_task_history_cleanup_plan_payload,
        execute_task_history_cleanup,
    )

    db_path = tmp_path / "bond_funds.db"
    conn = sqlite3.connect(db_path)
    try:
        conn.execute(
            """
            CREATE TABLE task_history (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                task_name TEXT NOT NULL,
                status TEXT NOT NULL,
                started_at TEXT NOT NULL,
                completed_at TEXT,
                duration INTEGER,
                records_processed INTEGER,
                records_inserted INTEGER,
                records_updated INTEGER,
                records_failed INTEGER,
                error_message TEXT,
                error_traceback TEXT,
                extra_data TEXT
            )
            """
        )

        def insert_row(task_name: str, status: str, started_at: str, extra_data: dict[str, Any] | None = None) -> int:
            cursor = conn.execute(
                """
                INSERT INTO task_history (
                    task_name, status, started_at, completed_at, duration,
                    records_processed, records_inserted, records_updated,
                    records_failed, error_message, error_traceback, extra_data
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    task_name,
                    status,
                    started_at,
                    started_at,
                    1,
                    1,
                    0,
                    0,
                    0,
                    "",
                    "",
                    json.dumps(extra_data or {}, ensure_ascii=False),
                ),
            )
            return int(cursor.lastrowid)

        old_success_a = insert_row("scheduled_daily_bond_refresh", "success", "2026-05-01T01:00:00")
        old_success_b = insert_row("scheduled_daily_bond_refresh", "success", "2026-05-02T01:00:00")
        recent_success = insert_row("scheduled_daily_bond_refresh", "success", "2026-06-04T01:00:00")
        old_watchdog = insert_row(
            "scheduled_snapshot_watchdog_refresh",
            "skipped",
            "2026-05-01T02:00:00",
            {"skip_reason": "effective_nav_snapshot_already_screened"},
        )
        recent_watchdog = insert_row(
            "scheduled_snapshot_watchdog_refresh",
            "skipped",
            "2026-06-04T02:00:00",
            {"skip_reason": "effective_nav_snapshot_already_screened"},
        )
        failed_row = insert_row("scheduled_intraday_bond_refresh", "failed", "2026-05-01T03:00:00")
        degraded_row = insert_row("scheduled_weekly_bond_maintenance", "degraded", "2026-05-01T04:00:00")
        running_row = insert_row("scheduled_daily_bond_refresh", "running", "2026-05-01T05:00:00")
        conn.commit()
    finally:
        conn.close()

    plan = build_task_history_cleanup_plan_payload(
        db_path=db_path,
        generated_at="2026-06-05T12:00:00",
        retention_days=14,
        recent_keep_per_task_status=1,
        max_sample_rows=20,
    )
    candidate_ids = {int(row["id"]) for row in plan["candidate_rows"]}
    assert candidate_ids == {old_success_a, old_success_b, old_watchdog}
    protected_ids = set(plan["protected_row_ids"])
    assert {recent_success, recent_watchdog, failed_row, degraded_row, running_row}.issubset(protected_ids)
    assert plan["summary"]["snapshot_watchdog_candidate_skipped_total"] == 1

    dry_json, dry_md, dry_payload = execute_task_history_cleanup(
        db_path=db_path,
        plan_payload=plan,
        output_dir=tmp_path / "audit",
        mode="dry-run",
        timestamp="20260605_120000",
    )
    assert dry_json.exists()
    assert dry_md.exists()
    assert dry_payload["status"] == "dry-run"

    conn = sqlite3.connect(db_path)
    try:
        before_apply_count = conn.execute("SELECT COUNT(*) FROM task_history").fetchone()[0]
    finally:
        conn.close()
    assert before_apply_count == 8

    with pytest.raises(ValueError, match="confirm_apply mismatch"):
        execute_task_history_cleanup(
            db_path=db_path,
            source_plan_artifact=dry_json,
            output_dir=tmp_path / "audit",
            archive_dir=tmp_path / "archive",
            mode="apply",
            confirm_apply="WRONG",
            backup_dir=tmp_path / "backups",
            compress_backup=False,
            timestamp="20260605_120001",
        )

    apply_json, apply_md, apply_payload = execute_task_history_cleanup(
        db_path=db_path,
        source_plan_artifact=dry_json,
        output_dir=tmp_path / "audit",
        archive_dir=tmp_path / "archive",
        mode="apply",
        confirm_apply=REQUIRED_APPLY_CONFIRMATION,
        backup_dir=tmp_path / "backups",
        compress_backup=False,
        timestamp="20260605_120002",
    )

    assert apply_json.exists()
    assert apply_md.exists()
    assert apply_payload["status"] == "success"
    assert apply_payload["summary"]["deleted_count"] == 3
    assert apply_payload["post_apply_consistency"]["status"] == "ok"
    archive_path = Path(apply_payload["archive"]["rows_archive_absolute_path"])
    assert archive_path.exists()
    assert len(archive_path.read_text(encoding="utf-8").strip().splitlines()) == 3
    skipped_summary_path = Path(apply_payload["archive"]["snapshot_watchdog_skipped_summary_absolute_path"])
    skipped_summary = json.loads(skipped_summary_path.read_text(encoding="utf-8"))
    assert skipped_summary["summary"]["candidate_skipped_total"] == 1

    conn = sqlite3.connect(db_path)
    try:
        remaining_ids = {
            int(row[0])
            for row in conn.execute("SELECT id FROM task_history ORDER BY id").fetchall()
        }
    finally:
        conn.close()
    assert candidate_ids.isdisjoint(remaining_ids)
    assert {recent_success, recent_watchdog, failed_row, degraded_row, running_row}.issubset(remaining_ids)


