def test_api_info_endpoint_exposes_lightweight_version_and_endpoint_contracts() -> None:
    import backend.app as backend_app

    client = backend_app.app.test_client()
    publication = {
        "latest_canonical_run_id": "20260606_101827_sync",
        "current_published_run_id": "20260606_101827_sync",
        "latest_canonical_report_path": "reports/runs/20260606_101827_sync/bond_analysis_report.json",
        "current_published_report_path": "reports/latest.json",
        "canonical_runs": [{"run_id": "20260606_101827_sync"}],
    }
    latest_report = {
        "run_id": "20260606_101827_sync",
        "final_count": 311,
    }

    with (
        patch.object(backend_app, "ensure_embedded_scheduler", side_effect=AssertionError("info should not start scheduler")),
        patch.object(backend_app, "_load_publication_registry_snapshot_cached", return_value=publication),
        patch.object(backend_app, "_load_latest_report_snapshot_cached", return_value=latest_report),
        patch.object(backend_app, "_load_publication_registry_cached", side_effect=AssertionError("info should use snapshot cache only")),
        patch.object(backend_app.manager, "latest_report", side_effect=AssertionError("info should not read manager latest report")),
        patch.object(backend_app, "_build_latest_dashboard_compact_cached", side_effect=AssertionError("info should not build dashboard payload")),
        patch.object(backend_app, "_build_tracker_current_response", side_effect=AssertionError("info should not build tracker detail")),
        patch.object(backend_app, "_build_recommendations_detail_response", side_effect=AssertionError("info should not build recommendations detail")),
    ):
        response = client.get("/api/info")

    assert response.status_code == 200
    payload = response.get_json()
    assert payload["status"] == "ok"
    assert payload["service"] == "fund-ana"
    assert payload["version"]["code_version"] == backend_app.__version__
    assert payload["version"]["latest_changelog"]["title"] == backend_app.VERSION_INFO.get("title")
    assert isinstance(payload["version"]["latest_changelog"]["changes"], list)
    assert 1 <= len(payload["version"]["latest_changelog"]["changes"]) <= 5
    assert payload["publication"]["latest_report_run_id"] == "20260606_101827_sync"
    assert payload["publication"]["latest_report_matches_current_published"] is True
    assert payload["publication"]["latest_report_matches_latest_canonical"] is True
    assert payload["build"]["code_version"] == backend_app.__version__
    assert "build_info_available" in payload["build"]
    assert payload["payload_scope"]["mode"] == "lightweight_info"
    assert payload["payload_scope"]["database_heavy_read"] is False
    assert payload["payload_scope"]["scheduler_heavy_read"] is False
    contracts = payload["endpoint_contracts"]
    contract_by_endpoint = {item["endpoint"]: item for item in contracts}
    assert contract_by_endpoint["/api/info"]["default_heavy"] is False
    assert contract_by_endpoint["/api/health/summary"]["default_heavy"] is False
    assert contract_by_endpoint["/api/bootstrap/summary"]["default_heavy"] is False
    assert contract_by_endpoint["/api/bootstrap/summary"]["default_scope"] == "lightweight"
    assert contract_by_endpoint["/api/reports/latest"]["default_heavy"] is False
    assert contract_by_endpoint["/api/scheduler/status/detail?full=1"]["default_heavy"] is True
    assert contract_by_endpoint["/api/tracker/current?full=1"]["default_heavy"] is True
    assert contract_by_endpoint["/api/favorites/score"]["default_scope"] == "compact"
    assert payload["heavy_endpoint_count"] >= 2
    upstream_contract = payload["upstream_api_source_contract"]
    assert upstream_contract["status"] == "ok"
    assert upstream_contract["contract_scope"] == "real_upstream_business_data_sources"
    assert upstream_contract["source_groups"]["tiantian"]["current_configured_base_url"] == (
        backend_app.settings.tiantian_base_url
    )
    assert upstream_contract["source_groups"]["autostock"]["current_configured_base_url"] == (
        backend_app.settings.autostock_base_url
    )
    assert "/fundMNRank" in upstream_contract["endpoint_index"]["tiantian"]
    assert "/fundMNHisNetList" in upstream_contract["endpoint_index"]["tiantian"]
    assert "/fund/detail/list" in upstream_contract["endpoint_index"]["autostock"]
    nav_contract = next(
        item
        for item in upstream_contract["source_groups"]["tiantian"]["endpoints"]
        if item["path"] == "/fundMNHisNetList"
    )
    assert "pagesize" in nav_contract["required_params"]
    assert "pageSize" in nav_contract["forbidden_param_aliases"]
    assert nav_contract["pagination"]["page_size_param"] == "pagesize"
    assert upstream_contract["quality_policy"]["fake_data_policy"] == "forbidden"
    assert upstream_contract["quality_policy"]["missing_value_policy"] == "preserve_missing_semantics"
    risk_contract = payload["risk_metric_formula_contract"]
    input_guards = risk_contract["database_engine"]["input_window_guard_contracts"]
    guard_by_code = {item["guard_code"]: item for item in input_guards}
    assert {
        "duplicate_nav_dates",
        "missing_selected_nav_values",
        "short_history_window",
        "insufficient_period_coverage",
        "stale_nav_against_snapshot",
    }.issubset(guard_by_code)
    assert guard_by_code["duplicate_nav_dates"]["truth_policy"] == "preserve_missing_semantics"
    assert "return None" in guard_by_code["short_history_window"]["missing_metric_semantics"]
    assert guard_by_code["stale_nav_against_snapshot"]["regression_test"] == (
        "test_risk_analyzer_multiyear_api_return_alignment_annualizes_cumulative_return"
    )
    parameter_contracts = risk_contract["database_engine"]["calculation_parameter_contracts"]
    parameter_by_code = {item["parameter_code"]: item for item in parameter_contracts}
    assert {
        "risk_free_rate",
        "sortino_minimum_acceptable_return",
        "annualization_frequency",
        "return_series_selection",
        "risk_adjusted_ratio_caps",
        "var_percentile_rules",
        "missing_metric_semantics",
    }.issubset(parameter_by_code)
    assert parameter_by_code["risk_free_rate"]["raw_unit"] == "decimal_ratio"
    assert parameter_by_code["annualization_frequency"]["configured_default_trading_days_per_year"] == 252
    assert parameter_by_code["risk_adjusted_ratio_caps"]["preserve_raw_fields"] is True
    assert parameter_by_code["missing_metric_semantics"]["disallow_zero_fill"] is True


def test_system_api_routes_are_registered_from_route_module() -> None:
    import backend.app as backend_app

    app_src = (PROJECT_ROOT / "backend" / "app.py").read_text(encoding="utf-8")
    system_route_src = (PROJECT_ROOT / "backend" / "api_routes" / "system.py").read_text(
        encoding="utf-8"
    )

    assert "from backend.api_routes.system import register_system_routes" in app_src
    assert "register_system_routes(" in app_src
    assert '@app.get("/api/info")' not in app_src
    assert '@app.get("/api/health")' not in app_src
    assert '@app.get("/api/healthz")' not in app_src
    assert '@app.get("/api/health/summary")' not in app_src
    assert '@app.get("/api/bootstrap/summary")' not in app_src
    assert '@app.get("/api/autostock/missing-response-observation")' not in app_src
    assert '@app.get("/api/info", endpoint="api_info")' in system_route_src
    assert '@app.get("/api/health", endpoint="health")' in system_route_src
    assert '@app.get("/api/healthz", endpoint="healthz")' in system_route_src
    assert '@app.get("/api/health/summary", endpoint="health_summary")' in system_route_src
    assert (
        '@app.get("/api/bootstrap/summary", endpoint="bootstrap_summary")'
        in system_route_src
    )
    assert 'endpoint="autostock_missing_response_observation"' in system_route_src

    route_by_rule = {
        rule.rule: rule.endpoint
        for rule in backend_app.app.url_map.iter_rules()
        if rule.rule
        in {
            "/api/info",
            "/api/health",
            "/api/healthz",
            "/api/health/summary",
            "/api/bootstrap/summary",
            "/api/autostock/missing-response-observation",
        }
    }
    assert route_by_rule["/api/info"] == "api_info"
    assert route_by_rule["/api/health"] == "health"
    assert route_by_rule["/api/healthz"] == "healthz"
    assert route_by_rule["/api/health/summary"] == "health_summary"
    assert route_by_rule["/api/bootstrap/summary"] == "bootstrap_summary"
    assert (
        route_by_rule["/api/autostock/missing-response-observation"]
        == "autostock_missing_response_observation"
    )


