def test_reports_api_routes_are_registered_from_route_module() -> None:
    import backend.app as backend_app

    app_src = (PROJECT_ROOT / "backend" / "app.py").read_text(encoding="utf-8")
    reports_route_src = (PROJECT_ROOT / "backend" / "api_routes" / "reports.py").read_text(
        encoding="utf-8"
    )

    assert "from backend.api_routes.reports import register_reports_routes" in app_src
    assert "register_reports_routes(" in app_src
    assert '@app.get("/api/status")' not in app_src
    assert '@app.get("/api/status/summary")' not in app_src
    assert '@app.post("/api/run")' not in app_src
    assert '@app.get("/api/reports")' not in app_src
    assert '@app.get("/api/reports/latest")' not in app_src
    assert '@app.get("/api/reports/latest/markdown")' not in app_src
    assert '@app.get("/api/preview-excel")' not in app_src
    assert '@app.get("/api/files/<path:relative_path>")' not in app_src
    assert '@app.get("/api/status", endpoint="status")' in reports_route_src
    assert '@app.get("/api/status/summary", endpoint="status_summary")' in reports_route_src
    assert '@app.post("/api/run", endpoint="run_workflow")' in reports_route_src
    assert '@app.get("/api/reports", endpoint="reports")' in reports_route_src
    assert '@app.get("/api/reports/latest", endpoint="latest_report")' in reports_route_src
    assert (
        '@app.get("/api/reports/latest/markdown", endpoint="latest_report_markdown")'
        in reports_route_src
    )
    assert '@app.get("/api/preview-excel", endpoint="preview_excel")' in reports_route_src
    assert (
        '@app.get("/api/files/<path:relative_path>", endpoint="project_file")'
        in reports_route_src
    )

    route_by_rule_and_method = {
        (rule.rule, method): rule.endpoint
        for rule in backend_app.app.url_map.iter_rules()
        if (
            rule.rule
            in {
                "/api/status",
                "/api/status/summary",
                "/api/run",
                "/api/reports",
                "/api/reports/latest",
                "/api/reports/latest/markdown",
                "/api/preview-excel",
            }
            or rule.rule.startswith("/api/files/")
        )
        for method in rule.methods
        if method in {"GET", "POST"}
    }
    assert route_by_rule_and_method[("/api/status", "GET")] == "status"
    assert route_by_rule_and_method[("/api/status/summary", "GET")] == "status_summary"
    assert route_by_rule_and_method[("/api/run", "POST")] == "run_workflow"
    assert route_by_rule_and_method[("/api/reports", "GET")] == "reports"
    assert route_by_rule_and_method[("/api/reports/latest", "GET")] == "latest_report"
    assert (
        route_by_rule_and_method[("/api/reports/latest/markdown", "GET")]
        == "latest_report_markdown"
    )
    assert route_by_rule_and_method[("/api/preview-excel", "GET")] == "preview_excel"
    assert route_by_rule_and_method[("/api/files/<path:relative_path>", "GET")] == "project_file"


def test_bootstrap_summary_endpoint_combines_header_health_and_workflow_payload() -> None:
    import backend.app as backend_app

    client = backend_app.app.test_client()
    scheduler_state = {
        "enabled": True,
        "scheduler_running": True,
        "automation_host_mode": "external_scheduler_process",
        "host_context": "external_scheduler_process",
        "configured_host_context": "external_scheduler_process",
        "jobs": [
            {"id": "daily_refresh", "next_run_time": "2026-05-19T07:30:00+08:00"},
        ],
    }

    with (
        patch.object(backend_app, "ensure_embedded_scheduler", lambda: None),
        patch.object(backend_app.SchedulerStateStore, "snapshot", return_value=scheduler_state),
        patch.object(
            backend_app.ProjectScheduler,
            "_scheduler_runtime_evidence",
            return_value={"alive": True},
        ),
        patch.object(backend_app, "_load_publication_registry_cached", return_value={}),
        patch.object(backend_app, "_load_publication_registry_snapshot_cached", return_value={}),
        patch.object(
            backend_app,
            "_workflow_header_summary",
            return_value={
                "status": "idle",
                "phase": None,
                "run_id": "20260519_073000_sync",
                "started_at": None,
                "finished_at": None,
                "error": None,
            },
        ),
    ):
        response = client.get("/api/bootstrap/summary")

    assert response.status_code == 200
    payload = response.get_json()
    assert payload["status"] == "ok"
    assert payload["health"]["status"] == "ok"
    assert payload["health"]["tiantian_base_url"] == backend_app.settings.tiantian_base_url
    assert payload["health"]["automation_mode"] == "automatic"
    assert payload["health"]["automation_status"] == "automatic"
    assert payload["health"]["manual_intervention_required"] is False
    assert payload["health"]["scheduler_running"] is True
    assert payload["health"]["next_run_label"] == "日更刷新"
    assert "database_source_audit" not in payload["health"]
    assert "scheduler_status" not in payload["health"]
    assert payload["workflow"]["status"] == "idle"
    assert payload["workflow"]["run_id"] == "20260519_073000_sync"
    assert "logs_tail" not in payload["workflow"]


