def test_build_scheduler_status_summary_payload_uses_report_freshness_risk_lag_projection() -> None:
    import backend.app as backend_app

    scheduler_state = {
        "enabled": True,
        "scheduler_running": True,
        "automation_host_mode": "external_scheduler_process",
        "host_context": "external_scheduler_process",
        "configured_host_context": "external_scheduler_process",
        "host_context_mismatch": False,
        "last_heartbeat_at": "2026-06-05T17:40:00",
        "job_drift_detected": False,
        "missing_job_ids": [],
        "unexpected_job_ids": [],
        "screening_backlog_due": False,
        "startup_catch_up_pending": False,
        "configured_job_ids": [],
        "effective_nav_snapshot": {
            "candidate_date": "2026-06-04",
            "ready": True,
            "signature": "sig-live",
        },
        "latest_screened_snapshot": {
            "candidate_date": "2026-06-04",
            "signature": "sig-live",
        },
        "last_runs": {},
        "schedule_stability_summary": {"summary": {"task_count": 4}, "tasks": []},
        "automation_closure_digest": {"summary": {"task_count": 4}, "alerts": [], "ordered_tasks": []},
        "maintenance_summary": {},
    }
    latest_report = {
        "run_id": "20260605_095125_sync",
        "generated_at": "2026-06-05T09:51:25",
        "database_freshness": {
            "risk_1y_freshness": _risk_1y_freshness_snapshot(),
        },
    }

    with (
        patch.object(backend_app, "_load_latest_report_snapshot_cached", return_value=latest_report),
        patch.object(
            backend_app,
            "_load_risk_lag_summary",
            side_effect=AssertionError("scheduler compact should use report risk freshness projection"),
        ),
        patch.object(backend_app, "_load_risk_sync_summary", return_value={}),
        patch.object(backend_app, "_load_risk_coverage_gap_summary", return_value={}),
        patch.object(backend_app, "_build_scheduler_overview_summary", side_effect=AssertionError("runtime fallback not needed")),
    ):
        payload = backend_app._build_scheduler_status_summary_payload(scheduler_state)

    risk_lag_summary = payload["risk_lag_summary"]
    assert risk_lag_summary["summary_source"] == "latest_report.database_freshness.risk_1y_freshness"
    assert risk_lag_summary["auxiliary_scope"] == "same_run_report_freshness_snapshot"
    assert risk_lag_summary["candidate_fund_count"] == 6161
    assert risk_lag_summary["effective_risk_uncovered_candidate_total"] == 584
    assert "effective_risk_uncovered_candidate_samples" not in risk_lag_summary
    governance = payload["nav_risk_governance_summary"]
    assert governance["risk_candidate_date"] == "2026-06-04"
    assert governance["risk_effective_end_date"] == "2026-06-04"
    assert governance["coverage_gate_status"] == "publish_ready"
    assert governance["risk_residual_warning_summary"]["auxiliary_scope"] == "same_run_report_freshness_snapshot"
    assert governance["risk_residual_warning_summary"]["replay_precision_status"] == "snapshot_frozen"


