def test_scheduler_status_summary_fragment_cache_hits_and_invalidates() -> None:
    import backend.app as backend_app

    backend_app._payload_cache.clear()
    backend_app._payload_cache_inflight.clear()
    scheduler_state = {
        "enabled": True,
        "scheduler_running": True,
        "automation_host_mode": "external_scheduler_process",
        "host_context": "external_scheduler_process",
        "configured_host_context": "external_scheduler_process",
        "host_context_mismatch": False,
        "last_heartbeat_at": "2026-06-05T17:40:00",
        "job_drift_detected": False,
        "missing_job_ids": [],
        "unexpected_job_ids": [],
        "screening_backlog_due": False,
        "startup_catch_up_pending": False,
        "configured_job_ids": [],
        "effective_nav_snapshot": {
            "candidate_date": "2026-06-04",
            "ready": True,
            "signature": "sig-live",
        },
        "latest_screened_snapshot": {
            "candidate_date": "2026-06-04",
            "signature": "sig-live",
        },
        "last_runs": {},
        "schedule_stability_summary": {"summary": {"task_count": 4}, "tasks": []},
        "automation_closure_digest": {"summary": {"task_count": 4}, "alerts": [], "ordered_tasks": []},
        "maintenance_summary": {},
    }
    latest_report = {
        "run_id": "20260605_095125_sync",
        "generated_at": "2026-06-05T09:51:25",
        "database_freshness": {
            "risk_1y_freshness": _risk_1y_freshness_snapshot(),
        },
    }
    publication = {
        "automation_layers": {
            "latest_successful_run": {
                "run_id": "20260605_095125_sync",
                "publishable": True,
                "publish_blockers": [],
            }
        }
    }
    risk_gap_summary = {
        "run_id": "20260605_095125_sync",
        "latest_canonical_run_id": "20260605_095125_sync",
        "replay_precision_status": "exact",
        "auxiliary_scope": "same_run_report_artifact",
        "actionable_gap_total": 0,
        "current_publish_blocker_total": 0,
    }

    with ExitStack() as stack:
        # This unit test controls the input snapshot; a live collector's WAL must not change its cache key.
        stack.enter_context(patch.object(backend_app, "_scheduler_summary_common_file_cache_basis", return_value={"fixture": "stable"}))
        stack.enter_context(patch.object(backend_app, "_load_current_final_selection_governance_queue_summary_cached", return_value={}))
        stack.enter_context(patch.object(backend_app, "_load_latest_report_snapshot_cached", return_value=latest_report))
        stack.enter_context(patch.object(backend_app, "_load_latest_report_cached", return_value=latest_report))
        stack.enter_context(patch.object(backend_app, "_load_database_overview", return_value={}))
        stack.enter_context(patch.object(backend_app, "_load_risk_sync_summary", return_value={}))
        stack.enter_context(patch.object(backend_app, "_load_risk_coverage_gap_summary", return_value=risk_gap_summary))
        first = backend_app._build_scheduler_status_summary_payload(
            scheduler_state,
            publication=publication,
        )
        second = backend_app._build_scheduler_status_summary_payload(
            scheduler_state,
            publication=publication,
        )
        changed_state = {
            **scheduler_state,
            "latest_screened_snapshot": {
                "candidate_date": "2026-06-05",
                "signature": "sig-new",
            },
        }
        third = backend_app._build_scheduler_status_summary_payload(
            changed_state,
            publication=publication,
        )

    first_profile = first["scheduler_summary_build_profile"]
    second_profile = second["scheduler_summary_build_profile"]
    third_profile = third["scheduler_summary_build_profile"]
    assert first_profile["schema_version"] >= 2
    assert {item["fragment"] for item in first_profile["fragment_cache"]} == {
        "automation_and_path_governance",
        "risk_coverage_gap_summary",
        "nav_risk_governance",
    }
    assert first_profile["fragment_cache_miss_count"] == 3
    assert first_profile["fragment_cache_hit_count"] == 0
    assert second_profile["fragment_cache_hit_count"] == 3
    assert second_profile["fragment_cache_miss_count"] == 0
    assert all(item["status"] == "hit" for item in second_profile["fragment_cache"])
    assert third_profile["fragment_cache_miss_count"] >= 1
    assert any(
        item["fragment"] in {"automation_and_path_governance", "nav_risk_governance"}
        and item["status"] == "miss"
        for item in third_profile["fragment_cache"]
    )


def _assert_dashboard_build_profile(
    payload: dict[str, Any],
    *,
    detail_scope: str,
    compact: bool,
    expected_step: str,
) -> None:
    profile = payload["dashboard_build_profile"]
    assert profile["schema_version"] >= 1
    assert profile["detail_scope"] == detail_scope
    assert profile["compact"] is compact
    assert profile["timing_unit"] == "seconds"
    assert profile["step_count"] > 0
    assert profile["total_seconds"] >= 0
    assert any(step["name"] == expected_step for step in profile["steps"])
    assert isinstance(profile["slowest_steps"], list)


def _assert_dashboard_build_profile_steps(
    payload: dict[str, Any],
    expected_steps: tuple[str, ...],
) -> None:
    step_names = {str(step.get("name") or "") for step in payload["dashboard_build_profile"]["steps"]}
    missing_steps = [step for step in expected_steps if step not in step_names]
    assert missing_steps == []


def test_dashboard_overview_sidecar_requires_matching_input_fingerprint(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import backend.app as backend_app

    reports_dir = tmp_path / "reports"
    latest_report = tmp_path / "latest.json"
    publication_registry = tmp_path / "publication_registry.json"
    scheduler_state = tmp_path / "scheduler_state.json"
    database = tmp_path / "bond_funds.db"
    for path, payload in (
        (latest_report, {"run_id": "run-1"}),
        (publication_registry, {"latest_canonical_run_id": "run-1"}),
        (scheduler_state, {"scheduler_running": True}),
    ):
        path.write_text(json.dumps(payload), encoding="utf-8")
    database.write_bytes(b"sqlite-main")

    monkeypatch.setattr(backend_app.settings, "reports_dir", reports_dir)
    monkeypatch.setattr(backend_app.settings, "latest_report_file", latest_report)
    monkeypatch.setattr(backend_app.settings, "publication_registry_file", publication_registry)
    monkeypatch.setattr(backend_app.settings, "database_path", database)
    monkeypatch.setattr(
        backend_app,
        "_runtime_scheduler_settings",
        lambda: SimpleNamespace(scheduler_state_file=scheduler_state),
    )
    # This fixture exercises filesystem fingerprints using a placeholder DB.
    # Low-volatility publication loading has its own database-backed tests.
    monkeypatch.setattr(backend_app, "_low_vol_overlap_audit_cache_token", lambda: "fixed-audit")

    original_basis = backend_app._build_dashboard_overview_cache_basis()
    response_payload = {
        "run_id": "run-1",
        "dashboard_build_profile": {"schema_version": 1, "steps": []},
    }
    backend_app._write_dashboard_overview_sidecar(original_basis, response_payload)

    assert backend_app._load_dashboard_overview_sidecar(original_basis) == response_payload
    sidecar_path = reports_dir / ".cache" / "dashboard_overview_response.json"
    assert sidecar_path.exists()

    scheduler_state.write_text(
        json.dumps({"scheduler_running": True, "last_heartbeat_at": "2026-06-06T02:25:00", "pid": 123}),
        encoding="utf-8",
    )
    heartbeat_only_basis = backend_app._build_dashboard_overview_cache_basis()
    assert heartbeat_only_basis == original_basis
    assert backend_app._load_dashboard_overview_sidecar(heartbeat_only_basis) == response_payload

    os.utime(publication_registry, None)
    publication_mtime_only_basis = backend_app._build_dashboard_overview_cache_basis()
    assert publication_mtime_only_basis == original_basis
    assert backend_app._load_dashboard_overview_sidecar(publication_mtime_only_basis) == response_payload

    (tmp_path / "bond_funds.db-wal").write_bytes(b"new-wal-frame")
    changed_basis = backend_app._build_dashboard_overview_cache_basis()
    assert changed_basis["database_file"] != original_basis["database_file"]
    assert backend_app._load_dashboard_overview_sidecar(changed_basis) is None


def test_dashboard_overview_cached_uses_sidecar_before_heavy_builder() -> None:
    import backend.app as backend_app

    cache_basis = {"schema_version": 1, "token": "stable"}
    with (
        patch.object(backend_app, "_build_dashboard_overview_cache_basis", return_value=cache_basis),
        patch.object(backend_app, "_dashboard_overview_cache_key", return_value="dashboard-overview-test-key"),
        patch.object(
            backend_app,
            "_load_dashboard_overview_sidecar",
            return_value={
                "run_id": "sidecar-run",
                "scheduler_overview": {
                    "scheduler_running": True,
                    "last_heartbeat_at": "2026-06-06T02:20:00",
                    "current_task": {},
                },
            },
        ),
        patch.object(
            backend_app,
            "_load_scheduler_state_snapshot_cached",
            return_value={
                "scheduler_running": False,
                "last_heartbeat_at": "2026-06-06T02:25:00",
                "current_task": {"task_name": "scheduled_snapshot_watchdog_refresh"},
            },
        ),
        patch.object(backend_app, "_cached_payload", side_effect=lambda _key, _ttl, builder: builder()),
        patch.object(
            backend_app,
            "_build_dashboard_overview_response",
            side_effect=AssertionError("sidecar hit should not build dashboard overview"),
        ),
    ):
        payload = backend_app._build_dashboard_overview_cached()

    assert payload["run_id"] == "sidecar-run"
    assert payload["scheduler_overview"]["scheduler_running"] is False
    assert payload["scheduler_overview"]["last_heartbeat_at"] == "2026-06-06T02:25:00"
    assert payload["scheduler_overview"]["current_task"]["task_name"] == "scheduled_snapshot_watchdog_refresh"
    assert payload["source_basis"]["source"] == (
        "dashboard_overview_current_published_report_scheduler_database_artifacts"
    )
    assert payload["source_basis"]["payload_mode"] == "overview"
    assert payload["source_basis"]["cache_basis_digest"]
    assert payload["cache_basis"] == payload["source_basis"]
    assert payload["source_contract"]["truth_policy"] == (
        "real_publication_registry_report_artifact_scheduler_state_database_and_runtime_artifacts_only"
    )
    assert payload["source_contract"]["cache_basis_digest"] == payload["source_basis"]["digest"]


