def test_final_selection_removed_is_not_counted_as_formal_publish_status() -> None:
    import pandas as pd

    df = pd.DataFrame(
        [
            {
                "发布结论状态": "最终精选未入围",
                "可投资性状态": "可投资",
                "数据就绪状态": "已就绪",
                "质量结论状态": "质量通过",
            },
            {
                "发布结论状态": "质量筛选拦截",
                "可投资性状态": "可投资",
                "数据就绪状态": "已就绪",
                "质量结论状态": "质量未通过",
            },
        ]
    )

    import backend.report_builder as report_builder

    audit_df = report_builder._build_status_split_audit(df)
    publish_rows = audit_df[audit_df["状态维度"] == "发布结论状态"].to_dict(orient="records")
    statuses = {row["状态值"]: row["数量"] for row in publish_rows}

    assert statuses["最终精选未入围"] == 1
    assert "正式发布" not in statuses


