def test_recommendations_latest_detail_group_scopes_fund_rows() -> None:
    import backend.app as backend_app

    client = backend_app.app.test_client()
    fake_payload = {
        "run_id": "20260415_110721_sync",
        "generated_at": "2026-04-15T11:07:21",
        "counts": {
            "final_count": 380,
            "stable_bond_final_count": 152,
            "enhanced_bond_final_count": 228,
            "project_tracker_current_active_count": 380,
            "project_tracker_total_periods": 5,
        },
        "artifacts": {},
        "project_publish_summary": {
            "project_tracker_summary": {
                "latest_nav_snapshot_date": "2026-04-14",
                "current_active_count": 380,
            },
            "portfolio_suggestions": {
                "available": True,
                "source_candidate_count": 18,
                "candidate_count": 18,
                "target_count": 6,
                "company_cap": 2,
                "groups": [
                    {
                        "name": "核心关注名单",
                        "description": "测试组合",
                        "count": 1,
                        "funds": [
                            {
                                "基金代码": "000001",
                                "基金名称": "测试基金A",
                                "债基风格标签": "综合纯债",
                                "正式投资评分": "92.1",
                            }
                        ],
                    },
                    {
                        "name": "增强债弹性扩展",
                        "description": "测试扩展",
                        "count": 2,
                        "funds": [
                            {
                                "基金代码": "000002",
                                "基金名称": "测试基金B",
                                "债基风格标签": "一级债增强",
                                "正式投资评分": "81.0",
                            },
                            {
                                "基金代码": "000003",
                                "基金名称": "测试基金C",
                                "债基风格标签": "二级债增强",
                                "正式投资评分": "80.0",
                            },
                        ],
                    },
                ],
            },
        },
    }

    with (
        patch.object(backend_app, "ensure_embedded_scheduler", lambda: None),
        patch.object(backend_app, "_load_latest_report_snapshot_cached", return_value=fake_payload),
        patch.object(backend_app, "_load_latest_report_cached", return_value=None),
        patch.object(backend_app.manager, "latest_report", return_value=fake_payload),
    ):
        full_response = client.get("/api/recommendations/latest/detail")
        scoped_response = client.get("/api/recommendations/latest/detail?group=增强债弹性扩展")
        scoped_compat_response = client.get("/api/recommendations/latest?scope=detail&group=核心关注名单")

    assert full_response.status_code == 200
    assert scoped_response.status_code == 200
    assert scoped_compat_response.status_code == 200

    full_payload = full_response.get_json()
    scoped_payload = scoped_response.get_json()
    compat_payload = scoped_compat_response.get_json()

    assert [item["基金代码"] for item in full_payload["portfolio_suggestions"]["funds"]] == [
        "000001",
        "000002",
        "000003",
    ]
    assert scoped_payload["payload_scope"]["mode"] == "detail"
    assert scoped_payload["payload_scope"]["group_parameter"] == "group"
    assert scoped_payload["payload_scope"]["detail_group_name"] == "增强债弹性扩展"
    assert scoped_payload["payload_scope"]["detail_group_found"] is True
    assert scoped_payload["payload_scope"]["detail_group_fund_count"] == 2
    assert [item["基金代码"] for item in scoped_payload["funds"]] == ["000002", "000003"]
    assert [item["基金代码"] for item in scoped_payload["rows"]] == ["000002", "000003"]
    assert scoped_payload["portfolio_suggestions"]["groups"][0]["name"] == "核心关注名单"
    assert "funds" not in scoped_payload["portfolio_suggestions"]["groups"][0]
    assert scoped_payload["portfolio_suggestions"]["groups"][1]["funds"][0]["基金代码"] == "000002"
    assert scoped_payload["payload_scope"]["available_groups"][0]["name"] == "核心关注名单"

    assert compat_payload["payload_scope"]["detail_group_name"] == "核心关注名单"
    assert [item["基金代码"] for item in compat_payload["portfolio_suggestions"]["funds"]] == ["000001"]


def test_recommendations_detail_sidecar_requires_matching_input_fingerprint(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import backend.app as backend_app

    reports_dir = tmp_path / "reports"
    runs_dir = reports_dir / "runs"
    latest_report = reports_dir / "latest.json"
    publication_registry = reports_dir / "publication_registry.json"
    database = tmp_path / "bond_funds.db"
    tracker_sidecar = runs_dir / "run-1" / "project_tracker_current_detail.json"
    tracker_excel = runs_dir / "run-1" / "tracker.xlsx"
    for path, payload in (
        (latest_report, {"run_id": "run-1", "counts": {"final_count": 1}}),
        (publication_registry, {"latest_canonical_run_id": "run-1"}),
        (
            tracker_sidecar,
            {
                "artifact_type": "project_tracker_current_detail_sidecar",
                "schema_version": 1,
                "rows": [{"基金代码": "000001"}],
            },
        ),
    ):
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(payload, ensure_ascii=False), encoding="utf-8")
    database.write_bytes(b"sqlite-main")
    tracker_excel.write_bytes(b"xlsx")

    monkeypatch.setattr(backend_app.settings, "project_root", tmp_path)
    monkeypatch.setattr(backend_app.settings, "reports_dir", reports_dir)
    monkeypatch.setattr(backend_app.settings, "runs_dir", runs_dir)
    monkeypatch.setattr(backend_app.settings, "latest_report_file", latest_report)
    monkeypatch.setattr(backend_app.settings, "publication_registry_file", publication_registry)
    monkeypatch.setattr(backend_app.settings, "database_path", database)

    payload = {
        "run_id": "run-1",
        "generated_at": "2026-06-06T02:40:00",
        "artifacts": {
            "project_tracker_current_detail_json": "reports/runs/run-1/project_tracker_current_detail.json",
            "project_tracker_excel": "reports/runs/run-1/tracker.xlsx",
        },
    }
    cache_basis = backend_app._build_recommendations_detail_cache_basis(payload)
    response_payload = {
        "run_id": "run-1",
        "payload_scope": {"mode": "detail"},
        "portfolio_suggestions": {"funds": [{"基金代码": "000001"}]},
        "rows": [{"基金代码": "000001"}],
        "funds": [{"基金代码": "000001"}],
    }

    sidecar_path = backend_app._write_recommendations_detail_sidecar(
        payload,
        cache_basis,
        response_payload,
    )
    assert sidecar_path == runs_dir / "run-1" / "recommendations_detail.json"
    loaded = backend_app._load_recommendations_detail_sidecar(payload, cache_basis)
    assert loaded is not None
    assert loaded["run_id"] == "run-1"
    assert loaded["cache_basis"] == cache_basis
    assert loaded["source_basis"] == cache_basis
    assert loaded["source_contract"]["source"] == "run_local_recommendations_detail"
    assert loaded["source_contract"]["truth_policy"] == "real_api_database_or_runtime_artifact_only"
    assert loaded["source_contract"]["business_value_synthesis"] == "forbidden"
    assert loaded["payload_scope"]["source_contract"]["source"] == "run_local_recommendations_detail"
    assert loaded["payload_scope"]["source_contract"]["cache_basis_present"] is True
    assert loaded["payload_scope"]["__recommendations_detail_sidecar"]["source"] == "run_local_recommendations_detail_sidecar"

    tracker_payload = json.loads(tracker_sidecar.read_text(encoding="utf-8"))
    tracker_payload["derived_fields"] = {
        "schema_version": 1,
        "generated_at": "2026-06-06T03:10:00",
        "cache_basis": {"runtime": "tracker-derived"},
        "data_source_by_code": {"000001": "fundMNRank"},
    }
    tracker_sidecar.write_text(json.dumps(tracker_payload, ensure_ascii=False), encoding="utf-8")
    assert backend_app._build_recommendations_detail_cache_basis(payload) == cache_basis
    assert backend_app._load_recommendations_detail_sidecar(payload, cache_basis) is not None

    os.utime(publication_registry, None)
    assert backend_app._build_recommendations_detail_cache_basis(payload) == cache_basis

    (tmp_path / "bond_funds.db-wal").write_bytes(b"new-wal-frame")
    changed_basis = backend_app._build_recommendations_detail_cache_basis(payload)
    assert changed_basis["database_file"] != cache_basis["database_file"]
    assert backend_app._load_recommendations_detail_sidecar(payload, changed_basis) is None


