def test_load_tracker_dataset_reads_near1w_from_group_sheet(tmp_path: Path) -> None:
    from backend.api_payloads import recommendations as recommendations_payloads

    tracker_file = tmp_path / "tracker.xlsx"
    filtered_file = tmp_path / "filtered.xlsx"
    tracker_file.write_text("", encoding="utf-8")
    filtered_file.write_text("", encoding="utf-8")

    def fake_read_tracker_workbook_sheet(_path, sheet_name, usecols):
        if sheet_name == "当前在榜":
            return pd.DataFrame(
                [
                    {
                        "基金代码": "000001",
                        "基金名称": "测试债A",
                        "正式榜分组": "纯债稳健榜",
                        "正式投资评分": "89.5",
                        "出现次数": "4",
                        "出现频率(%)": "66.67",
                        "基金规模(亿)": "12.3",
                        "数据来源": "fundMNRank",
                    }
                ]
            )
        raise ValueError(f"unexpected sheet: {sheet_name}")

    def fake_read_excel_cached(_path, sheet_name, usecols):
        if sheet_name == "推荐理由与风格":
            return pd.DataFrame(
                [
                    {
                        "基金代码": "000001",
                        "债基风格标签": "综合纯债",
                        "长期稳定性标签": "稳定",
                    }
                ]
            )
        if sheet_name == "纯债稳健榜":
            assert "近1周(%)" in usecols
            return pd.DataFrame(
                [
                    {
                        "基金代码": "000001",
                        "基金公司": "测试基金",
                        "基金规模(亿)": "12.3",
                        "近1周(%)": "0.12",
                        "近1月(%)": "0.25",
                        "近3月(%)": "0.8",
                        "1年-波动率": "0.55",
                        "1年-最大回撤(%)": "-0.22",
                        "1年-年化收益(%)": "3.2",
                        "1年-夏普比率": "1.05",
                        "最新净值日期": "2026-05-22",
                        "数据来源": "fundMNRank",
                    }
                ]
            )
        raise ValueError(f"unexpected sheet: {sheet_name}")

    dataset = recommendations_payloads.load_tracker_dataset(
        {
            "artifacts": {
                "project_tracker_excel": str(tracker_file.relative_to(tmp_path)),
                "filtered_excel": str(filtered_file.relative_to(tmp_path)),
            }
        },
        settings=SimpleNamespace(project_root=tmp_path),
        read_excel_cached=fake_read_excel_cached,
        read_tracker_workbook_sheet=fake_read_tracker_workbook_sheet,
    )

    assert dataset["group_records_by_code"]["000001"]["近1周(%)"] == "0.12"


