def test_autostock_budget_plan_reserves_automation_calls() -> None:
    from backend.autostock_budget import plan_autostock_call_budget

    exhausted_for_ui = plan_autostock_call_budget(
        quota_snapshot={
            "quota_limited": True,
            "max_calls_per_hour": 100,
            "quota_remaining": 10,
            "quota_exhausted": False,
        },
        needed_call_count=1,
        reserve_calls=20,
    )
    assert exhausted_for_ui["allowed_call_count"] == 0
    assert exhausted_for_ui["quota_unavailable"] is True
    assert exhausted_for_ui["quota_reserved_for_automation"] == 20

    enough_for_ui = plan_autostock_call_budget(
        quota_snapshot={
            "quota_limited": True,
            "max_calls_per_hour": 100,
            "quota_remaining": 25,
            "quota_exhausted": False,
        },
        needed_call_count=1,
        reserve_calls=20,
    )
    assert enough_for_ui["allowed_call_count"] == 1
    assert enough_for_ui["quota_unavailable"] is False


def test_fetch_favorite_autostock_snapshot_reserves_scheduler_budget(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import backend.app as backend_app

    # This drill exercises the retained AutoStock path explicitly.
    monkeypatch.setattr(backend_app.settings, "autostock_enabled", True)

    class _UnexpectedClient:
        def get_fund_batch_with_meta(self, *_args, **_kwargs):
            raise AssertionError("favorites score must not call AutoStock when UI budget is unavailable")

    monkeypatch.setattr(backend_app, "_get_autostock_client", lambda: _UnexpectedClient())
    monkeypatch.setattr(backend_app, "_get_autostock_batch_size", lambda: 50)
    monkeypatch.setattr(
        backend_app,
        "_read_autostock_quota_snapshot",
        lambda now=None: {
            "quota_limited": True,
            "max_calls_per_hour": 100,
            "recent_call_count": 90,
            "quota_remaining": 10,
            "quota_exhausted": False,
            "rate_limit_wait_seconds": 0.0,
            "state_read_error": None,
        },
    )

    snapshot = backend_app._fetch_favorite_autostock_snapshot(["000001", "000002"])

    assert snapshot == {}
    meta = snapshot.autostock_budget_meta
    assert meta["status"] == "quota_degraded"
    assert meta["request_source"] == "favorites_score"
    assert meta["requested_count"] == 2
    assert meta["upstream_requested_count"] == 0
    assert meta["skipped_quota_count"] == 2
    assert meta["quota_unavailable"] is True
    assert meta["quota_reserved_for_automation"] == backend_app._FAVORITE_AUTOSTOCK_AUXILIARY_RESERVE_CALLS


def test_fetch_favorite_autostock_snapshot_batches_large_queries_without_50_code_truncation(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import backend.app as backend_app

    # This drill exercises the retained AutoStock path explicitly.
    monkeypatch.setattr(backend_app.settings, "autostock_enabled", True)

    calls: list[list[str]] = []

    class _BatchClient:
        def get_fund_batch_with_meta(self, codes, *, batch_size):
            batch_codes = list(codes)
            calls.append(batch_codes)
            return (
                [
                    {
                        "code": code,
                        "name": f"基金{code}",
                        "netWorth": "1.0000",
                        "netWorthDate": "2026-06-22",
                        "expectWorth": "1.0001",
                        "expectGrowth": "0.01",
                        "expectWorthDate": "2026-06-22 10:30:00",
                    }
                    for code in batch_codes
                ],
                {"quota_exhausted": False, "last_error": None},
            )

    monkeypatch.setattr(backend_app, "_get_autostock_client", lambda: _BatchClient())
    monkeypatch.setattr(backend_app, "_get_autostock_batch_size", lambda: 50)
    monkeypatch.setattr(
        backend_app,
        "_read_autostock_quota_snapshot",
        lambda now=None: {
            "quota_limited": True,
            "max_calls_per_hour": 100,
            "recent_call_count": 0,
            "quota_remaining": 100,
            "quota_exhausted": False,
            "rate_limit_wait_seconds": 0.0,
            "state_read_error": None,
        },
    )

    codes = [f"{index:06d}" for index in range(1, 301)]
    snapshot = backend_app._fetch_favorite_autostock_snapshot(codes)

    assert len(snapshot) == 300
    assert [len(item) for item in calls] == [50, 50, 50, 50, 50, 50]
    assert calls[0][0] == "000001"
    assert calls[-1][-1] == "000300"
    meta = snapshot.autostock_budget_meta
    assert meta["status"] == "ok"
    assert meta["requested_count"] == 300
    assert meta["upstream_requested_count"] == 300
    assert meta["upstream_returned_count"] == 300
    assert meta["returned_count"] == 300
    assert meta["batch_count"] == 6
    assert meta["skipped_over_limit_count"] == 0
    assert meta["skipped_quota_count"] == 0
    assert meta["max_request_codes"] >= 300


