def test_overlay_favorite_row_with_autostock_marks_empty_estimate_as_unavailable_text() -> None:
    import backend.app as backend_app

    row = {
        "基金代码": "000001",
        "基金名称": "测试债A",
        "最新单位净值": "1.0000",
    }
    autostock_row = {
        "code": "000001",
        "name": "测试债A",
        "netWorth": "1.0000",
        "netWorthDate": "2026-05-11",
        "expectWorth": "",
        "expectGrowth": "",
        "expectWorthDate": "",
    }

    result = backend_app._overlay_favorite_row_with_autostock(row, autostock_row)

    assert result["实时估值"] == ""
    assert result["__valuation_state"] == "unresolved"
    assert result["__valuation_status_label"] == "待实时估值接口补查"
    assert result["__valuation_reason"] == "valuation_lookup_pending"
    assert result["实时估值时间"] == ""
    assert result["实时估算净值"] == ""
    assert result["最新单位净值"] == backend_app._normalize_number_text("1.0000", digits=4)
    assert result["最新净值日期"] == "2026-05-11"


