def test_dashboard_latest_compact_cache_invalidates_when_latest_report_content_changes(tmp_path: Path) -> None:
    import backend.app as backend_app

    latest_report_file = tmp_path / "latest.json"
    publication_registry_file = tmp_path / "publication_registry.json"
    scheduler_state_file = tmp_path / "scheduler_state.json"
    reports_dir = tmp_path / "reports"
    (reports_dir / "audit" / "final_selection_contraction_shadow").mkdir(parents=True)
    latest_report_file.write_text('{"run_id":"run1"}', encoding="utf-8")
    publication_registry_file.write_text('{"current_published_run_id":"run1"}', encoding="utf-8")
    scheduler_state_file.write_text('{"scheduler_running":true}', encoding="utf-8")
    settings = SimpleNamespace(
        project_root=tmp_path,
        latest_report_file=latest_report_file,
        publication_registry_file=publication_registry_file,
        scheduler_state_file=scheduler_state_file,
        reports_dir=reports_dir,
    )
    calls = {"count": 0}

    def _fake_dashboard_builder(*_args, **_kwargs):
        calls["count"] += 1
        return {"build_seq": calls["count"], "run_id": f"dashboard-{calls['count']}"}

    backend_app._payload_cache.clear()
    backend_app._payload_cache_inflight.clear()
    with (
        patch.object(backend_app, "settings", settings),
        patch.object(backend_app, "_runtime_scheduler_settings", return_value=settings),
        patch.object(backend_app, "_load_current_published_report_cached", return_value={"run_id": "run1"}),
        patch.object(backend_app, "_load_latest_report_snapshot_cached", return_value={"run_id": "run1"}),
        patch.object(backend_app, "_load_latest_report_cached", return_value={"run_id": "run1"}),
        patch.object(backend_app, "_load_publication_registry_snapshot_cached", return_value={}),
        patch.object(backend_app, "_load_publication_registry_cached", return_value={}),
        patch.object(backend_app, "_load_scheduler_state_snapshot_cached", return_value={}),
        patch.object(backend_app.dashboard_payloads, "build_latest_dashboard_response", side_effect=_fake_dashboard_builder),
    ):
        first = backend_app._build_latest_dashboard_compact_cached()
        second = backend_app._build_latest_dashboard_compact_cached()
        latest_report_file.write_text('{"run_id":"run2"}', encoding="utf-8")
        third = backend_app._build_latest_dashboard_compact_cached()

    assert first["build_seq"] == 1
    assert second["build_seq"] == 1
    assert third["build_seq"] == 2
    assert calls["count"] == 2


