def test_cached_payload_collapses_concurrent_builders() -> None:
    import backend.app as backend_app

    backend_app._payload_cache.clear()
    backend_app._payload_cache_inflight.clear()
    calls = {"count": 0}
    ready = threading.Event()

    def _builder():
        calls["count"] += 1
        ready.wait(timeout=2)
        return {"value": "ok"}

    results = []

    def _run():
        results.append(backend_app._cached_payload("concurrent-test", 30.0, _builder))

    first = threading.Thread(target=_run)
    second = threading.Thread(target=_run)
    first.start()
    second.start()
    time.sleep(0.1)
    ready.set()
    first.join(timeout=2)
    second.join(timeout=2)

    assert results == [{"value": "ok"}, {"value": "ok"}]
    assert calls["count"] == 1


def test_positive_ratio_shadow_watch_normalization_backfills_machine_readable_semantics() -> None:
    publish_summary = {
        "positive_ratio_semantics": {
            "definition": "1年日频正收益天数占比",
            "industry_standard": False,
        },
        "low_vol_positive_ratio_shadow_watch": {
            "available": True,
            "focus_sample_count": 100,
            "monthly_shadow_ready_count": 80,
            "positive_ratio_gate_hit_count": 30,
            "positive_ratio_gap_alert_count": 18,
            "low_vol_overlap_summary": {
                "available": True,
                "annual_positive_direct_final_impact_count": 0,
                "annual_without_positive_direct_final_impact_count": 1,
                "positive_without_annual_direct_final_impact_count": 1,
                "positive_only_direct_final_impact_count": 0,
            },
        },
    }

    normalized_watch = normalize_low_vol_positive_ratio_shadow_watch(publish_summary)
    semantics = build_positive_ratio_semantics_summary(publish_summary, normalized_watch)

    assert normalized_watch["semantics"]["metric_family"] == "internal_stability_proxy"
    assert normalized_watch["semantics"]["shadow_interpretation_mode"] == "unverified_strategy_impact"
    assert normalized_watch["semantics"]["production_vs_shadow_alignment_status"] == "gap_alert_observed"
    assert normalized_watch["semantics"]["shadow_ready_sample_ratio_pct"] == 80.0
    assert normalized_watch["semantics"]["shadow_gap_alert_ratio_pct"] == 18.0
    assert normalized_watch["semantics"]["production_gate_hit_ratio_pct"] == 30.0
    assert normalized_watch["semantics"]["strategy_materiality_status"] == "unknown"
    assert normalized_watch["semantics"]["production_governance_decision"] == "await_frozen_strategy_audit"
    assert normalized_watch["semantics"]["governance_judgement"] == "unverified"
    assert normalized_watch["semantics"]["positive_ratio_independent_direct_final_impact_count"] is None
    assert normalized_watch["semantics"]["recommended_audit_path"] == "audit_low_vol_annual_positive_ratio_overlap"
    assert "治理结论为 `await_frozen_strategy_audit`" in normalized_watch["explanation"]
    assert semantics["positive_ratio_independent_direct_final_impact_count"] is None
    assert semantics["headline"] == normalized_watch["headline"]


