def test_audit_final_selection_incremental_safety_review_flags_block_and_watch(tmp_path: Path) -> None:
    module = _load_script_module(
        "audit_final_selection_contraction_shadow_for_test_safety_review",
        "scripts/audit_final_selection_contraction_shadow.py",
    )
    db_path = tmp_path / "bond_funds.db"
    conn = sqlite3.connect(str(db_path))
    try:
        conn.executescript(
            """
            CREATE TABLE funds (
                fcode TEXT PRIMARY KEY,
                shortname TEXT,
                ftype TEXT,
                estab_date TEXT,
                scale_billion REAL,
                has_holding_period INTEGER,
                holding_days INTEGER,
                holding_period_source TEXT,
                is_buyable INTEGER,
                purchase_status TEXT,
                mgr_fee_rate REAL,
                trust_fee_rate REAL,
                sales_fee_rate REAL
            );
            CREATE TABLE fund_returns (
                fcode TEXT PRIMARY KEY,
                latest_nav_date TEXT,
                latest_nav REAL,
                daily_growth REAL,
                return_1w REAL,
                return_1m REAL,
                return_3m REAL,
                return_6m REAL,
                return_1y REAL,
                return_2y REAL,
                return_3y REAL,
                return_ytd REAL,
                return_since REAL
            );
            CREATE TABLE fund_risk_metrics (
                fcode TEXT,
                period TEXT,
                annual_return REAL,
                volatility REAL,
                max_drawdown REAL,
                sharpe_ratio REAL,
                calmar_ratio REAL,
                positive_ratio REAL,
                data_points INTEGER,
                end_date TEXT
            );
            CREATE TABLE fund_annual_returns (
                fcode TEXT,
                year INTEGER,
                annual_return REAL,
                percentile REAL
            );
            CREATE TABLE fund_rank_history (
                fcode TEXT,
                rank_date TEXT,
                period TEXT,
                rank_position INTEGER,
                category_total INTEGER,
                percentile REAL
            );
            """
        )
        conn.executemany(
            "INSERT INTO funds VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                ("000001", "已入围", "债券型-长债", "2020-01-01", 10.0, 0, None, "no_signal_reviewed", 1, "开放申购", 0.3, 0.1, 0.0),
                ("000002", "观察候选", "债券型-长债", "2020-01-01", 20.0, 0, None, "no_signal_reviewed", 1, "开放申购", 0.3, 0.1, 0.0),
                ("000003", "低规模候选", "债券型-长债", "2024-01-01", 1.0, 0, None, "no_signal_reviewed", 1, "开放申购", 0.3, 0.1, 0.0),
            ],
        )
        conn.executemany(
            "INSERT INTO fund_returns(fcode, latest_nav_date) VALUES (?, ?)",
            [("000001", "2026-05-22"), ("000002", "2026-05-22"), ("000003", "2026-05-22")],
        )
        conn.executemany(
            "INSERT INTO fund_risk_metrics VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            [
                ("000001", "1y", 3.0, 0.005, 0.003, 1.2, 5.0, 65.0, 242, "2026-05-22"),
                ("000002", "1y", 3.0, 0.005, 0.003, 0.6, 5.0, 65.0, 242, "2026-05-22"),
                ("000003", "1y", 3.0, 0.005, 0.003, 1.2, 5.0, 65.0, 242, "2026-05-22"),
            ],
        )
        for code in ("000001", "000002"):
            for year in range(2021, 2026):
                conn.execute("INSERT INTO fund_annual_returns VALUES (?, ?, ?, ?)", (code, year, 2.0, 0.2))
            for month in range(1, 13):
                conn.execute(
                    "INSERT INTO fund_rank_history VALUES (?, ?, ?, ?, ?, ?)",
                    (code, f"2026-{month:02d}-01", "overall", 10, 100, 0.2),
                )
        conn.commit()
    finally:
        conn.close()

    records = pd.DataFrame(
        [
            {
                "基金代码": "000001",
                "基金名称": "已入围",
                "正式榜分组": "纯债稳健榜",
                "债基风格标签": "利率债",
                "正式精选状态": "正式入围",
                "正式投资评分": 90.0,
                "_final_stability_score": 100.0,
            },
            {
                "基金代码": "000002",
                "基金名称": "观察候选",
                "正式榜分组": "纯债稳健榜",
                "债基风格标签": "利率债",
                "正式精选状态": "最终精选未入围",
                "最终精选原因代码": "final_selection_stability_cap",
                "正式投资评分": 89.0,
                "_final_stability_score": 99.0,
            },
            {
                "基金代码": "000003",
                "基金名称": "低规模候选",
                "正式榜分组": "纯债稳健榜",
                "债基风格标签": "利率债",
                "正式精选状态": "最终精选未入围",
                "最终精选原因代码": "final_selection_stability_cap",
                "正式投资评分": 88.0,
                "_final_stability_score": 98.0,
            },
        ]
    )
    snapshot_payload = {
        "dynamic_post_review_records": [
            {"基金代码": "000002", "AutoStock原始校验状态": "strict_match"},
            {"基金代码": "000003", "AutoStock原始校验状态": "unknown"},
        ]
    }

    review = module._build_incremental_candidate_safety_review(
        records,
        snapshot_payload=snapshot_payload,
        settings=SimpleNamespace(final_selection_target_max=1, final_selection_group_min_ratio=0.25, database_path=db_path, exclude_holding_days_gt=90),
        target_deltas=[1, 2],
    )

    assert review["available"] is True
    row_map = {row["基金代码"]: row for row in review["candidate_rows"]}
    assert row_map["000002"]["safety_status"] == "watch"
    assert "sharpe_min_below_floor" in row_map["000002"]["safety_reason_text"]
    assert row_map["000003"]["safety_status"] == "block"
    assert "scale_too_small" in row_map["000003"]["safety_reason_text"]
    assert review["delta_summary"][0]["watch_count"] == 1
    assert review["delta_summary"][1]["block_count"] == 1
    governance = review["governance_summary"]
    assert governance["clean_pass_count"] == 0
    assert governance["watch_count"] == 1
    assert governance["block_count"] == 1
    assert governance["delta_recommendations"][0]["recommendation"] == "hold_target_max_until_watch_reasons_resolved"
    assert governance["delta_recommendations"][1]["recommendation"] == "hold_target_max_until_blockers_resolved"
    action_map = {item["action_key"]: item for item in governance["action_items"]}
    assert action_map["review_hard_blocking_reasons"]["candidate_count"] == 1
    assert action_map["inspect_boundary_quality"]["candidate_count"] == 1
    automation_queue = governance["automation_queue"]
    assert automation_queue["available"] is True
    assert automation_queue["queue_total"] == 5
    assert automation_queue["candidate_code_total"] == 2
    assert automation_queue["queues"]["backfill_long_term_features"]["codes"] == ["000002", "000003"]
    assert automation_queue["queues"]["inspect_boundary_quality"]["codes"] == ["000002"]
    assert automation_queue["queues"]["review_hard_blocking_reasons"]["codes"] == ["000003"]
    assert automation_queue["queues"]["resolve_autostock_unknown"]["codes"] == ["000003"]
    queue_map = {
        (row["action_key"], row["基金代码"]): row
        for row in automation_queue["queue_rows"]
    }
    assert queue_map[("resolve_autostock_unknown", "000003")]["downstream_queue"] == (
        "autostock_maturity_retry_or_dual_source_review"
    )
    assert queue_map[("review_hard_blocking_reasons", "000003")]["downstream_queue"] == (
        "publish_hard_gate_hold"
    )
    assert queue_map[("backfill_long_term_features", "000002")]["downstream_queue"] == (
        "long_term_history_feature_maintenance"
    )

    boundary_shadow = module._build_boundary_quality_shadow(
        pd.DataFrame(review["candidate_rows"]),
        contraction_df=records,
    )
    assert boundary_shadow["available"] is True
    assert boundary_shadow["candidate_count"] == 1
    assert boundary_shadow["reason_counts"] == [{"label": "sharpe_min_below_floor", "count": 1}]
    assert boundary_shadow["style_summary"][0]["candidate_codes"] == ["000002"]
    boundary_row = boundary_shadow["candidate_rows"][0]
    assert boundary_row["基金代码"] == "000002"
    assert boundary_row["boundary_quality_action"] == "backfill_long_term_before_boundary_decision"
    assert boundary_row["score_gap_vs_style_selected_min"] == -1.0


