def test_audit_project_tracker_membership_volatility_marks_non_latest_run_unavailable(
    tmp_path: Path,
    capsys: pytest.CaptureFixture[str],
) -> None:
    module = _load_script_module(
        "audit_project_tracker_membership_volatility_run_scope_test",
        "scripts/audit_project_tracker_membership_volatility.py",
    )

    reports_dir = tmp_path / "reports"
    runs_dir = reports_dir / "runs"
    archived_runs_dir = reports_dir / "archive" / "superseded_runs"
    latest_run_id = "20260430_latest"
    archived_run_id = "20260430_archived"

    latest_report_file = reports_dir / "latest.json"
    latest_report_file.parent.mkdir(parents=True, exist_ok=True)
    latest_report_file.write_text(
        json.dumps({"run_id": latest_run_id, "artifacts": {}}, ensure_ascii=False),
        encoding="utf-8",
    )

    archived_run_dir = archived_runs_dir / archived_run_id
    archived_run_dir.mkdir(parents=True, exist_ok=True)
    (archived_run_dir / f"bond_analysis_report_{archived_run_id}.json").write_text(
        json.dumps({"run_id": archived_run_id, "artifacts": {}}, ensure_ascii=False),
        encoding="utf-8",
    )

    tracker_meta_path = reports_dir / "最终优质基金累积跟踪_report_meta.json"
    tracker_meta_path.write_text(json.dumps({}, ensure_ascii=False), encoding="utf-8")

    settings = SimpleNamespace(
        latest_report_file=latest_report_file,
        reports_dir=reports_dir,
        runs_dir=runs_dir,
        archived_runs_dir=archived_runs_dir,
        project_root=tmp_path,
    )

    with (
        patch.object(sys, "argv", ["audit_project_tracker_membership_volatility.py", "--run-id", archived_run_id]),
        patch.object(module, "load_settings", return_value=settings),
    ):
        exit_code = module.main()

    assert exit_code == 0
    summary = json.loads(capsys.readouterr().out)
    assert summary["available"] is False
    assert summary["status"] == "latest_tracker_meta_only"
    assert summary["status_label"] == "仅支持 latest"
    assert summary["replay_precision_status"] == "missing"


