def test_data_truthfulness_live_dashboard_blocks_missing_strategy_shadow_contract() -> None:
    module = _load_script_module(
        "audit_data_truthfulness_dashboard_shadow_contract_for_test",
        "scripts/audit_data_truthfulness.py",
    )
    payload = {
        "publish_reason_summary": {
            "annual_return_gate_shadow": {
                "baseline_final_count": 310,
                "shadow_final_count": 312,
                "decision_summary": {
                    "baseline_final_count": 310,
                    "shadow_final_count": 312,
                    "recommended_action": "compare_local_shadow_scenarios_before_any_threshold_change",
                },
            }
        }
    }

    summary, blockers = module._validate_live_dashboard_strategy_shadow_contract(
        payload,
        expected_publication={"counts": {"final_count": 310}},
    )

    assert summary["available"] is True
    assert "dashboard_annual_return_shadow_truth_contract_missing" in blockers

    payload["publish_reason_summary"]["annual_return_gate_shadow"]["truth_contract"] = {
        "truth_scope": "strategy_shadow_observation",
        "publish_truth": False,
        "official_count_field": "counts.final_count",
        "shadow_count_field": "shadow_final_count",
        "business_value_synthesis": "forbidden",
        "direct_threshold_relaxation_recommended_now": False,
        "missing_value_policy": "preserve_missing_semantics",
    }

    summary, blockers = module._validate_live_dashboard_strategy_shadow_contract(
        payload,
        expected_publication={"counts": {"final_count": 310}},
    )

    assert blockers == []
    assert summary["truth_scope"] == "strategy_shadow_observation"
    assert summary["publish_truth"] is False
    assert summary["baseline_final_count"] == 310
    assert summary["shadow_final_count"] == 312

    payload["publish_reason_summary"]["annual_return_gate_shadow"]["decision_summary"][
        "top_local_shadow_scenarios"
    ] = [
        {
            "scenario_key": "dominant_style_band_all",
            "direct_relieved_final_count": 2,
        }
    ]
    summary, blockers = module._validate_live_dashboard_strategy_shadow_contract(
        payload,
        expected_publication={"counts": {"final_count": 310}},
    )

    assert "dashboard_annual_return_shadow_local_quality_direction_missing" in blockers

    payload["publish_reason_summary"]["annual_return_gate_shadow"]["decision_summary"][
        "top_local_shadow_scenarios"
    ][0].update(
        {
            "replacement_quality_direction": "replacement_quality_weaker",
            "replacement_quality_recommended_action": (
                "reject_local_threshold_change_until_replacement_quality_improves"
            ),
            "replacement_quality_threshold_change_supported_now": False,
        }
    )
    summary, blockers = module._validate_live_dashboard_strategy_shadow_contract(
        payload,
        expected_publication={"counts": {"final_count": 310}},
    )

    assert "dashboard_annual_return_shadow_local_forward_status_missing" in blockers

    payload["publish_reason_summary"]["annual_return_gate_shadow"]["decision_summary"][
        "top_local_shadow_scenarios"
    ][0].update(
        {
            "forward_validation_status": "future_data_pending",
            "forward_validation_direction": "forward_validation_pending",
            "forward_validation_recommended_action": "wait_for_real_future_nav_before_threshold_change",
            "forward_validation_ready_window_count": 0,
            "forward_validation_window_count": 4,
            "forward_validation_threshold_change_supported_now": False,
        }
    )
    summary, blockers = module._validate_live_dashboard_strategy_shadow_contract(
        payload,
        expected_publication={"counts": {"final_count": 310}},
    )

    assert blockers == []
    assert summary["direct_relief_scenario_count"] == 1
    assert summary["scenario_quality_signal_available_count"] == 1
    assert summary["scenario_quality_threshold_safe_count"] == 1
    assert summary["scenario_forward_validation_available_count"] == 1
    assert summary["scenario_forward_validation_threshold_safe_count"] == 1


