def test_load_latest_annual_return_gate_shadow_payload_does_not_fallback_across_runs(tmp_path: Path) -> None:
    from backend.annual_return_gate_shadow import load_latest_annual_return_gate_shadow_payload

    reports_dir = tmp_path / "reports"
    audit_dir = reports_dir / "audit" / "annual_return_gate_shadow"
    audit_dir.mkdir(parents=True, exist_ok=True)
    artifact = audit_dir / "annual_return_gate_shadow_older_run_20260430_083541.json"
    artifact.write_text(
        json.dumps({"run_id": "older_run", "direct_relieved_final_count": 5}, ensure_ascii=False),
        encoding="utf-8",
    )
    settings = SimpleNamespace(reports_dir=reports_dir)

    path, payload = load_latest_annual_return_gate_shadow_payload(settings, run_id="missing_run")
    assert path is None
    assert payload is None

    path, payload = load_latest_annual_return_gate_shadow_payload(
        settings,
        run_id="missing_run",
        allow_fallback_to_any_run=True,
    )
    assert path == artifact
    assert payload["run_id"] == "older_run"


def test_workflow_execute_keeps_one_report_revision_after_annual_shadow_audit(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    from backend.workflow import WorkflowManager

    project_root = tmp_path
    latest_report_file = project_root / "reports" / "latest.json"
    state_file = project_root / "workflow_state.json"
    settings = SimpleNamespace(
        project_root=project_root,
        latest_report_file=latest_report_file,
        state_file=state_file,
        tiantian_base_url="http://example.test",
        autostock_base_url="http://example.test",
    )

    manager = WorkflowManager(settings=settings)
    # The transaction boundary is covered by test_publication_transaction.py.
    monkeypatch.setattr(manager, "_commit_formal_report", lambda *_a, **_kw: None)
    manager.store = SimpleNamespace(
        set_phase=lambda *_a, **_kw: None,
        append_log=lambda *_a, **_kw: None,
        set_published_report=lambda *_a, **_kw: None,
    )

    build_calls: list[str] = []

    def _fake_run_project_pipeline(_settings, _options, _log):
        return {"artifact": "x"}

    def _fake_build_report_payload(*, settings, run_id, artifacts, publication_control=None):
        events.append("build")
        build_calls.append(run_id)
        assert publication_control["eligible_for_formal_publication"] is True
        return {
            "run_id": run_id,
            "artifacts": {"report_markdown": f"reports/{run_id}.md"},
        }

    events: list[str] = []
    shadow_calls: list[str] = []

    monkeypatch.setattr("backend.workflow.run_project_pipeline", _fake_run_project_pipeline)
    monkeypatch.setattr("backend.workflow.build_report_payload", _fake_build_report_payload)
    monkeypatch.setattr(
        WorkflowManager,
        "_run_annual_return_gate_shadow_audit",
        lambda self, run_id, report=None: events.append("shadow") or shadow_calls.append(run_id),
    )
    monkeypatch.setattr(
        "backend.workflow.archive_superseded_runs",
        lambda settings, keep_run_id: events.append("publish") or {"latest_canonical_run_id": keep_run_id},
    )
    monkeypatch.setattr(
        "backend.workflow.load_latest_canonical_report_payload",
        lambda settings: {
            "run_id": "20260430_123000_sync",
            "artifacts": {"report_markdown": "reports/current.md"},
        },
    )
    monkeypatch.setattr("backend.workflow.load_publication_registry", lambda settings: {})

    result = manager._execute("20260430_123000_sync", {})

    assert build_calls == ["20260430_123000_sync"]
    assert shadow_calls == ["20260430_123000_sync"]
    assert events == ["build", "publish", "shadow"]
    assert result["run_id"] == "20260430_123000_sync"


def test_workflow_execute_reuse_existing_outputs_skips_shadow_audit_and_second_rebuild(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    from backend.workflow import WorkflowManager

    project_root = tmp_path
    latest_report_file = project_root / "reports" / "latest.json"
    state_file = project_root / "workflow_state.json"
    settings = SimpleNamespace(
        project_root=project_root,
        latest_report_file=latest_report_file,
        state_file=state_file,
        tiantian_base_url="http://example.test",
        autostock_base_url="http://example.test",
    )

    manager = WorkflowManager(settings=settings)
    log_messages: list[str] = []
    manager.store = SimpleNamespace(
        set_phase=lambda *_a, **_kw: None,
        append_log=lambda message, *_a, **_kw: log_messages.append(str(message)),
        set_published_report=lambda *_a, **_kw: None,
    )

    build_calls: list[str] = []

    def _fake_run_project_pipeline(_settings, _options, _log):
        return {"artifact": "x"}

    def _fake_build_report_payload(*, settings, run_id, artifacts, publication_control=None):
        build_calls.append(run_id)
        return {
            "run_id": run_id,
            "artifacts": {"report_markdown": f"reports/{run_id}.md"},
        }

    lightweight_calls: list[str] = []

    def _fake_build_lightweight_report_payload(*, settings, run_id, artifacts, base_payload):
        lightweight_calls.append(run_id)
        return {
            "run_id": run_id,
            "artifacts": {"report_markdown": f"reports/{run_id}.md"},
            "counts": {},
            "project_publish_summary": {},
        }

    shadow_calls: list[str] = []

    monkeypatch.setattr("backend.workflow.run_project_pipeline", _fake_run_project_pipeline)
    monkeypatch.setattr("backend.workflow.build_report_payload", _fake_build_report_payload)
    monkeypatch.setattr(
        "backend.workflow.build_lightweight_report_payload",
        _fake_build_lightweight_report_payload,
    )
    monkeypatch.setattr(
        WorkflowManager,
        "_run_annual_return_gate_shadow_audit",
        lambda self, run_id, report=None: shadow_calls.append(run_id),
    )
    monkeypatch.setattr(
        "backend.workflow.archive_superseded_runs",
        lambda settings, keep_run_id: {"latest_canonical_run_id": keep_run_id},
    )
    monkeypatch.setattr(
        "backend.workflow.load_latest_canonical_report_payload",
        lambda settings: {
            "run_id": "20260430_123000_sync",
            "artifacts": {"report_markdown": "reports/current.md"},
        },
    )
    publication_registry_calls: list[str] = []
    monkeypatch.setattr(
        "backend.workflow.load_publication_registry",
        lambda settings: publication_registry_calls.append("load") or {},
    )

    result = manager._execute(
        "20260430_123000_sync",
        {"reuse_existing_outputs": True},
    )

    assert build_calls == []
    assert lightweight_calls == ["20260430_123000_sync"]
    assert shadow_calls == []
    assert publication_registry_calls == ["load"]
    assert any("执行轻量报告刷新" in message for message in log_messages)
    assert any("不改写正式发布指针" in message for message in log_messages)
    assert result["run_id"] == "20260430_123000_sync"


