def test_favorite_fund_history_api_reads_saved_records(tmp_path: Path) -> None:
    import backend.app as backend_app

    client = backend_app.app.test_client()
    original_history_file = backend_app.settings.favorites_history_file
    backend_app.settings.favorites_history_file = tmp_path / "favorite_queries.json"
    backend_app.settings.favorites_history_file.write_text(
        json.dumps(
            {
                "records": [
                    {
                        "id": "1",
                        "label": "测试查询",
                        "codes": ["1", "000002"],
                        "created_at": "2026-04-17T14:00:00",
                        "updated_at": "2026-04-17T14:05:00",
                    }
                ]
            },
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )
    try:
        with patch.object(backend_app, "ensure_embedded_scheduler", lambda: None):
            response = client.get("/api/favorites/history")
    finally:
        backend_app.settings.favorites_history_file = original_history_file

    assert response.status_code == 200
    payload = response.get_json()
    assert payload["records"][0]["label"] == "测试查询"
    assert payload["records"][0]["codes"] == ["000001", "000002"]
    assert payload["records"][0]["entry_type"] == "query"


