def test_favorite_metric_details_api_returns_cached_periodic_return_payload() -> None:
    import backend.app as backend_app

    client = backend_app.app.test_client()

    with (
        patch.object(backend_app, "ensure_embedded_scheduler", lambda: None),
        patch.object(
            backend_app,
            "_load_cached_favorite_metric_detail_payload",
            return_value={
                "000001": {
                    "weekly_recent": {
                        "records": [{"label": "2026-05-16", "return_pct": "0.12"}],
                        "total_volatility_pct": "0.34",
                    },
                    "monthly_ytd": {
                        "records": [{"label": "2026-04", "return_pct": "0.82"}],
                        "total_volatility_pct": "0.56",
                    },
                }
            },
        ) as detail_mock,
        patch.object(
            backend_app,
            "_build_favorite_metric_detail_source_basis",
            return_value={
                "schema_version": 1,
                "source": "favorite_metric_details_runtime_query",
                "requested_codes": ["000001"],
                "effective_codes": ["000001"],
                "returned_codes": ["000001"],
                "database_file": "db-token::empty_or_missing_wal",
                "cache_ttl_seconds": 300.0,
                "missing_value_policy": "preserve_missing_semantics",
                "digest": "metric-detail-digest",
            },
        ) as basis_mock,
    ):
        response = client.post("/api/favorites/metric-details", json={"codes": ["1"]})

    assert response.status_code == 200
    payload = response.get_json()
    assert payload["requested_count"] == 1
    assert payload["returned_count"] == 1
    assert payload["details"]["000001"]["weekly_recent"]["records"][0]["return_pct"] == "0.12"
    assert payload["details"]["000001"]["monthly_ytd"]["total_volatility_pct"] == "0.56"
    assert payload["source_basis"] == payload["cache_basis"]
    assert payload["source_basis"]["schema_version"] == 1
    assert payload["source_basis"]["source"] == "favorite_metric_details_runtime_query"
    assert payload["source_basis"]["requested_codes"] == ["000001"]
    assert payload["source_basis"]["database_file"] == "db-token::empty_or_missing_wal"
    assert payload["source_basis"]["missing_value_policy"] == "preserve_missing_semantics"
    assert payload["source_contract"]["source"] == "favorite_metric_details_runtime_query"
    assert payload["source_contract"]["truth_policy"] == (
        "real_sqlite_nav_annual_return_and_local_calculation_only"
    )
    assert payload["source_contract"]["business_value_synthesis"] == "forbidden"
    assert payload["source_contract"]["frontend_rendered_truth_allowed"] is False
    assert payload["source_contract"]["cache_basis_digest"] == "metric-detail-digest"
    detail_mock.assert_called_once_with(["000001"])
    basis_mock.assert_called_once()


