def test_favorite_metric_detail_source_basis_uses_sqlite_wal_token(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import backend.app as backend_app

    db_path = tmp_path / "favorite_metric_details.db"
    db_path.write_bytes(b"sqlite")
    wal_path = tmp_path / "favorite_metric_details.db-wal"
    wal_path.write_bytes(b"wal")
    monkeypatch.setattr(
        backend_app,
        "settings",
        SimpleNamespace(
            database_path=db_path,
            project_root=tmp_path,
        ),
    )

    basis = backend_app._build_favorite_metric_detail_source_basis(
        ["1", "000002", "1"],
        details={"000001": {"weekly_recent": {}}, "000002": {"monthly_ytd": {}}},
    )

    assert basis["schema_version"] == backend_app.FAVORITE_METRIC_DETAIL_SOURCE_BASIS_SCHEMA_VERSION
    assert basis["requested_codes"] == ["000001", "000002"]
    assert basis["effective_codes"] == ["000001", "000002"]
    assert basis["returned_codes"] == ["000001", "000002"]
    assert basis["database_file"].endswith(f":{wal_path.stat().st_size}")
    assert basis["database_file_path"] == "favorite_metric_details.db"
    assert basis["missing_value_policy"] == "preserve_missing_semantics"
    assert "fund_nav_history" in basis["source_tables"]
    assert basis["digest"]


def test_favorite_metric_detail_cache_key_includes_sqlite_wal_token(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import backend.app as backend_app

    db_path = tmp_path / "favorite_metric_details.db"
    db_path.write_bytes(b"sqlite")
    wal_path = tmp_path / "favorite_metric_details.db-wal"
    wal_path.write_bytes(b"wal")
    captured: dict[str, Any] = {}
    monkeypatch.setattr(
        backend_app,
        "settings",
        SimpleNamespace(
            database_path=db_path,
        ),
    )

    def fake_cached_payload(cache_key: str, ttl_seconds: float, builder: Any) -> dict[str, Any]:
        captured["cache_key"] = cache_key
        captured["ttl_seconds"] = ttl_seconds
        return {}

    monkeypatch.setattr(backend_app, "_cached_payload", fake_cached_payload)

    assert backend_app._load_cached_favorite_metric_detail_payload(["1"]) == {}
    assert "empty_or_missing_wal" not in captured["cache_key"]
    assert f":{wal_path.stat().st_size}" in captured["cache_key"]
    assert captured["ttl_seconds"] == backend_app._FAVORITE_METRIC_DETAIL_CACHE_TTL_SECONDS


