def test_load_favorite_periodic_return_details_map_builds_real_weekly_and_monthly_sequences(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import backend.app as backend_app

    db_path = tmp_path / "favorite_metric_details.db"
    conn = sqlite3.connect(db_path)
    try:
        conn.execute(
            """
            CREATE TABLE fund_nav_history (
                fcode TEXT,
                nav_date TEXT,
                unit_nav REAL,
                accum_nav REAL,
                daily_growth REAL
            )
            """
        )
        nav_rows = [
            ("000001", "2024-01-01", 0.90, 0.90, None),
            ("000001", "2025-12-31", 0.99, 0.99, None),
            ("000001", "2026-01-31", 1.00, 1.00, None),
            ("000001", "2026-02-28", 1.02, 1.02, None),
            ("000001", "2026-03-31", 1.01, 1.01, None),
            ("000001", "2026-04-30", 1.04, 1.04, None),
            ("000001", "2026-05-08", 1.05, 1.05, None),
            ("000001", "2026-05-16", 1.03, 1.03, None),
            ("000001", "2026-05-23", 1.06, 1.06, None),
        ]
        conn.executemany(
            "INSERT INTO fund_nav_history (fcode, nav_date, unit_nav, accum_nav, daily_growth) VALUES (?, ?, ?, ?, ?)",
            nav_rows,
        )
        conn.commit()
    finally:
        conn.close()

    frozen_now = datetime(2026, 5, 23, 15, 0, 0)

    class _FrozenDatetime(datetime):
        @classmethod
        def now(cls, tz=None):
            if tz is not None:
                return frozen_now.replace(tzinfo=tz)
            return frozen_now

    monkeypatch.setattr(backend_app, "settings", SimpleNamespace(database_path=db_path))
    monkeypatch.setattr(backend_app, "datetime", _FrozenDatetime)
    captured_read: dict[str, Any] = {}
    original_read_sql_query = backend_app.pd.read_sql_query

    def _capturing_read_sql_query(*args: Any, **kwargs: Any) -> pd.DataFrame:
        frame = original_read_sql_query(*args, **kwargs)
        captured_read["sql"] = str(args[0] if args else kwargs.get("sql") or "")
        captured_read["params"] = list(kwargs.get("params") or [])
        captured_read["row_count"] = len(frame)
        return frame

    monkeypatch.setattr(backend_app.pd, "read_sql_query", _capturing_read_sql_query)

    result = backend_app._load_favorite_periodic_return_details_map(["000001"])

    weekly = result["000001"]["weekly_recent"]
    monthly = result["000001"]["monthly_ytd"]

    assert "windowed_nav" in captured_read["sql"]
    assert "baseline_nav" in captured_read["sql"]
    assert captured_read["params"][-2:] == ["2026-01-01", "2026-01-01"]
    assert captured_read["row_count"] == 8

    assert weekly["records"] == [
        {
            "label": "2026-04-03",
            "period_start": "2026-03-28",
            "period_end": "2026-04-03",
            "return_pct": "-0.98",
        },
        {
            "label": "2026-05-01",
            "period_start": "2026-04-25",
            "period_end": "2026-05-01",
            "return_pct": "2.97",
        },
        {
            "label": "2026-05-08",
            "period_start": "2026-05-02",
            "period_end": "2026-05-08",
            "return_pct": "0.96",
        },
        {
            "label": "2026-05-22",
            "period_start": "2026-05-16",
            "period_end": "2026-05-22",
            "return_pct": "-1.9",
        },
        {
            "label": "2026-05-29",
            "period_start": "2026-05-23",
            "period_end": "2026-05-29",
            "return_pct": "2.91",
        },
    ]
    assert weekly["total_volatility_pct"] == "1.98"

    assert monthly["records"] == [
        {
            "label": "2026-01",
            "period_start": "2026-01-01",
            "period_end": "2026-01-31",
            "return_pct": "1.01",
        },
        {
            "label": "2026-02",
            "period_start": "2026-02-01",
            "period_end": "2026-02-28",
            "return_pct": "2",
        },
        {
            "label": "2026-03",
            "period_start": "2026-03-01",
            "period_end": "2026-03-31",
            "return_pct": "-0.98",
        },
        {
            "label": "2026-04",
            "period_start": "2026-04-01",
            "period_end": "2026-04-30",
            "return_pct": "2.97",
        },
        {
            "label": "2026-05",
            "period_start": "2026-05-01",
            "period_end": "2026-05-31",
            "return_pct": "1.92",
        },
    ]
    assert monthly["total_volatility_pct"] == "1.34"


