def test_risk_metric_cap_audit_replays_raw_metrics_instead_of_reusing_capped_scores() -> None:
    from backend.report_builder import _build_risk_metric_cap_audit

    frame = pd.DataFrame(
        [
            {
                "基金代码": "000002",
                "债基风格标签": "中短债",
                "raw_sharpe_ratio": 1.0,
                "raw_sortino_ratio": 100.0,
                "sharpe_ratio": 1.0,
                "sortino_ratio": 10.0,
                "1年-夏普比率": 1.0,
                "1年-索提诺比率": 100.0,
                "1年-夏普比率(展示封顶)": 1.0,
                "1年-索提诺比率(展示封顶)": 10.0,
                "1年-夏普cap命中": 0,
                "1年-索提诺cap命中": 1,
                "annual_return": 0.03,
                "1年-年化收益(%)": 3.0,
                "calmar_ratio": 4.0,
                "1年-卡玛比率": 4.0,
            },
            {
                "基金代码": "000001",
                "债基风格标签": "中短债",
                "raw_sharpe_ratio": 1.0,
                "raw_sortino_ratio": 20.0,
                "sharpe_ratio": 1.0,
                "sortino_ratio": 10.0,
                "1年-夏普比率": 1.0,
                "1年-索提诺比率": 20.0,
                "1年-夏普比率(展示封顶)": 1.0,
                "1年-索提诺比率(展示封顶)": 10.0,
                "1年-夏普cap命中": 0,
                "1年-索提诺cap命中": 1,
                "annual_return": 0.03,
                "1年-年化收益(%)": 3.0,
                "calmar_ratio": 4.0,
                "1年-卡玛比率": 4.0,
            },
        ]
    )

    audit = _build_risk_metric_cap_audit(frame, preview_top_n=1)

    # Risk-only rows are not a scoreable population. They must be reported as
    # incomparable rather than allowing stable-sort order to look like a cap
    # induced ranking change.
    assert audit["top_n_changed_count"] == 0
    assert audit["top_n_comparable_count"] == 0
    assert audit["top_n_incomparable_count"] == 2

    complete = frame.copy()
    complete["return_6m"] = [3.0, 3.0]
    complete["return_1y"] = [3.0, 3.0]
    complete["return_3y"] = [9.0, 9.0]
    complete["annual_return"] = [3.0, 3.0]
    complete["max_drawdown"] = [0.01, 0.01]
    complete["volatility"] = [0.02, 0.02]
    complete["positive_ratio"] = [60.0, 60.0]
    complete["fee_total_numeric"] = [0.3, 0.3]
    complete["scale_billion"] = [20.0, 20.0]
    complete["费率筛选值(%)"] = [0.3, 0.3]
    complete["费率口径"] = ["api_exact", "api_exact"]
    complete_audit = _build_risk_metric_cap_audit(complete, preview_top_n=1)
    assert complete_audit["top_n_comparable_count"] == 2
    assert complete_audit["top_n_changed_count"] == 2
    assert complete_audit["top_n_only_raw_codes"] == ["000002"]
    assert complete_audit["top_n_only_capped_codes"] == ["000001"]


def test_bond_mainlist_audit_queries_latest_risk_metric_period_rows(tmp_path: Path) -> None:
    from utils.bond_mainlist_audit import _query_bond_universe_rows, _query_rows_by_codes

    db_path = tmp_path / "bond_mainlist_audit_latest_risk.db"
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    try:
        conn.executescript(
            """
            CREATE TABLE funds (
                fcode TEXT PRIMARY KEY,
                shortname TEXT,
                company_name TEXT,
                manager_names TEXT,
                benchmark TEXT,
                ftype TEXT,
                type_category TEXT,
                scale_billion REAL
            );
            CREATE TABLE fund_returns (
                fcode TEXT PRIMARY KEY,
                return_1y REAL,
                return_3y REAL
            );
            CREATE TABLE fund_risk_metrics (
                fcode TEXT,
                period TEXT,
                end_date TEXT,
                annual_return REAL,
                sharpe_ratio REAL,
                raw_sharpe_ratio REAL,
                max_drawdown REAL,
                volatility REAL
            );
            CREATE INDEX idx_risk_period_fcode_end_date
                ON fund_risk_metrics(period, fcode, end_date);
            """
        )
        conn.execute(
            """
            INSERT INTO funds VALUES
            (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                "000001",
                "单元测试债基",
                "测试基金公司",
                "测试经理",
                "测试基准",
                "中长期纯债型",
                "fixed_income",
                10.0,
            ),
        )
        conn.execute("INSERT INTO fund_returns VALUES (?, ?, ?)", ("000001", 1.1, 3.3))
        conn.executemany(
            """
            INSERT INTO fund_risk_metrics(
                fcode, period, end_date, annual_return, sharpe_ratio,
                raw_sharpe_ratio, max_drawdown, volatility
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            [
                ("000001", "1y", "2026-04-20", 2.0, 1.0, 1.1, 0.020, 0.030),
                ("000001", "1y", "2026-04-21", 3.0, 2.0, 2.2, 0.010, 0.020),
                ("000001", "1y", "2026-04-21", 4.0, 3.0, 3.3, 0.008, 0.018),
                ("000001", "3y", "2026-04-19", 5.0, 4.0, 4.4, 0.030, 0.040),
                ("000001", "3y", "2026-04-22", 6.0, 5.0, 5.5, 0.025, 0.035),
            ],
        )
        conn.commit()

        row_map = _query_rows_by_codes(conn, ["000001"])
        universe_rows = _query_bond_universe_rows(conn)
    finally:
        conn.close()

    row = row_map["000001"]
    assert row["annual_return_1y"] == pytest.approx(4.0)
    assert row["sharpe_1y"] == pytest.approx(3.3)
    assert row["mdd_1y"] == pytest.approx(0.008)
    assert row["annual_return_3y"] == pytest.approx(6.0)
    assert row["sharpe_3y"] == pytest.approx(5.5)
    assert len(universe_rows) == 1
    assert universe_rows[0]["annual_return_1y"] == pytest.approx(4.0)
    assert universe_rows[0]["annual_return_3y"] == pytest.approx(6.0)


