def test_build_portfolio_suggestions_enforces_no_duplicate_codes_or_company_cap() -> None:
    rows: list[dict[str, str]] = []
    tracker_rows: list[dict[str, object]] = []
    for idx in range(48):
        if idx < 18:
            formal_group = "纯债稳健榜"
            style = "综合纯债"
        elif idx < 30:
            formal_group = "纯债稳健榜"
            style = "中短债"
        elif idx < 39:
            formal_group = "增强债弹性榜"
            style = "一级债增强"
        else:
            formal_group = "增强债弹性榜"
            style = "二级债增强"
        company = "大公司" if idx < 8 else f"公司{idx:02d}"
        code = f"{idx + 1:06d}"
        rows.append(
            {
                "基金代码": code,
                "基金名称": f"基金{idx:02d}",
                "基金公司": company,
                "正式榜分组": formal_group,
                "债基风格标签": style,
                "母基金名称": f"母基金{idx:02d}",
                "费率合计(%)": f"{0.20 + idx * 0.01:.2f}",
                "正式投资评分": f"{95.0 - idx * 0.3:.4f}",
                "1年-最大回撤(%)": f"{0.01 + idx * 0.001:.4f}",
                "1年-波动率": f"{0.02 + idx * 0.001:.4f}",
                "1年-年化收益(%)": f"{3.0 + idx * 0.05:.2f}",
                "1年-夏普比率": f"{3.5 - idx * 0.02:.4f}",
                "1年-卡玛比率": f"{8.0 - idx * 0.05:.4f}",
                "近期得分": f"{90.0 - idx * 0.4:.4f}",
                "长期得分": f"{88.0 - idx * 0.35:.4f}",
                "综合加权得分": f"{95.0 - idx * 0.3:.4f}",
                "近1月(%)": "0.20",
                "近3月(%)": "0.80",
                "基金规模(亿)": f"{8.0 + idx:.1f}",
                "是否可申购": "可申购",
                # P2-01 兼容：测试本意验证核心+扩展整体装配而非降档路径，
                # 因此把持有期状态统一设为已确认<=90天，扩展组的最小确认下限不触发。
                "持有期状态": "已确认<=90天",
                "项目质量信心": "高信心" if idx % 5 else "中信心",
                "AutoStock原始校验状态": "strict_match" if idx % 4 else "soft_pass_with_warnings",
                "长期稳定性标签": "长期稳定性强" if idx % 6 else "长期历史部分缺失",
            }
        )
        tracker_rows.append(
            {
                "基金代码": code,
                "出现次数": 5 if idx < 20 else 3,
                "出现频率(%)": 100.0 if idx < 20 else 60.0,
                "连续缺席期数": 0,
                "当前是否在榜": "是",
                "跟踪总期数": 5,
            }
        )

    portfolio_df, portfolio_summary = _build_portfolio_suggestions(
        pd.DataFrame(rows),
        tracker_features_df=pd.DataFrame(tracker_rows),
    )

    assert portfolio_summary["available"] is True
    assert int(portfolio_summary["candidate_count"]) == 48
    assert int(portfolio_summary["target_count"]) == 36
    assert int(portfolio_summary["fund_count"]) == 36
    assert portfolio_summary["quality_gate"]["selection_reason"] == "skipped_small_candidate_pool"
    assert portfolio_summary["target_policy"]["band_mode"] == "quality_first_narrow_band"
    codes = portfolio_df["基金代码"].astype(str).tolist()
    assert len(codes) == len(set(codes))
    company_counts = portfolio_df["基金公司"].astype(str).value_counts().to_dict()
    assert company_counts["大公司"] <= 2
    assert {"投资优先池得分", "项目质量信心", "出现次数", "AutoStock原始校验状态", "长期稳定性标签", "风险提示"}.issubset(portfolio_df.columns)
    weight_series = portfolio_df["建议权重"].astype(str)
    assert weight_series.str.endswith("%").all()
    grouped_weight_sums = (
        portfolio_df.assign(_weight=weight_series.str.rstrip("%").astype(float))
        .groupby("组合名称")["_weight"]
        .sum()
        .round(2)
        .to_dict()
    )
    for total in grouped_weight_sums.values():
        assert total == pytest.approx(100.0, abs=0.05)
    assert any(count > 1 for count in portfolio_df.groupby("组合名称")["建议权重"].nunique().tolist())


