    assert enhanced_codes == ["100001", "100002"]

    weights = {
        row["基金代码"]: float(str(row["建议权重"]).rstrip("%"))
        for row in portfolio_df.to_dict(orient="records")
        if row["组合名称"] == "增强债弹性扩展"
    }
    assert weights["100001"] > weights["100002"]


