def test_build_priority_pool_tracker_features_includes_current_snapshot_without_workbook_dependency(tmp_path: Path) -> None:
    settings = load_settings(PROJECT_ROOT / "config" / "project.yaml")
    original_runs_dir = settings.runs_dir
    try:
        settings.runs_dir = tmp_path / "runs"
        settings.runs_dir.mkdir(parents=True, exist_ok=True)
        current_df = pd.DataFrame(
            [
                {"基金代码": "000001"},
                {"基金代码": "000002"},
            ]
        )
        features = _build_priority_pool_tracker_features(
            settings,
            current_run_id="20260415_999999_sync",
            current_generated_at="2026-04-15T10:00:00",
            current_nav_snapshot_date="2026-04-15",
            current_df=current_df,
        )
    finally:
        settings.runs_dir = original_runs_dir

    assert set(features["基金代码"].tolist()) == {"000001", "000002"}
    assert set(features["当前是否在榜"].tolist()) == {"是"}
    assert set(features["出现次数"].tolist()) == {1}
    assert set(features["跟踪总期数"].tolist()) == {1}


def test_scheduler_chain_audit_flags_backlog_and_degraded_runs() -> None:
    import backend.app as backend_app

    audit = backend_app._build_scheduler_chain_audit(
        {
            "startup_catch_up_pending": True,
            "startup_catch_up_due_jobs": ["daily_refresh", "intraday_refresh"],
            "job_drift_detected": True,
            "missing_job_ids": ["snapshot_watchdog"],
            "unexpected_job_ids": [],
            "screening_backlog_due": True,
            "screening_backlog_reason": "effective_nav_snapshot_advanced_without_collection",
            "daily_run": {
                "status": "degraded",
                "screening_triggered": True,
                "screening_reason": "effective_nav_snapshot_advanced_without_collection",
                "warning_reason": "nav_history_sync_maintenance_failed",
                "action_category": "screening_triggered",
                "no_action_category": None,
                "degraded": True,
                "degraded_stage": "nav-history-sync-maintenance",
            },
            "intraday_run": {
                "status": "success",
                "screening_triggered": False,
                "screening_reason": "snapshot_unchanged",
                "action_category": "scan_only_no_material_change",
                "no_action_category": "maintenance_only",
            },
            "weekly_run": {
                "status": "failed",
                "warning_reason": "report_refresh_failed",
                "action_category": "none",
                "no_action_category": None,
                "degraded_stage": "report-refresh",
            },
            "snapshot_watchdog_run": {
                "status": "skipped",
                "skip_reason": "workflow_busy",
                "action_category": "none",
                "no_action_category": "automation_guard",
            },
        }
    )

    assert audit["aligned"] is False
    assert audit["issue_count"] == 6
    issue_codes = {item["code"] for item in audit["open_issues"]}
    assert "startup_catch_up_pending" in issue_codes
    assert "scheduler_job_drift" in issue_codes
    assert "screening_backlog_due" in issue_codes
    assert "daily_refresh_degraded" in issue_codes
    assert "weekly_maintenance_failed" in issue_codes
    assert "snapshot_watchdog_skip_guard" in issue_codes


