def test_scheduler_recent_failure_recovery_summary_flags_recovered_sequences(tmp_path: Path) -> None:
    import backend.app as backend_app
    from backend.scheduler_diagnostics import build_recent_scheduler_failure_recovery_summary

    reports_dir = tmp_path / "reports"
    audit_dir = reports_dir / ".audit" / "scheduler_task_runs" / "20260524"
    audit_dir.mkdir(parents=True)

    def _write_audit(
        filename: str,
        *,
        status: str,
        started_at: str,
        finished_at: str,
        error: str | None = None,
        workflow_error: str | None = None,
        workflow_run_id: str | None = None,
        failed_subtask_duration: float | None = None,
    ) -> None:
        logs_tail = []
        if failed_subtask_duration is not None:
            logs_tail = [
                "  ----------------------------------------------------------------------",
                "  1        任务1: 长期筛选                 ✅ 成功       71.5秒           0",
                "  2        任务2: 短期筛选                 ✅ 成功       70.0秒           0",
                f"  3        任务3: 最终筛选                 ❌ 失败       {failed_subtask_duration}秒         1",
            ]
        payload = {
            "generated_at": finished_at,
            "task": {
                "task_name": "scheduled_snapshot_watchdog_refresh",
                "task_key": "snapshot_watchdog",
                "started_at": started_at,
                "finished_at": finished_at,
                "status": status,
            },
            "task_result": {
                "task_name": "scheduled_snapshot_watchdog_refresh",
                "status": status,
                "started_at": started_at,
                "finished_at": finished_at,
                "error": error,
                "screening_triggered": status == "success",
                "screening_run_id": workflow_run_id
                or ("20260524_104235_sync" if status == "success" else "20260524_041235_sync"),
                "screening_reason": "effective_nav_snapshot_advanced_without_collection"
                if status == "success"
                else None,
            },
            "workflow_summary": {
                "run_id": workflow_run_id
                or ("20260524_104235_sync" if status == "success" else "20260524_041235_sync"),
                "error": workflow_error or error,
                "options": {
                    "run_collection": False,
                    "run_screening": True,
                    "force_calculate_risk": True,
                },
                "logs_tail": logs_tail,
            },
        }
        (audit_dir / filename).write_text(json.dumps(payload), encoding="utf-8")

    _write_audit(
        "20260524_041234_scheduled_snapshot_watchdog_refresh.json",
        status="failed",
        started_at="2026-05-24T04:12:34",
        finished_at="2026-05-24T04:59:43",
        error="workflow_subprocess_failed exit=1",
        workflow_error="步骤失败: daily-screening-master (exit=1)",
        workflow_run_id="20260524_041235_sync",
        failed_subtask_duration=2659.3,
    )
    _write_audit(
        "20260524_051234_scheduled_snapshot_watchdog_refresh.json",
        status="failed",
        started_at="2026-05-24T05:12:34",
        finished_at="2026-05-24T05:59:43",
        error="workflow_subprocess_failed exit=1",
        workflow_error="步骤失败: daily-screening-master (exit=1)",
        workflow_run_id="20260524_051235_sync",
        failed_subtask_duration=879.6,
    )
    _write_audit(
        "20260524_104234_scheduled_snapshot_watchdog_refresh.json",
        status="success",
        started_at="2026-05-24T10:42:34",
        finished_at="2026-05-24T10:49:51",
    )

    summary = build_recent_scheduler_failure_recovery_summary(
        SimpleNamespace(reports_dir=reports_dir, project_root=tmp_path),
        now=datetime(2026, 5, 24, 13, 0, 0),
    )
    watchdog = summary["task_map"]["snapshot_watchdog"]

    assert summary["summary"]["recovered_sequence_total"] == 1
    assert watchdog["latest_recovered_sequence"]["failure_count"] == 2
    assert watchdog["latest_recovered_sequence"]["recovery_screening_run_id"] == "20260524_104235_sync"
    assert watchdog["latest_recovered_sequence"]["failure_workflow_run_ids"] == [
        "20260524_041235_sync",
        "20260524_051235_sync",
    ]
    assert watchdog["latest_recovered_sequence"]["latest_failed_stage"] == "daily-screening-master"
    assert watchdog["latest_recovered_sequence"]["latest_failed_subtask"] == "任务3: 最终筛选"
    assert watchdog["latest_recovered_sequence"]["latest_failure_exit_code"] == 1
    assert watchdog["latest_recovered_sequence"]["max_failed_subtask_duration_seconds"] == 2659.3
    assert (
        watchdog["latest_recovered_sequence"]["recovery_screening_reason"]
        == "effective_nav_snapshot_advanced_without_collection"
    )
    assert watchdog["attention_needed"] is True

    audit = backend_app._build_scheduler_chain_audit(
        {
            "startup_catch_up_pending": False,
            "startup_catch_up_due_jobs": [],
            "job_drift_detected": False,
            "missing_job_ids": [],
            "unexpected_job_ids": [],
            "screening_backlog_due": False,
            "screening_backlog_reason": None,
            "recent_failure_recovery_summary": summary,
            "daily_run": {},
            "intraday_run": {},
            "weekly_run": {},
            "snapshot_watchdog_run": {},
        }
    )
    issue_codes = {item["code"] for item in audit["open_issues"]}
    assert "snapshot_watchdog_recent_failure_sequence_recovered" in issue_codes
    recovered_issue = next(
        item for item in audit["open_issues"] if item["code"] == "snapshot_watchdog_recent_failure_sequence_recovered"
    )
    assert "阶段 daily-screening-master" in recovered_issue["detail"]
    assert "子任务 任务3: 最终筛选" in recovered_issue["detail"]
    assert "exit=1" in recovered_issue["detail"]


