def test_scheduler_recent_failure_summary_uses_task_history_and_weekly_lookback(
    tmp_path: Path,
) -> None:
    import backend.app as backend_app
    from backend.scheduler_diagnostics import build_recent_scheduler_failure_recovery_summary

    database_path = tmp_path / "scheduler-history.db"
    with sqlite3.connect(database_path) as conn:
        conn.execute(
            """
            CREATE TABLE task_history (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                task_name TEXT NOT NULL,
                status TEXT NOT NULL,
                started_at DATETIME NOT NULL,
                completed_at DATETIME,
                error_message TEXT,
                extra_data TEXT
            )
            """
        )
        for started_at, stage, reason in (
            (
                "2026-08-09 03:00:00",
                "nav-history-archive-preview",
                "nav_history_archive_preview_failed",
            ),
            (
                "2026-08-16 03:00:00",
                "rank-history-archive-rolling",
                "rank_history_archive_rolling_failed",
            ),
        ):
            extra = {
                "status": "degraded",
                "started_at": started_at.replace(" ", "T"),
                "finished_at": started_at.replace(" 03:00:00", "T04:00:00"),
                "degraded_stage": stage,
                "warning_reason": reason,
                "screening_triggered": True,
            }
            conn.execute(
                """
                INSERT INTO task_history (
                    task_name, status, started_at, completed_at, error_message, extra_data
                ) VALUES (?, ?, ?, ?, ?, ?)
                """,
                (
                    "scheduled_weekly_bond_maintenance",
                    "degraded",
                    started_at,
                    started_at.replace("03:00:00", "04:00:00"),
                    None,
                    json.dumps(extra),
                ),
            )

    summary = build_recent_scheduler_failure_recovery_summary(
        SimpleNamespace(
            reports_dir=tmp_path / "reports",
            project_root=tmp_path,
            database_path=database_path,
        ),
        now=datetime(2026, 8, 24, 12, 0, 0),
    )
    weekly = summary["task_map"]["weekly_maintenance"]
    sequence = weekly["open_failure_sequence"]

    assert summary["source"] == "task_history"
    assert summary["lookback_days_by_task"]["weekly_maintenance"] == 56
    assert summary["summary"]["open_degradation_sequence_total"] == 1
    assert weekly["attention_needed"] is True
    assert sequence["failure_count"] == 2
    assert sequence["failed_run_count"] == 0
    assert sequence["degraded_run_count"] == 2
    assert sequence["latest_failed_stage"] == "rank-history-archive-rolling"

    audit = backend_app._build_scheduler_chain_audit(
        {
            "scheduler_running": True,
            "recent_failure_recovery_summary": summary,
            "daily_run": {},
            "intraday_run": {},
            "weekly_run": {},
            "snapshot_watchdog_run": {},
        }
    )
    issue = next(
        item
        for item in audit["open_issues"]
        if item["code"] == "weekly_maintenance_recent_degradation_sequence_open"
    )
    assert issue["severity"] == "warning"
    assert "rank-history-archive-rolling" in issue["detail"]


def test_scheduler_state_persists_recent_failure_recovery_summary(tmp_path: Path) -> None:
    from backend.scheduler_state import SchedulerStateStore

    store = SchedulerStateStore(tmp_path / "scheduler-state.json")
    recent_summary = {
        "source": "task_history",
        "summary": {"open_degradation_sequence_total": 1},
        "tasks": [{"task_key": "weekly_maintenance", "attention_needed": True}],
    }
    store.set_runtime_status_summary(
        {"recent_failure_recovery_summary": recent_summary}
    )

    assert store.snapshot()["recent_failure_recovery_summary"] == recent_summary


