def test_scheduler_run_api_summary_drops_task_history_preview_samples() -> None:
    import backend.app as backend_app

    run = {
        "task_name": "scheduled_weekly_bond_maintenance",
        "status": "success",
        "action_category": "scan_only_no_material_change",
        "task_history_governance_preview": {
            "status": "success",
            "artifact_path": "reports/audit/task_history_governance/preview.json",
            "markdown_path": "reports/audit/task_history_governance/preview.md",
            "summary": {
                "total_rows": 42,
                "retention_candidate_total": 3,
                "large_extra_data_candidate_total": 1,
            },
            "retention_candidate_samples": [{"id": 1}],
            "large_extra_data_candidate_samples": [{"id": 2}],
        },
        "task_history_governance_preview_error": None,
        "task_history_cleanup_execution": {
            "status": "dry-run",
            "mode": "dry-run",
            "artifact_path": "reports/audit/task_history_cleanup/cleanup.json",
            "summary": {
                "candidate_total": 1,
                "deleted_count": 0,
                "candidate_samples": [{"id": 3}],
            },
            "archive": {
                "archived_row_count": 0,
                "archived_row_samples": [{"id": 4}],
            },
            "min_apply_candidate_total": 100,
            "apply_skipped_reason": "below_min_apply_candidate_total",
        },
        "task_history_cleanup_execution_error": None,
    }

    summary = backend_app.scheduler_diagnostics.summarize_scheduler_run_for_api(run)
    preview = summary["task_history_governance_preview"]
    cleanup = summary["task_history_cleanup_execution"]

    assert preview["status"] == "success"
