def test_runtime_excluded_fund_codes_include_dynamic_terminal_upstream_entries(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    dynamic_rules_path = tmp_path / "long_term_terminal_upstream_exclusions.json"
    dynamic_rules_path.write_text(
        json.dumps(
            {
                "generated_at": "2026-04-25T12:00:00",
                "rule_group": "terminal_upstream_limited_high_confidence",
                "entries": [
                    {
                        "fcode": "000001",
                        "shortname": "终局停更债A",
                        "enabled": True,
                        "reason": "测试终态上游受限样本",
                        "source": "test",
                    },
                    {
                        "fcode": "000002",
                        "shortname": "停用样本",
                        "enabled": False,
                        "reason": "disabled",
                        "source": "test",
                    },
                ],
            },
            ensure_ascii=False,
        ),
        encoding="utf-8",
    )
    monkeypatch.setattr(
        fund_exclusion_rules_module,
        "DEFAULT_TERMINAL_UPSTREAM_LIMITED_RULES_PATH",
        dynamic_rules_path,
    )
    fund_exclusion_rules_module.clear_fund_exclusion_rules_cache()

    try:
        codes = fund_exclusion_rules_module.get_runtime_excluded_fund_codes(
            terminal_override_path=str(dynamic_rules_path),
        )
        groups = fund_exclusion_rules_module.get_fund_exclusion_rule_groups(
            terminal_override_path=str(dynamic_rules_path),
        )
    finally:
        fund_exclusion_rules_module.clear_fund_exclusion_rules_cache()

    assert "000001" in codes
    assert "000002" not in codes
    terminal_groups = [
        group
        for group in groups
        if group.get("group") == "terminal_upstream_limited_high_confidence"
    ]
    assert len(terminal_groups) == 1
    assert terminal_groups[0]["enabled_count"] == 1


def test_build_scheduler_overview_summary_prefers_schedule_slot_run_over_latest_retry() -> None:
    import backend.app as backend_app

    scheduler_state = {
        "enabled": True,
        "scheduler_running": True,
        "automation_host_mode": "external_scheduler_process",
        "task_schedule_slot_runs": {
            "intraday_refresh": [
                {
                    "task_name": "scheduled_intraday_bond_refresh",
                    "status": "skipped",
                    "started_at": "2026-04-20T13:45:00",
                    "finished_at": "2026-04-20T13:49:26",
                    "skip_reason": "effective_nav_snapshot_already_screened",
                    "screening_triggered": False,
                }
            ]
        },
        "task_closures": {
            "intraday_refresh": {
                "task_name": "scheduled_intraday_bond_refresh",
                "status": "success",
                "action_category": "scan_only_no_material_change",
                "latest_screened_snapshot": {"candidate_date": "2026-04-17", "signature": "slot-screened"},
                "child_tasks": {},
            }
        },
        "last_runs": {
            "scheduled_intraday_bond_refresh": {
                "task_name": "scheduled_intraday_bond_refresh",
                "status": "success",
                "started_at": "2026-04-20T21:42:50",
                "finished_at": "2026-04-20T21:52:49",
                "screening_triggered": True,
                "logs_tail": ["retry"],
            }
        },
        "jobs": [{"id": "intraday_refresh"}],
        "current_task": {},
        "manual_run_history": [],
        "screening_backlog_due": False,
        "startup_catch_up_pending": False,
        "configured_job_ids": [],
        "missing_job_ids": [],
        "unexpected_job_ids": [],
        "job_drift_detected": False,
        "effective_nav_snapshot": {},
        "latest_screened_snapshot": {},
        "nav_freshness": {},
    }

    with patch.object(ProjectScheduler, "_build_empty_detail_payload_audit", return_value={"available": False}):
        summary = backend_app._build_scheduler_overview_summary(scheduler_state)

    assert summary["intraday_run"]["started_at"] == "2026-04-20T13:45:00"
