def test_build_scheduler_chain_audit_flags_late_start() -> None:
    import backend.app as backend_app

    scheduler_overview = {
        "automation_host_mode": "external_scheduler_process",
        "configured_host_context": "external_scheduler_process",
        "host_context_mismatch": False,
        "startup_catch_up_pending": False,
        "startup_catch_up_due_jobs": [],
        "screening_backlog_due": False,
        "screening_backlog_reason": None,
        "daily_run": {
            "status": "success",
            "screening_triggered": True,
            "collection_skipped": True,
            "started_late": True,
            "start_delay_seconds": 2220,
            "startup_catch_up_suspected": True,
            "startup_catch_up_origin": "external_scheduler_restart_catch_up",
        },
        "intraday_run": {
            "status": "success",
            "started_late": False,
            "start_delay_seconds": 0,
            "startup_catch_up_suspected": False,
        },
        "weekly_run": {
            "status": "success",
            "started_late": False,
            "start_delay_seconds": 0,
            "startup_catch_up_suspected": False,
        },
        "snapshot_watchdog_run": {
            "status": "skipped",
            "no_action_category": "already_screened",
            "started_late": False,
            "start_delay_seconds": 0,
            "startup_catch_up_suspected": False,
        },
        "automation_closure_digest": {
            "alerts": [],
        },
    }

    audit = backend_app._build_scheduler_chain_audit(scheduler_overview)

    assert audit["aligned"] is True
    issue_codes = {item["code"] for item in audit["open_issues"]}
    assert "daily_refresh_late_start" not in issue_codes
    assert audit["runs"]["daily_refresh"]["started_late"] is True
    assert audit["runs"]["daily_refresh"]["startup_catch_up_suspected"] is True
    assert audit["runs"]["daily_refresh"]["startup_catch_up_origin"] == "external_scheduler_restart_catch_up"
    assert audit["runs"]["daily_refresh"]["late_start_cause"] == "startup_catch_up"
    assert audit["runs"]["intraday_refresh"]["late_start_cause"] is None


