def test_scheduler_status_detail_section_endpoint_returns_lightweight_blocks() -> None:
    import backend.app as backend_app

    client = backend_app.app.test_client()
    backend_app._payload_cache.clear()
    backend_app._payload_cache_inflight.clear()
    scheduler_state = {
        "enabled": True,
        "scheduler_running": True,
        "automation_host_mode": "external_scheduler_process",
        "host_context": "external_scheduler_process",
        "configured_host_context": "external_scheduler_process",
        "manual_run_history": [{"job_id": "daily_refresh", "status": "success"}],
        "pending_manual_run_requests": [{"job_id": "intraday_refresh", "status": "accepted"}],
        "task_closures": {
            "daily_refresh": {
                "task_name": "scheduled_daily_bond_refresh",
                "status": "success",
            }
        },
        "child_task_idle_streaks": {
            "daily_refresh": {"nav_history_sync": {"idle_streak": 2}},
        },
    }

    with (
        patch.object(backend_app, "ensure_embedded_scheduler", lambda: None),
        patch.object(backend_app.SchedulerStateStore, "snapshot", return_value=scheduler_state),
        patch.object(
            backend_app,
            "_build_scheduler_status_payload",
            side_effect=AssertionError("section endpoint should use lightweight detail index"),
        ),
        patch.object(
            backend_app,
            "_build_scheduler_status_summary_cached",
            return_value={
                "scheduler_running": True,
                "automation_autonomy": {"status": "automatic"},
                "daily_run": {"task_name": "scheduled_daily_bond_refresh", "status": "success"},
                "intraday_run": {},
                "weekly_run": {},
                "snapshot_watchdog_run": {},
                "automation_closure_digest": {"summary": {"closed": True}},
                "current_final_selection_governance_queue": {
                    "available": False,
                    "reason": "not_loaded_in_unit_test",
                    "scope": "current_runtime_advisory_queue",
                    "publication_truth": False,
                },
            },
        ),
    ):
        response = client.get("/api/scheduler/status/detail?section=task_closures")
        invalid_response = client.get("/api/scheduler/status/detail?section=unknown")

    assert response.status_code == 200
    payload = response.get_json()
    assert payload["detail_scope"] == "section"
    assert payload["section"] == "task_closures"
    assert payload["source_basis"]["source"] == "scheduler_status_detail_runtime_state"
    assert payload["cache_basis"] == payload["source_basis"]
    assert payload["source_basis"]["detail_scope"] == "section"
    assert payload["source_basis"]["section"] == "task_closures"
    assert payload["source_contract"]["truth_policy"] == (
        "real_scheduler_state_publication_registry_database_and_runtime_artifacts_only"
    )
    assert payload["source_contract"]["business_value_synthesis"] == "forbidden"
    assert payload["source_contract"]["frontend_rendered_truth_allowed"] is False
    assert payload["source_contract"]["cache_basis_digest"] == payload["source_basis"]["digest"]
    assert payload["scheduler_detail_build_profile"]["detail_scope"] == "section"
    assert payload["scheduler_detail_build_profile"]["section"] == "task_closures"
    assert any(
        step["name"] == "section_payload_load"
        for step in payload["scheduler_detail_build_profile"]["steps"]
    )
    assert payload["task_closures"]["daily_refresh"]["task_name"] == "scheduled_daily_bond_refresh"
    assert payload["child_task_idle_streaks"]["daily_refresh"]["nav_history_sync"]["idle_streak"] == 2
    assert payload["scheduler_detail_split"]["default_detail_heavy"] is False
    assert invalid_response.status_code == 400
    invalid_payload = invalid_response.get_json()
    assert invalid_payload["error"] == "unknown_scheduler_detail_section"
    assert invalid_payload["source_basis"]["source"] == "scheduler_status_detail_runtime_state"
    assert invalid_payload["source_contract"]["business_value_synthesis"] == "forbidden"
    assert invalid_payload["scheduler_detail_build_profile"]["detail_scope"] == "section"
    assert invalid_payload["scheduler_detail_build_profile"]["section"] == "unknown"
    assert "task_closures" in invalid_payload["available_sections"]


