def test_scheduler_failure_drill_closes_failure_observability_loop() -> None:
    from backend.scheduler_failure_drill import build_scheduler_failure_drill_payload

    payload = build_scheduler_failure_drill_payload(SimpleNamespace())
    checks = {item["name"]: item for item in payload["checks"]}
    surface = payload["failure_surface"]

    assert payload["passed"] is True
    assert checks["failed_task_marked_attention"]["passed"] is True
    assert checks["chain_audit_contains_failure_issue"]["passed"] is True
    assert checks["task_artifacts_exposed"]["passed"] is True
    assert checks["publication_status_not_corrupted_by_failed_task"]["passed"] is True
    assert payload["summary"]["attention_total"] >= 1
    assert payload["summary"]["artifact_task_count"] == 1
    assert payload["summary"]["publication_status"] == "success_published"
    assert surface["automation_closure_daily"]["status"] == "failed"
    assert surface["automation_closure_daily"]["attention_needed"] is True
    assert surface["task_run_artifact_daily"]["task_log_file_project_path"] == "logs/tasks/task_drill_scheduled_daily_bond_refresh.log"
    assert (
        surface["task_run_artifact_daily"]["task_run_audit_json_project_path"]
        == "reports/.audit/scheduler_task_runs/20260429/task_drill_daily_failure.json"
    )
    assert any(
        item.get("code") == "daily_refresh_failed"
        for item in surface["chain_audit_open_issues"]
    )


