def test_run_regression_smoke_classifies_warning_ready_assertion_as_test_expectation_mismatch(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setattr(os, "execv", lambda *_args, **_kwargs: None)
    module = _load_script_module(
        "test_run_regression_smoke_classification_module",
        "scripts/run_regression_smoke.py",
    )
    stdout_text = "\n".join(
        [
            "=================================== FAILURES ===================================",
            ">   ???",
            "E   AssertionError: assert 'warning' == 'ready'",
            "E     - ready",
            "E     + warning",
        ]
    )

    classification = module._classify_command_issue(
        returncode=1,
        stdout_text=stdout_text,
        stderr_text="",
    )
    command_result = {
        "label": "pytest_scheduler_guard",
        "status": "failed",
        "returncode": 1,
        **classification,
    }
    summary = module._build_smoke_issue_summary(
        [
            {
                "group": "scheduler_guard",
                "description": "调度状态、自动化护栏与官方入口口径回归",
                "status": "failed",
                "commands": [command_result],
            }
        ]
    )

    assert classification["issue_classification_status"] == "test_expectation_mismatch"
    assert classification["issue_classification_label"] == "测试口径不匹配"
    assert "warning" in " ".join(classification["evidence_snippets"])
    assert summary["issue_classification_status"] == "test_expectation_mismatch"
    assert summary["test_expectation_mismatch_total"] == 1
    assert summary["production_degradation_total"] == 0
    assert summary["failed_group_classifications"][0]["group"] == "scheduler_guard"


