def test_scheduler_run_semantic_status_distinguishes_normal_and_blocking_skips() -> None:
    from backend.scheduler_status_support import classify_scheduler_run_semantic_status

    already_screened = classify_scheduler_run_semantic_status(
        status="skipped",
        skip_reason="effective_nav_snapshot_already_screened",
        no_action_category="already_screened",
    )
    busy_guard = classify_scheduler_run_semantic_status(
        status="skipped",
        skip_reason="workflow_busy_locked",
        no_action_category="automation_guard",
    )
    unavailable = classify_scheduler_run_semantic_status(
        status="skipped",
        skip_reason="workflow_executor_unavailable",
        no_action_category="automation_guard",
    )
    unknown_skip = classify_scheduler_run_semantic_status(
        status="skipped",
        skip_reason="unexpected_skip_reason",
    )

    assert already_screened["run_semantic_status"] == "skipped_normal"
    assert already_screened["skip_semantic_status"] == "normal"
    assert already_screened["manual_intervention_hint"] is False
    assert busy_guard["run_semantic_status"] == "skipped_normal"
    assert busy_guard["skip_semantic_status"] == "normal"
    assert unavailable["run_semantic_status"] == "skipped_blocked"
    assert unavailable["skip_semantic_status"] == "blocked"
    assert unavailable["manual_intervention_hint"] is True
    assert unknown_skip["run_semantic_status"] == "skipped_blocked"
    assert unknown_skip["manual_intervention_hint"] is True


