def test_weekly_maintenance_marks_degraded_when_tiantian_gap_remains() -> None:
    scheduler = ProjectScheduler.__new__(ProjectScheduler)
    scheduler.settings = SimpleNamespace(scheduler_weekly_long_term_history_limit=20)
    scheduler.workflow_manager = SimpleNamespace(is_running=lambda: False)
    scheduler.task_recorder = None
    scheduler.state_store = None
    scheduler._log = lambda message: None

    with (
        patch("backend.scheduler.run_project_pipeline", return_value={}),
        patch(
            "backend.scheduler.run_bond_universe_sync",
            return_value={
                "diffs_after_sync": {
                    "missing_in_local_vs_tiantian_total": 3,
                    "missing_in_local_vs_autostock_total": 25,
                    "newly_synced_codes_total": 10,
                },
            },
        ),
        patch(
            "backend.scheduler.run_nav_history_maintenance",
            return_value={
                "maintenance_result": {"processed_total": 0, "failed_total": 0},
                "audit_after": {"candidate_total": 400},
            },
        ),
        patch(
            "backend.scheduler.run_long_term_history_maintenance",
            return_value={
                "maintenance_result": {"processed_total": 20, "annual_success_total": 20, "rank_success_total": 19},
                "audit_after": {"candidate_total": 3100},
            },
        ),
    ):
        result = ProjectScheduler._execute_weekly_maintenance(scheduler)

    assert result["status"] == "degraded"
    assert result["degraded"] is True
    assert result["degraded_stage"] == "bond-universe-sync"
    assert result["warning_reason"] == "bond_universe_gap_remains"


