    assert result["holding_period_change_summary"]["holding_period_name_unparsed_delta"] == -2
    assert len(run_sync_calls) == 1
    # P0-03.1: holding_period 变化触发完整重评分，不再仅刷报告
    assert run_sync_calls[0]["reuse_existing_outputs"] is False
    assert run_sync_calls[0]["collection_profile"] == "weekly"


