def test_bond_fee_semantics_audit_distinguishes_sales_fee_zero_from_total_fee_zero() -> None:
    audit = build_bond_fee_semantics_audit(
        pd.DataFrame(
            [
                {
                    "基金代码": "000001",
                    "基金名称": "完整费率债A",
                    "基金类型": "债券型-长债",
                    "管理费率": 0.3,
                    "托管费率": 0.1,
                    "销售服务费率": 0.0,
                },
                {
                    "基金代码": "000002",
                    "基金名称": "完整费率债C",
                    "基金类型": "债券型-长债",
                    "管理费率": 0.3,
                    "托管费率": 0.1,
                    "销售服务费率": 0.2,
                },
            ]
        )
    )

    assert audit["available"] is True
    assert audit["summary"]["sales_fee_zero_rows"] == 1
    assert audit["summary"]["sales_fee_positive_rows"] == 1
    assert audit["summary"]["total_fee_zero_rows"] == 0
    assert audit["summary"]["total_fee_positive_rows"] == 2
    assert audit["summary"]["fee_component_complete_rows"] == 2
    assert audit["summary"]["total_fee_missing_component_as_zero_rows"] == 0
    assert audit["runtime_semantic_status_counts"] == {"exact": 2}
    assert audit["total_fee_semantic_status_counts"] == {"exact_positive": 2}
    assert "不等同于费率合计" in "；".join(audit["notes"])


def test_bond_fee_semantics_audit_flags_total_fee_missing_component_as_zero() -> None:
    audit = build_bond_fee_semantics_audit(
        pd.DataFrame(
            [
                {
                    "基金代码": "000001",
                    "基金名称": "销售缺失债A",
                    "基金类型": "债券型-长债",
                    "管理费率": 0.3,
                    "托管费率": 0.1,
                    "销售服务费率": None,
                },
                {
                    "基金代码": "000002",
                    "基金名称": "三项缺失债",
                    "基金类型": "债券型-长债",
                    "管理费率": None,
                    "托管费率": None,
                    "销售服务费率": None,
                },
            ]
        )
    )

    assert audit["summary"]["fee_component_complete_rows"] == 0
    assert audit["summary"]["fee_component_missing_rows"] == 2
    assert audit["summary"]["total_fee_positive_rows"] == 1
