def test_combined_quality_floor_keeps_enhanced_style_caps_relaxed() -> None:
    secondary = _combined_quality_floor("二级债增强")
    primary = _combined_quality_floor("一级债增强")
    pure_bond = _combined_quality_floor("综合纯债")

    assert secondary["fee_total_max"] > 0.60
    assert secondary["max_drawdown_max"] > 0.020
    assert secondary["volatility_max"] > 0.060
    assert primary["fee_total_max"] > 0.60
    assert pure_bond["fee_total_max"] == 0.60
    assert pure_bond["max_drawdown_max"] <= 0.020


