def test_since_inception_annualized_return_uses_accum_nav_and_quality_guards(tmp_path: Path) -> None:
    import backend.app as backend_app

    db_path = tmp_path / "bond_funds.db"
    conn = sqlite3.connect(str(db_path))
    try:
        conn.execute("CREATE TABLE funds (fcode TEXT PRIMARY KEY, estab_date DATE)")
        conn.execute(
            "CREATE TABLE fund_nav_history ("
            "id INTEGER PRIMARY KEY AUTOINCREMENT, "
            "fcode TEXT NOT NULL, "
            "nav_date DATE NOT NULL, "
            "unit_nav FLOAT NOT NULL, "
            "accum_nav FLOAT, "
            "daily_growth FLOAT)"
        )
        conn.executemany(
            "INSERT INTO funds (fcode, estab_date) VALUES (?, ?)",
            [
                ("000001", "2024-01-01"),
                ("000002", "2025-09-01"),
                ("000003", "2024-01-01"),
            ],
        )
        conn.executemany(
            "INSERT INTO fund_nav_history (fcode, nav_date, unit_nav, accum_nav, daily_growth) VALUES (?, ?, ?, ?, ?)",
            [
                ("000001", "2024-01-01", 1.00, 1.00, None),
                ("000001", "2026-01-01", 1.10, 1.21, None),
                ("000002", "2025-09-01", 1.00, 1.00, None),
                ("000002", "2026-01-01", 1.03, 1.03, None),
                ("000003", "2024-03-15", 1.00, 1.00, None),
                ("000003", "2026-03-15", 1.20, 1.44, None),
            ],
        )
        conn.commit()
    finally:
        conn.close()

    original_db_path = backend_app.settings.database_path
    try:
        backend_app.settings.database_path = db_path
        result = backend_app._compute_accum_nav_ratio_annualized_return_map(["000001", "000002", "000003"])
    finally:
        backend_app.settings.database_path = original_db_path

    assert result["000001"] == "9.99"
    assert "000002" not in result
    assert "000003" not in result


