def test_database_freshness_summary_requires_matching_sqlite_fingerprint(tmp_path: Path) -> None:
    from backend.database_freshness_summary import (
        build_database_freshness_summary,
        load_valid_database_freshness_summary,
        write_database_freshness_summary,
    )

    db_path = tmp_path / "bond_funds.db"
    reports_dir = tmp_path / "reports"
    conn = sqlite3.connect(str(db_path))
    try:
        conn.execute("CREATE TABLE funds (fcode TEXT PRIMARY KEY, last_updated_at TEXT)")
        conn.execute("CREATE TABLE fund_returns (fcode TEXT PRIMARY KEY, latest_nav_date TEXT, last_updated_at TEXT)")
        conn.execute("CREATE TABLE fund_nav_history (fcode TEXT, nav_date TEXT)")
        conn.execute("CREATE TABLE fund_rank_history (fcode TEXT, rank_date TEXT)")
        conn.execute("CREATE TABLE fund_risk_metrics (fcode TEXT, period TEXT, end_date TEXT, calculated_at TEXT)")
        conn.execute("INSERT INTO funds VALUES ('000001', '2026-06-05T08:00:00')")
        conn.execute("INSERT INTO fund_returns VALUES ('000001', '2026-06-04', '2026-06-05T08:01:00')")
        conn.execute("INSERT INTO fund_nav_history VALUES ('000001', '2026-06-04')")
        conn.execute("INSERT INTO fund_rank_history VALUES ('000001', '2026-06-04')")
        conn.execute("INSERT INTO fund_risk_metrics VALUES ('000001', '1y', '2026-06-04', '2026-06-05T08:02:00')")
        conn.commit()
    finally:
        conn.close()

    settings_stub = SimpleNamespace(
        database_path=db_path,
        reports_dir=reports_dir,
        project_root=tmp_path,
        core_root=PROJECT_ROOT / "core",
    )
    payload = build_database_freshness_summary(settings_stub)
    write_database_freshness_summary(settings_stub, payload)

    loaded = load_valid_database_freshness_summary(settings_stub)
    assert loaded is not None
    assert loaded["overview_fields"]["nav_history_record_count"] == 1
    assert loaded["rank_history_summary"]["latest_rank_business_date"] == "2026-06-04"

    os.utime(db_path, (time.time() + 5, time.time() + 5))
    assert load_valid_database_freshness_summary(settings_stub) is None


