    archive_conn = sqlite3.connect(str(archive_path))
    try:
        conn.execute(
            "CREATE TABLE fund_nav_history ("
            "id INTEGER PRIMARY KEY AUTOINCREMENT, "
            "fcode TEXT NOT NULL, "
            "nav_date TEXT NOT NULL, "
            "unit_nav REAL)"
        )
        conn.execute(
            "INSERT INTO fund_nav_history (fcode, nav_date, unit_nav) VALUES ('000001', '2021-06-03', 1.10)"
        )
        conn.commit()
        archive_conn.execute(
            "CREATE TABLE fund_nav_history_archive ("
            "fcode TEXT NOT NULL, "
            "nav_date TEXT NOT NULL, "
            "unit_nav REAL)"
        )
        archive_conn.execute(
            "INSERT INTO fund_nav_history_archive (fcode, nav_date, unit_nav) VALUES ('000001', '2021-06-01', 1.00)"
        )
        archive_conn.commit()
    finally:
        archive_conn.close()
        conn.close()

    monkeypatch.setattr(
        forward_validation,
        "load_latest_nav_history_archive_binding",
        lambda: {
            "archive_path": str(archive_path),
            "archive_table_name": "fund_nav_history_archive",
            "archive_cutoff_date": "2021-06-03",
        },
    )

    nav_df = forward_validation._load_nav_history_for_codes(
        db_path,
        ["000001"],
        start_date="2021-06-01",
        end_date="2021-06-03",
    )

    assert nav_df["nav_date"].dt.strftime("%Y-%m-%d").tolist() == ["2021-06-01", "2021-06-03"]
    assert nav_df["unit_nav"].tolist() == [1.0, 1.1]


