def test_reports_endpoint_defaults_to_compact_registry_payload_without_loading_full_reports() -> None:
    import backend.app as backend_app

    client = backend_app.app.test_client()
    publication = {
        "latest_canonical_run_id": "run-2",
        "current_published_run_id": "run-2",
        "latest_canonical_report_path": "reports/runs/run-2/report.json",
        "current_published_report_path": "reports/runs/run-2/report.json",
        "canonical_runs": [
            {
                "run_id": "run-2",
                "generated_at": "2026-04-22T07:43:32",
                "business_date": "2026-04-22",
                "final_count": 312,
                "dynamic_final_count": 549,
                "published": True,
                "publishable": True,
                "risk_publish_ready": True,
                "counts": {
                    "final_count": 312,
                    "dynamic_final_count": 549,
                    "screenable_universe_count": 7000,
                    "unused_heavy_count": 999,
                },
                "snapshot": {
                    "candidate_date": "2026-04-22",
                    "candidate_fund_count": 7800,
                    "risk_1y_effective_end_date": "2026-04-22",
                    "unused_snapshot_detail": "omitted",
                },
                "artifacts": {
                    "filtered_csv": "reports/runs/run-2/final.csv",
                    "report_json": "reports/runs/run-2/report.json",
                    "screening_audit_excel": "reports/runs/run-2/heavy.xlsx",
                },
                "project_publish_summary": {"heavy": "should not leak"},
            }
        ],
    }

    with (
        patch.object(backend_app, "ensure_embedded_scheduler", lambda: None),
        patch.object(backend_app, "_load_publication_registry_cached", return_value=publication),
        patch.object(backend_app.manager, "list_reports", side_effect=AssertionError("default should not load full reports")),
    ):
        response = client.get("/api/reports")

    assert response.status_code == 200
    payload = response.get_json()
    assert payload["payload_scope"]["mode"] == "compact"
    assert payload["payload_scope"]["full_endpoint"] == "/api/reports?full=1"
    assert payload["report_count"] == 1
    report = payload["reports"][0]
    assert report["run_id"] == "run-2"
    assert report["counts"] == {
        "final_count": 312,
        "dynamic_final_count": 549,
        "screenable_universe_count": 7000,
    }
    assert report["snapshot"] == {
        "candidate_date": "2026-04-22",
        "candidate_fund_count": 7800,
        "risk_1y_effective_end_date": "2026-04-22",
    }
    assert report["artifacts"] == {
        "filtered_csv": "reports/runs/run-2/final.csv",
        "report_json": "reports/runs/run-2/report.json",
    }
    assert "project_publish_summary" not in report

    with (
        patch.object(backend_app, "ensure_embedded_scheduler", lambda: None),
        patch.object(backend_app.manager, "list_reports", return_value=[{"run_id": "full-run", "project_publish_summary": {"kept": True}}]) as list_reports_mock,
    ):
        full_response = client.get("/api/reports?full=1")

    assert full_response.status_code == 200
    assert full_response.get_json()[0]["project_publish_summary"] == {"kept": True}
    list_reports_mock.assert_called_once_with()


def test_reports_latest_response_exposes_report_source_contract() -> None:
    import backend.app as backend_app

    client = backend_app.app.test_client()
    payload = {
        "run_id": "run-2",
        "generated_at": "2026-04-22T07:43:32",
        "final_count": 312,
        "counts": {"final_count": 312},
        "project_publish_summary": {
            "project_tracker_summary": {"current_active_count": 312},
        },
        "artifacts": {
            "report_json": "reports/runs/run-2/report.json",
        },
    }
    publication = {
        "latest_canonical_run_id": "run-2",
        "current_published_run_id": "run-2",
        "latest_canonical_report_path": "reports/runs/run-2/report.json",
        "current_published_report_path": "reports/runs/run-2/report.json",
        "automation_layers": {"scheduler": "ok"},
    }

    with (
        patch.object(backend_app, "ensure_embedded_scheduler", lambda: None),
        patch.object(backend_app, "_load_current_published_report_cached", return_value=payload),
        patch.object(backend_app, "_load_latest_report_cached", side_effect=AssertionError("published payload should be used")),
        patch.object(backend_app, "_load_publication_registry_cached", return_value=publication),
    ):
        response = client.get("/api/reports/latest")

    assert response.status_code == 200
    response_payload = response.get_json()
    source_basis = response_payload["source_basis"]
    assert response_payload["cache_basis"] == source_basis
    assert source_basis["source"] == "reports_latest_current_published_or_latest_report"
    assert source_basis["payload_source"] == "current_published_report"
    assert source_basis["run_id"] == "run-2"
    assert source_basis["final_count"] == 312
    assert source_basis["latest_canonical_run_id"] == "run-2"
    assert source_basis["current_published_run_id"] == "run-2"
    assert source_basis["latest_report_file"] != ""
    assert source_basis["publication_registry_file"] != ""
    assert source_basis["digest"]
    assert response_payload["source_contract"]["truth_policy"] == (
        "real_publication_registry_and_report_artifact_only"
    )
    assert response_payload["source_contract"]["business_value_synthesis"] == "forbidden"
    assert response_payload["source_contract"]["frontend_rendered_truth_allowed"] is False
    assert response_payload["source_contract"]["cache_basis_digest"] == source_basis["digest"]


