def test_publication_endpoint_defaults_to_summary_and_keeps_full_registry_on_request(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import backend.app as backend_app

    client = backend_app.app.test_client()
    reports_dir = tmp_path / "reports"
    run_dir = reports_dir / "runs" / "run-2"
    run_dir.mkdir(parents=True)
    latest_report_file = reports_dir / "latest.json"
    publication_registry_file = reports_dir / "publication_registry.json"
    report_json = run_dir / "report.json"
    latest_report_file.write_text("{}", encoding="utf-8")
    publication_registry_file.write_text("{}", encoding="utf-8")
    report_json.write_text("{}", encoding="utf-8")
    publication = {
        "latest_canonical_run_id": "run-2",
        "current_published_run_id": "run-2",
        "latest_canonical_report_path": "reports/runs/run-2/report.json",
        "canonical_runs": [
            {
                "run_id": "run-2",
                "generated_at": "2026-04-22T07:43:32",
                "group_key": "nav:2026-04-22",
                "published": True,
                "publishable": True,
                "snapshot": {
                    "candidate_date": "2026-04-22",
                    "candidate_fund_count": 7800,
                    "coverage_ratio_vs_total": 0.9,
                    "unused_snapshot_detail": "omitted",
                },
            },
            {
                "run_id": "run-diagnostic",
                "generated_at": "2026-04-22T08:00:00",
                "group_key": "nav:2026-04-23",
                "published": False,
                "publishable": False,
                "publish_blockers": [
                    {
                        "code": "risk_coverage_not_ready",
                        "label": "风险覆盖不足",
                        "detail": "风险指标覆盖未达到发布门槛。",
                        "severity": "blocking",
                    }
                ],
                "snapshot": {
                    "candidate_date": "2026-04-23",
                    "candidate_fund_count": 7700,
                    "coverage_ratio_vs_total": 0.89,
                },
            },
        ],
        "automation_layers": {"heavy": True},
        "publication_integrity": {"aligned": True},
    }

    monkeypatch.setattr(backend_app.settings, "project_root", tmp_path)
    monkeypatch.setattr(backend_app.settings, "reports_dir", reports_dir)
    monkeypatch.setattr(backend_app.settings, "runs_dir", reports_dir / "runs")
    monkeypatch.setattr(backend_app.settings, "latest_report_file", latest_report_file)
    monkeypatch.setattr(backend_app.settings, "publication_registry_file", publication_registry_file)
    with (
        patch.object(backend_app, "ensure_embedded_scheduler", lambda: None),
        patch.object(backend_app, "_load_publication_registry_cached", return_value=publication),
    ):
        response = client.get("/api/publication")
        summary_response = client.get("/api/publication/summary")
        full_response = client.get("/api/publication?full=1")

    assert response.status_code == 200
    payload = response.get_json()
    assert payload["payload_scope"]["mode"] == "summary"
    assert payload["payload_scope"]["full_endpoint"] == "/api/publication?full=1"
    assert payload["latest_canonical_run_id"] == "run-2"
    assert payload["canonical_run_count"] == 2
    published_record = next(item for item in payload["canonical_runs"] if item["run_id"] == "run-2")
    diagnostic_record = next(item for item in payload["canonical_runs"] if item["run_id"] == "run-diagnostic")
    assert published_record["publishable"] is True
    assert published_record["run_semantics"] == "formal_publication"
    assert published_record["publication_status"] == "current_published"
    assert diagnostic_record["publishable"] is False
    assert diagnostic_record["publish_blocked"] is True
    assert diagnostic_record["run_semantics"] == "diagnostic_only"
    assert diagnostic_record["publication_status"] == "not_publishable"
    assert diagnostic_record["publish_blockers"][0]["code"] == "risk_coverage_not_ready"
    assert "automation_layers" not in payload
    assert "publication_integrity" not in payload
    source_basis = payload["source_basis"]
    assert payload["cache_basis"] == source_basis
    assert source_basis["source"] == "publication_summary_publication_registry_artifact"
    assert source_basis["payload_mode"] == "summary"
    assert source_basis["latest_canonical_run_id"] == "run-2"
    assert source_basis["current_published_run_id"] == "run-2"
    assert source_basis["canonical_run_ids"] == ["run-2", "run-diagnostic"]
    assert source_basis["latest_canonical_run_present"] is True
    assert source_basis["current_published_run_present"] is True
    assert source_basis["publication_registry_file"] != "missing"
    assert source_basis["latest_report_file"] != "missing"
    assert source_basis["latest_canonical_report_token"] != "missing"
    assert payload["source_contract"]["truth_policy"] == "real_publication_registry_artifact_only"
    assert payload["source_contract"]["business_value_synthesis"] == "forbidden"
    assert payload["source_contract"]["frontend_rendered_truth_allowed"] is False
    assert payload["source_contract"]["cache_basis_digest"] == source_basis["digest"]

    assert summary_response.status_code == 200
    summary_payload = summary_response.get_json()
    assert summary_payload["source_basis"] == source_basis
    assert summary_payload["cache_basis"] == source_basis
    assert summary_payload["source_contract"] == payload["source_contract"]

    assert full_response.status_code == 200
    full_payload = full_response.get_json()
    assert full_payload["automation_layers"] == {"heavy": True}
    assert full_payload["publication_integrity"] == {"aligned": True}
    assert "source_basis" not in full_payload


