            patch.object(backend_app, "_apply_since_inception_annualized_return_to_funds", side_effect=lambda rows: rows),
            patch.object(backend_app, "_load_fund_data_source_map", data_source_mock),
            patch.object(backend_app, "_compute_since_inception_annualized_return_map", annualized_mock),
            patch.object(backend_app, "_attach_since_inception_annual_return_breakdown_rows", attach_mock),
            patch.object(backend_app, "_load_cached_style_metric_benchmark_map", benchmark_mock),
