def test_project_tracker_membership_change_summary_classifies_formal_list_transitions() -> None:
    from backend.project_tracker import _build_project_tracker_membership_change_summary

    snapshots = [
        {
            "business_date": "2026-04-27",
            "nav_snapshot_date": "2026-04-27",
            "run_id": "run_1",
            "csv_df": pd.DataFrame({"基金代码": ["000001", "000002", "000003"]}),
        },
        {
            "business_date": "2026-04-28",
            "nav_snapshot_date": "2026-04-28",
            "run_id": "run_2",
            "csv_df": pd.DataFrame({"基金代码": ["000001", "000003", "000004"]}),
        },
        {
            "business_date": "2026-04-29",
            "nav_snapshot_date": "2026-04-29",
            "run_id": "run_3",
            "csv_df": pd.DataFrame({"基金代码": ["000001", "000002", "000004", "000005"]}),
        },
    ]

    payload = _build_project_tracker_membership_change_summary(
        snapshots,
        tracked_fund_count=5,
        repeated_fund_count=3,
    )
    summary = payload["latest_membership_change_summary"]

    assert summary["available"] is True
    assert summary["new_entry_count"] == 1
    assert summary["continued_count"] == 2
    assert summary["returned_count"] == 1
    assert summary["dropped_count"] == 1
    assert summary["new_entry_codes_sample"] == ["000005"]
    assert summary["returned_codes_sample"] == ["000002"]
    assert summary["dropped_codes_sample"] == ["000003"]
    assert "新增入榜1只" in payload["latest_changes"]
    assert "缺席后回归1只" in payload["latest_changes"]
    rolling = summary["rolling_change_stability_summary"]
    assert rolling["available"] is True
    assert rolling["comparison_count"] == 2
    assert rolling["window_size"] == 2
    assert rolling["comparison_periods"] == ["2026-04-28", "2026-04-29"]
    assert rolling["mean_current_change_rate_pct"] == 41.66
    assert rolling["mean_dropped_rate_pct"] == 33.33
    assert rolling["latest_comparison"]["current_period"] == "2026-04-29"
    assert rolling["elevated_change_alert"] is False
    assert rolling["rolling_alert_codes"] == []


def test_project_tracker_duplicate_snapshot_reuse_keeps_transition_basis_unique(tmp_path: Path) -> None:
    from backend import project_tracker

    settings = SimpleNamespace(project_root=tmp_path)
    first = tmp_path / "first.xlsx"
    duplicate = tmp_path / "duplicate.xlsx"
    second = tmp_path / "second.xlsx"
    first.write_text("placeholder", encoding="utf-8")
    duplicate.write_text("placeholder", encoding="utf-8")
    second.write_text("placeholder", encoding="utf-8")
    process_df = pd.DataFrame(
        [
            {
                "业务日期": "2026-04-27",
                "净值快照日期": "2026-04-27",
                "快照签名": "sig_1",
                "项目批次": "run_1",
                "生成时间": "2026-04-27T10:00:00",
                "正式推荐数量": 2,
                "来源文件": first.name,
            },
            {
                "业务日期": "2026-04-27",
                "净值快照日期": "2026-04-27",
                "快照签名": "sig_1",
                "项目批次": "run_1_retry",
                "生成时间": "2026-04-27T11:00:00",
                "正式推荐数量": 2,
                "来源文件": duplicate.name,
            },
            {
                "业务日期": "2026-04-28",
                "净值快照日期": "2026-04-28",
                "快照签名": "sig_2",
                "项目批次": "run_2",
                "生成时间": "2026-04-28T10:00:00",
                "正式推荐数量": 2,
                "来源文件": second.name,
            },
        ]
    )

    def _fake_load_tracker_source_frame(path: Path) -> tuple[pd.DataFrame, str, str]:
        if path.name == "second.xlsx":
            return pd.DataFrame({"基金代码": ["000001", "000003"]}), "sig_2", "2026-04-28"
        return pd.DataFrame({"基金代码": ["000001", "000002"]}), "sig_1", "2026-04-27"

    unique_snapshots = project_tracker._build_project_tracker_unique_snapshots_from_process_rows(
        settings,
        process_df,
        load_tracker_source_frame=_fake_load_tracker_source_frame,
    )
    payload = project_tracker._build_project_tracker_membership_change_summary(unique_snapshots)
    summary = payload["latest_membership_change_summary"]

    assert [item["run_id"] for item in unique_snapshots] == ["run_1_retry", "run_2"]
    assert summary["current_run_id"] == "run_2"
    assert summary["previous_run_id"] == "run_1_retry"
    assert summary["continued_count"] == 1
    assert summary["new_entry_count"] == 1
    assert summary["dropped_count"] == 1
    assert summary["rolling_change_stability_summary"]["comparison_count"] == 1


