def test_write_multisheet_workbook_uses_lightweight_body_style_for_large_sheet(tmp_path: Path) -> None:
    workbook_path = tmp_path / "large_lightweight.xlsx"
    large_df = pd.DataFrame(
        {
            "基金名称": [f"测试基金{i:04d}" for i in range(3200)],
            "1年-年化收益(%)": ["1.23" for _ in range(3200)],
        }
    )

    _write_multisheet_workbook(
        workbook_path,
        main_sheet_name="Sheet1",
        main_df=large_df,
        left_align_column="基金名称",
        highlight_fill_color="FFF2CC",
    )

    wb = load_workbook(workbook_path)
    try:
        ws = wb["Sheet1"]
        assert ws["A1"].fill.fill_type == "solid"
        assert ws["A2"].fill.fill_type is None
        assert ws["A2"].alignment.horizontal == "left"
        assert ws["B2"].alignment.horizontal in (None, "general")
        assert ws["A2"].value == "测试基金0000"
        assert ws["B2"].value == "1.23"
    finally:
        wb.close()


