def test_layer10_keeps_all_eligible_when_top_n_is_none() -> None:
    df = pd.DataFrame(
        [
            {"fcode": "000001", "combo_score": 80.0, "ftype": "债券型"},
            {"fcode": "000002", "combo_score": 78.0, "ftype": "债券型"},
            {"fcode": "000003", "combo_score": 75.0, "ftype": "债券型"},
        ]
    )

    engine = FilteringEngine(
        period_years=1,
        data_loader=SimpleNamespace(),
        verbose=False,
        enable_tracking=False,
        fund_type="bond",
    )

    result = engine._layer10_final_selection(df, sort_col="combo_score", top_n=None)

    assert result["fcode"].tolist() == ["000001", "000002", "000003"]


