# P0-02 回归：磁盘 TTL 清理（cleanup_disk_usage）
# --------------------------------------------------------------------------


def test_cleanup_disk_usage_plan_archive_respects_keep_count_and_days(tmp_path: Path) -> None:
    from scripts import cleanup_disk_usage

    archive_root = tmp_path / "archive"
    archive_root.mkdir()
    now = datetime(2026, 4, 19, 12, 0, 0)

    # 构造 10 个归档，每个 10 天间隔：0/10/20/.../90 天前
    for i in range(10):
        day = now - timedelta(days=10 * i)
        run_dir = archive_root / f"{day:%Y%m%d}_080000_sync"
        run_dir.mkdir()
        (run_dir / "bond_analysis_report_stub.json").write_text("{}", encoding="utf-8")

    # 再加一个命名不规范的目录（应始终保留，避免误删人工产物）
    manual_dir = archive_root / "manual_whatever"
    manual_dir.mkdir()
    (manual_dir / "note.txt").write_text("hi", encoding="utf-8")

    # 场景 A：每天只有一个 run，因此最近 50 天的每日检查点都会保留。
    kept, removed = cleanup_disk_usage.plan_archive_cleanup(
        archive_root, keep_count=3, keep_days=50, now=now
    )
    kept_names = {p.name for p in kept}
    removed_names = {item.path.name for item in removed}

    # 无日期的 manual_dir 一定在 kept
    assert "manual_whatever" in kept_names
    # 最近 50 天 = 6 个（含今天，跨度 0/10/20/30/40/50 天）都在 kept
    recent_5 = {f"{(now - timedelta(days=10*i)):%Y%m%d}_080000_sync" for i in range(6)}
    assert recent_5.issubset(kept_names)
    # 60/70/80/90 天前的 4 个被标记删除
    old_5 = {f"{(now - timedelta(days=10*i)):%Y%m%d}_080000_sync" for i in range(6, 10)}
    assert old_5 == removed_names, f"kept={kept_names}, removed={removed_names}"


