def test_cleanup_disk_usage_plan_logs_skips_non_dated_files(tmp_path: Path) -> None:
    from scripts import cleanup_disk_usage

    logs_root = tmp_path / "logs"
    logs_root.mkdir()
    now = datetime(2026, 4, 19, 12, 0, 0)

    # 3 个日志：今天、8 天前、30 天前
    files = {
        f"collector_{now:%Y-%m-%d}.log": 0,
        f"database_{(now - timedelta(days=8)):%Y-%m-%d}.log": 8,
        f"api_{(now - timedelta(days=30)):%Y-%m-%d}.log": 30,
        "README.log": None,  # 无日期后缀，应保留
        f"collector_{(now - timedelta(days=20)):%Y-%m-%d}.log.2": 20,  # rotate 产物
    }
    for name, age in files.items():
        path = logs_root / name
        path.write_text("x", encoding="utf-8")
        modified = (now - timedelta(days=age or 0)).timestamp()
        os.utime(path, (modified, modified))

    kept, removed = cleanup_disk_usage.plan_logs_cleanup(logs_root, keep_days=14, now=now)
    kept_names = {p.name for p in kept}
    removed_names = {item.path.name for item in removed}

    assert "README.log" in kept_names
    assert f"collector_{now:%Y-%m-%d}.log" in kept_names
    assert f"database_{(now - timedelta(days=8)):%Y-%m-%d}.log" in kept_names
    assert f"api_{(now - timedelta(days=30)):%Y-%m-%d}.log" in removed_names
    # 20 天前的 rotate 产物也必须被删
    assert f"collector_{(now - timedelta(days=20)):%Y-%m-%d}.log.2" in removed_names


def test_cleanup_disk_usage_plan_maintenance_candidates_protects_recent_and_non_matching(
    tmp_path: Path,
) -> None:
    from scripts import cleanup_disk_usage

    now = datetime(2026, 7, 8, 12, 0, 0)
    nav_dir = tmp_path / "backend/data/maintenance/nav_history_vacuum"
    rank_dir = tmp_path / "backend/data/maintenance/rank_history_vacuum"
    nav_dir.mkdir(parents=True)
    rank_dir.mkdir(parents=True)

    old_nav = nav_dir / "bond_funds_vacuum_candidate_20260701_010000.db"
    old_nav.write_bytes(b"old-nav")
    os.utime(old_nav, (now.timestamp() - 7 * 86400, now.timestamp() - 7 * 86400))

    recent_nav = nav_dir / "bond_funds_vacuum_candidate_20260708_080000.db"
    recent_nav.write_bytes(b"recent-nav")
    os.utime(recent_nav, (now.timestamp() - 2 * 3600, now.timestamp() - 2 * 3600))

    old_rank = rank_dir / "bond_funds_vacuum_candidate_20260701_020000.db"
    old_rank.write_bytes(b"old-rank")
    os.utime(old_rank, (now.timestamp() - 7 * 86400, now.timestamp() - 7 * 86400))

    unrelated = nav_dir / "manual_snapshot.db"
    unrelated.write_bytes(b"manual")
    os.utime(unrelated, (now.timestamp() - 30 * 86400, now.timestamp() - 30 * 86400))

    kept, removed = cleanup_disk_usage.plan_maintenance_candidate_cleanup(
        tmp_path,
        keep_count=0,
        min_age_hours=6,
        now=now,
    )

    assert {item.path.name for item in removed} == {
        old_nav.name,
        old_rank.name,
    }
    assert {path.name for path in kept} == {recent_nav.name}
    assert unrelated.exists(), "非 vacuum candidate 命名文件不应进入清理范围"


