def test_cleanup_disk_usage_apply_actually_removes_targets(tmp_path: Path) -> None:
    from scripts import cleanup_disk_usage

    archive_root = tmp_path / "archive"
    logs_root = tmp_path / "logs"
    maintenance_root = tmp_path / "backend/data/maintenance/nav_history_vacuum"
    archive_root.mkdir()
    logs_root.mkdir()
    maintenance_root.mkdir(parents=True)
    now = datetime(2026, 4, 19, 12, 0, 0)

    old_run = archive_root / "20260101_080000_sync"
    old_run.mkdir()
    (old_run / "f.json").write_text("{}", encoding="utf-8")
    new_run = archive_root / "20260418_080000_sync"
    new_run.mkdir()

    old_log = logs_root / f"collector_{(now - timedelta(days=40)):%Y-%m-%d}.log"
    old_log.write_text("old", encoding="utf-8")
    modified = (now - timedelta(days=40)).timestamp()
    os.utime(old_log, (modified, modified))
    fresh_log = logs_root / f"collector_{now:%Y-%m-%d}.log"
    fresh_log.write_text("fresh", encoding="utf-8")
    old_candidate = maintenance_root / "bond_funds_vacuum_candidate_20260401_010000.db"
    old_candidate.write_bytes(b"candidate")
    os.utime(old_candidate, (now.timestamp() - 10 * 86400, now.timestamp() - 10 * 86400))

    settings_stub = SimpleNamespace(
        archived_runs_dir=archive_root,
        project_root=tmp_path,
        runs_dir=tmp_path / "runs",
    )

    report = cleanup_disk_usage.run_cleanup(
        settings=settings_stub,
        archive_keep_count=1,
        archive_keep_days=10,
        logs_keep_days=14,
        maintenance_candidate_keep_count=0,
        maintenance_candidate_min_age_hours=6,
        apply=True,
        now=now,
    )

    assert report.dry_run is False
    assert not old_run.exists(), "过期归档应被删除"
    assert new_run.exists(), "最新归档应被保留"
    assert not old_log.exists(), "40 天前日志应被删除"
    assert fresh_log.exists(), "今天日志应保留"
    assert not old_candidate.exists(), "过期 VACUUM candidate 应被删除"
    payload = report.to_dict()
    assert payload["archive"]["removed_total"] >= 1
    assert payload["logs"]["removed_total"] >= 1
    assert payload["maintenance_candidates"]["removed_total"] >= 1


