    assert execution_plan["scope_files"] == ["bond_funds_backup_20260501_000000.db.zst"]
    assert "bond_funds_pre_rank_archive_20260604_rank_hot_delete_pre_backup.db.zst" in protected_files
    assert "bond_funds_pre_rank_vacuum_replace_20260604_rank_vacuum_after_hotdelete.db" in protected_files
    assert not manual_review_files.intersection(
        {
            "bond_funds_pre_rank_archive_20260604_rank_hot_delete_pre_backup.db.zst",
            "bond_funds_pre_rank_vacuum_replace_20260604_rank_vacuum_after_hotdelete.db",
        }
    )
    assert all("pre_rank" not in item for item in execution_plan["scope_files"])


