# P0-02.3 回归：publication registry 归档区增量索引
# --------------------------------------------------------------------------


def test_publication_registry_archive_index_is_populated_and_reused(tmp_path: Path) -> None:
    """构造 2 个归档 run，首轮构建索引后第二轮命中索引，内容与首轮等价。"""

    from backend import publication

    archive_root = tmp_path / "archive" / "superseded_runs"
    archive_root.mkdir(parents=True)
    runs_root = tmp_path / "runs"
    runs_root.mkdir()

    def _write_run(run_id: str, final_count: int, archived: bool) -> Path:
        parent = archive_root if archived else runs_root
        run_dir = parent / run_id
        run_dir.mkdir()
        payload = {
            "run_id": run_id,
            "generated_at": f"2026-04-{10 + int(run_id[6:8]):02d}T08:00:00",
            "counts": {"final_count": final_count},
            "artifacts": {},
            "database_freshness": {
                "effective_nav_snapshot": {"candidate_date": "2026-04-10", "ready": True, "signature": "sig"},
                "risk_1y_freshness": {"aligned": True},
            },
        }
        report_path = run_dir / f"bond_analysis_report_{run_id}.json"
        report_path.write_text(json.dumps(payload), encoding="utf-8")
        return report_path

    _write_run("20260410_080000_sync", final_count=100, archived=True)
    _write_run("20260411_080000_sync", final_count=120, archived=True)
    _write_run("20260418_080000_sync", final_count=140, archived=False)

    settings_stub = SimpleNamespace(
        runs_dir=runs_root,
        archived_runs_dir=archive_root,
        reports_dir=tmp_path,
        latest_report_file=tmp_path / "latest.json",
        publication_registry_file=tmp_path / "publication_registry.json",
        effective_nav_coverage_ratio=0.9,
        effective_nav_weekday_only=True,
        database_path=tmp_path / "nonexistent.db",
    )

    # 第一次扫描：索引初次建立
    first = publication._collect_run_records(settings_stub)
    first_run_ids = sorted(r["run_id"] for r in first)
    assert first_run_ids == [
        "20260410_080000_sync",
        "20260411_080000_sync",
        "20260418_080000_sync",
    ]

    index_path = publication._archive_index_path(settings_stub)
    assert index_path.exists(), "归档索引应被写入"
    index = publication._load_archive_index(settings_stub)
    # 两个归档的 run 都应被索引（runs_dir 下的不进索引）
    assert len(index) == 2, f"expected 2 archive entries, got {len(index)}: {list(index)}"
    for key, entry in index.items():
        assert "mtime_ns" in entry and "size" in entry and "record" in entry
        assert entry["record"]["run_id"] in {"20260410_080000_sync", "20260411_080000_sync"}

    # 第二次扫描：命中索引，结果应完全一致
    second = publication._collect_run_records(settings_stub)
    assert sorted(r["run_id"] for r in second) == first_run_ids

    # 改动其中一个归档文件的内容（mtime/size 会变），索引应自动失效并重建
    target_report = archive_root / "20260410_080000_sync" / "bond_analysis_report_20260410_080000_sync.json"
    original_payload = json.loads(target_report.read_text())
    original_payload["counts"]["final_count"] = 999
    target_report.write_text(json.dumps(original_payload), encoding="utf-8")
    # 部分文件系统 mtime 粒度到秒，连续两次 write_text 可能 mtime 一致。
    # 显式把 mtime 推进 2 秒，模拟"真实隔段时间修改"。
    now_ts = time.time()
    os.utime(target_report, (now_ts + 2.0, now_ts + 2.0))

    third = publication._collect_run_records(settings_stub)
    third_record = next(r for r in third if r["run_id"] == "20260410_080000_sync")
    assert third_record["final_count"] == 999, "修改归档后索引应失效并重读"


