def test_rescreen_report_after_maintenance_uses_full_screening_not_reuse(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """P0-03.1: 维护数据变化后的重评分必须 reuse_existing_outputs=False，
    而不是此前的 `_refresh_report_from_existing_outputs` 只刷报告。"""

    from backend.scheduler import ProjectScheduler

    scheduler = ProjectScheduler.__new__(ProjectScheduler)

    captured_options: list[dict] = []

    def _fake_subprocess(self, options, *, log=None):
        captured_options.append(dict(options))
        return {"status": "success", "run_id": "rescreen_stub"}

    def _fake_available(self):
        return True

    monkeypatch.setattr(ProjectScheduler, "_run_workflow_in_subprocess", _fake_subprocess)
    monkeypatch.setattr(ProjectScheduler, "_workflow_execution_available", _fake_available)

    result = scheduler._rescreen_report_after_maintenance(
        collection_profile="weekly",
        log=lambda _m: None,
    )

    assert result == {"status": "success", "run_id": "rescreen_stub"}
    assert len(captured_options) == 1
    options = captured_options[0]
    assert options["run_collection"] is False
    assert options["run_screening"] is True
    assert options["reuse_existing_outputs"] is False, (
        "维护后重评分必须跑真正的筛选，而不是仅刷报告"
    )
    assert options["collection_profile"] == "weekly"


