def test_snapshot_watchdog_triggers_intraday_when_snapshot_advanced(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """P0-03.2: 有效净值快照发生变化且当日未处理过，watchdog 应触发一次
    `_execute_scheduled_refresh('intraday')` 且 task_name 带 watchdog 前缀。"""

    from backend import scheduler as scheduler_module
    from backend.scheduler import ProjectScheduler

    scheduler = ProjectScheduler.__new__(ProjectScheduler)
    scheduler.settings = SimpleNamespace(
        database_path=Path("/tmp/nonexistent.db"),
        latest_report_file=Path("/tmp/nonexistent_latest.json"),
        effective_nav_coverage_ratio=0.9,
        effective_nav_weekday_only=True,
        scheduler_intraday_nav_history_sync_enabled=True,
        scheduler_intraday_nav_history_sync_limit=0,
        scheduler_intraday_long_term_history_enabled=False,
        scheduler_intraday_long_term_history_limit=0,
        scheduler_intraday_long_term_history_refresh_stale=False,
    )
    scheduler.workflow_manager = SimpleNamespace(is_running=lambda: False)
    scheduler.state_store = SimpleNamespace(snapshot=lambda: {})

    # 当前快照推进到 2026-04-17，但 latest 里记着 2026-04-15
    current_stub = SimpleNamespace(
        ready=True,
        readiness_reason="ready",
        candidate_date="2026-04-17",
        signature="sig_new",
        raw_max_latest_nav_date="2026-04-17",
        future_outlier_fund_count=0,
    )
    latest_stub = {"candidate_date": "2026-04-15", "signature": "sig_old"}

    monkeypatch.setattr(scheduler_module, "load_effective_nav_snapshot", lambda *a, **kw: current_stub)
    monkeypatch.setattr(scheduler_module, "load_latest_screened_db_snapshot", lambda _p: latest_stub)

    captured_calls: list[dict] = []

    def _fake_refresh(self, **kwargs):
        captured_calls.append(dict(kwargs))
        return {"task_name": kwargs.get("task_name"), "status": "success"}

    monkeypatch.setattr(ProjectScheduler, "_execute_scheduled_refresh", _fake_refresh)

    result = scheduler._execute_snapshot_watchdog()

    assert len(captured_calls) == 1, "快照推进时 watchdog 必须触发一次 scheduled_refresh"
    call = captured_calls[0]
    assert call["task_name"] == "scheduled_snapshot_watchdog_refresh"
    assert call["refresh_window"] == "intraday"
    assert call["long_term_history_refresh_stale"] is False
    assert result["task_name"] == "scheduled_snapshot_watchdog_refresh"
    assert result.get("trigger_source") == "snapshot_watchdog"


def test_snapshot_watchdog_skips_when_current_snapshot_already_processed(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """P0-03.2: 若当日已经处理过同一快照（last_runs 里有 success），watchdog 必须
    skipped 而不是重复触发，避免同快照风暴。"""

    from backend import scheduler as scheduler_module
    from backend.scheduler import ProjectScheduler

    scheduler = ProjectScheduler.__new__(ProjectScheduler)
    scheduler.settings = SimpleNamespace(
        database_path=Path("/tmp/nonexistent.db"),
        latest_report_file=Path("/tmp/nonexistent_latest.json"),
        effective_nav_coverage_ratio=0.9,
        effective_nav_weekday_only=True,
        scheduler_intraday_nav_history_sync_enabled=True,
        scheduler_intraday_nav_history_sync_limit=0,
        scheduler_intraday_long_term_history_enabled=False,
        scheduler_intraday_long_term_history_limit=0,
        scheduler_intraday_long_term_history_refresh_stale=False,
    )
    scheduler.workflow_manager = SimpleNamespace(is_running=lambda: False)

    current_stub = SimpleNamespace(
        ready=True,
        readiness_reason="ready",
        candidate_date="2026-04-17",
        signature="sig_new",
        raw_max_latest_nav_date="2026-04-17",
        future_outlier_fund_count=0,
    )
    latest_stub = {"candidate_date": "2026-04-15", "signature": "sig_old"}

    # state_store 里记录"intraday 刚成功且 after snapshot = 当前快照"，应触发"已处理"判重
    scheduler.state_store = SimpleNamespace(
        snapshot=lambda: {
            "last_runs": {
                "scheduled_intraday_bond_refresh": {
                    "status": "success",
                    "screening_triggered": True,
                    "after_effective_nav_snapshot": {
                        "candidate_date": "2026-04-17",
                        "signature": "sig_new",
                    },
                }
            }
        }
    )

    monkeypatch.setattr(scheduler_module, "load_effective_nav_snapshot", lambda *a, **kw: current_stub)
    monkeypatch.setattr(scheduler_module, "load_latest_screened_db_snapshot", lambda _p: latest_stub)

    captured: list[dict] = []

    def _fake_refresh(self, **kwargs):
        captured.append(dict(kwargs))
        return {"task_name": kwargs.get("task_name"), "status": "success"}

    monkeypatch.setattr(ProjectScheduler, "_execute_scheduled_refresh", _fake_refresh)

    result = scheduler._execute_snapshot_watchdog()

    assert result["status"] == "skipped"
    assert result["skip_reason"] == "current_snapshot_already_processed"
    assert result["screening_triggered"] is False
    assert captured == [], "快照已被 intraday_refresh 处理过，watchdog 不应再触发"


