def test_last_refresh_processed_current_snapshot_recognizes_watchdog_runs() -> None:
    """V2: watchdog 跑完会落 last_runs["scheduled_snapshot_watchdog_refresh"]。
    下次 watchdog 调用时 _last_refresh_processed_current_snapshot 必须识别这条记录，
    避免发布门禁失败导致 latest.json signature 未更新时重复触发同快照。"""

    from backend.scheduler import ProjectScheduler

    scheduler = ProjectScheduler.__new__(ProjectScheduler)

    current_snapshot = SimpleNamespace(
        candidate_date="2026-04-17",
        signature="sig_new",
    )

    state_payload = {
        "last_runs": {
            "scheduled_snapshot_watchdog_refresh": {
                "status": "success",
                "screening_triggered": True,
                "after_effective_nav_snapshot": {
                    "candidate_date": "2026-04-17",
                    "signature": "sig_new",
                },
            }
        }
    }

    assert scheduler._last_refresh_processed_current_snapshot(
        current_snapshot,
        state_payload=state_payload,
    ) is True

    # 反向验证：watchdog 处理的是旧快照时不应被误判
    state_payload_old = {
        "last_runs": {
            "scheduled_snapshot_watchdog_refresh": {
                "status": "success",
                "screening_triggered": True,
                "after_effective_nav_snapshot": {
                    "candidate_date": "2026-04-15",
                    "signature": "sig_old",
                },
            }
        }
    }
    assert scheduler._last_refresh_processed_current_snapshot(
        current_snapshot,
        state_payload=state_payload_old,
    ) is False


