def test_scheduler_start_registers_snapshot_watchdog_job_alongside_cron(tmp_path: Path) -> None:
    """V6: 真实跑 ProjectScheduler.start() 一次，检查 4 个 jobs 全部注册；
    随后 shutdown 并断言 watchdog 使用 IntervalTrigger。"""

    from backend.scheduler import ProjectScheduler, SchedulerStateStore
    from apscheduler.triggers.cron import CronTrigger
    from apscheduler.triggers.interval import IntervalTrigger

    # 构造一个最小 settings，让 start() 能真正跑到 add_job 然后立刻 shutdown
    state_file = tmp_path / "scheduler_state.json"
    heartbeat_file = tmp_path / "scheduler_heartbeat.json"
    pid_file = tmp_path / "scheduler.pid"

    settings = SimpleNamespace(
        project_root=tmp_path,
        scheduler_timezone="Asia/Shanghai",
        scheduler_daily_hour=7,
        scheduler_daily_minute=30,
        scheduler_intraday_refresh_enabled=True,
        scheduler_intraday_hour=13,
        scheduler_intraday_minute=45,
        scheduler_weekly_day_of_week="sun",
        scheduler_weekly_hour=3,
        scheduler_weekly_minute=0,
        scheduler_snapshot_watchdog_enabled=True,
        scheduler_snapshot_watchdog_interval_minutes=17,
        scheduler_state_file=state_file,
        scheduler_heartbeat_file=heartbeat_file,
        scheduler_pid_file=pid_file,
        scheduler_heartbeat_interval_seconds=60,
        database_path=tmp_path / "empty.db",
        latest_report_file=tmp_path / "latest.json",
    )

    scheduler = ProjectScheduler.__new__(ProjectScheduler)
    scheduler.settings = settings
    scheduler.state_store = SchedulerStateStore(state_file)
    scheduler.workflow_manager = SimpleNamespace(
        is_running=lambda: False,
        run_sync=lambda _o: {"run_id": "stub"},
    )

    class _StubTaskRecorder:
        def start_task(self, name):
            return {"task_name": name}

        def finish_task(self, *a, **kw):
            return None

        def recover_stale_tasks(self, reason):
            return {"recovered_total": 0, "recovered_task_names": []}

    scheduler.task_recorder = _StubTaskRecorder()

    from apscheduler.schedulers.background import BackgroundScheduler

    scheduler.scheduler = BackgroundScheduler(daemon=True)
    scheduler._started = False
    scheduler._heartbeat_thread = None
    scheduler._heartbeat_stop_event = threading.Event()
    scheduler._startup_recovery_started = True  # 跳过 startup catch-up 线程
    scheduler._startup_recovery_lock = threading.Lock()
    scheduler.stop_event = threading.Event()
    scheduler._lock = threading.Lock()
    scheduler._manual_run_lock = threading.Lock()
    scheduler.logger = lambda _msg: None  # 绕过 __init__ 时的 logger 注入

    try:
        scheduler.start()
        jobs = {job.id: job for job in scheduler.scheduler.get_jobs()}
        assert set(jobs) == {
            "daily_refresh",
            "intraday_refresh",
            "weekly_maintenance",
            "snapshot_watchdog",
        }, f"预期 4 个 job，实际: {set(jobs)}"
        watchdog_job = jobs["snapshot_watchdog"]
        assert isinstance(watchdog_job.trigger, IntervalTrigger)
        # IntervalTrigger(minutes=17) 对应 1020 秒
        assert watchdog_job.trigger.interval.total_seconds() == 17 * 60
        assert watchdog_job.misfire_grace_time == 17 * 60 // 2
        for cron_job_id in ("daily_refresh", "intraday_refresh", "weekly_maintenance"):
            assert isinstance(jobs[cron_job_id].trigger, CronTrigger), (
                f"{cron_job_id} 应使用 CronTrigger"
            )
    finally:
        try:
            scheduler.shutdown()
        except Exception:
            pass


