def test_risk_calculator_reads_runtime_override_for_risk_free_rate(tmp_path: Path) -> None:
    """覆盖 override 优先级：runtime_overrides.yaml > env > default。"""

    from bond_fund_screening import runtime_overrides as ro
    from bond_fund_screening.core.risk_calculator import RiskCalculator
    from bond_fund_screening.config import RISK_FREE_RATE as DEFAULT_RFR

    override_path = tmp_path / "runtime_overrides.yaml"
    ro.write_risk_free_rate(
        0.022,
        updated_at="2026-05-01T08:00:00",
        source_detail="test",
        overrides_path=override_path,
    )

    resolution = ro.get_risk_free_rate(DEFAULT_RFR, overrides_path=override_path)
    assert resolution.source == "runtime_overrides"
    assert resolution.value == pytest.approx(0.022)
    assert resolution.updated_at == "2026-05-01T08:00:00"

    # 不传 risk_free_rate 参数时，应从生产 overrides 解析；此处走 default 路径
    # 避免污染全局 cache
    ro.refresh()


def test_runtime_overrides_reads_legacy_config_path_when_data_path_absent(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from bond_fund_screening import runtime_overrides as ro
    from bond_fund_screening.config import RISK_FREE_RATE as DEFAULT_RFR

    data_path = tmp_path / "backend" / "data" / "runtime_overrides.yaml"
    legacy_path = tmp_path / "config" / "runtime_overrides.yaml"
    legacy_path.parent.mkdir(parents=True, exist_ok=True)
    legacy_path.write_text(
        yaml.safe_dump(
            {
                "risk_free_rate": {
                    "value": 0.0199,
                    "updated_at": "2026-05-22T12:00:00",
                    "source_detail": "legacy",
                }
            },
            allow_unicode=True,
            sort_keys=False,
        ),
        encoding="utf-8",
    )

    monkeypatch.setattr(ro, "_DEFAULT_OVERRIDES_PATH", data_path)
    monkeypatch.setattr(ro, "_LEGACY_OVERRIDES_PATH", legacy_path)
    ro.refresh()

    resolution = ro.get_risk_free_rate(float(DEFAULT_RFR), overrides_path=data_path)
    assert resolution.value == pytest.approx(0.0199)
    assert resolution.source == "runtime_overrides"
    assert resolution.updated_at == "2026-05-22T12:00:00"


def test_runtime_overrides_writes_to_data_path_while_seeding_from_legacy(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from bond_fund_screening import runtime_overrides as ro

    data_path = tmp_path / "backend" / "data" / "runtime_overrides.yaml"
    legacy_path = tmp_path / "config" / "runtime_overrides.yaml"
    legacy_path.parent.mkdir(parents=True, exist_ok=True)
    legacy_path.write_text(
        yaml.safe_dump(
            {"other_runtime_flag": {"enabled": True}},
            allow_unicode=True,
            sort_keys=False,
        ),
        encoding="utf-8",
    )

    monkeypatch.setattr(ro, "_DEFAULT_OVERRIDES_PATH", data_path)
    monkeypatch.setattr(ro, "_LEGACY_OVERRIDES_PATH", legacy_path)
    ro.refresh()

    ro.write_risk_free_rate(
        0.0202,
        updated_at="2026-05-22T12:30:00",
        source_detail="seeded_from_legacy",
        overrides_path=data_path,
    )

    assert data_path.exists() is True
    payload = yaml.safe_load(data_path.read_text(encoding="utf-8"))
    assert payload["other_runtime_flag"]["enabled"] is True
    assert payload["risk_free_rate"]["value"] == pytest.approx(0.0202)
    assert payload["risk_free_rate"]["updated_at"] == "2026-05-22T12:30:00"
    assert payload["risk_free_rate"]["source_detail"] == "seeded_from_legacy"
    assert legacy_path.exists() is True


def test_risk_calculator_falls_back_to_default_when_override_absent(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from bond_fund_screening import runtime_overrides as ro
    from bond_fund_screening.core.risk_calculator import RiskCalculator
    from bond_fund_screening.config import RISK_FREE_RATE as DEFAULT_RFR

    isolated_overrides_path = tmp_path / "runtime_overrides.yaml"
    original_get_risk_free_rate = ro.get_risk_free_rate
    monkeypatch.delenv("BOND_FUND_RISK_FREE_RATE", raising=False)
    monkeypatch.setattr(
        ro,
        "get_risk_free_rate",
        lambda default: original_get_risk_free_rate(
            default,
            overrides_path=isolated_overrides_path,
        ),
    )
    ro.refresh(isolated_overrides_path)
    calc = RiskCalculator()  # 不传 risk_free_rate 参数
    assert calc.risk_free_rate == pytest.approx(float(DEFAULT_RFR))
    assert calc.risk_free_rate_source == "default"


