def test_enhanced_scoring_engine_signed_var_and_drawdown_units_preserve_risk_order(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import bond_fund_screening.core.enhanced_scoring_engine as enhanced_scoring_engine_module

    monkeypatch.setattr(
        enhanced_scoring_engine_module,
        "get_risk_free_rate",
        lambda default: SimpleNamespace(value=0.018, source="default", updated_at=None),
    )
    engine = enhanced_scoring_engine_module.EnhancedScoringEngine(fund_category="bond")

    assert engine.current_baselines["max_drawdown"] == {
        "good": pytest.approx(0.03),
        "bad": pytest.approx(0.10),
        "direction": "negative",
    }
    assert engine.current_baselines["var_95"]["direction"] == "positive"
    assert engine._calc_absolute_bonus(-0.05, "var_95") == pytest.approx(1.0)
    assert engine._calc_absolute_bonus(-0.15, "var_95") == pytest.approx(0.0)

    frame = pd.DataFrame(
        {
            "sharpe_ratio": [1.0, 1.0],
            "sortino_ratio": [1.5, 1.5],
            "max_drawdown": [0.01, 0.12],
            "var_95": [-0.001, -0.02],
        },
        index=["safer", "riskier"],
    )
    risk_scores = engine._calc_risk_scores(frame)
    assert risk_scores["safer"] > risk_scores["riskier"]


def test_refresh_risk_free_rate_fetches_10y_from_chinabond_html(monkeypatch: pytest.MonkeyPatch) -> None:
    refresh_module = _load_script_module(
        "refresh_risk_free_rate_test_module",
        "scripts/refresh_risk_free_rate.py",
    )

    class _FakeResponse:
        def __init__(self, text: str = "") -> None:
            self.text = text

        def raise_for_status(self) -> None:
            return None

    class _FakeSession:
        def __init__(self) -> None:
            self.headers = {}

        def get(self, url: str, timeout: int = 20):
            return _FakeResponse("")

        def post(self, url: str, timeout: int = 20):
            return _FakeResponse(
                "<table><tr><td>7.0y</td><td>1.6039</td></tr>"
                "<tr><td>10.0y</td><td>1.7448</td></tr></table>"
            )

    monkeypatch.setattr(refresh_module.requests, "Session", _FakeSession)
    assert refresh_module._fetch_from_api() == pytest.approx(0.017448)


def test_bond_screening_risk_calculator_keeps_raw_ratios_alongside_capped_values() -> None:
    from bond_fund_screening.core.risk_calculator import RiskCalculator

    calc = RiskCalculator(risk_free_rate=0.015, mar=0.0, trading_days_per_year=252)
    dates = pd.date_range("2025-01-01", periods=260, freq="B")
    daily_growth = np.where(np.arange(len(dates)) % 2 == 0, 0.17, 0.19)
    daily_growth[1] = -0.000001
    accum_nav = np.cumprod(1.0 + (daily_growth / 100.0))
    nav = pd.DataFrame(
        {
            "nav_date": dates,
            "unit_nav": accum_nav,
            "accum_nav": accum_nav,
            "daily_growth": daily_growth,
        }
    )

    metrics = calc.calculate_all_metrics(nav, period_years=1.0)

    assert metrics["raw_sharpe_ratio"] is not None
    assert metrics["raw_sortino_ratio"] is not None
    assert metrics["raw_sharpe_ratio"] >= metrics["sharpe_ratio"]
    assert metrics["raw_sortino_ratio"] >= metrics["sortino_ratio"]
    assert metrics["sharpe_ratio"] == pytest.approx(5.0)
    assert metrics["sortino_ratio"] == pytest.approx(10.0)
    assert metrics["sharpe_ratio_cap_hit"] is True
    assert metrics["sortino_ratio_cap_hit"] is True


def test_bond_screening_risk_calculator_rejects_sparse_weekly_daily_growth() -> None:
    from bond_fund_screening.core.risk_calculator import RiskCalculator

    calc = RiskCalculator(risk_free_rate=0.015, mar=0.0, trading_days_per_year=252)
    dates = pd.date_range("2025-04-21", periods=53, freq="7D")
    weekly_growth = [0.0002, 0.0016, -0.0004, 0.0011, 0.0003, 0.0012, -0.0002, 0.0009]
    accum_nav = [1.0]
    for idx in range(1, len(dates)):
        accum_nav.append(accum_nav[-1] * (1 + weekly_growth[(idx - 1) % len(weekly_growth)]))

    nav = pd.DataFrame(
        {
            "nav_date": dates,
            "unit_nav": [1.0 + idx * 0.0001 for idx in range(len(dates))],
            "accum_nav": accum_nav,
            "daily_growth": [None] + [0.01] * (len(dates) - 1),
        }
    )

    metrics = calc.calculate_all_metrics(nav, period_years=1.0)

    assert metrics["volatility"] is not None
    assert metrics["volatility"] > 0.0005
    assert metrics["raw_sharpe_ratio"] is not None
    assert metrics["raw_sharpe_ratio"] < 20


