def test_scheduler_builds_risk_free_rate_drift_audit() -> None:
    """P1-03.3: weekly_maintenance 末段调用的 drift audit helper 必须返回一致结构。"""

    from backend.scheduler import ProjectScheduler
    from backend.config import load_settings

    scheduler = ProjectScheduler.__new__(ProjectScheduler)
    scheduler.settings = load_settings()

    audit = scheduler._build_risk_free_rate_drift_audit(alert_bps=25.0)
    assert set(audit.keys()) == {
        "baseline",
        "current_value",
        "current_source",
        "current_updated_at",
        "drift_bps",
        "alert_bps_threshold",
        "alert_triggered",
    }
    assert isinstance(audit["drift_bps"], float)
    assert audit["alert_bps_threshold"] == 25.0
    # 基线场景下无 override，source 应为 default，drift 为 0
    assert audit["current_source"] in {"default", "env", "runtime_overrides"}


def test_scheduler_detects_risk_free_rate_refresh_value_change() -> None:
    from backend.scheduler import ProjectScheduler

    unchanged = {
        "succeeded": True,
        "report": {
            "applied": True,
            "current_value": 0.017299,
            "post_value": 0.017299,
        },
    }
    changed = {
        "succeeded": True,
        "report": {
            "applied": True,
            "current_value": 0.017448,
            "post_value": 0.017299,
        },
    }

    assert ProjectScheduler._risk_free_rate_refresh_changed(unchanged) is False
    assert ProjectScheduler._risk_free_rate_refresh_changed(changed) is True
    assert ProjectScheduler._risk_free_rate_refresh_changed({"succeeded": False}) is False


def test_scheduler_risk_parameter_rescreen_forces_full_risk_recalculation() -> None:
    from backend.scheduler import ProjectScheduler

    scheduler = ProjectScheduler.__new__(ProjectScheduler)
    calls: list[dict[str, Any]] = []
    scheduler._workflow_execution_available = lambda: True

    def _fake_run(options, *, log=None):
        calls.append(dict(options))
        return {"run_id": "risk_parameter_rescreen_run", "counts": {"final_count": 3}}

    scheduler._run_workflow_in_subprocess = _fake_run

    result = ProjectScheduler._rescreen_report_after_risk_parameter_change(
        scheduler,
        collection_profile="weekly",
        log=lambda message: None,
    )

    assert result["run_id"] == "risk_parameter_rescreen_run"
    assert calls == [
        {
            "run_collection": False,
            "run_screening": True,
            "reuse_existing_outputs": False,
            "collection_profile": "weekly",
            "force_calculate_risk": True,
            "risk_refresh_changed_nav_only": False,
        }
    ]


