# P1-04 / B7.2 回归：accum_nav 局部补齐
# --------------------------------------------------------------------------


def test_gap_fill_accum_nav_fills_from_unit_nav_and_adjust_factor() -> None:
    from bond_fund_screening.core.risk_calculator import RiskCalculator

    df = pd.DataFrame(
        {
            "unit_nav": [1.0, 1.01, 0.95, 0.96, 0.97],
            "adjust_factor": [1.0, 1.0, 1.1, 1.1, 1.1],
            "accum_nav": [1.0, 1.01, None, None, 1.07],
            "daily_growth": [0.0, 1.0, -5.94, 1.05, 1.04],
        }
    )
    filled, count = RiskCalculator._gap_fill_accum_nav(df)
    # 第 3/4 行应被 unit_nav * adjust_factor 补齐
    assert count == 2
    assert filled.loc[2, "accum_nav"] == pytest.approx(0.95 * 1.1)
    assert filled.loc[3, "accum_nav"] == pytest.approx(0.96 * 1.1)
    # 原有值保持不变
    assert filled.loc[0, "accum_nav"] == pytest.approx(1.0)
    assert filled.loc[4, "accum_nav"] == pytest.approx(1.07)


def test_gap_fill_accum_nav_falls_back_to_daily_growth_accumulation() -> None:
    from bond_fund_screening.core.risk_calculator import RiskCalculator

    df = pd.DataFrame(
        {
            "unit_nav": [1.0, 1.01, None, 1.03, 1.04],
            "accum_nav": [1.0, 1.01, None, None, 1.04],
            "daily_growth": [0.0, 1.0, 0.5, 0.8, 0.0],
        }
    )
    filled, count = RiskCalculator._gap_fill_accum_nav(df)
    # 2/3 行走 daily_growth 累乘：
    # row2 = 1.01 * 1.005 = 1.01505
    # row3 = 1.01505 * 1.008 = 1.02317...
    assert count == 2
    assert filled.loc[2, "accum_nav"] == pytest.approx(1.01 * 1.005, rel=1e-6)
    assert filled.loc[3, "accum_nav"] == pytest.approx(1.01 * 1.005 * 1.008, rel=1e-6)


