def test_data_loader_nav_latest_dates_use_returns_summary_without_history_table(tmp_path: Path) -> None:
    from bond_fund_screening.core.data_loader import DataLoader

    db_path = tmp_path / "nav_latest_returns_summary.db"
    with sqlite3.connect(db_path) as conn:
        conn.execute(
            "CREATE TABLE fund_returns (fcode TEXT PRIMARY KEY, latest_nav_date TEXT)"
        )
        conn.executemany(
            "INSERT INTO fund_returns VALUES (?, ?)",
            [
                ("000001", "2026-06-05"),
                ("000002", "2026-06-04"),
            ],
        )

