# --------------------------------------------------------------------------
# P1-05 / B7.3 回归：一致性指标日历月影子口径
# --------------------------------------------------------------------------


def test_compute_monthly_returns_trading20_default_is_unchanged() -> None:
    """P1-05: 主口径 trading20 行为与原 _calculate_consistency 一致，确保不动主链路。"""

    from bond_fund_screening.core.risk_calculator import compute_monthly_returns_from_daily

    # 60 日，trading_days_per_month=20 → 3 个月桶
    dates = pd.date_range("2026-01-01", periods=60, freq="B")
    daily = pd.Series([0.001] * 60, index=dates)
    months_trading = compute_monthly_returns_from_daily(daily, trading_days_per_month=20)
    assert len(months_trading) == 3
    # 每桶 (1+0.001)^20 - 1 ≈ 0.020190
    assert months_trading[0] == pytest.approx((1 + 0.001) ** 20 - 1, rel=1e-9)


def test_compute_monthly_returns_calendar_mode_groups_by_natural_month() -> None:
    """calendar 模式按自然月末对齐，跨月边界处行为与 trading20 不同。"""

    from bond_fund_screening.core.risk_calculator import (
        compute_monthly_returns_from_daily,
        compute_monthly_returns_by_calendar,
    )

    # 构造 2 个自然月，避免 pd.date_range 滑到第 3 个月
    dates = pd.date_range("2026-02-01", "2026-03-31", freq="B")
    daily = pd.Series([0.001] * len(dates), index=dates)

    calendar_months = compute_monthly_returns_from_daily(daily, mode="calendar")
    calendar_helper = compute_monthly_returns_by_calendar(daily)
    assert calendar_months == calendar_helper, "mode='calendar' 应委托到日历月 helper"

    february_count = sum(1 for d in dates if d.month == 2)
    march_count = sum(1 for d in dates if d.month == 3)
    assert len(calendar_months) == 2
    assert calendar_months[0] == pytest.approx((1 + 0.001) ** february_count - 1, rel=1e-9)
    assert calendar_months[1] == pytest.approx((1 + 0.001) ** march_count - 1, rel=1e-9)


def test_compute_monthly_returns_calendar_mode_handles_no_datetime_index() -> None:
    """没有 DatetimeIndex 时 calendar 模式应返回空列表，保持降级安全。"""

    from bond_fund_screening.core.risk_calculator import compute_monthly_returns_by_calendar

    # 纯整数 index，不能 to_datetime
    series = pd.Series([0.001, 0.002, 0.003], index=["a", "b", "c"])
    assert compute_monthly_returns_by_calendar(series) == []


