def test_parse_holding_detail_struct_extracts_days_from_cycle_preserve_buytime() -> None:
    """L1: CYCLE / PRSVPERIOD / BUYTIME 字段支持多种上游字符串格式。"""

    from utils.holding_period_parser import parse_holding_detail_struct

    # BUYTIME=180 → 180 天
    m = parse_holding_detail_struct(buy_time="180")
    assert m is not None and m.days == 180 and m.source == "detail_struct"

    # CYCLE=6M → 180 天
    m = parse_holding_detail_struct(cycle="6M")
    assert m is not None and m.days == 180

    # PRSVPERIOD=1年 → 365 天
    m = parse_holding_detail_struct(preserve_period="1年")
    assert m is not None and m.days == 365

    # "180天" → 180
    m = parse_holding_detail_struct(cycle="180天")
    assert m is not None and m.days == 180

    # 多字段同时给：长持有期优先
    m = parse_holding_detail_struct(cycle="6M", preserve_period="1Y", buy_time="90")
    assert m is not None and m.days == 365  # 1Y > 6M > 90

    # 全是 "--" / "0" → None
    assert parse_holding_detail_struct(cycle="--", preserve_period="0", buy_time="") is None


def test_parse_holding_with_priority_prefers_detail_struct_over_name() -> None:
    """L1 命中时直接返回，不走 L2 name/L3 strategy_text。"""

    from utils.holding_period_parser import parse_holding_with_priority

    match, layer = parse_holding_with_priority(
        shortname="某债券基金A",
        cycle="6M",
    )
    assert layer == "detail_struct"
    assert match is not None and match.days == 180
    # keyword 体现来源字段
    assert "CYCLE" in str(match.keyword)


def test_parse_holding_with_priority_falls_back_to_name() -> None:
    """L1 无效时走 L2 name，source_layer='name'。"""

    from utils.holding_period_parser import parse_holding_with_priority

    match, layer = parse_holding_with_priority(
        shortname="某债券基金30天持有A",
        cycle="--",
        preserve_period="0",
        buy_time="",
    )
