def test_parse_holding_with_priority_picks_longest_when_both_layers_hit() -> None:
    """V6: L1 和 L2 都命中但天数不同，应取最长（保守策略，防止短 L1 压住长 L2）。"""

    from utils.holding_period_parser import parse_holding_with_priority

    # L1=3M→90, L2 name=180天→180；取 180
    match, layer = parse_holding_with_priority(
        shortname="某债券180天持有A",
        cycle="3M",
    )
    assert match is not None
    assert match.days == 180
    assert layer == "name"

    # L1=1Y→365, L2 name=30天→30；取 365
    match, layer = parse_holding_with_priority(
        shortname="某债券30天持有A",
        cycle="1Y",
    )
    assert match is not None
    assert match.days == 365
    assert layer == "detail_struct"

    # L1=6M→180, L2 name=180天→180；一致，取 L1（优先级归属）
    match, layer = parse_holding_with_priority(
        shortname="某债券180天持有A",
        cycle="6M",
    )
    assert match is not None
    assert match.days == 180
    assert layer == "detail_struct"


