def test_holding_period_collector_non_force_skips_non_actionable_struct_refresh_candidates() -> None:
    """已有来源且结构化字段不会提升结果时，不应继续进入盘中补强扫描。"""

    import sys as _sys
    _sys.path.insert(0, str(PROJECT_ROOT / "core"))
    from collectors.supplement_holding_period import HoldingPeriodCollector
    from database.connection import DatabaseManager

    db_path = PROJECT_ROOT / "backend" / "data" / "test_holding_period_struct_refresh_filter.db"
    if db_path.exists():
        db_path.unlink()

    conn = sqlite3.connect(str(db_path))
    try:
        conn.execute(
            """
            CREATE TABLE funds (
                fcode TEXT PRIMARY KEY,
                shortname TEXT,
                fullname TEXT,
                ftype TEXT,
                investment_target TEXT,
                investment_strategy TEXT,
                has_holding_period INTEGER,
                holding_days INTEGER,
                holding_keywords TEXT,
                cycle TEXT,
                preserve_period TEXT,
                buy_time TEXT,
                holding_period_source TEXT,
                company_id TEXT
            )
            """
        )
        conn.executemany(
            """
            INSERT INTO funds (
                fcode, shortname, fullname, ftype, investment_target, investment_strategy,
                has_holding_period, holding_days, holding_keywords, cycle, preserve_period,
                buy_time, holding_period_source, company_id
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            [
                # actionable：结构化 6M=180，与当前 name/180 一致，但应提升来源到 detail_struct
                ("000020", "某债券180天持有A", "", "债券型-中短债", "", "", 1, 180, "180天持有", "6M", "", "", "name", "80000001"),
                # 非 actionable：结构化 30 天，小于当前 name/180
                ("000021", "某债券180天持有C", "", "债券型-中短债", "", "", 1, 180, "180天持有", "", "", "30", "name", "80000001"),
                # actionable：结构化 1Y=365，大于当前 name/180
                ("000022", "某债券180天持有E", "", "债券型-中短债", "", "", 1, 180, "180天持有", "1Y", "", "", "name", "80000001"),
                # actionable：无持有期但结构化可直接给值
                ("000023", "普通债券基金A", "", "债券型-长债", "", "", 0, None, None, "", "2年", "", "no_signal_reviewed", "80000001"),
                # 非 actionable：已经是 detail_struct，且结构化值未变化
                ("000024", "某债券365天持有A", "", "债券型-长债", "", "", 1, 365, "struct:PRSVPERIOD=1年", "", "1年", "", "detail_struct", "80000001"),
            ],
        )
        conn.commit()
    finally:
        conn.close()

    collector = HoldingPeriodCollector(
        config={"database": {"path": str(db_path)}},
        db_manager=DatabaseManager(db_path=str(db_path)),
    )
    try:
        funds = collector._get_funds_to_update(force_update=False)
    finally:
        collector.db_manager.close()
        if db_path.exists():
            db_path.unlink()

    codes = sorted(str(item.get("fcode") or "") for item in funds)
    assert codes == ["000020", "000022", "000023"]


def test_compute_dynamic_style_thresholds_uses_robust_clip_source_by_default() -> None:
    from backend.project_quality_thresholds import compute_dynamic_style_thresholds

    df = pd.DataFrame(
        [
            {
                "债基风格标签": "综合纯债",
                "综合加权得分": 80.0,
                "近期得分": 79.0,
                "长期得分": 81.0,
                "1年-年化收益(%)": 3.0,
                "1年-夏普比率": 1.2,
                "1年-索提诺比率": 1.3,
                "1年-卡玛比率": 3.5,
                "1年-正收益比率": 65.0,
                "费率合计(%)": 0.30,
                "1年-最大回撤(%)": 0.010,
                "1年-波动率": 0.020,
            }
            for _ in range(20)
        ]
        + [
            {
                "债基风格标签": "综合纯债",
                "综合加权得分": 99.0,
                "近期得分": 99.0,
                "长期得分": 99.0,
                "1年-年化收益(%)": 20.0,
                "1年-夏普比率": 9.0,
                "1年-索提诺比率": 9.0,
                "1年-卡玛比率": 9.0,
                "1年-正收益比率": 99.0,
                "费率合计(%)": 0.01,
                "1年-最大回撤(%)": 0.001,
                "1年-波动率": 0.001,
            }
        ]
    )

    style_thresholds, global_thresholds, style_meta = compute_dynamic_style_thresholds(df)

    assert "综合纯债" in style_thresholds
    assert global_thresholds["annual_return_min"] >= 2.0
    assert style_meta["综合纯债"]["threshold_source"] == "style_quantile_robust"


