def test_share_family_key_requires_non_empty_company_id() -> None:
    """V4: company_id 缺失时 _family_key 返回空串，不跨公司错误聚合。"""

    import sys as _sys
    _sys.path.insert(0, str(PROJECT_ROOT / "core"))
    from collectors.supplement_holding_period import HoldingPeriodCollector

    collector = HoldingPeriodCollector.__new__(HoldingPeriodCollector)

    # 两只不同 fcode、company_id 都是 None、shortname 归一化后同名
    f_none_1 = {"fcode": "A", "shortname": "某债券基金A", "company_id": None}
    f_none_2 = {"fcode": "C", "shortname": "某债券基金C", "company_id": None}
    f_with = {"fcode": "B", "shortname": "某债券基金A", "company_id": "80000001"}

    assert collector._family_key(f_none_1) == ""
    assert collector._family_key(f_none_2) == ""
    assert collector._family_key(f_with) == "80000001|某债券基金"

    # 传播时空 key 直接 continue
    scanned = [
        {**f_none_1, "has_holding_period": 1, "holding_days": 180,
         "buy_time": "180", "preserve_period": "", "cycle": ""},
        {**f_none_2, "has_holding_period": 0, "holding_days": None},
    ]
    pending = [{"fcode": "A", "has_holding_period": 1, "holding_days": 180,
                "holding_keywords": "x", "holding_period_source": "detail_struct"}]
    propagated = collector._apply_share_family_propagation(scanned, pending)
    # A 提供确认但 key 为空，C 也不应被传播
    assert propagated == []


def test_fund_model_schema_has_new_holding_period_fields(tmp_path: Path) -> None:
    """P1-01.1: cold-start bootstrap 后 funds 表应包含 9 个新列。"""

    from backend.schema_bootstrap import ensure_database_schema, reset_cache_for_tests
    from backend.config import load_settings

    db_path = tmp_path / "p1_01_schema.db"
    base = load_settings()
    patched = SimpleNamespace(
        project_root=base.project_root,
        core_root=base.core_root,
        database_path=db_path,
    )

    reset_cache_for_tests()
    try:
        res = ensure_database_schema(patched, force=True)
    finally:
        reset_cache_for_tests()

    assert res.ok is True

    conn = sqlite3.connect(str(db_path))
    try:
        cols = {row[1] for row in conn.execute("PRAGMA table_info(funds)").fetchall()}
    finally:
        conn.close()

    expected = {
        "cycle",
        "preserve_period",
        "preserve_date",
        "preserve_type",
        "buy_time",
        "feature_code",
        "base_fund_type_code",
        "rating_shanghai",
        "holding_period_source",
    }
    assert expected.issubset(cols), f"缺失新列: {expected - cols}"


