def _make_extension_row(fcode: str, status: str, score: float = 50.0) -> dict[str, Any]:
    return {
        "基金代码": fcode,
        "基金名称": f"基金{fcode}",
        "持有期状态": status,
        "扩展优先排序得分_num": score,
        "投资优先池得分_num": score,
        "正式投资评分_num": score,
    }


def test_shrink_extension_group_keeps_original_when_confirmed_meets_floor() -> None:
    """确认样本 ≥ min_confirmed(默认 3) 时不降档，返回原 df。"""

    from backend.report_builder import _shrink_extension_group_by_confirmed_floor

    rows = [
        _make_extension_row("000001", "已确认<=90天", 80.0),
        _make_extension_row("000002", "已确认<=90天", 75.0),
        _make_extension_row("000003", "已确认<=90天", 70.0),
        _make_extension_row("000004", "名称未识别持有期限制", 65.0),
        _make_extension_row("000005", "名称未识别持有期限制", 60.0),
    ]
    df = pd.DataFrame(rows)
    shrunk, info = _shrink_extension_group_by_confirmed_floor(df, group_label="纯债稳健扩展")
    assert info["downgraded"] is False
    assert info["confirmed_count"] == 3
    assert info["original_size"] == 5
    assert info["final_size"] == 5
    assert len(shrunk.index) == 5


def test_shrink_extension_group_downgrades_when_confirmed_insufficient() -> None:
    """确认=2 且未知=5 时：保留 2 确认 + 2 未知（50% 未知上限），total=4，downgraded=True。"""

    from backend.report_builder import _shrink_extension_group_by_confirmed_floor

    rows = [
        _make_extension_row("000001", "已确认<=90天", 80.0),
        _make_extension_row("000002", "已确认<=90天", 75.0),
        _make_extension_row("000003", "名称未识别持有期限制", 70.0),
        _make_extension_row("000004", "名称未识别持有期限制", 65.0),
        _make_extension_row("000005", "名称未识别持有期限制", 60.0),
        _make_extension_row("000006", "名称未识别持有期限制", 55.0),
        _make_extension_row("000007", "名称未识别持有期限制", 50.0),
    ]
    df = pd.DataFrame(rows)
    shrunk, info = _shrink_extension_group_by_confirmed_floor(df, group_label="增强债弹性扩展")
    assert info["downgraded"] is True
    assert info["reason"] == "insufficient_confirmed_holding_sample"
    assert info["confirmed_count"] == 2
    assert info["original_size"] == 7
    assert info["final_size"] == 4
    assert info["unknown_slots_allowed"] == 2

    # 保留的 4 只：000001 / 000002 两个确认 + 得分最高的两个未知 000003 / 000004
    kept_codes = set(shrunk["基金代码"].tolist())
    assert kept_codes == {"000001", "000002", "000003", "000004"}
    # 确认样本计数
    kept_confirmed = int(shrunk["持有期状态"].astype(str).eq("已确认<=90天").sum())
    assert kept_confirmed == 2


def test_shrink_extension_group_empties_when_no_confirmed_sample() -> None:
    """confirmed=0 且未知样本不满足严格 fallback 时整组剔除。"""

