def test_detail_collector_falls_back_to_stop_watch_when_detail_unavailable(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    """P1-09.1: 主 _fetch_detail_payload 返回空时调 /fundMNStopWatch 兜底写关键结构字段。
    V2: 仅对 funds 当前为 NULL/占位的字段做写入，不覆盖已有值。"""

    import sys as _sys
    _sys.path.insert(0, str(PROJECT_ROOT / "core"))
    from collectors.detail_collector import FundDetailCollector
    from database.connection import get_db_manager
    from database.models import Base, Fund

    db_path = tmp_path / "detail_fallback.db"
    db_manager = get_db_manager(db_path=str(db_path))
    Base.metadata.create_all(db_manager.engine)

    # 事先插一只基金，ftype/estab_date 都为空（模拟 funds 已有记录但字段缺失）
    with db_manager.get_session() as session:
        session.add(Fund(fcode="000001", shortname="测试基金"))

    collector = FundDetailCollector.__new__(FundDetailCollector)
    collector.db_manager = db_manager

    class _FakeApi:
        def get_fund_stop_watch(self, fcode):
            return {
                "FCODE": fcode,
                "FTYPE": "债券型-中短债",
                "FEATURE": "038",
                "BFUNDTYPE": "001",
                "ESTABDATE": "2022-06-30",
            }

    collector.api = _FakeApi()
    collector._fetch_detail_payload = lambda _fc: None  # type: ignore[assignment]

    captured_updates: list[dict] = []
    orig_bulk = FundDetailCollector._bulk_update_fund_details

    def _capture_bulk(self, payloads, batch_size=1, *, record_api_source_evidence=True):
        captured_updates.extend(payloads)
        return orig_bulk(self, payloads, batch_size=batch_size, record_api_source_evidence=record_api_source_evidence)

    collector._bulk_update_fund_details = _capture_bulk.__get__(collector, FundDetailCollector)  # type: ignore[method-assign]

    ok = collector.collect_fund_detail("000001", force_update=False)
    assert ok is False
    assert len(captured_updates) == 1
    payload = captured_updates[0]
    assert payload["fcode"] == "000001"
    assert payload.get("ftype") == "债券型-中短债"
    assert payload.get("feature_code") == "038"
    assert payload.get("base_fund_type_code") == "001"
    assert "estab_date" in payload
    # stop_watch 不含 CYCLE/INVSTRA/INVTGT — 不得被写入
    assert "cycle" not in payload
    assert "investment_target" not in payload

    # V2: 第二次调用（funds 字段已填），应该不再覆盖
    captured_updates.clear()
    ok_again = collector.collect_fund_detail("000001", force_update=False)
    assert ok_again is False
    assert captured_updates == []


def test_detail_collector_batch_path_also_uses_stop_watch_fallback(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    """V7: collect_all_details → _collect_detail_update_payload 批量路径在
    Detail 失败时也应走 StopWatch 兜底（V2 保守覆盖），与单只 collect_fund_detail 对齐。"""

    import sys as _sys
    _sys.path.insert(0, str(PROJECT_ROOT / "core"))
    from collectors.detail_collector import FundDetailCollector
    from database.connection import get_db_manager
    from database.models import Base, Fund

    db_path = tmp_path / "detail_batch.db"
    db_manager = get_db_manager(db_path=str(db_path))
    Base.metadata.create_all(db_manager.engine)
    with db_manager.get_session() as session:
        session.add(Fund(fcode="000001", shortname="批量测试基金"))

    collector = FundDetailCollector.__new__(FundDetailCollector)
    collector.db_manager = db_manager

    stop_watch_called = {"count": 0}

    class _FakeApi:
        def get_fund_stop_watch(self, fcode):
            stop_watch_called["count"] += 1
            return {
                "FCODE": fcode,
                "FTYPE": "债券型-长债",
                "FEATURE": "038",
                "BFUNDTYPE": "001",
                "ESTABDATE": "2023-01-01",
            }

    collector.api = _FakeApi()
    collector._fetch_detail_payload = lambda _fc: None  # type: ignore[assignment]

    # 批量路径主入口
    result = collector._collect_detail_update_payload("000001")
    assert result is None  # 批量队列不收 StopWatch 结果，避免覆盖
    assert stop_watch_called["count"] == 1  # 批量路径确实触发了 StopWatch

    # DB 侧应当被 StopWatch 的保守写入补齐
    with db_manager.get_session() as session:
        fund = session.query(Fund).filter_by(fcode="000001").first()
        assert fund.ftype == "债券型-长债"
        assert fund.feature_code == "038"
        assert fund.base_fund_type_code == "001"
        assert fund.estab_date is not None

    # runtime_excluded 基金不进入 StopWatch
    from collectors import detail_collector as dc_module
    monkeypatch.setattr(dc_module, "is_runtime_excluded_fund", lambda _c: True)
    stop_watch_called["count"] = 0
    assert collector._collect_detail_update_payload("099999") is None
    assert stop_watch_called["count"] == 0


