def test_detail_collector_stop_watch_fallback_skips_empty_and_runtime_excluded(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """V1: 空 fcode 或 runtime_excluded 基金不应触发 StopWatch 兜底。"""

    import sys as _sys
    _sys.path.insert(0, str(PROJECT_ROOT / "core"))
    from collectors import detail_collector as dc_module
    from collectors.detail_collector import FundDetailCollector

    collector = FundDetailCollector.__new__(FundDetailCollector)

    stop_watch_called = {"count": 0}

    class _FakeApi:
        def get_fund_stop_watch(self, fcode):
            stop_watch_called["count"] += 1
            return {"FCODE": fcode, "FTYPE": "债券型"}

    collector.api = _FakeApi()
    collector._fetch_detail_payload = lambda _fc: None  # type: ignore[assignment]
    collector._bulk_update_fund_details = lambda p, **_kw: (len(p), [])  # type: ignore[assignment]

    class _FakeDbManager:
        def get_session(self, **_kw):
            raise AssertionError("应在 runtime_excluded/空 fcode 分支前就 return")

    collector.db_manager = _FakeDbManager()

    # 场景 1: 空 fcode
    assert collector.collect_fund_detail("", force_update=False) is False
    assert stop_watch_called["count"] == 0

    # 场景 2: 空白 fcode
    assert collector.collect_fund_detail("   ", force_update=False) is False
    assert stop_watch_called["count"] == 0

    # 场景 3: runtime_excluded 基金
    monkeypatch.setattr(dc_module, "is_runtime_excluded_fund", lambda _c: True)
    assert collector.collect_fund_detail("099999", force_update=False) is False
    assert stop_watch_called["count"] == 0


def test_fund_model_has_external_curation_and_rating_multi_source(tmp_path: Path) -> None:
    """P1-09.2 / P1-09.3: 冷启动后 funds 表应含 external_curation_flag + rating_multi_source。"""

    from backend.schema_bootstrap import ensure_database_schema, reset_cache_for_tests
    from backend.config import load_settings

    db_path = tmp_path / "p1_09_schema.db"
    base = load_settings()
    patched = SimpleNamespace(
        project_root=base.project_root,
        core_root=base.core_root,
        database_path=db_path,
    )

    reset_cache_for_tests()
    try:
        res = ensure_database_schema(patched, force=True)
    finally:
        reset_cache_for_tests()
    assert res.ok is True

    conn = sqlite3.connect(str(db_path))
    try:
        funds_cols = {row[1] for row in conn.execute("PRAGMA table_info(funds)").fetchall()}
        tables = {row[0] for row in conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table'"
        ).fetchall()}
    finally:
        conn.close()

    assert "external_curation_flag" in funds_cols
    assert "rating_multi_source" in funds_cols
    assert "fund_grades" in tables


def test_fetch_tiantian_curated_codes_paginates_until_empty_or_duplicates() -> None:
    """V3: _fetch_tiantian_curated_codes 在空响应 / 重复数据 / upstream_total 达阈值 /
    上游报错 / max_pages 保底 各场景下正确 break 不死循环。"""

    from backend.bond_universe_sync import _fetch_tiantian_curated_codes

    # 场景 1: 三页后第 4 页返回空 → 应停止
    class _StubEndpointsA:
        def __init__(self):
            self.calls = []

        def get_bond_fund_rank(self, fund_type, sort_column, page_index, page_size, only_buyable, **kwargs):
            self.calls.append(page_index)
            if page_index <= 3:
                return {
                    "TotalCount": 90,
                    "Datas": [{"FCODE": f"{page_index:02d}{idx:04d}"} for idx in range(30)],
                }
            return {"TotalCount": 90, "Datas": []}

    endpoints = _StubEndpointsA()
    codes, meta = _fetch_tiantian_curated_codes(endpoints, cltype="038", log=None, page_size=30, max_pages=10)
    assert len(codes) == 90
    # 第 3 页完成后 len(codes) >= upstream_total → break，不需要探第 4 页
    assert meta["pages_fetched"] == 3
    assert meta["upstream_total_count"] == 90

    # 场景 2: 首页就已达 upstream total → 一页即停
    class _StubEndpointsB:
        def __init__(self):
            self.calls = []

        def get_bond_fund_rank(self, fund_type, sort_column, page_index, page_size, only_buyable, **kwargs):
            self.calls.append(page_index)
            return {
                "TotalCount": 10,
                "Datas": [{"FCODE": f"{idx:06d}"} for idx in range(10)],
            }

    endpoints = _StubEndpointsB()
    codes, meta = _fetch_tiantian_curated_codes(endpoints, cltype="038", log=None, page_size=30, max_pages=10)
    assert len(codes) == 10
    # 首页 10 >= total 10，break after page 1
    assert meta["pages_fetched"] == 1

    # 场景 3: 上游抛异常 → break 并在 errors 中记录
    class _StubEndpointsC:
        def get_bond_fund_rank(self, fund_type, sort_column, page_index, page_size, only_buyable, **kwargs):
            if page_index >= 2:
                raise RuntimeError("upstream timeout")
            return {"TotalCount": 60, "Datas": [{"FCODE": f"{idx:06d}"} for idx in range(30)]}

    endpoints = _StubEndpointsC()
    codes, meta = _fetch_tiantian_curated_codes(endpoints, cltype="038", log=None, page_size=30, max_pages=10)
    assert len(codes) == 30  # 第 1 页成功，第 2 页报错
    assert meta["pages_fetched"] == 1
    assert len(meta["errors"]) == 1

    assert "upstream timeout" in meta["errors"][0]

    # 场景 4: 无新增数据 (added=0) 也 break
    class _StubEndpointsD:
        def __init__(self):
            self.call_count = 0

        def get_bond_fund_rank(self, fund_type, sort_column, page_index, page_size, only_buyable, **kwargs):
            self.call_count += 1
            # 每次都返回同样 5 只基金 → 第 2 次 added=0 触发 break
            return {
                "TotalCount": 999,
                "Datas": [{"FCODE": f"{idx:06d}"} for idx in range(5)],
            }

    endpoints = _StubEndpointsD()
    codes, meta = _fetch_tiantian_curated_codes(endpoints, cltype="038", log=None, page_size=30, max_pages=10)
    assert len(codes) == 5
    assert endpoints.call_count == 2  # 第 1 页有效，第 2 页全重复触发 break

    # 场景 5: max_pages 保底
    class _StubEndpointsE:
        def __init__(self):
            self.calls = 0

        def get_bond_fund_rank(self, fund_type, sort_column, page_index, page_size, only_buyable, **kwargs):
            self.calls += 1
            return {
                "TotalCount": 999999,
                "Datas": [{"FCODE": f"{page_index:04d}{idx:02d}"} for idx in range(5)],
            }

    endpoints = _StubEndpointsE()
    codes, meta = _fetch_tiantian_curated_codes(endpoints, cltype="038", log=None, page_size=5, max_pages=3)
    assert meta["pages_fetched"] == 3  # 达 max_pages 即停


def _seed_nav_archive_preview_rows(db_manager) -> None:
    with db_manager.get_session(task_name="seed_nav_archive_preview_rows") as session:
        for code in ("010001", "010002"):
            for nav_date in pd.date_range("2018-01-01", "2026-01-01", freq="180D"):
                session.add(
                    FundNavHistory(
                        fcode=code,
                        nav_date=nav_date.date(),
                        unit_nav=1.0,
                        accum_nav=1.0,
                        daily_growth=0.01,
                    )
                )


def test_nav_history_archive_analysis_builds_readonly_retention_preview(tmp_path: Path) -> None:
    db_path = tmp_path / "nav_archive_analysis.db"
    init_database(str(db_path))
