def test_nav_history_archive_preflight_matches_current_runbook_scope(tmp_path: Path) -> None:
    from utils.nav_history_archive_preflight import build_nav_history_archive_preflight_payload
    from utils.nav_history_archive_runbook import build_nav_history_archive_runbook_payload

    db_path = tmp_path / "nav_archive_preflight.db"
    init_database(str(db_path))
    db_manager = get_db_manager(str(db_path))
    _seed_nav_archive_preview_rows(db_manager)

    hotspots = build_primary_database_hotspots(db_manager)
    aggregate_profile = build_nav_history_storage_profile(db_manager)
    retention = build_nav_history_retention_preview(
        db_manager,
        database_hotspots=hotspots,
    )
    strategy = build_nav_history_archive_strategy_preview(aggregate_profile, retention)
    runbook = build_nav_history_archive_runbook_payload(
        nav_history_storage_profile=aggregate_profile,
        nav_history_retention_preview=retention,
        nav_history_archive_strategy_preview=strategy,
    )

    preflight = build_nav_history_archive_preflight_payload(
        db_manager=db_manager,
        runbook_payload=runbook,
        source_runbook_artifact="unit-test-runbook.json",
    )

    assert preflight["checks"]["ready_for_manual_signoff"] is True
    assert preflight["summary"]["live_cold_row_count"] == runbook["summary"]["estimated_archive_row_count"]
    assert preflight["summary"]["live_cold_fund_count"] == runbook["summary"]["estimated_archive_fund_count"]


