def test_screening_history_cleanup_backup_sidecar_cleanup_removes_empty_wal_shm(
    tmp_path: Path,
) -> None:
    from utils import screening_history_cleanup_backup as backup_module

    backup_path = tmp_path / "bond_funds_pre_screening_cleanup_test.db"
    conn = sqlite3.connect(str(backup_path))
    try:
        conn.execute("CREATE TABLE sample (id INTEGER PRIMARY KEY)")
        conn.commit()
    finally:
        conn.close()

    wal_path = tmp_path / "bond_funds_pre_screening_cleanup_test.db-wal"
    shm_path = tmp_path / "bond_funds_pre_screening_cleanup_test.db-shm"
    wal_path.write_bytes(b"")
    shm_path.write_bytes(b"\0" * 32768)

    payload = backup_module._cleanup_backup_sidecars_for_artifact(backup_path)

    assert payload["removed_sidecar_count"] == 2
    assert {item["kind"] for item in payload["removed_sidecars"]} == {"wal", "shm"}
    assert payload["sidecars_before"]["wal"]["exists"] is True
    assert payload["sidecars_before"]["shm"]["size_bytes"] == 32768
    assert payload["sidecars_after_cleanup"]["wal"]["exists"] is False
    assert payload["sidecars_after_cleanup"]["shm"]["exists"] is False
    assert not wal_path.exists()
    assert not shm_path.exists()


