    _freeze_datetime_in(
        monkeypatch,
        "utils.nav_history_archive_cold_query_compat_audit",
        frozen=datetime(2026, 6, 3, 12, 0, 0),
    )
    db_path = tmp_path / "backend/data/bond_funds.db"
    output_dir = tmp_path / "reports/audit/nav_history_archive"
    db_path.parent.mkdir(parents=True)
    output_dir.mkdir(parents=True)
    conn = sqlite3.connect(str(db_path))
    try:
        conn.execute(
            """
            CREATE TABLE fund_nav_history (
                fcode TEXT NOT NULL,
                nav_date TEXT NOT NULL,
                unit_nav REAL NOT NULL,
                accum_nav REAL,
                daily_growth REAL
            )
            """
        )
        conn.executemany(
            """
            INSERT INTO fund_nav_history (fcode, nav_date, unit_nav, accum_nav, daily_growth)
            VALUES (?, ?, ?, ?, ?)
            """,
            [
                ("010001", "2021-07-01", 1.0, 1.0, 0.01),
                ("010001", "2023-01-01", 1.02, 1.02, 0.01),
                ("010001", "2026-06-02", 1.08, 1.08, 0.01),
                ("010002", "2021-09-01", 1.0, 1.0, 0.01),
                ("010002", "2026-06-02", 1.05, 1.05, 0.01),
            ],
        )
        conn.commit()
    finally:
        conn.close()

    readiness_payload = {
        "summary": {
            "archive_cutoff_date": "2022-01-01",
            "readiness_status": "ready_for_manual_window_execution",
            "ready_for_manual_window_execution": True,
        }
    }
    payload = build_nav_history_archive_cold_query_compat_audit_payload(
        db_path=db_path,
        readiness_payload=readiness_payload,
        output_dir=output_dir,
        project_root=tmp_path,
    )
