def test_nav_history_archive_union_filters_cold_rows_by_active_cutoff(
    tmp_path: Path,
) -> None:
    from database.nav_history_queries import (
        attach_nav_history_archive_if_available,
        build_nav_history_union_source_sql,
        detach_nav_history_archive,
    )

    main_db = tmp_path / "backend/data/bond_funds.db"
    archive_db = tmp_path / "backend/data/archives/fund_nav_history_before_2021-01-01.db"
    main_db.parent.mkdir(parents=True)
    archive_db.parent.mkdir(parents=True)

    conn = sqlite3.connect(str(main_db))
    archive_conn = sqlite3.connect(str(archive_db))
    try:
        conn.execute(
            """
            CREATE TABLE fund_nav_history (
                fcode TEXT NOT NULL,
                nav_date TEXT NOT NULL,
                unit_nav REAL NOT NULL,
                accum_nav REAL,
                daily_growth REAL
            )
            """
        )
        conn.execute(
            "INSERT INTO fund_nav_history VALUES (?, ?, ?, ?, ?)",
            ("010003", "2026-06-02", 1.30, 1.30, 0.01),
        )
        conn.commit()
        archive_conn.execute(
            """
            CREATE TABLE fund_nav_history_archive (
                fcode TEXT NOT NULL,
                nav_date TEXT NOT NULL,
                unit_nav REAL NOT NULL,
                accum_nav REAL,
                daily_growth REAL
            )
            """
        )
        archive_conn.executemany(
            "INSERT INTO fund_nav_history_archive VALUES (?, ?, ?, ?, ?)",
            [
                ("010001", "2020-12-31", 1.00, 1.00, 0.01),
                ("010002", "2021-01-01", 1.10, 1.10, 0.01),
            ],
        )
        archive_conn.commit()

        archive_attach = attach_nav_history_archive_if_available(
            conn,
            archive_path=archive_db,
            archive_table_name="fund_nav_history_archive",
            archive_cutoff_date="2021-01-01",
        )
        nav_source_sql = build_nav_history_union_source_sql(archive_attach)
        rows = conn.execute(
            f"""
            WITH nav_source AS (
                {nav_source_sql}
            )
            SELECT fcode, nav_date
            FROM nav_source
            ORDER BY fcode
            """
        ).fetchall()
    finally:
        if "archive_attach" in locals() and archive_attach.get("attached"):
            detach_nav_history_archive(conn, alias=str(archive_attach.get("alias") or "nav_archive_db"))
        archive_conn.close()
        conn.close()

    assert rows == [("010001", "2020-12-31"), ("010003", "2026-06-02")]


