def test_apply_external_curation_flags_adds_clears_and_merges(tmp_path: Path) -> None:
    """P1-09.2: _apply_external_curation_flags 的三路径：新增 / 合并 / 清除。"""

    from backend.bond_universe_sync import _apply_external_curation_flags

    db_path = tmp_path / "curation.db"
    conn = sqlite3.connect(str(db_path))
    try:
        conn.execute(
            """
            CREATE TABLE funds (
                fcode TEXT PRIMARY KEY,
                external_curation_flag TEXT,
                last_updated_at TEXT
            )
            """
        )
        conn.executemany(
            "INSERT INTO funds (fcode, external_curation_flag) VALUES (?, ?)",
            [
                ("000001", None),                     # 应新增
                ("000002", "tiantian_038"),           # 已有该 flag，保持
                ("000003", "tiantian_022"),           # 合并 → "tiantian_022+tiantian_038"
                ("000004", "tiantian_038"),           # 不在 curation → 清除
                ("000005", "tiantian_038+tiantian_022"),  # 不在 curation → 仅剥离 038
            ],
        )
        conn.commit()
    finally:
        conn.close()

    curation = {"000001", "000002", "000003"}
    summary = _apply_external_curation_flags(
        db_path, curation_codes=curation, flag="tiantian_038"
    )

    assert summary["updated_total"] == 2  # 000001 新增 + 000003 合并
    assert summary["cleared_total"] == 2  # 000004 清空 + 000005 剥离

    conn = sqlite3.connect(str(db_path))
    try:
        results = dict(conn.execute(
            "SELECT fcode, external_curation_flag FROM funds"
        ).fetchall())
    finally:
        conn.close()

    assert results["000001"] == "tiantian_038"
    assert results["000002"] == "tiantian_038"
    assert results["000003"] in ("tiantian_022+tiantian_038",)
    assert results["000004"] in (None, "")
    assert results["000005"] == "tiantian_022"


def test_aggregate_rating_multi_source_builds_readable_string() -> None:
    """P1-09.3: 三/四机构评级聚合字符串格式。"""

    import sys as _sys
    _sys.path.insert(0, str(PROJECT_ROOT / "core"))
    from collectors.supplement_fund_grade import _aggregate_rating_multi_source

    assert _aggregate_rating_multi_source("5", "4", None, None) == "ZS:5|SH:4|JA:-|HT:-"
    assert _aggregate_rating_multi_source(None, None, None, None) is None
    assert _aggregate_rating_multi_source("5", "4", "3", "2") == "ZS:5|SH:4|JA:3|HT:2"
    assert _aggregate_rating_multi_source("", "", "4", "") == "ZS:-|SH:-|JA:4|HT:-"


def test_fund_grade_collector_persist_grades_upserts_and_updates_funds(tmp_path: Path) -> None:
    """V5: _persist_grades 用 SQLite ON CONFLICT 真实做 UPSERT，
    并把最近一期聚合到 funds.rating_multi_source。"""

    import sys as _sys
    _sys.path.insert(0, str(PROJECT_ROOT / "core"))
    from datetime import date
    from collectors.supplement_fund_grade import FundGradeCollector
    from database.connection import get_db_manager
    from database.models import Base, Fund, FundGrade

    db_path = tmp_path / "fund_grades.db"
    db_manager = get_db_manager(db_path=str(db_path))
    Base.metadata.create_all(db_manager.engine)

    with db_manager.get_session() as session:
        session.add(Fund(fcode="000001", shortname="测试基金 A"))
        session.add(Fund(fcode="000002", shortname="测试基金 B"))

    collector = FundGradeCollector.__new__(FundGradeCollector)
    collector.db_manager = db_manager

    # 首次写入
    records_v1 = [
        {"fcode": "000001", "rdate": date(2026, 3, 31), "zspj_zs": "5", "szpj3": "4", "japj": None, "htpj": None},
        {"fcode": "000002", "rdate": date(2026, 3, 31), "zspj_zs": "3", "szpj3": None, "japj": "4", "htpj": None},
    ]
    updated = collector._persist_grades(records_v1)
    assert updated == 2

    with db_manager.get_session() as session:
        rows = session.query(FundGrade).order_by(FundGrade.fcode).all()
        assert len(rows) == 2
        assert rows[0].fcode == "000001"
        assert rows[0].zspj_zs == "5"
        funds = {f.fcode: f for f in session.query(Fund).all()}
        assert funds["000001"].rating_multi_source == "ZS:5|SH:4|JA:-|HT:-"
        assert funds["000002"].rating_multi_source == "ZS:3|SH:-|JA:4|HT:-"

    # 同 (fcode, rdate) 重写 → UPDATE 不插重复
    records_v2 = [
        {"fcode": "000001", "rdate": date(2026, 3, 31), "zspj_zs": "5", "szpj3": "5", "japj": "5", "htpj": "4"},
    ]
    updated = collector._persist_grades(records_v2)
    assert updated == 1

    with db_manager.get_session() as session:
        rows = session.query(FundGrade).filter_by(fcode="000001").all()
        assert len(rows) == 1  # 不应该变成 2 条（UPSERT 正确）
        assert rows[0].szpj3 == "5"
        assert rows[0].japj == "5"
        assert rows[0].htpj == "4"
        fund = session.query(Fund).filter_by(fcode="000001").first()
        assert fund.rating_multi_source == "ZS:5|SH:5|JA:5|HT:4"


def test_audit_external_curation_overlap_script_runs(tmp_path: Path) -> None:
    """P1-09.4 冷启动 smoke：新 DB 无数据时脚本能正确产出 0 交集审计 JSON。"""

    import subprocess

    env = os.environ.copy()
    env.setdefault("PYTHONPATH", f"{PROJECT_ROOT}:{PROJECT_ROOT / 'core'}")

    out_path = tmp_path / "audit.json"
    result = subprocess.run(
        [
            sys.executable,
            str(PROJECT_ROOT / "scripts" / "audit_external_curation_overlap.py"),
            "--output",
            str(out_path),
        ],
        cwd=str(PROJECT_ROOT),
        capture_output=True,
        text=True,
        env=env,
        timeout=60,
    )
    assert result.returncode == 0, f"audit 脚本失败: {result.stderr}"
    assert out_path.exists()
    payload = json.loads(out_path.read_text(encoding="utf-8"))
    assert "summaries" in payload
    labels = {item["label"] for item in payload["summaries"]}
    assert labels == {"curated_038_vs_final", "high_star_vs_final", "curated_038_vs_high_star"}
    assert payload["production_strategy_eligible"] is False
    assert "不得直接驱动生产筛选阈值" in payload["strategy_use_warning"]


