def test_classify_duration_proxy_maps_benchmark_keywords() -> None:
    from backend.bond_duration_proxy import classify_duration_proxy

    # 中短融 → short
    proxy = classify_duration_proxy(benchmark="中债-中短融 0-3 年指数", style_tag="中短债")
    assert proxy.bucket == "short"
    assert proxy.proxy_years == pytest.approx(1.5)

    # 中短债 / 1-3 年 → short_mid
    proxy = classify_duration_proxy(benchmark="中债 1-3年政策性金融债", style_tag="中短债")
    assert proxy.bucket == "short_mid"
    assert proxy.proxy_years == pytest.approx(2.2)

    # 中债综合 → mid
    proxy = classify_duration_proxy(benchmark="中债综合财富指数", style_tag="综合纯债")
    assert proxy.bucket == "mid"

    # 5-10 年长债 → long
    proxy = classify_duration_proxy(benchmark="中债 5-10年国债", style_tag="利率债")
    assert proxy.bucket == "long"
    assert proxy.proxy_years == pytest.approx(7.0)

    # 可转债 benchmark → convertible
    proxy = classify_duration_proxy(benchmark="中信标普可转债指数", style_tag="转债增强")
    assert proxy.bucket == "convertible"

    # 转债 style 但 benchmark 未含关键词：优先 style
    proxy = classify_duration_proxy(benchmark="", style_tag="转债增强")
    assert proxy.bucket == "convertible"

    # style fallback：中短债无 benchmark
    proxy = classify_duration_proxy(benchmark="", style_tag="中短债")
    assert proxy.bucket == "short_mid"
    assert proxy.proxy_years == pytest.approx(2.2)


