# --------------------------------------------------------------------------
# P0-04.1 / B12 回归：/fundMNHisNetList 参数大小写
# --------------------------------------------------------------------------


def test_get_nav_history_uses_lowercase_pagesize_param() -> None:
    """按天天基金官方文档 /fundMNHisNetList 要求，pagesize 必须是全小写。
    项目此前误用驼峰 pageSize，自建代理宽容但一旦上游收紧会静默截断历史。
    """

    from api.endpoints import FundAPIEndpoints  # type: ignore

    captured_params: dict[str, object] = {}

    class _StubClient:
        def get(self, endpoint, params=None):
            captured_params["endpoint"] = endpoint
            captured_params["params"] = dict(params or {})
            return {"Datas": []}

    endpoints = FundAPIEndpoints(_StubClient())
    endpoints.get_nav_history("000001", page_index=2, page_size=1000)

    params = captured_params.get("params") or {}
    assert "pagesize" in params, f"应传全小写 pagesize，实际传参: {params}"
    assert "pageSize" not in params, f"不应再传驼峰 pageSize，实际传参: {params}"
    assert params.get("pageIndex") == 2
    assert params.get("pagesize") == 1000
    assert params.get("FCODE") == "000001"


# --------------------------------------------------------------------------
# P0-04.3 / B15 回归：AutoStockClient.get_fund_detail 弃用单码路径
# --------------------------------------------------------------------------


def test_autostock_get_fund_detail_single_is_deprecated_and_delegates_to_batch() -> None:
    """get_fund_detail(single) 必须触发 DeprecationWarning，并把请求委托到批量接口。"""

    import warnings

    from api.autostock_client import AutoStockClient  # type: ignore

    client = AutoStockClient.__new__(AutoStockClient)  # 绕过 __init__ 的网络依赖

    captured: dict[str, object] = {}

    def _stub_batch(codes, start_date=None, end_date=None, batch_size=400):
        captured["codes"] = list(codes)
        captured["start_date"] = start_date
        captured["end_date"] = end_date
        captured["batch_size"] = batch_size
        return [{"code": codes[0], "netWorth": 1.23, "name": "stub"}]

    client.get_fund_detail_batch = _stub_batch  # type: ignore[method-assign]

    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        result = client.get_fund_detail("000001", start_date="2026-01-01")

    assert any(issubclass(w.category, DeprecationWarning) for w in caught), (
        "get_fund_detail 单码调用必须触发 DeprecationWarning"
    )
    assert captured["codes"] == ["000001"]
    assert captured["start_date"] == "2026-01-01"
    assert captured["batch_size"] == 1
    assert isinstance(result, dict) and result.get("code") == "000001"


# --------------------------------------------------------------------------
# P0-04.4 / B16 回归：AutoStock 配额耗尽时报告构建降级而非异常
# --------------------------------------------------------------------------


def test_report_builder_autostock_quota_exceeded_marks_unavailable_and_returns_current(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    """当 AutoStock 批量调用抛 AutoStockQuotaExceeded 时，
    `_supplement_official_autostock_statuses` 应保持原 DataFrame 不变、
    通过 DataFrame.attrs['autostock_validation_unavailable'] 记录降级原因，
    同时向可选的 status_context dict 写入同一降级载荷（V5 双通道保护）。"""

    from api.autostock_client import AutoStockQuotaExceeded  # type: ignore
    from backend import report_builder

    df = pd.DataFrame(
        [
            {
                "基金代码": "000001",
                "基金名称": "示例纯债 A",
                "基金类型": "债券型-长债",
                "最新净值日期": "2026-04-17",
                "区间收益基准日": None,
                "区间收益来源": None,
                "区间收益来源SHA256": None,
                "最新单位净值": 1.0,
                "近1周(%)": 0.1,
                "近1月(%)": 0.4,
                "近3月(%)": 1.2,
                "近6月(%)": 2.1,
                "近1年(%)": 4.0,
                "AutoStock原始校验状态": "",
                "AutoStock告警原因": "",
            }
        ]
    )

    class _FakeClient:
        def __init__(self, *args, **kwargs):
            pass

        def get_fund_batch(self, codes, batch_size=None):
            raise AutoStockQuotaExceeded(retry_after_seconds=1234.0, max_calls_per_hour=100)

    def _fake_loader(_settings):
        return (
            _FakeClient,
            lambda *args, **kwargs: {},
            lambda *args, **kwargs: {"details": {}},
        )

    monkeypatch.setattr(report_builder, "_load_autostock_runtime_for_report", _fake_loader)
    monkeypatch.setattr(
        report_builder,
        "_load_autostock_cross_validation_config_for_report",
        lambda: {"batch_size": 10},
    )

    base_settings = SimpleNamespace(
        project_root=tmp_path,
        reports_dir=tmp_path / "reports",
        autostock_base_url="https://api.autostock.cn/v1",
        autostock_rate_limit_min_interval_seconds=2.0,
        autostock_rate_limit_max_calls_per_hour=100,
        autostock_rate_limit_shared_state_path=tmp_path / "autostock_state.json",
        autostock_batch_fund_default=50,
    )

    status_context: dict[str, object] = {}
    result = report_builder._supplement_official_autostock_statuses(
        df, settings=base_settings, status_context=status_context
    )

    assert isinstance(result, pd.DataFrame)
    # 原有数据不被破坏
    assert result.loc[0, "基金代码"] == "000001"
    # 通道 1：DataFrame.attrs
    unavailable = result.attrs.get("autostock_validation_unavailable")
    assert isinstance(unavailable, dict)
    assert unavailable.get("reason") == "autostock_quota_exceeded"
    assert unavailable.get("retry_after_seconds") == pytest.approx(1234.0)
    assert unavailable.get("max_calls_per_hour") == 100
    # 通道 2：status_context dict，供 build_report_payload 直接采集
    ctx_unavailable = status_context.get("autostock_validation_unavailable")
    assert isinstance(ctx_unavailable, dict)
    assert ctx_unavailable == unavailable
    source_entries = status_context.get("autostock_validation_source_evidence")
    assert isinstance(source_entries, list)
    assert source_entries[0]["source_type"] == "unavailable"
    assert source_entries[0]["reason"] == "autostock_quota_exceeded"


