def test_autostock_fund_batch_meta_includes_source_evidence() -> None:
    from api.autostock_client import AutoStockClient  # type: ignore

    client = AutoStockClient.__new__(AutoStockClient)
    client.base_url = "https://api.autostock.cn/v1"
