    def _fake_request_with_meta(url, method="GET", max_retries=3, **kwargs):
        assert url.endswith("/fund?code=000001,000002")
        return (
            [
                {"code": "000001", "name": "测试债基A"},
                {"code": "000002", "name": "测试债基B"},
            ],
            {"status_code": 200, "business_code": 0, "message": "ok", "quota_error": False},
        )

