def test_data_truthfulness_audit_blocks_autostock_source_evidence_integrity_anomalies() -> None:
    import scripts.audit_data_truthfulness as audit_script

    summary, blockers, warnings = audit_script._validate_autostock_source_evidence_entry(
        {
            "schema_version": 1,
            "task": "autostock_validation",
            "source": "AutoStock /fund",
            "source_type": "api_batch",
            "endpoint_path": "/fund/all",
            "request_window": {"started_at": "", "finished_at": ""},
            "target_count": 2,
            "api_target_count": 2,
            "request_count": 2,
            "response_count": 1,
            "accepted_response_count": 1,
            "failed_response_count": 0,
            "transport_exception_count": 1,
            "returned_record_count": 1,
            "returned_unique_count": 3,
            "missing_count": 1,
            "failed_batch_count": 1,
            "failed_batches": [],
            "quota_exhausted": False,
            "response_hash": "",
            "sample_codes": [],
            "requested_total": 1,
            "requested_unique_total": 3,
            "requested_batch_size": 0,
            "effective_batch_size": 0,
            "max_workers": 0,
            "source_complete": True,
        },
        index=7,
        required=True,
    )

    assert summary["endpoint_path"] == "/fund/all"
    assert warnings == []
    assert "autostock_api_endpoint_path_invalid:7:/fund/all" in blockers
    assert "autostock_api_request_window_missing:7" in blockers
    assert any(item.startswith("autostock_api_request_terminal_count_mismatch:7") for item in blockers)
    assert any(item.startswith("autostock_api_returned_unique_exceeds_records:7") for item in blockers)
    assert any(item.startswith("autostock_api_returned_plus_missing_exceeds_target:7") for item in blockers)
    assert "autostock_api_missing_codes_preview_empty:7" in blockers
    assert "autostock_api_response_hash_missing:7" in blockers
    assert "autostock_api_sample_codes_missing:7" in blockers
    assert any(item.startswith("autostock_api_requested_unique_target_mismatch:7") for item in blockers)
    assert any(item.startswith("autostock_api_requested_total_lt_unique:7") for item in blockers)
    assert "autostock_api_requested_batch_size_invalid:7:0" in blockers
    assert "autostock_api_effective_batch_size_invalid:7:0" in blockers
    assert "autostock_api_max_workers_invalid:7:0" in blockers


