def test_core_autostock_cross_validation_demotes_tiny_residual_missing_to_hard_block() -> None:
    from bond_fund_screening.tasks import final_screening_autostock_helpers as autostock_helpers
    from bond_fund_screening.tasks import final_screening_quality_gate_helpers as quality_gate_helpers

    class _ResidualMissingClient:
        SAFE_FUND_BATCH_SIZE = 50

        def __init__(self, *args, **kwargs):
            pass

        def get_fund_batch_with_meta(self, codes, batch_size=50):
            return [
                {"code": "000001", "name": "示例 A"},
                {"code": "000002", "name": "示例 B"},
            ], {"missing_count": 1, "quota_exhausted": False, "last_error": None}

    def _normalize(value: object) -> str | None:
        text = str(value or "").strip()
        return text.zfill(6) if text.isdigit() else (text or None)

    df_candidates = pd.DataFrame(
        [{"fcode": "000001"}, {"fcode": "000002"}, {"fcode": "000003"}]
    )
    df_local = pd.DataFrame(
        [
            {"基金代码": "000001", "基金名称": "示例 A"},
            {"基金代码": "000002", "基金名称": "示例 B"},
            {"基金代码": "000003", "基金名称": "示例 C"},
        ]
    )

    def _compare(local_row, autostock_row, config):
        return {
            "passed": True,
            "hard_reasons": [],
            "warning_reasons": [],
            "details": {
                "基金代码": _normalize(local_row.get("基金代码")),
                "基金名称": local_row.get("基金名称"),
                "失败原因": "",
                "告警原因": "",
            },
        }

    recovered_meta = {
        "missing_count": 1,
        "quota_exhausted": False,
        "last_error": None,
        "fallback_recovery": {
            "initial_missing_count": 1,
            "recovered_count": 0,
            "remaining_missing_count": 1,
        },
    }
    with patch.object(
        quality_gate_helpers,
        "_recover_autostock_missing_rows",
        return_value=(
            [{"code": "000001", "name": "示例 A"}, {"code": "000002", "name": "示例 B"}],
            recovered_meta,
        ),
    ):
        validated_df, failed_codes, summary, failed_df = (
            quality_gate_helpers.cross_validate_candidate_pool_with_autostock(
                df_candidates,
                df_local_complete=df_local,
                build_validation_summary_fn=autostock_helpers.build_autostock_validation_summary,
                normalize_fcode_fn=_normalize,
                get_fund_complete_info_fn=lambda codes: df_local,
                required_local_columns=("基金代码", "基金名称"),
                load_autostock_cross_validation_config_fn=lambda: {
                    "base_url": "https://api.autostock.cn/v1",
                    "min_interval": 0.0,
                    "timeout": 1,
                    "max_calls_per_hour": 0,
                    "batch_size": 50,
                    "budget_reserve_calls": 0,
                    "max_fetch_calls_per_run": 50,
                    "residual_missing_max_count": 1,
                    "residual_missing_max_ratio": 0.5,
                    "nav_relative_tolerance_pct": 1.0,
                    "nav_absolute_tolerance": 0.001,
                    "nav_date_soft_lag_days": 5,
                    "return_relative_tolerance_pct": 5.0,
                    "return_absolute_tolerance": 0.5,
                    "return_small_base_threshold": 1.0,
                },
                build_autostock_validation_cache_key_fn=lambda *args, **kwargs: "cache-key",
                load_autostock_validation_cache_fn=lambda key: None,
                build_autostock_local_signature_fn=lambda row: str(row.get("基金代码") or ""),
                build_autostock_cache_entry_map_fn=lambda payload: {},
                load_recent_autostock_validation_caches_fn=lambda: [],
                autostock_client_cls=_ResidualMissingClient,
                compare_candidate_with_autostock_fn=_compare,
                write_autostock_validation_cache_fn=lambda *args, **kwargs: None,
                cache_schema_version="test",
                shared_state_path=None,
            )
        )

    assert set(validated_df["fcode"]) == {"000001", "000002"}
    assert failed_codes == {"000003"}
    assert failed_df.iloc[0]["失败原因"] == "missing_in_autostock"
    assert summary["batch_meta"]["residual_missing_demoted_to_hard_block"] is True
    assert summary["reason_counts"] == [{"reason": "missing_in_autostock", "count": 1}]


