def test_tiantian_valuation_fetch_falls_back_to_secondary_domain(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import backend.app as backend_app

    calls: list[str] = []

    class _Response:
        def __init__(self, payload):
            self._payload = payload

        def raise_for_status(self):
            return None

        def json(self):
            return self._payload

    def post(url, **_kwargs):
        calls.append(url)
        if url == backend_app._TRACKER_VALUATION_ENDPOINTS[0]:
            raise backend_app.requests.ConnectionError("primary down")
        return _Response(
            {
                "success": True,
                "errorCode": 0,
                "data": [{"FCODE": "000001", "GSZ": 1.1, "GSZZL": 0.2, "GZTIME": "2026-07-28 10:00"}],
            }
        )

    monkeypatch.setattr(backend_app, "_post_tiantian_tracker_valuation_request", post)

    rows, meta = backend_app._fetch_tiantian_tracker_valuation_rows(["000001"])

    assert calls == list(backend_app._TRACKER_VALUATION_ENDPOINTS)
    assert rows[0]["FCODE"] == "000001"
    assert meta["endpoint"] == backend_app._TRACKER_VALUATION_ENDPOINTS[1]


def test_tracker_valuation_missing_cache_uses_shorter_ttl() -> None:
    import backend.app as backend_app

    now = time.time()
    missing_entry = {
        "fetched_at": now - backend_app._VALUATION_MISSING_CACHE_TTL_SECONDS - 1,
        "payload": {"available": False, "reason": "valuation_not_provided"},
    }
    available_entry = {
        "fetched_at": now - backend_app._VALUATION_MISSING_CACHE_TTL_SECONDS - 1,
        "payload": {"available": True, "estimated_nav": "1.0"},
    }

    assert backend_app._is_tracker_valuation_cache_entry_fresh(missing_entry, now) is False
    assert backend_app._is_tracker_valuation_cache_entry_fresh(available_entry, now) is True


