def test_data_truthfulness_audit_accepts_positive_ratio_percent_points(tmp_path: Path) -> None:
    module = _load_script_module(
        "audit_data_truthfulness_positive_ratio_for_test",
        "scripts/audit_data_truthfulness.py",
    )
    db_path = tmp_path / "risk_metrics.db"
    with sqlite3.connect(db_path) as conn:
        conn.executescript(
            """
            CREATE TABLE fund_risk_metrics (
                fcode TEXT,
                period TEXT,
                volatility REAL,
                max_drawdown REAL,
                var_95 REAL,
                var_99 REAL,
                annual_return REAL,
                positive_ratio REAL
            );
            INSERT INTO fund_risk_metrics VALUES
                ('000001', '1y', 0.018, 0.032, -0.004, -0.008, 3.5, 55.0);
            """
        )

    payload = module._risk_metric_truth(SimpleNamespace(database_path=db_path))

    assert payload["status"] == "ok"
    assert payload["blockers"] == []
    assert payload["invalid_counts"]["positive_ratio_percent_point_out_of_range"] == 0
    assert payload["period_summary"][0]["positive_ratio_range"] == [55.0, 55.0]
    assert payload["metric_unit_registry"]["percentage_point_fields"]["positive_ratio"]["raw_unit"] == "percent_point"
    contract = payload["risk_metric_formula_contract"]
    assert contract["database_engine"]["metrics"]["var_95"]["sign_convention"] == "lower_tail_return_percentile"
    assert contract["database_engine"]["metrics"]["var_95"]["positive_values_allowed"] is True
    guard_summary = payload["risk_metric_input_guard_contracts"]
    assert "duplicate_nav_dates" in guard_summary["observed_guard_codes"]
    assert "missing_selected_nav_values" in guard_summary["observed_guard_codes"]
    assert "short_history_window" in guard_summary["observed_guard_codes"]
    assert "insufficient_period_coverage" in guard_summary["observed_guard_codes"]
    assert "stale_nav_against_snapshot" in guard_summary["observed_guard_codes"]
    parameter_summary = payload["risk_metric_calculation_parameter_contracts"]
    assert "risk_free_rate" in parameter_summary["observed_parameter_codes"]
    assert "sortino_minimum_acceptable_return" in parameter_summary["observed_parameter_codes"]
    assert "annualization_frequency" in parameter_summary["observed_parameter_codes"]
    assert "return_series_selection" in parameter_summary["observed_parameter_codes"]
    assert "risk_adjusted_ratio_caps" in parameter_summary["observed_parameter_codes"]
    assert "var_percentile_rules" in parameter_summary["observed_parameter_codes"]
    assert "missing_metric_semantics" in parameter_summary["observed_parameter_codes"]
    reader_checks = payload["risk_latest_reader_contracts"]
    assert all(not item["missing_patterns"] for item in reader_checks)
    readiness_reader_checks = payload["risk_readiness_reader_contracts"]
    readiness_paths = {item["path"] for item in readiness_reader_checks}
    assert "backend/effective_nav.py" in readiness_paths
    assert "backend/scheduler.py" in readiness_paths
    assert "backend/app.py" in readiness_paths
    assert "backend/long_term_history_maintenance.py" in readiness_paths
    assert "core/collectors/detail_collector.py" in readiness_paths
    assert "backend/risk_lag_audit.py" in readiness_paths
    assert "backend/risk_coverage_gap_audit.py" in readiness_paths
    assert all(not item["missing_patterns"] for item in readiness_reader_checks)


def test_data_truthfulness_audit_blocks_missing_risk_input_guard_contract(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _load_script_module(
        "audit_data_truthfulness_risk_input_guard_contract_for_test",
        "scripts/audit_data_truthfulness.py",
    )
    db_path = tmp_path / "risk_metrics_missing_guard.db"
    with sqlite3.connect(db_path) as conn:
        conn.executescript(
            """
            CREATE TABLE fund_risk_metrics (
                fcode TEXT,
                period TEXT,
                volatility REAL,
                max_drawdown REAL,
                var_95 REAL,
                var_99 REAL,
                annual_return REAL,
                positive_ratio REAL
            );
            INSERT INTO fund_risk_metrics VALUES
                ('000001', '1y', 0.018, 0.032, -0.004, -0.008, 3.5, 55.0);
            """
        )
    broken_contract = module.risk_metric_formula_contract()
    broken_contract["database_engine"]["input_window_guard_contracts"] = [
        item
        for item in broken_contract["database_engine"]["input_window_guard_contracts"]
        if item.get("guard_code") != "duplicate_nav_dates"
    ]
    monkeypatch.setattr(module, "risk_metric_formula_contract", lambda: broken_contract)

    payload = module._risk_metric_truth(SimpleNamespace(database_path=db_path))

    assert payload["status"] == "needs_review"
    assert "risk_formula_contract_input_guard_missing:duplicate_nav_dates" in payload["blockers"]


