def test_risk_formula_contract_exposes_calculation_parameters() -> None:
    from backend.risk_metric_contract import risk_metric_formula_contract

    contract = risk_metric_formula_contract()
    parameters = {
        item["parameter_code"]: item
        for item in contract["database_engine"]["calculation_parameter_contracts"]
    }

    assert parameters["risk_free_rate"]["raw_unit"] == "decimal_ratio"
    assert "sharpe_ratio" in parameters["risk_free_rate"]["applies_to"]
    assert parameters["sortino_minimum_acceptable_return"]["daily_mar_formula"] == (
        "minimum_acceptable_return / periods_per_year"
    )
    assert parameters["annualization_frequency"]["configured_default_trading_days_per_year"] == 252
    assert "365.25" in parameters["annualization_frequency"]["actual_years_formula"]
    assert parameters["return_series_selection"]["converted_return_unit"] == "decimal_ratio"
    assert any(
        "daily_growth" in source
        for source in parameters["return_series_selection"]["source_priority"]
    )
    assert parameters["risk_adjusted_ratio_caps"]["preserve_raw_fields"] is True
    assert parameters["risk_adjusted_ratio_caps"]["sharpe_display_cap"] == 5.0
    assert parameters["risk_adjusted_ratio_caps"]["sortino_display_cap_abs"] == 10.0
    layer6_calmar = parameters["layer6_calmar_rules"]
    assert layer6_calmar["risk_free_rate_deduction"] is True
    assert layer6_calmar["style_min_drawdown_floor_table"]["中短债"] == pytest.approx(0.002)
    assert layer6_calmar["style_min_drawdown_floor_table"]["综合纯债"] == pytest.approx(0.003)
    assert layer6_calmar["style_min_drawdown_floor_table"]["default"] == pytest.approx(0.005)
    assert layer6_calmar["cap_rule"] == "[-20.0, 20.0]"
    screening_layer6 = contract["screening_layer6_engine"]["calmar_ratio_contract"]
    assert screening_layer6["formula"] == "(annual_return - risk_free_rate) / effective_drawdown"
    assert screening_layer6["cap_rule"]["lower"] == -20.0
    assert screening_layer6["cap_rule"]["upper"] == 20.0
    assert "calmar_effective_drawdown" in screening_layer6["audit_fields"]
    assert parameters["var_percentile_rules"]["var_95_percentile"] == 5
    assert parameters["var_percentile_rules"]["var_99_percentile"] == 1
    assert parameters["var_percentile_rules"]["positive_values_allowed"] is True
    assert parameters["missing_metric_semantics"]["disallow_zero_fill"] is True


