def test_data_truthfulness_source_truth_manifest_checks_schema_and_run_artifacts(tmp_path: Path) -> None:
    module = _load_script_module(
        "audit_data_truthfulness_source_truth_manifest_for_test",
        "scripts/audit_data_truthfulness.py",
    )
    db_path = tmp_path / "truth.db"
    with sqlite3.connect(db_path) as conn:
        conn.executescript(
            """
            CREATE TABLE funds (
                fcode TEXT,
                shortname TEXT,
                type_code TEXT,
                data_source TEXT
            );
            INSERT INTO funds VALUES ('000001', '测试基金A', '31', 'fundMNRank');
            """
        )

    run_dir = tmp_path / "reports" / "runs" / "run1"
    run_dir.mkdir(parents=True)
    formal_csv = run_dir / "formal.csv"
    formal_csv.write_text("基金代码,基金名称\n000001,测试基金A\n", encoding="utf-8")
    latest_report = tmp_path / "latest.json"
    latest_report.write_text(
        json.dumps(
            {
                "run_id": "run1",
                "artifacts": {
                    "filtered_csv": str(formal_csv.relative_to(tmp_path)),
                },
            },
            ensure_ascii=False,
        ),
        encoding="utf-8",
    )
    settings = SimpleNamespace(
        project_root=tmp_path,
        database_path=db_path,
        latest_report_file=latest_report,
    )
    original_domains = module.SOURCE_TRUTH_DOMAINS
    module.SOURCE_TRUTH_DOMAINS = (
        {
            "key": "minimal_fund_directory",
            "label": "最小基金目录",
            "upstream_sources": ("Tiantian /fundMNRank",),
            "truth_rule": "Only API-derived rows are valid.",
            "tables": (
                {
                    "name": "funds",
                    "required": True,
                    "min_row_count": 1,
                    "required_fields": ("fcode", "shortname", "type_code", "data_source"),
                    "identity_fields": ("fcode",),
                },
            ),
            "required_artifacts": (
                {
                    "key_path": "artifacts.filtered_csv",
                    "required": True,
                    "artifact_type": "formal_filtered_csv",
                },
            ),
        },
    )
    try:
        payload = module._source_truth_manifest(settings)
    finally:
        module.SOURCE_TRUTH_DOMAINS = original_domains

    assert payload["status"] == "ok"
    assert payload["blockers"] == []
    domain = payload["domains"]["minimal_fund_directory"]
    assert domain["tables"][0]["row_count"] == 1
    assert domain["tables"][0]["missing_required_fields"] == []
    assert domain["artifacts"][0]["exists"] is True
    assert "Tiantian /fundMNRank" in domain["upstream_sources"]


