    broken_payload = module._risk_snapshot_input_consistency(settings)

    assert broken_payload["status"] == "needs_review"
    assert "risk_nav_snapshot_signature_mismatch_current_returns" in broken_payload["blockers"]
    assert "formal_list_risk_nav_snapshot_signature_mismatch" in broken_payload["blockers"]
