def test_data_truthfulness_annual_return_rank_consistency_checks_sidecar_and_percentile(
    tmp_path: Path,
) -> None:
    module = _load_script_module(
        "audit_data_truthfulness_annual_return_rank_consistency_for_test",
        "scripts/audit_data_truthfulness.py",
    )
    db_path = tmp_path / "truth.db"
    annual_window = module._complete_calendar_year_window(module.ANNUAL_RETURN_LONG_TERM_WINDOW_YEARS)
    latest_rank_date = module.datetime.now().date()
    annual_entries: list[dict[str, Any]] = []
    with sqlite3.connect(db_path) as conn:
        conn.executescript(
            """
            CREATE TABLE funds (
                fcode TEXT,
                estab_date TEXT
            );
            CREATE TABLE fund_annual_returns (
                fcode TEXT,
                year INTEGER,
                annual_return REAL,
                rank_in_category INTEGER,
                category_count INTEGER,
                percentile REAL
            );
            CREATE TABLE fund_rank_history (
                fcode TEXT,
                rank_date TEXT,
                rank_position INTEGER,
                category_total INTEGER,
                percentile REAL
            );
            INSERT INTO funds VALUES ('000001', '2010-01-01');
            """
        )
        for index, year in enumerate(annual_window, start=1):
            annual_return = 1.0 + index / 10.0
            rank_in_category = index
            category_count = 100
            percentile = rank_in_category / category_count
            conn.execute(
                "INSERT INTO fund_annual_returns VALUES ('000001', ?, ?, ?, ?, ?)",
                (year, annual_return, rank_in_category, category_count, percentile),
            )
            annual_entries.append(
                {
                    "year": year,
                    "annual_return": module._format_number_text(annual_return, digits=2),
                    "rank_in_category": rank_in_category,
                    "category_count": category_count,
                    "percentile": module._format_number_text(percentile * 100.0, digits=2),
                    "is_partial_year": False,
                }
            )
        for offset in range(25):
            rank_date = (latest_rank_date - timedelta(days=offset)).isoformat()
            rank_position = offset + 1
            category_total = 100
            percentile = rank_position / category_total
            conn.execute(
                "INSERT INTO fund_rank_history VALUES ('000001', ?, ?, ?, ?)",
                (rank_date, rank_position, category_total, percentile),
            )

    run_dir = tmp_path / "reports" / "runs" / "run1"
    run_dir.mkdir(parents=True)
    formal_csv = run_dir / "formal.csv"
    formal_csv.write_text(
        "\ufeff基金代码,基金名称\n000001,测试基金A\n",
        encoding="utf-8",
    )
    tracker_sidecar = run_dir / "project_tracker_current_detail.json"
    tracker_sidecar.write_text(
        json.dumps(
            {
                "artifact_type": "project_tracker_current_detail_sidecar",
                "run_id": "run1",
                "derived_fields": {
                    "annual_return_breakdown_by_code": {
                        "000001": annual_entries,
                    },
                },
            },
            ensure_ascii=False,
        ),
        encoding="utf-8",
    )
    latest_report = tmp_path / "latest.json"
    latest_report.write_text(
        json.dumps(
            {
                "run_id": "run1",
                "final_count": 1,
                "artifacts": {
                    "filtered_csv": str(formal_csv.relative_to(tmp_path)),
                    "project_tracker_current_detail_json": str(tracker_sidecar.relative_to(tmp_path)),
                },
            },
            ensure_ascii=False,
        ),
        encoding="utf-8",
    )
    settings = SimpleNamespace(
        project_root=tmp_path,
        database_path=db_path,
        latest_report_file=latest_report,
        scheduler_long_term_history_rank_stale_days=9999,
    )

    payload = module._annual_return_rank_consistency(settings)

    assert payload["status"] == "ok"
    assert payload["blockers"] == []
    assert payload["formal_list_summary"]["annual_long_term_ready_count"] == 1
    assert payload["formal_list_summary"]["rank_ready_count"] == 1
    assert payload["formal_list_summary"]["annual_breakdown_sidecar_mismatch_count"] == 0
    assert payload["database_summary"]["annual_returns"]["annual_percentile_formula_mismatch"] == 0
    assert payload["database_summary"]["rank_history"]["rank_percentile_formula_mismatch"] == 0

    with sqlite3.connect(db_path) as conn:
        conn.execute(
            "UPDATE fund_annual_returns SET percentile = 0.99 WHERE fcode = '000001' AND year = ?",
            (annual_window[0],),
        )

    broken_payload = module._annual_return_rank_consistency(settings)

    assert broken_payload["status"] == "needs_review"
    assert "annual_percentile_formula_mismatch" in broken_payload["blockers"]
    assert "tracker_annual_breakdown_sidecar_db_mismatch" in broken_payload["blockers"]


