def _attach_collect_funds_snapshot_missing_semantics(
    evidence: dict[str, Any],
    *,
    missing_count: int = 1,
) -> dict[str, Any]:
    semantics = {
        "schema_version": 1,
        "source": "fundMNRank",
        "truth_policy": "preserve_missing_semantics",
        "missing_value_handling": (
            "Missing snapshot fields are recorded as upstream missing evidence; "
            "the collector does not synthesize nav_date/nav_value or convert them to 0."
        ),
        "fields": {
            "FSRQ": {
                "raw_field": "FSRQ",
                "business_field": "nav_date",
                "missing_count": missing_count,
                "raw_field_present_count": missing_count,
                "raw_field_absent_count": 0,
                "non_missing_count": 0,
                "value_type_counts": {"str": missing_count},
                "missing_reason_counts": {"raw_value_placeholder_text": missing_count},
                "missing_samples": [
                    {
                        "page": 1,
                        "fcode": "000001",
                        "raw_field_present": True,
                        "raw_value_type": "str",
                        "missing_reason": "raw_value_placeholder_text",
                    }
                ],
            },
            "DWJZ": {
                "raw_field": "DWJZ",
                "business_field": "nav_value",
                "missing_count": missing_count,
                "raw_field_present_count": missing_count,
                "raw_field_absent_count": 0,
                "non_missing_count": 0,
                "value_type_counts": {"str": missing_count},
                "missing_reason_counts": {"raw_value_placeholder_text": missing_count},
                "missing_samples": [
                    {
                        "page": 1,
                        "fcode": "000001",
                        "raw_field_present": True,
                        "raw_value_type": "str",
                        "missing_reason": "raw_value_placeholder_text",
                    }
                ],
            },
        },
    }
    evidence["total_missing_nav_date_count"] = missing_count
    evidence["total_missing_nav_value_count"] = missing_count
    evidence["snapshot_missing_semantics"] = deepcopy(semantics)
    for type_evidence in evidence.get("types") or []:
        type_evidence["missing_nav_date_count"] = missing_count
        type_evidence["missing_nav_value_count"] = missing_count
        type_evidence["snapshot_missing_semantics"] = deepcopy(semantics)
    return evidence


def _write_collect_funds_contract_log(
    root: Path,
    evidence: dict[str, Any],
    *,
    success: bool = True,
) -> None:
    log_dir = root / "reports" / ".audit" / "subprocess_logs" / "20260609_130000"
    log_dir.mkdir(parents=True)
    stdout_path = log_dir / "20260609_130001_collect-funds.stdout.log"
    stderr_path = log_dir / "20260609_130001_collect-funds.stderr.log"
    meta_path = log_dir / "20260609_130001_collect-funds.meta.json"
    stdout_path.write_text(
        "\n".join(
            [
                "任务完成统计",
                "总任务数:    1",
                "已处理:      1",
                "成功:        1",
                "跳过:        0",
                "失败:        0",
                "成功率:      100.00%",
                "FundCollector 统计",
                "总数:     1",
                "成功:     1",
                "失败:     0",
                "跳过:     0",
                "成功率:   100.00%",
                f"api_source_evidence={json.dumps(evidence, ensure_ascii=False)}",
                "✅ bond基金列表采集完成: 1只",
            ]
        ),
        encoding="utf-8",
    )
    stderr_path.write_text("", encoding="utf-8")
    meta_path.write_text(json.dumps({"task_name": "collect-funds"}, ensure_ascii=False), encoding="utf-8")
    (log_dir / "subprocess_index.json").write_text(
        json.dumps(
            {
                "generated_at": "2026-06-09T13:00:00",
                "run_id": None,
                "subprocess_count": 1,
                "success_count": 1 if success else 0,
                "failed_count": 0 if success else 1,
                "failed_task_names": [] if success else ["collect-funds"],
                "items": [
                    {
                        "task_name": "collect-funds",
                        "success": success,
                        "return_code": 0 if success else 1,
                        "timed_out": False,
                        "duration_seconds": 1.0,
                        "started_at": "2026-06-09T13:00:01",
                        "finished_at": "2026-06-09T13:00:02",
                        "command": ["python", "main.py", "collect-funds", "-t", "bond"],
                        "meta_path_relative": str(meta_path.relative_to(root)),
                        "stdout_path_relative": str(stdout_path.relative_to(root)),
                        "stderr_path_relative": str(stderr_path.relative_to(root)),
                    }
                ],
            },
            ensure_ascii=False,
        ),
        encoding="utf-8",
    )


