def test_data_truthfulness_flags_collect_funds_rank_aggregate_mismatches() -> None:
    module = _load_script_module(
        "audit_data_truthfulness_collect_funds_rank_aggregate_mismatch_for_test",
        "scripts/audit_data_truthfulness.py",
    )
    evidence = _collect_funds_api_source_evidence_for_test(2)
    evidence["type_count"] = 2
    evidence["total_page_request_count"] = 2
    evidence["total_collected_record_count"] = 3
    evidence["duplicate_record_count"] = 0
    evidence["total_intra_type_duplicate_code_count"] = 1

    blockers, warnings = module._validate_collect_funds_api_source_evidence(
        [evidence],
        bond_fund_count=2,
    )

    assert "api_source_evidence_type_count_mismatch:1:2!=1" in blockers
    assert any(
        item.startswith(
            "api_source_evidence_aggregate_sum_mismatch:1:total_page_request_count=2!=sum(page_request_count)=1"
        )
        for item in blockers
    )
    assert any(
        item.startswith(
            "api_source_evidence_aggregate_sum_mismatch:1:total_collected_record_count=3!=sum(collected_record_count)=2"
        )
        for item in blockers
    )
    assert "api_source_evidence_unique_duplicate_count_mismatch:1:2+0!=3" in blockers
    assert "api_source_evidence_duplicate_count_lt_intra_type_duplicate:1:0<1" in blockers


