def test_data_truthfulness_live_field_detail_probes_are_audit_read_only(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _load_script_module(
        "audit_data_truthfulness_live_field_read_only_for_test",
        "scripts/audit_data_truthfulness.py",
    )
    captured: list[str] = []

    def fake_fetch_live_json(base_url: str, endpoint: str, timeout_seconds: float):
        captured.append(endpoint)
        if endpoint.startswith("/api/tracker/current"):
            return 200, _tracker_current_live_response_for_test(), None, 0.01
        if endpoint.startswith("/api/recommendations/latest/detail"):
            return (
                200,
                _recommendations_detail_live_response_for_test(),
                None,
                0.01,
            )
        if endpoint.startswith("/api/recommendations/latest"):
            return 200, _recommendations_summary_live_response_for_test(), None, 0.01
        if endpoint.startswith("/api/tracker/valuations"):
            return 200, _tracker_valuations_response_for_test(["000001"]), None, 0.01
        raise AssertionError(f"unexpected endpoint {endpoint}")

    monkeypatch.setattr(module, "_fetch_live_json", fake_fetch_live_json)
    monkeypatch.setattr(
        module,
        "_fetch_live_json_post",
        lambda _base_url, endpoint, payload, _timeout_seconds: (
            (200, _favorite_metric_detail_response_for_test(payload["codes"]), None, 0.01)
            if endpoint == "/api/favorites/metric-details"
            else (_ for _ in ()).throw(AssertionError(f"unexpected endpoint {endpoint}"))
        ),
    )
    tracker_spec = next(item for item in module.LIVE_FIELD_ENDPOINTS if item["key"] == "tracker_detail")
    recommendations_spec = next(item for item in module.LIVE_FIELD_ENDPOINTS if item["key"] == "recommendations_detail")
    recommendations_summary_spec = next(item for item in module.LIVE_FIELD_ENDPOINTS if item["key"] == "recommendations_summary")
    tracker_valuations_spec = next(item for item in module.LIVE_FIELD_ENDPOINTS if item["key"] == "tracker_valuations")
    metric_details_spec = next(item for item in module.LIVE_FIELD_ENDPOINTS if item["key"] == "favorite_metric_details")

    tracker_result = module._sample_live_field_endpoint(
        base_url="http://127.0.0.1:8090",
        timeout_seconds=1.0,
        endpoint_spec=tracker_spec,
        sample_codes=["000001"],
    )
    recommendations_result = module._sample_live_field_endpoint(
        base_url="http://127.0.0.1:8090",
        timeout_seconds=1.0,
        endpoint_spec=recommendations_spec,
        sample_codes=["000001"],
    )
    recommendations_summary_result = module._sample_live_field_endpoint(
        base_url="http://127.0.0.1:8090",
        timeout_seconds=1.0,
        endpoint_spec=recommendations_summary_spec,
        sample_codes=["000001"],
    )
    tracker_valuations_result = module._sample_live_field_endpoint(
        base_url="http://127.0.0.1:8090",
        timeout_seconds=1.0,
        endpoint_spec=tracker_valuations_spec,
        sample_codes=["000001"],
    )
    metric_details_result = module._sample_live_field_endpoint(
        base_url="http://127.0.0.1:8090",
        timeout_seconds=1.0,
        endpoint_spec=metric_details_spec,
        sample_codes=["000001"],
    )

    assert captured == [
        "/api/tracker/current?detail=1&audit_read_only=1",
        "/api/recommendations/latest/detail?audit_read_only=1",
        "/api/recommendations/latest",
        "/api/tracker/valuations?audit_read_only=1&codes=000001",
    ]
    assert tracker_result["diagnostics"]["audit_read_only"] is True
    assert tracker_result["diagnostics"]["derived_sidecar_write_status"] == "audit_read_only"
    assert tracker_result["source_basis"]["source"] == "tracker_current_published_report_tracker_artifact"
    assert tracker_result["source_basis"]["payload_mode"] == "detail"
