    assert metric_details_result["details_count"] == 1
    assert metric_details_result["source_basis"]["requested_codes"] == ["000001"]
    assert metric_details_result["cache_basis"] == metric_details_result["source_basis"]
    assert metric_details_result["source_contract"]["business_value_synthesis"] == "forbidden"
    assert (
        metric_details_result["source_contract"]["cache_basis_digest"]
        == metric_details_result["source_basis"]["digest"]
    )


