@pytest.mark.parametrize("schema_version", [None, 1, 3])
def test_frontend_field_lineage_rejects_legacy_lifetime_return_definition(
    tmp_path: Path, schema_version: int | None,
) -> None:
    module = _load_script_module("audit_lifetime_definition_for_test", "scripts/audit_data_truthfulness.py")
    settings = _write_frontend_field_lineage_fixture(module, tmp_path)
    latest = json.loads(settings.latest_report_file.read_text(encoding="utf-8"))
    tracker_path = tmp_path / latest["artifacts"]["project_tracker_current_detail_json"]
    tracker = json.loads(tracker_path.read_text(encoding="utf-8"))
    derived = tracker["derived_fields"]
    derived["schema_version"] = schema_version
    derived["accum_nav_ratio_annualized_by_code"] = {"000001": "8.88"}
    tracker_path.write_text(json.dumps(tracker, ensure_ascii=False), encoding="utf-8")

    payload = module._frontend_field_lineage_truth(
        settings, include_live_api=False, live_base_url="http://127.0.0.1:8090", timeout_seconds=1.0,
    )
    assert "tracker_derived_platform_return_schema_mismatch" in payload["blockers"]
    lineage = payload["field_lineage"]["平台成立以来收益年化(%)"]
    assert lineage["available"] is False
    assert lineage["available_count"] == 0
    assert "成立以来年化收益率(%)" not in payload["field_lineage"]


@pytest.mark.parametrize("platform_map", [None, {}, {"000001": 0}])
def test_frontend_field_lineage_platform_return_preserves_missing_and_zero(
    tmp_path: Path, platform_map: dict | None,
) -> None:
    module = _load_script_module("audit_lifetime_missing_for_test", "scripts/audit_data_truthfulness.py")
    settings = _write_frontend_field_lineage_fixture(module, tmp_path)
    latest = json.loads(settings.latest_report_file.read_text(encoding="utf-8"))
    tracker_path = tmp_path / latest["artifacts"]["project_tracker_current_detail_json"]
    tracker = json.loads(tracker_path.read_text(encoding="utf-8"))
    tracker["derived_fields"]["annualized_return_by_code"] = platform_map
    tracker["derived_fields"]["accum_nav_ratio_annualized_by_code"] = {"000001": "8.88"}
    tracker_path.write_text(json.dumps(tracker, ensure_ascii=False), encoding="utf-8")

    payload = module._frontend_field_lineage_truth(
        settings, include_live_api=False, live_base_url="http://127.0.0.1:8090", timeout_seconds=1.0,
    )
    lineage = payload["field_lineage"]["平台成立以来收益年化(%)"]
    assert lineage["available"] is (platform_map is not None)
    assert lineage["available_count"] == (1 if platform_map else 0)
    if platform_map is None:
        assert "tracker_derived_map_missing:annualized_return_by_code" in payload["blockers"]
    elif not platform_map:
        assert "tracker_derived_map_empty:annualized_return_by_code" in payload["warnings"]
    else:
        assert payload["blockers"] == []
        assert payload["warnings"] == []


