def _upstream_api_source_contract_for_test() -> dict[str, Any]:
    tiantian_paths = [
        "/fundMNRank",
        "/fundSearch",
        "/fundMNHisNetList",
        "/fundMNDetailInformation",
        "/fundMNMangerList",
        "/fundMSNMangerInfo",
        "/fundMNPeriodIncrease",
        "/fundRankDiagram",
    ]
    autostock_paths = [
        "/fund/all",
        "/fund",
        "/fund/detail",
        "/fund/detail/list",
    ]
    tiantian_endpoints = [
        {
            "path": "/fundMNRank",
            "pagination": {
                "required": True,
                "page_index_param": "pageIndex",
                "page_size_param": "pageSize",
                "declared_total_field": "TotalCount",
            },
            "source_evidence_required": True,
            "required_params": {
                "FundType": ["31", "32"],
                "pageIndex": "1-based integer",
                "pageSize": "positive integer",
            },
        },
        {
            "path": "/fundMNHisNetList",
            "pagination": {
                "required": True,
                "page_index_param": "pageIndex",
                "page_size_param": "pagesize",
                "declared_total_field": "TotalCount",
            },
            "required_params": {
                "FCODE": "6-digit fund code",
                "pageIndex": "1-based integer",
                "pagesize": "positive integer; lowercase spelling is required",
            },
            "forbidden_param_aliases": ["pageSize"],
            "source_evidence_required": True,
        },
    ]
    tiantian_endpoints.extend(
        {"path": path, "pagination": {"required": False}, "source_evidence_required": True}
        for path in tiantian_paths
        if path not in {"/fundMNRank", "/fundMNHisNetList"}
    )
    autostock_endpoints = [
        {"path": path, "pagination": {"required": False}, "source_evidence_required": True}
        for path in autostock_paths
    ]
    return {
        "schema_version": 1,
        "status": "ok",
        "contract_scope": "real_upstream_business_data_sources",
        "source_groups": {
            "tiantian": {
                "current_configured_base_url": "http://108.62.161.95:18087",
                "runtime_base_url": "http://108.62.161.95:18087",
                "read_only_probe": {
                    "endpoint": "/api/settings/apis/probe",
                    "writes_database": False,
                    "writes_business_artifacts": False,
                },
                "endpoints": tiantian_endpoints,
            },
            "autostock": {
                "current_configured_base_url": "https://api.autostock.cn/v1",
                "runtime_base_url": "https://api.autostock.cn/v1",
                "endpoints": autostock_endpoints,
            },
        },
        "endpoint_index": {
            "tiantian": tiantian_paths,
            "autostock": autostock_paths,
        },
        "quality_policy": {
            "fake_data_policy": "forbidden",
            "missing_value_policy": "preserve_missing_semantics",
            "threshold_policy": "do not loosen production safety gates to increase final counts",
        },
    }


