    assert publication_registry_summary["source"] == "publication_summary_publication_registry_artifact"
    assert publication_registry_summary["source_contract"]["truth_policy"] == (
        "real_publication_registry_artifact_only"
    )
    assert publication_registry_summary["source_contract"]["frontend_rendered_truth_allowed"] is False
    dashboard_summary = result["endpoints"]["/api/dashboard/latest?sample_limit=0"]["summary"]
    assert dashboard_summary["publication_status"]["status"] == "success_published"
    assert dashboard_summary["dashboard_latest_source"]["available"] is True
    assert dashboard_summary["dashboard_latest_source"]["source"] == (
        "dashboard_latest_current_published_report_scheduler_database_artifacts"
    )
    assert dashboard_summary["dashboard_latest_source"]["payload_mode"] == "compact"
    assert dashboard_summary["dashboard_latest_source"]["detail_scope"] == "compact"
    assert dashboard_summary["dashboard_latest_source"]["latest_report_run_id"] == "run1"
    assert dashboard_summary["dashboard_latest_source"]["latest_successful_run_id"] == "run1"
    assert dashboard_summary["dashboard_latest_source"]["publication_status"] == "success_published"
    assert dashboard_summary["dashboard_latest_source"]["publication_status_source"]["present"] is True
    assert dashboard_summary["dashboard_latest_source"]["publication_status_source"]["source"] == (
        "publication_registry_runtime_overlay"
    )
    assert dashboard_summary["dashboard_latest_source"]["publication_status_source"][
        "current_published_run_id"
    ] == "run1"
    assert dashboard_summary["dashboard_latest_source"]["daily_screening_run_id"] == "run1"
    assert dashboard_summary["dashboard_latest_source"]["sample_limit"] == 0
    assert dashboard_summary["dashboard_latest_source"]["source_contract"]["truth_policy"] == (
        "real_publication_registry_report_artifact_scheduler_state_database_and_runtime_artifacts_only"
    )
    assert dashboard_summary["dashboard_latest_source"]["source_contract"]["frontend_rendered_truth_allowed"] is False
    dashboard_overview_summary = result["endpoints"]["/api/dashboard/overview"]["summary"]
    assert dashboard_overview_summary["dashboard_overview_source"]["available"] is True
    assert dashboard_overview_summary["dashboard_overview_source"]["source"] == (
        "dashboard_overview_current_published_report_scheduler_database_artifacts"
    )
    assert dashboard_overview_summary["dashboard_overview_source"]["final_count"] == 3
    assert dashboard_overview_summary["dashboard_overview_source"]["source_contract"]["frontend_rendered_truth_allowed"] is False
    expected_lightweight_sources = {
        "/api/status/summary": (
            "workflow_status_summary_runtime_manager",
            "workflow_summary",
            "false_workflow_runtime_diagnostics_only",
        ),
        "/api/health/summary": (
            "health_summary_scheduler_publication_runtime_artifacts",
            "health_summary",
            "false_health_diagnostics_only",
        ),
        "/api/bootstrap/summary": (
            "bootstrap_summary_health_workflow_runtime_artifacts",
            "bootstrap_summary",
            "false_bootstrap_diagnostics_only",
        ),
        "/api/scheduler/status": (
            "scheduler_status_compact_runtime_state",
            "scheduler_status_compact",
            "false_scheduler_diagnostics_only",
        ),
    }
    for endpoint, (expected_source, expected_payload_mode, expected_official_truth) in expected_lightweight_sources.items():
        source_summary = result["endpoints"][endpoint]["summary"]["lightweight_status_source"]
        assert source_summary["available"] is True
        assert source_summary["source"] == expected_source
        assert source_summary["payload_mode"] == expected_payload_mode
        assert source_summary["latest_report_run_id"] == "run1"
        assert source_summary["latest_canonical_run_id"] == "run1"
        assert source_summary["current_published_run_id"] == "run1"
        assert source_summary["source_contract"]["truth_policy"] == (
            "real_runtime_state_publication_registry_database_and_runtime_artifacts_only"
        )
        assert source_summary["source_contract"]["missing_value_policy"] == "preserve_missing_semantics"
        assert source_summary["source_contract"]["business_value_synthesis"] == "forbidden"
        assert source_summary["source_contract"]["official_publication_truth"] == expected_official_truth
        assert source_summary["source_contract"]["frontend_rendered_truth_allowed"] is False
    scheduler_summary = result["endpoints"]["/api/scheduler/status/detail?sample_limit=0"]["summary"]
    assert scheduler_summary["scheduler_status"]["manual_intervention_required"] is False
    assert scheduler_summary["scheduler_status"]["status"] == "automatic_recovering"
    assert scheduler_summary["scheduler_status"]["scheduler_running"] is True
    assert "weekly_maintenance_degraded" not in scheduler_summary["scheduler_status"]["warning_issue_codes"]
    assert "weekly_maintenance_degraded" in scheduler_summary["scheduler_status"]["resolved_warning_issue_codes"]
    assert (
        scheduler_summary["scheduler_status"]["resolved_warning_issue_details"]["weekly_maintenance_degraded"][
            "root_cause_status"
        ]
        == "resolved_awaiting_next_weekly_maintenance"
    )
    health_summary = result["endpoints"]["/api/health/summary"]["summary"]
    assert health_summary["scheduler_header_status"]["manual_intervention_required"] is False
    assert health_summary["scheduler_header_status"]["scheduler_running"] is True
    assert health_summary["autostock_directory_source"]["status"] == "watch"
    assert health_summary["autostock_directory_source"]["parse_error_count"] == 1
    assert health_summary["autostock_directory_source"]["formal_final_overlap_count"] == 0
    assert health_summary["autostock_directory_source"]["truth_policy"] == "preserve_missing_semantics"
    assert health_summary["weekly_maintenance_warning_truth"]["status"] == "watch"
    assert health_summary["weekly_maintenance_warning_truth"]["manual_intervention_required"] is False
    assert (
        health_summary["weekly_maintenance_warning_truth"]["scheduler_warning_root_cause_status"]
        == "resolved_awaiting_next_weekly_maintenance"
    )
    assert health_summary["weekly_maintenance_warning_truth"]["collect_details_empty_detail_count"] == 2
    assert (
        health_summary["weekly_maintenance_warning_truth"][
            "collect_details_stderr_blockers_explained_by_empty_detail"
        ]
        is True
    )
    bootstrap_summary = result["endpoints"]["/api/bootstrap/summary"]["summary"]
    assert bootstrap_summary["scheduler_header_status"]["status"] == "automatic_recovering"
    assert bootstrap_summary["autostock_directory_source"]["source"] == "AutoStock /fund/all"
    assert bootstrap_summary["weekly_maintenance_warning_truth"]["truth_policy"] == (
        "read_only_runtime_artifact_evidence_no_state_mutation"
    )
    settings_summary = result["endpoints"]["/api/settings/apis"]["summary"]
    assert settings_summary["api_settings"]["scheduler_runtime_evidence_available"] is True
    info_summary = result["endpoints"]["/api/info"]["summary"]
    assert info_summary["upstream_api_source_contract"]["tiantian_base_url"] == "http://108.62.161.95:18087"
    assert info_summary["upstream_api_source_contract"]["autostock_base_url"] == "https://api.autostock.cn/v1"
    assert info_summary["upstream_api_source_contract"]["nav_history_page_size_param"] == "pagesize"
    assert info_summary["upstream_api_source_contract"]["fake_data_policy"] == "forbidden"


