def test_data_truthfulness_project_file_source_headers_contract() -> None:
    module = _load_script_module(
        "audit_data_truthfulness_project_file_headers_for_test",
        "scripts/audit_data_truthfulness.py",
    )
    headers = {
        "X-Fund-ANA-Source": "project_file_artifact_binary",
        "X-Fund-ANA-Truth-Policy": "real_project_file_artifact_only",
        "X-Fund-ANA-Missing-Value-Policy": "preserve_missing_semantics",
        "X-Fund-ANA-Business-Value-Synthesis": "forbidden",
        "X-Fund-ANA-Official-Publication-Truth": "false_binary_transfer_only",
        "X-Fund-ANA-Frontend-Rendered-Truth-Allowed": "false",
        "X-Fund-ANA-Run-ID": "run1",
        "X-Fund-ANA-Artifact-Key": "filtered_excel",
        "X-Fund-ANA-Artifact-Declared": "true",
        "X-Fund-ANA-File-Token": "111:222",
        "X-Fund-ANA-File-Content-Token": "333:abc",
        "X-Fund-ANA-Latest-Canonical-Run-ID": "run1",
        "X-Fund-ANA-Current-Published-Run-ID": "run1",
        "X-Fund-ANA-Source-Basis-Digest": "digest",
        "X-Fund-ANA-Source-Basis-Schema-Version": "1",
    }
    summary, blockers = module._validate_live_project_file_source_headers(
        headers,
        expected_publication={
            "latest_report_run_id": "run1",
            "latest_canonical_run_id": "run1",
            "current_published_run_id": "run1",
        },
        expected_artifact_key="filtered_excel",
    )
    assert blockers == []
    assert summary["available"] is True
    assert summary["source"] == "project_file_artifact_binary"
    assert summary["truth_policy"] == "real_project_file_artifact_only"
    assert summary["business_value_synthesis"] == "forbidden"

    bad_headers = dict(headers)
    bad_headers.pop("X-Fund-ANA-File-Content-Token")
    bad_headers["X-Fund-ANA-Frontend-Rendered-Truth-Allowed"] = "true"
    bad_headers["X-Fund-ANA-Artifact-Declared"] = "false"
    bad_headers["X-Fund-ANA-Artifact-Key"] = "watch_excel"
    _, bad_blockers = module._validate_live_project_file_source_headers(
        bad_headers,
        expected_publication={
            "latest_report_run_id": "run1",
            "latest_canonical_run_id": "run1",
            "current_published_run_id": "run1",
        },
        expected_artifact_key="filtered_excel",
    )
    assert "project_file_source_header_x_fund_ana_frontend_rendered_truth_allowed_mismatch" in bad_blockers
    assert "project_file_source_header_artifact_declared_not_true" in bad_blockers
    assert "project_file_source_header_artifact_key_mismatch" in bad_blockers
    assert "project_file_source_header_x_fund_ana_file_content_token_missing" in bad_blockers


