def test_data_truthfulness_frontend_truth_blocks_missing_percent_fake_zero(tmp_path: Path) -> None:
    module = _load_script_module(
        "audit_data_truthfulness_frontend_fake_zero_for_test",
        "scripts/audit_data_truthfulness.py",
    )
    frontend_dir = tmp_path / "frontend"
    frontend_dir.mkdir()
    for page_name in [
        "index.html",
        "tracker.html",
        "recommendations.html",
        "favorites.html",
        "reports.html",
        "task-summary.html",
        "operations.html",
        "excel_viewer.html",
        "settings.html",
    ]:
        (frontend_dir / page_name).write_text(
            '<script src="/version-widget.js?v=test"></script>',
            encoding="utf-8",
        )
    bad_js = frontend_dir / "recommendations.js"
    bad_js.write_text(
        "\n".join(
            [
                "const title = `近1月涨跌 ${formatSignedPercentText(String(value || '').trim() || '0')}`;",
                "const riskCoverage = formatPercent((payload.coverage_ratio_vs_candidate || 0) * 100, 2);",
            ]
        )
        + "\n",
        encoding="utf-8",
    )
    settings = SimpleNamespace(project_root=tmp_path)

    payload = module._frontend_truth(settings)

    assert payload["status"] == "blocker"
    assert "frontend_missing_percent_rendered_as_zero" in payload["blockers"]
    assert "frontend_missing_ratio_rendered_as_zero" in payload["blockers"]
    assert payload["fake_zero_percent_matches"][0]["path"] == "frontend/recommendations.js"
    assert payload["fake_zero_ratio_matches"][0]["path"] == "frontend/recommendations.js"

    bad_js.write_text(
        "\n".join(
            [
                "const title = `近1月涨跌 ${formatSignedPercentOrDash(value)}`;",
                "const riskCoverage = formatRatioPercent(payload.coverage_ratio_vs_candidate, 2);",
            ]
        )
        + "\n",
        encoding="utf-8",
    )

    repaired_payload = module._frontend_truth(settings)

    assert repaired_payload["status"] == "ok"
    assert repaired_payload["blockers"] == []
    assert repaired_payload["fake_zero_percent_matches"] == []
    assert repaired_payload["fake_zero_ratio_matches"] == []


