def test_data_truthfulness_source_scan_allowed_context_keeps_real_fake_suspicious() -> None:
    module = _load_script_module(
        "audit_data_truthfulness_source_scan_for_test",
        "scripts/audit_data_truthfulness.py",
    )

    assert module._is_source_scan_allowed_context('placeholders = ",".join("?" for _ in codes)', "backend/app.py")
    assert module._is_source_scan_allowed_context(
        '<input type="search" placeholder="输入基金代码或名称" />',
        "frontend/recommendations.html",
    )
    assert module._is_source_scan_allowed_context(
        "if self._is_placeholder_value(value):",
        "core/collectors/detail_collector.py",
    )
    assert module._is_source_scan_allowed_context(
        '"Datas=None is preserved as upstream missing, not converted to fake detail data",',
        "backend/upstream_api_contract.py",
    )
    assert module._is_source_scan_allowed_context(
        '"fake_data_policy": "forbidden",',
        "backend/upstream_api_contract.py",
    )
    assert not module._is_source_scan_allowed_context(
        "fake_business_data = {'annual_return': 0}",
        "backend/report_builder.py",
    )
    assert module._source_scan_context_category(
        "fake_business_data = {'annual_return': 0}",
        "backend/report_builder.py",
    ) == "suspicious_production_keyword"
    assert module._source_scan_context_category(
        "sample_codes = normalized_final_codes[:sample_limit]",
        "scripts/audit_data_truthfulness.py",
    ) == "allowed_truth_audit_implementation"


