def test_frontend_scheduler_shared_helpers_are_lazy_loaded_on_scheduler_pages() -> None:
    frontend_dir = PROJECT_ROOT / "frontend"
    app_src = (PROJECT_ROOT / "backend" / "app.py").read_text(encoding="utf-8")
    shared_src = (frontend_dir / "shared.js").read_text(encoding="utf-8")
    scheduler_shared_src = (frontend_dir / "scheduler-shared.js").read_text(encoding="utf-8")
    html_scripts = {
        html_file.name: html_file.read_text(encoding="utf-8")
        for html_file in sorted(frontend_dir.glob("*.html"))
    }

    assert 'send_from_directory(FRONTEND_DIR, "scheduler-shared.js")' in app_src
    assert "function formatSchedulerRuntime(enabled, running)" in scheduler_shared_src
    assert "function renderAutomationClosureCards(digest, options = {})" in scheduler_shared_src
    assert "function formatSchedulerRuntime(enabled, running)" not in shared_src
    assert "function renderAutomationClosureCards(digest, options = {})" not in shared_src

    scheduler_helper_pages = {"index.html", "operations.html", "settings.html"}
    for page_name in scheduler_helper_pages:
        assert re.search(_script_tag_with_optional_version("scheduler-shared.js"), html_scripts[page_name])
    for page_name, html_src in html_scripts.items():
        if page_name in scheduler_helper_pages:
            _assert_script_loaded_before(html_src, "shared.js", "scheduler-shared.js")
            continue
        assert not re.search(_script_tag_with_optional_version("scheduler-shared.js"), html_src)


