def test_frontend_recommendations_detail_is_explicitly_requested_after_summary() -> None:
    recommendations_src = (PROJECT_ROOT / "frontend" / "recommendations.js").read_text(encoding="utf-8")
    shared_src = (PROJECT_ROOT / "frontend" / "shared.js").read_text(encoding="utf-8")

    assert "function shouldLoadRecommendationDetail(options = {})" in recommendations_src
    assert "data-rec-load-detail=\"1\"" in recommendations_src
    assert "await initRecommendationsPage({ detail: true, group: initialGroup });" in recommendations_src
    assert "loadDetail ? loadFavoriteFundHistory() : Promise.resolve({ records: [] })" in recommendations_src
    assert "async function loadRecommendationsLatestDetail(options = {})" in shared_src
    assert "params.set('group', group);" in shared_src
    assert "`/api/recommendations/latest/detail?${suffix}`" in shared_src
    assert "const recommendationDetailPayloadCache = new Map();" in recommendations_src
    assert "loadRecommendationDetailPayloadForGroup(summaryPayload, initialDetailGroup)" in recommendations_src
    assert "selectRecommendationGroup(nextGroup)" in recommendations_src

    summary_branch_index = recommendations_src.index("if (isRecommendationSummaryPayload(payload))")
    no_detail_index = recommendations_src.index("if (!loadDetail)", summary_branch_index)
    detail_load_index = recommendations_src.index(
        "payload = await loadRecommendationDetailPayloadForGroup(summaryPayload, initialDetailGroup);",
        summary_branch_index,
    )
    assert no_detail_index < detail_load_index
    assert "return;" in recommendations_src[no_detail_index:detail_load_index]
    assert "renderRecommendationSummaryShell(payload);\n    try {\n      payload = await loadRecommendationsLatestDetail();" not in recommendations_src
def test_data_truthfulness_workflow_summary_allows_isolated_diagnostic_run(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _load_script_module(
        "audit_data_truthfulness_workflow_diagnostic_run_for_test",
        "scripts/audit_data_truthfulness.py",
    )
    payload = {
        "status": "succeeded",
        "phase": "completed",
        "run_id": "diagnostic-run",
        "logs_tail": [],
        "source_basis": {
            "source": "workflow_status_summary_runtime_manager",
            "run_id": "diagnostic-run",
        },
        "source_contract": {
            "source": "workflow_status_summary_runtime_manager",
            "official_publication_truth": "false_workflow_runtime_diagnostics_only",
            "frontend_rendered_truth_allowed": False,
        },
    }

    summary, blockers = module._validate_live_workflow_status_summary(
        payload,
        expected_publication={"latest_report_run_id": "published-run"},
    )

    assert blockers == []
    assert summary["run_id"] == "diagnostic-run"


@pytest.mark.parametrize(
    "payload_patch",
    [
        {"source_contract": {}},
        {"source_basis": {"source": "workflow_status_summary_runtime_manager", "run_id": "other-run"}},
        {"source_contract": {
            "source": "workflow_status_summary_runtime_manager",
            "official_publication_truth": "publication_registry",
            "frontend_rendered_truth_allowed": False,
        }},
    ],
)
def test_data_truthfulness_workflow_summary_rejects_unproven_diagnostic_mismatch(
    payload_patch: dict[str, Any],
) -> None:
    module = _load_script_module(
        "audit_data_truthfulness_workflow_unproven_diagnostic_for_test",
        "scripts/audit_data_truthfulness.py",
    )
    payload = {
        "status": "succeeded",
        "phase": "completed",
        "run_id": "diagnostic-run",
        "logs_tail": [],
        "source_basis": {
            "source": "workflow_status_summary_runtime_manager",
            "run_id": "diagnostic-run",
        },
        "source_contract": {
            "source": "workflow_status_summary_runtime_manager",
            "official_publication_truth": "false_workflow_runtime_diagnostics_only",
            "frontend_rendered_truth_allowed": False,
        },
    }
    payload.update(payload_patch)

    _summary, blockers = module._validate_live_workflow_status_summary(
        payload,
        expected_publication={"latest_report_run_id": "published-run"},
    )

    assert "workflow_success_run_id_mismatch" in blockers
